 for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++)if(brcConditionsOverlap(rows[i].c,rows[j].c))return {key:rows[j].key,message:'翻新周期的'+rows[i].label+'与'+rows[j].label+'条件重叠'};
