// 规模等级只读GSV条件；利润条件独立用于经营标签，缺失利润不影响规模评级。
const brcGradeScaleCache=new WeakMap();
function brcNormalizeGradeAxes(conditions,defaults){
 for(const key of Object.keys(defaults).filter(key=>key.startsWith('grades.'))){
  const metric=key.includes('.sales')?'gsv':'profitRate';
  const keep=c=>c?.conditions?{...c,conditions:c.conditions.map(keep).filter(Boolean)}:c&&(!c.metric||c.metric===metric)?c:null;
  const next=keep(conditions[key]);
  conditions[key]=next&&brcPredicateBoxes(next,metric).some(box=>box[metric])?next:defaults[key];
 }
}
function brcGradeSalesRanges(level,conditions=null,mode='month'){
 const source=conditions||brcConditions(),order=['S','A','B','C'];
 let cache=brcGradeScaleCache.get(source);if(!cache){cache=new Map();brcGradeScaleCache.set(source,cache)}
 const cacheKey=mode+':'+level;if(cache.has(cacheKey))return cache.get(cacheKey);
 const ranges=grade=>{
  const key=brcGradeKeys(grade).sales;
  const keep=c=>c?.conditions?{op:c.op,conditions:c.conditions.map(keep).filter(Boolean)}:c&&(!c.metric||c.metric==='gsv')?{...c,metric:'gsv'}:null;
  const c=keep(source[key]);
  if(!c)return [];
  return brcPredicateBoxes(brcMapCondition(c,value=>value*brcGradeFactor(mode)),'gsv').map(box=>box.gsv).filter(Boolean);
 };
 // 自定义区间若重叠，沿用S→A→B→C的优先级；图表与判定使用同一有效区间。
 const higher=order.slice(0,order.indexOf(level)).flatMap(ranges),remaining=brcRangesComplement(higher);
 const result=brcMergeRanges(ranges(level).flatMap(a=>remaining.map(b=>brcRangeIntersection(a,b)).filter(Boolean)));
 cache.set(cacheKey,result);return result;
}
function brcProductOperatingMatch(level,profit){
 return Number.isFinite(profit)&&brcPredicateTest(brcConditions()[brcGradeKeys(level).profit],'profitRate',{profitRate:profit});
}
// 条件是判定真值来源；数值投影只供公式、目标、旧图表和兼容数据读取。
function brcConditions(){
 if(typeof brcSaved!=='undefined'&&brcSaved.conditions)return brcSaved.conditions;
 const values=Object.fromEntries(brcDefinitions.map(r=>[r.key,typeof brcNumber==='function'?brcNumber(r.key):r.value]));return brcDefaultConditions(values);
}
function brcMatch(key,value,context={}){const metric=brcMetricConfig(key).default;return brcPredicateTest(brcConditions()[key],metric,{...context,[metric]:value})}
// 三种天数共用近15日均净销量；组成缺失不当作0，无正净销量不计算天数。
function brcStockMetrics(stock){
 const valid=value=>Number.isFinite(value)&&value>=0,daily=stock.dailyNet15;
 if(daily!==undefined&&(!Number.isFinite(daily)||daily<=0))return {coverage15:null,sellableCoverage15:null,totalCoverage15:null};
 const days=units=>valid(units)&&Number.isFinite(daily)&&daily>0?units/daily:null;
 const parts=[stock.warehouse,stock.transit,stock.factoryAvailable];
 const sellable=valid(stock.sellableUnits)?stock.sellableUnits:parts.every(valid)?parts.reduce((sum,value)=>sum+value,0):null;
 return {coverage15:valid(stock.coverage15)?stock.coverage15:days(stock.warehouse),
  sellableCoverage15:valid(stock.sellableCoverage15)?stock.sellableCoverage15:days(sellable),
  totalCoverage15:valid(stock.totalCoverage15)?stock.totalCoverage15:days(stock.totalUnits)};
}
function brcStockRuleMatch(key,stock){const metrics=brcStockMetrics(stock);return brcMatch(key,metrics[key==='stock.shortDays'?'totalCoverage15':'coverage15'],metrics)}
function brcStockStagnant(stock){
 const positiveSales=stock.dailyNet15===undefined?Number.isFinite(stock.coverage15):Number.isFinite(stock.dailyNet15)&&stock.dailyNet15>0;
 return Number.isFinite(stock.warehouse)&&stock.warehouse>0&&positiveSales&&brcStockRuleMatch('stock.slowDays',stock);
}
function brcStockRuleText(key){return brcNamedConditionText(key,brcConditions()[key])}
function brcStockWarningMetrics(stock,excluded=false){
 const days=brcStockMetrics(stock);
 // 台账明确给出空天数时保留缺失；不以推算值覆盖数据源的空值。
 if(Number.isFinite(stock.dailyNet15)&&stock.dailyNet15>0)for(const key of Object.keys(days))if(Object.hasOwn(stock,key))days[key]=Number.isFinite(stock[key])&&stock[key]>=0?stock[key]:null;
 return {...days,warehouse:Number.isFinite(stock.warehouse)?stock.warehouse:null,netSales15:Number.isFinite(stock.dailyNet15)?Math.round(stock.dailyNet15*15):null,excluded:excluded?1:0};
}
function brcStockWarningRuleText(key){return brcNamedConditionText(key,brcConditions()[key])}
function brcStockWarningPrimary(key,stock){
 const first=c=>c?.conditions?first(c.conditions[0]):c,metric=brcTermMetric(key,first(brcConditions()[key]));
 return {name:metric.label,value:brcStockWarningMetrics(stock)[metric.id]};
}
function brcDescribe(key,unit){const item=brcEditorByKey.get(key);return brcPredicateText(key,brcConditions()[key],unit??item?.unit??'')}
function brcBandTone(id,value,context={}){
 const band=brcBands.find(b=>b.id===id);if(!band||band.style!=='score'&&!Number.isFinite(value))return 'gray';
 const conditions=brcConditions();
 for(const [index,key] of band.keys.entries())if(band.style==='score'?brcPredicateTest(conditions[key],'value',{...context,value:Number.isFinite(value)?value:null}):brcTestCondition(conditions[key],value))return band.tones[index];
 return 'gray';
}
function brcBandRows(id){const band=brcBands.find(b=>b.id===id);return band?band.keys.map((key,index)=>({tone:band.tones[index],label:brcEditorByKey.get(key).label,text:brcDescribe(key)})):[]}
function brcBandText(id){return brcBandRows(id).map(r=>r.label+'：'+r.text).join('；')}
function brcGradeKeys(level){return {sales:'grades.'+level+'.'+(level==='C'?'salesBelow':'salesAbove'),profit:'grades.'+level+'.'+(['A','C'].includes(level)?'profitBelow':'profitAbove')}}
// 图片规范按月销配置；近30天/月沿用月门槛，季/年换算，利润率不缩放。
function brcGradeFactor(mode='quarter'){return mode==='year'?12:mode==='quarter'?3:1}
function brcGradeCondition(key,mode='quarter'){
 const scale=c=>{const next=brcCloneCondition(c);if(next.conditions)next.conditions=next.conditions.map(scale);else if((next.metric||brcMetricConfig(key).default)==='gsv'&&Number.isFinite(next.a))next.a*=brcGradeFactor(mode);return next};return scale(brcConditions()[key]);
}
function brcProductGrade(sales,profit,mode='quarter'){
 if(!Number.isFinite(sales))return null;
 return ['S','A','B','C'].find(level=>brcGradeSalesRanges(level,null,mode).some(range=>brcRangeHas(range,sales)))||null;
}
function brcGradeConditionText(key,mode='quarter',unit){
 const condition=brcMapCondition(brcGradeCondition(key,mode),value=>Math.round(value*1000000)/1000000);
 return brcPredicateText(key,condition,unit??brcEditorByKey.get(key)?.unit??'');
}
function brcGradeDescription(level,mode='quarter'){return 'GSV'+brcConditionText(brcRangesCondition(brcGradeSalesRanges(level,null,mode)),'万元')}
function brcGradeRegions(level,conditions=null,mode='quarter'){
 return brcGradeSalesRanges(level,conditions,mode).map(gsv=>({gsv}));
}
function brcGradeRules(mode='quarter'){
 const universe={lo:-Infinity,hi:Infinity,lc:false,hc:false};
 return Object.fromEntries(['S','A','B','C'].map(level=>{
  const regions=brcGradeRegions(level,null,mode).map(box=>({sales:box.gsv||universe,profit:box.profitRate||universe})),rule={regions};
  for(const axis of ['sales','profit']){const ranges=brcMergeRanges(regions.map(region=>region[axis]));rule[axis+'Ranges']=ranges;if(Number.isFinite(ranges[0]?.lo))rule[axis+'Above']=ranges[0].lo;if(Number.isFinite(ranges.at(-1)?.hi))rule[axis+'Below']=ranges.at(-1).hi;}
  return [level,rule];
 }));
}
function brcProjectValues(values,conditions){
 const next={...values};
 for(const item of brcEditorItems){
  if(item.kind!=='condition'||!item.legacy)continue;const c=conditions[item.key];if(c.op==='else')continue;
  const metric=brcMetricConfig(item.key).default,terms=brcConditionTerms(c).filter(term=>!term.metric||term.metric===metric);if(!terms.length)continue;const range=brcInterval(c.op==='all'||c.op==='any'?{op:c.op,conditions:terms}:terms[0]),bound=item.anchor==='b'?range.hi:range.lo;
  next[item.legacy]=Number.isFinite(bound)?bound:Number.isFinite(range.hi)?range.hi:terms[0]?.a;
  if(item.aliases?.length&&Number.isFinite(range.hi))next[item.aliases[0]]=range.hi;
 }
 return next;
}
function brcLinkBandBoundary(key,before,after,conditions){
 const item=brcEditorByKey.get(key),cycle=brcRefurbCycleKeys.includes(key);if((!item?.band&&!cycle)||before.op==='else'||after.op==='else')return;
 const score=item.band?.startsWith('score.'),scoreMetrics=score?brcScoreMetrics(before):[];
 if(score&&(scoreMetrics.length!==1||brcScoreMetrics(after).length!==1||brcScoreMetrics(after)[0]!==scoreMetrics[0]))return;
 const oldRanges=brcRanges(before),newRanges=brcRanges(after);if(oldRanges.length!==1||newRanges.length!==1)return;
 const oldRange=oldRanges[0],newRange=newRanges[0],band=cycle?{keys:brcRefurbCycleKeys}:brcBands.find(b=>b.id===item.band);
 for(const peerKey of band.keys.filter(k=>k!==key)){
  const peer=brcNormalizeCondition(conditions[peerKey]);if(!peer||['else','any'].includes(peer.op))continue;const terms=brcConditionTerms(peer);
  for(const term of terms){
   if(score&&(term.metric||'value')!==scoreMetrics[0])continue;
   if(['lt','lte'].includes(term.op)&&Number.isFinite(oldRange.lo)&&Number.isFinite(newRange.lo)&&term.a===oldRange.lo){term.a=newRange.lo;term.op=newRange.lc?'lt':'lte';}
   if(['gt','gte'].includes(term.op)&&Number.isFinite(oldRange.hi)&&Number.isFinite(newRange.hi)&&term.a===oldRange.hi){term.a=newRange.hi;term.op=newRange.hc?'gt':'gte';}
  }
  conditions[peerKey]=peer.op==='all'?{...peer,conditions:terms}:terms[0];
 }
}

// 相对目标的差额用于店铺连续两期退货判断；零目标正值仍可判定。
function brcRelativeExcess(actual,target){return target>0?(actual-target)/target*100:actual>0?Infinity:null}
// 同一结果的条件共用连接关系；保留原字段键及默认逻辑，兼容已保存配置。
const brcResultGroups=[
 ...['S','A','B','C'].map(level=>({id:'grade-'+level,title:level+'级',keys:[brcGradeKeys(level).sales],op:'all'})),
 ...[['quarter','new.quarterGsv'],['year','new.yearGsv'],['season','new.seasonGsv']].map(([id,key])=>({id:'success-'+id,title:'销售成功',keys:[key,'new.profit','new.return'],op:'all'})),
 {id:'quality-risk',title:'品质风险',keys:['quality.returnDelta','quality.orders','quality.contactDelta'],parts:['quality-return','quality.contactDelta'],relationKey:'quality.contactDelta',addKey:'quality.contactDelta',op:'any'},
 {id:'quality-return',title:'总退风险',keys:['quality.returnDelta','quality.orders'],parent:'quality-risk',op:'all'},
 {id:'quality-worsening',title:'退货恶化',keys:['quality.worsenSales','quality.worsenReturn','quality.worsenReceived'],parts:['quality.worsenSales','quality-worsening-rate'],op:'all'},
 {id:'quality-worsening-rate',title:'退货增长条件',keys:['quality.worsenReturn','quality.worsenReceived'],parent:'quality-worsening',op:'any'},
 {id:'stock-platform',title:'高危库存',keys:['stock.profit','stock.return','stock.received','stock.violations'],op:'any'},
 {id:'stock-stagnant-warning',title:'呆滞预警',keys:['stock.warning.warehouse','stock.warning.netSales','stock.warning.coverageDays'],op:'all'},
 {id:'stock-shortage-warning',title:'缺货预警',keys:['stock.shortage.excluded','stock.shortage.netSales','stock.shortage.sellableDays','stock.shortage.totalDays'],parts:['stock.shortage.excluded','stock.shortage.netSales','stock-shortage-days'],op:'all'},
 {id:'stock-shortage-days',title:'天数条件',keys:['stock.shortage.sellableDays','stock.shortage.totalDays'],parent:'stock-shortage-warning',op:'any'}
];
function brcResultGroup(id){return brcResultGroups.find(group=>group.id===id)}
function brcResultRelationKey(id){const group=brcResultGroup(id);return group.relationKey||group.keys[0]}
function brcResultOp(id,conditions=brcConditions()){const group=brcResultGroup(id);return conditions[brcResultRelationKey(id)]?.groupOp||group.op}
function brcResultMembers(id,conditions=brcConditions()){return brcResultGroup(id).keys.filter(key=>!conditions[key]?.groupSkip)}
function brcResultCondition(id,conditions=brcConditions(),transform=(key,c)=>c){
 const group=brcResultGroup(id),op=brcResultOp(id,conditions);
 const named=(key,c)=>c.conditions?{op:c.op,conditions:c.conditions.map(term=>named(key,term))}:{op:c.op,a:c.a,metric:c.metric||brcMetricConfig(key).default};
 const parts=group.parts||group.keys,terms=parts.flatMap(part=>{
  const nested=brcResultGroup(part);
  if(nested)return brcResultMembers(part,conditions).length?[brcResultCondition(part,conditions,transform)]:[];
  return conditions[part]?.groupSkip?[]:[named(part,transform(part,conditions[part]))];
 });
 return {op:terms.length?op:'any',conditions:terms.flatMap(term=>term.op===op?term.conditions:[term])};
}
// 保存时替换条件对象；按版本对象缓存编译结果，避免逐SKU反复展开规则。
const brcResultMatchCache=new WeakMap();
function brcResultMatch(id,metrics,source=brcConditions()){let cache=brcResultMatchCache.get(source);if(!cache){cache=new Map();brcResultMatchCache.set(source,cache)}if(!cache.has(id))cache.set(id,brcResultCondition(id,source));return brcPredicateTest(cache.get(id),'value',metrics)}
function brcResultText(id,source=brcConditions()){
 const group=brcResultGroup(id),metrics=new Map(group.keys.flatMap(key=>brcMetricConfig(key).choices.map(metric=>[metric.id,metric])));
 // 默认排除状态用业务文案展示，保留布尔条件本身及其他配置的描述。
 const text=c=>c.conditions?brcJoinConditionText(c,text):c.metric==='excluded'&&c.op==='eq'&&c.a===0?'非清仓品、非下架品':(metrics.get(c.metric)?.label||'—')+brcMetricConditionText(metrics.get(c.metric),c);
 return text(brcResultCondition(id,source));
}
function brcResultKeyActive(id,key){return brcResultMembers(id).includes(key)}
function brcResultLeafCount(id,conditions){
 const count=c=>c.conditions?c.conditions.reduce((n,term)=>n+count(term),0):1;
 return brcResultMembers(id,conditions).reduce((n,key)=>n+count(conditions[key]),0);
}
// 保存前验证区间、判灯覆盖和二维分级冲突；不替业务补齐分级空档。
function brcValidate(values,conditions=brcDefaultConditions(values)){
 const error=(key,message)=>({key,message});
 for(const rule of brcDefinitions.filter(item=>item.editable===false))if(!Number.isFinite(values[rule.key])||values[rule.key]<rule.min||values[rule.key]>rule.max)return error(rule.key,'历史测算参数无效');
 for(const group of brcResultGroups){
  const primary=conditions[brcResultRelationKey(group.id)];
  if(primary?.groupOp&&!['all','any'].includes(primary.groupOp))return error(group.keys[0],'请选择有效的且／或关系');
  if(!group.parent&&!brcResultMembers(group.id,conditions).length)return error(group.keys[0],'请至少保留一条条件');
 }
 for(const item of brcEditorItems){
  const valid=n=>Number.isFinite(n)&&n>=item.min&&n<=item.max&&(!item.integer||Number.isInteger(n));
  if(item.kind==='parameter'){if(!valid(values[item.key]))return error(item.key,item.label+'需为'+brcEditorDisplayValue(item.min,item.unit)+'至'+brcEditorDisplayValue(item.max,item.unit)+brcEditorUnit(item.unit).label+'之间的'+(item.integer?'整数':'有效数值'));continue;}
  const original=conditions[item.key],c=brcNormalizeCondition(original);
  if(c?.groupSkip&&brcResultGroups.some(group=>group.keys.includes(item.key)))continue;
  if(!c||c.op==='else')return error(item.key,'请选择有效判定条件');
  if(original.op==='between'&&(typeof original.lower!=='boolean'||typeof original.upper!=='boolean'||original.a>=original.b))return error(item.key,'区间终点须大于起点，并明确两端是否包含等号');
  const validateTerm=(term,depth=0)=>{
   if(!term||depth>12)return '请选择有效判定条件';
   if(['all','any'].includes(term.op)){
    if(!Array.isArray(term.conditions)||!term.conditions.length)return item.band&&depth===0?'':'请至少添加一条条件';
    for(const child of term.conditions){const message=validateTerm(child,depth+1);if(message)return message}return '';
   }
   if(!['gt','gte','lt','lte','eq'].includes(term.op))return '请选择有效判定条件';
   const metric=brcTermMetric(item.key,term);if(!metric)return '请选择当前业务可用的指标';
   if(metric.valueType==='boolean'&&term.op!=='eq')return '状态条件仅支持等于“是”或“否”';
   return !Number.isFinite(term.a)||term.a<metric.min||term.a>metric.max||metric.integer&&!Number.isInteger(term.a)?metric.label+'需填写'+brcEditorDisplayValue(metric.min,metric.unit)+'至'+brcEditorDisplayValue(metric.max,metric.unit)+brcEditorUnit(metric.unit).label+'之间的'+(metric.integer?'整数':'有效数值'):'';
  };
  const message=validateTerm(c);if(message)return error(item.key,message);
  if(!brcPredicateBoxes(c,brcMetricConfig(item.key).default).length&&!(item.band&&c.op==='any'&&!c.conditions.length))return error(item.key,'条件无法同时满足，请调整数值或“且／或”关系');
 }
 for(const group of brcResultGroups)if(brcResultMembers(group.id,conditions).length&&!brcPredicateBoxes(brcResultCondition(group.id,conditions),'value').length)return error(group.keys[0],group.title+'条件无法同时满足，请调整数值或“且／或”关系');
 for(const band of brcBands){
  if(band.style==='score'){const result=brcValidateScoreBand(band,conditions);if(result)return result;continue}
  const rows=band.keys.map(key=>({key,c:conditions[key]}));
  const explicit=rows.filter(r=>r.c.op!=='else');
  for(let i=0;i<explicit.length;i++)for(let j=i+1;j<explicit.length;j++)if(brcConditionsOverlap(explicit[i].c,explicit[j].c))return error(explicit[j].key,band.section+'的'+brcEditorByKey.get(explicit[i].key).label+'与'+brcEditorByKey.get(explicit[j].key).label+'条件重叠');
  if(!brcCoversLine(rows.map(r=>r.c)))return error(rows[rows.length-1].key,band.section+'存在未覆盖区间，请补齐明确的比较条件');
 }
 const levels=['S','A','B','C'];
 for(let i=0;i<levels.length;i++)for(let j=i+1;j<levels.length;j++){
  const a=brcGradeKeys(levels[i]),b=brcGradeKeys(levels[j]);
  if(brcGradeRegions(levels[i],conditions).some(x=>brcGradeRegions(levels[j],conditions).some(y=>brcBoxIntersection(x,y))))return error(b.sales,levels[i]+'级与'+levels[j]+'级规则区间重叠');
 }
 return brcValidateRefurbCycle(values,conditions);
}
// 成功条件按完整考核期取值；季度与年度各自保存生效边界，不改变出池等参数。
function brcSuccessKeys(kind){return [kind==='year'?'new.yearGsv':'new.quarterGsv','new.seasonGsv','new.profit','new.return']}
function brcSuccessCopy(conditions){return Object.fromEntries([...new Set([...brcSuccessKeys('quarter'),...brcSuccessKeys('year')])].map(key=>[key,brcCloneCondition(conditions[key])]))}
function brcSuccessCurrent(){
 const date=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}),year=date.slice(0,4);
 return {quarter:year+'-Q'+Math.ceil(Number(date.slice(5,7))/3),year};
}
function brcSuccessPeriodValid(kind,value){return kind==='year'?/^[1-9]\d{3}$/.test(value):/^[1-9]\d{3}-Q[1-4]$/.test(value)}
function brcSuccessReadTimeline(raw,conditions,values){
 if(!raw)return {
  baseline:brcSuccessCopy(conditions),
  quarter:[{from:brcSuccessStart('quarter'),conditions:brcSuccessCopy(conditions)}],
  year:[{from:brcSuccessStart('year'),conditions:brcSuccessCopy(conditions)}]
 };
 const copy=source=>{
  if(!source||Object.keys(brcSuccessCopy(conditions)).some(key=>!source[key]))throw Error('成功条件记录缺失');
  const result=brcSuccessCopy(source),merged={...conditions,...result};
  if(brcValidate(brcProjectValues(values,merged),merged))throw Error('成功条件记录无效');return result;
 };
 const timeline={baseline:copy(raw.baseline)};
 for(const kind of ['quarter','year']){
  if(!Array.isArray(raw[kind]))throw Error('成功条件生效期间缺失');
  const seen=new Set();timeline[kind]=raw[kind].map(item=>{
   if(!brcSuccessPeriodValid(kind,item.from)||seen.has(item.from))throw Error('成功条件生效期间无效');
   seen.add(item.from);return {from:item.from,conditions:copy(item.conditions)};
  }).sort((a,b)=>a.from.localeCompare(b.from));
 }
 return timeline;
}
function brcSuccessConditions(annual,date){
 const kind=annual?'year':'quarter',from=date?date.slice(0,4)+(annual?'':'-Q'+Math.ceil(Number(date.slice(5,7))/3)):brcSuccessCurrent()[kind];
 const timeline=brcSaved.successTimeline;
 if(!timeline)return brcSaved.conditions;
 return timeline[kind].filter(item=>item.from<=from).at(-1)?.conditions||timeline.baseline;
}

function brcSuccessPeriodText(kind,from){const period=from||(kind==='year'?'2026':'2026-Q1');return kind==='year'?period.slice(2)+'年':period.slice(2).replace('-Q','/Q')}
function brcSuccessRules(kind){
 const timeline=brcSaved.successTimeline||brcSuccessReadTimeline(null,brcSaved.conditions,brcSaved.values),current=brcSuccessCurrent()[kind];
 const rows=[{from:'',conditions:timeline.baseline},...timeline[kind]],active=rows.filter(row=>row.from<=current).at(-1);
 return rows.map((row,index)=>({...row,status:row===active?'current':row.from>current?'pending':'history',until:rows[index+1]?.from||''}));
}
function brcSuccessRuleStatus(status){return {current:'当前生效',pending:'待生效',history:'历史规则'}[status]}

// 初始方案的展示期间也参与唯一性校验；保留旧基线供更早历史取值。
function brcSuccessStart(kind){return kind==='year'?'2026':'2026-Q1'}
function brcSuccessVisibleRules(kind){return brcSuccessRules(kind).filter(row=>row.from||!row.until||row.until>brcSuccessStart(kind))}
function brcSuccessEffectiveFrom(kind,row){return row.from||brcSuccessStart(kind)}
function brcSuccessConflict(kind,from,originalFrom=null){return brcSuccessVisibleRules(kind).find(row=>row.from!==originalFrom&&brcSuccessEffectiveFrom(kind,row)===from)}
function brcSuccessDuplicateText(kind,from){return brcSuccessPeriodText(kind,from)+'已有规则，请在查看规则中编辑'}
// v3保存且/或条件组；读取时兼容v1数值、v2区间，旧存储保留。
const BRC_STORAGE='dashboard-business-rules-v3',BRC_PREVIOUS_STORAGE='dashboard-business-rules-v2',BRC_LEGACY_STORAGE='dashboard-business-rules-v1';
// 本次仅一次重置旧新品成功方案；升级后新增、编辑的规则正常保留。
const BRC_SUCCESS_DEFAULT_REVISION=1;
function brcRead(){
 try{
  const data=JSON.parse(localStorage.getItem(BRC_STORAGE)||localStorage.getItem(BRC_PREVIOUS_STORAGE)||localStorage.getItem(BRC_LEGACY_STORAGE)||'null');
  if(![1,2,3].includes(data?.version)||!Number.isInteger(data.revision)||data.revision<0)return null;
  const values=Object.fromEntries(brcDefinitions.map(rule=>[rule.key,rule.source==='数智罗盘SABC规则配置'?rule.value:data.values?.[rule.key]??rule.value]));
  // 将旧默认10天订正为15天；保留其他自定义值，后续显式保存的配置不再迁移。
  if(data.deliveryRuleRevision!==1&&values['new.deliveryDays']===10)values['new.deliveryDays']=brcDefaults['new.deliveryDays'];
  // 店铺退货改为实际减目标＞3%，旧相对比例条件不能沿用。
  const upgradeShopReturns=data.shopReturnRuleRevision!==1;
  if(upgradeShopReturns)values['shops.returnExcess']=brcDefaults['shops.returnExcess'];
  // 旧的本地SABC覆盖值不再参与运行，等级和经营标签始终读取统一来源。
  // 本次订正仅升级退货灯色，保留其他业务配置；后续用户保存的条件正常保留。
  const upgradeReturns=data.returnRuleRevision!==1,returnKeys=new Set(brcBands.filter(b=>b.id.startsWith('return.')).flatMap(b=>b.keys));
  if(upgradeReturns){values['lights.return']=2;values['lights.received']=.5;}
  const defaults=brcDefaultConditions(values),conditions=brcExpandLegacyFallbacks(Object.fromEntries(Object.entries(defaults).map(([key,c])=>[key,data.version>=2&&data.conditions?.[key]&&!(upgradeReturns&&returnKeys.has(key))&&!key.startsWith('grades.')&&!(upgradeShopReturns&&key==='shops.returnExcess')?brcNormalizeCondition(data.conditions[key]):c])));
  brcNormalizeGradeAxes(conditions,defaults);
  const projected=brcProjectValues(values,conditions);return brcValidate(projected,conditions)?null:{version:3,returnRuleRevision:1,deliveryRuleRevision:1,shopReturnRuleRevision:1,revision:data.revision,values:projected,conditions,successDefaultRevision:data.successDefaultRevision||0,successTimeline:brcSuccessReadTimeline(data.successDefaultRevision===BRC_SUCCESS_DEFAULT_REVISION?data.successTimeline:null,conditions,projected),updatedAt:String(data.updatedAt||'')};
 }catch(_){return null}
}
let brcSaved=brcRead()||{version:3,returnRuleRevision:1,deliveryRuleRevision:1,shopReturnRuleRevision:1,revision:0,values:{...brcDefaults},conditions:brcDefaultConditions(brcDefaults),updatedAt:''};
// 默认季度、年度各一套显式生效规则。
brcSaved.successTimeline??=brcSuccessReadTimeline(null,brcSaved.conditions,brcSaved.values);
if(brcSaved.successDefaultRevision!==BRC_SUCCESS_DEFAULT_REVISION){
 const next={...brcSaved,successDefaultRevision:BRC_SUCCESS_DEFAULT_REVISION};
 if(brcRead()){
  try{brcPersistRules({...next,revision:brcSaved.revision+1})}catch(_){brcSaved=next}
 }else brcSaved=next;
}
function brcNumber(key){return brcSaved.values[key]??brcDefaults[key]}
function brcCommit(group,draft,draftConditions=brcDefaultConditions(draft)){
 if(!brcGroups.some(([key])=>key===group))throw Error('业务对象不存在');
 if((brcRead()?.revision||0)!==brcSaved.revision)throw Error('配置已在其他页面更新，请取消更改后重试');
 const values={...brcSaved.values},conditions=brcCopyConditions(brcSaved.conditions);
 for(const item of brcConfigurableItems.filter(item=>item.group===group)){if(item.kind==='parameter')values[item.key]=draft[item.key];else conditions[item.key]=brcNormalizeCondition(draftConditions[item.key]);}
 const projected=brcProjectValues(values,conditions),invalid=brcValidate(projected,conditions);
 if(invalid)throw Object.assign(Error(invalid.message),{field:invalid.key});
 const next={version:3,returnRuleRevision:1,deliveryRuleRevision:1,shopReturnRuleRevision:1,revision:brcSaved.revision+1,values:projected,conditions,successTimeline:brcSuccessReadTimeline(brcSaved.successTimeline,brcSaved.conditions,brcSaved.values),updatedAt:new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'})};
 return brcPersistRules(next);
}
function brcPersistRules(next){
 next={...next,successDefaultRevision:BRC_SUCCESS_DEFAULT_REVISION};
 // 只持久化本系统维护的规则；SABC配置不写入本地规则存储。
 const owned=entries=>Object.fromEntries(Object.entries(entries).filter(([key])=>!key.startsWith('grades.')));
 try{localStorage.setItem(BRC_STORAGE,JSON.stringify({...next,values:owned(next.values),conditions:owned(next.conditions)}))}catch(_){throw Error('保存失败，请检查浏览器存储空间')}
 brcSaved=next;return next;
}
// 仅负责数值呈现：调用方继续提供原判灯结果，不在这里计算阈值。
function numberSignalClass(tone,allTones=false){
 const color=({red:'red','rp-quality-red':'red',orange:'yellow',yellow:'yellow','rp-quality-yellow':'yellow'})[tone]||(allTones&&['green','rp-quality-green'].includes(tone)?'green':'');
 return color?'number-signal number-signal--'+color:'';
}
function numberSignal(value,tone,options=false){
 // 兼容原纯文字布尔参数；同组判灯要求完整标签时显式开启全部灯色。
 const settings=typeof options==='boolean'?{plain:options}:options||{};
 const text=String(value??'—'),classes=numberSignalClass(tone,settings.allTones);
 // 缺失、持平及文字状态不套数值标签。
 return !settings.plain&&classes&&/\d/.test(text)?'<span class="'+classes+' number-signal-text">'+esc(text)+'</span>':esc(text);
}

// 总退/已收退主值、呆滞及罚款冻结字段仅保留文字色；偏差另由辅助行呈现。
function numberSignalMain(field){
 const plain=field.noNumericSignal||['return','returns','returnRate','returned','received','receivedRate','fine','frozen','fineAmount','frozenAmount','fineCount','frozenCount','sanctions'].includes(field.key)||/^stale/.test(field.key||'');
 return numberSignal(field.value,field.tone,plain);
}
// 公共筛选字典：只集中已确认相同的枚举；各模块仍决定取值范围和单/多选方式。
const filterCatalog=(()=>{
 const platformNames=Object.freeze({douyin:'抖音',kuaishou:'快手',wechat:'视频号',tmall:'天猫',jd:'京东',pdd:'拼多多'});
 const platforms=Object.freeze(Object.values(platformNames));
 const chainAliases=Object.freeze({环境:'环境',环境类:'环境',环境链:'环境',清洁:'清洁',清洁类:'清洁',清洁链:'清洁',厨电:'厨电',厨电类:'厨电',厨房类:'厨电',厨房链:'厨电','个护&健康':'个护&健康','个护 & 健康链':'个护&健康',个护类:'个护&健康',健康类:'个护&健康'});
 const departmentAliases=Object.freeze({产品部:'产品中心',品质部:'品质中心',研发部:'研发中心'});
 return Object.freeze({
  platformNames,platforms,
  // 项目风险与共用待办共享范围；降本等模块保留各自业务范围。
  primaryDepartments:Object.freeze(['产品中心','项目部','品质中心','研发中心','采购部']),
  normalizeDepartment(value){
   const name=String(value??'').trim();
   return Object.hasOwn(departmentAliases,name)?departmentAliases[name]:name;
  },
  // 展示枚举按业务顺序；数字索引保留历史身份，避免重排后串到其他链群。
  chains:Object.freeze(['环境','清洁','厨电','个护&健康']),
  chainByIndex:Object.freeze(['清洁','厨电','环境','个护&健康']),
  normalizeChain(value){
   const text=String(value??'').trim();
   return Object.hasOwn(chainAliases,text)?chainAliases[text]:null;
  },
  dashboardBrands:Object.freeze(['苏泊尔','美的','创维','海尔','康佳']),
  // 保留旧调用名，销售渠道字段和其他平台筛选共用六项枚举。
  salesChannels:platforms,
  platformColors:Object.freeze({抖音:'#fa803b',快手:'#009a29',视频号:'#cf73ad',天猫:'#7167ed',京东:'#35a9d4',拼多多:'#e77369'}),
  seasons:Object.freeze(['夏季品','冬季品','四季品']),
  developmentTypes:Object.freeze(['自研','自选']),
  productTypes:Object.freeze([{value:'new',label:'新品'},{value:'old',label:'老品'},{value:'clearance',label:'清仓品'}].map(Object.freeze)),
  supplierCoreBrands:Object.freeze([['美海'],['康创'],['苏泊尔']].map(Object.freeze)),
  supplierBrandMembers:Object.freeze({美海:Object.freeze(['美的','海尔']),康创:Object.freeze(['康佳','创维']),苏泊尔:Object.freeze(['苏泊尔'])}),
  // 原始供应关系及历史风险记录使用原品牌，不因展示分组而重建身份。
  supplierSourceBrands:Object.freeze(['美的','海尔','苏泊尔','康佳','创维']),
  supplierCoreMaterials:Object.freeze(['电机','电池','电源线','线路板','塑料件','包装'])
 });
})();
window.FilterCatalog=filterCatalog;
// 旧调用名兼容：只读取六平台事实，不将内部销售组织映射为平台。
function salesChannelRows(platformRows=[],explicitRows=[]){
 const direct=new Map(platformRows.filter(row=>filterCatalog.platforms.includes(row.platform)).map(row=>[row.platform,row]));
 const explicit=new Map(explicitRows.filter(row=>filterCatalog.platforms.includes(row.channel)).map(row=>[row.channel,row]));
 return filterCatalog.platforms.map(channel=>{
  const row=direct.get(channel)||explicit.get(channel);if(!row)return {channel};
  const {platform,...facts}=row;return {...facts,channel};
 });
}
// 前台与数智罗盘共用的平台分类规则；旧值只做有依据的迁移，考核属性独立保留。
window.ShopClassification=(()=>{
 const platforms=filterCatalog.platformNames;
 const rules={京东:['自营','POP旗舰店','POP专卖店'],天猫:['旗舰店','专卖店'],拼多多:['旗舰店','专卖店'],抖音:['旗舰店','专卖店'],快手:['旗舰店','专卖店'],视频号:['旗舰店','专卖店']};
 const pending='无分类',order=['旗舰店','POP旗舰店','专卖店','POP专卖店','自营',pending];
 const name=platform=>Object.hasOwn(platforms,platform)?platforms[platform]:platform;
 const allowed=platform=>Object.hasOwn(rules,name(platform))?[...rules[name(platform)]]:[];
 function options(selection='all',includePending=true){
  const selected=(Array.isArray(selection)?selection:[selection]).filter(p=>p&&p!=='all');
  const values=new Set((selected.length?selected:Object.keys(rules)).flatMap(allowed));
  return order.filter(value=>values.has(value)||(includePending&&value===pending));
 }
 function normalize(platform,category){
  const current=String(category||'').trim();
  const migrated=name(platform)==='京东'?({'自营店':'自营','旗舰店':'POP旗舰店','专卖店':'POP专卖店'}[current]||current):current;
  return allowed(platform).includes(migrated)?migrated:pending;
 }
 function infer(platform,shopName=''){
  const category=/自营/.test(shopName)?'自营店':/旗舰店/.test(shopName)?'旗舰店':/专卖店/.test(shopName)?'专卖店':null;
  return normalize(platform,category);
 }
 function resolve(platform,shop,saved){
  const source=saved&&Object.hasOwn(saved,'shopCategory')?saved:shop;
  const shopCategory=source?.shopCategory?normalize(platform,source.shopCategory):infer(platform,shop.name);
  const legacy=shopCategory===pending?(source?.legacyShopCategory||source?.shopCategory):null;
  return {shopCategory,...(legacy&&legacy!==pending&&legacy!=='待确认'?{legacyShopCategory:legacy}:{}),assessed:typeof saved?.assessed==='boolean'?saved.assessed:!!shop.assessed};
 }
 function store(data){
  const shops={};
  if(data?.version===1&&data.shops&&typeof data.shops==='object'&&!Array.isArray(data.shops))for(const [key,value] of Object.entries(data.shops)){
   const parts=key.split('|');if(parts.length!==2||!Object.hasOwn(rules,parts[0])||!parts[1]||!value||typeof value!=='object')continue;
   const row={};
   if(typeof value.shopCategory==='string'){
    row.shopCategory=normalize(parts[0],value.shopCategory);
    if(row.shopCategory===pending){const legacy=value.legacyShopCategory||value.shopCategory;if(legacy!==pending&&legacy!=='待确认')row.legacyShopCategory=String(legacy)}
   }
   if(typeof value.assessed==='boolean')row.assessed=value.assessed;
   if(Object.keys(row).length)shops[key]=row;
  }
  return {version:1,shops};
 }
 const valid=(platform,category)=>allowed(platform).includes(category);
 const rank=category=>{const index=order.indexOf(category);return index<0?order.length:index};
 return {name,allowed,options,normalize,infer,resolve,store,valid,rank,pending};
})();
