function tableInlineProductGrade(cell,gradeCell){
 const template=document.createElement('template'),grade=document.createElement('span');
 template.innerHTML=String(gradeCell??'');const text=template.content.textContent.trim()||'待分级';
 grade.className='product-grade-label';grade.dataset.productGrade=/^[SABCD]/.test(text)?text[0]:'unrated';
 grade.textContent=text;grade.setAttribute('aria-label','产品分级：'+text);
 template.innerHTML=String(cell??'');let line=template.content.querySelector('.product-name-line');
 if(!line){
  const name=template.content.querySelector('.prodname strong,.dp-product b,.rp-identity b,strong,b');
  line=document.createElement('span');line.className='product-name-line';
  if(name){name.before(line);line.append(name);while(line.nextElementSibling?.matches('.rp-platform-mark,.channel-icon'))line.append(line.nextElementSibling)}
  else{line.append(...template.content.childNodes);template.content.append(line)}
 }
 line.append(grade);return template.innerHTML;
}
function table(headers,rows,cls=''){
 const plain=header=>String(header).replace(/<[^>]*>/g,'').trim(),gradeIndex=headers.findIndex(header=>/^(?:产品分级|产品等级)$/.test(plain(header)));
 const columns=headers.flatMap((header,index)=>index>0&&/^(?:季品|链群|所属链群|产品链群|产品分级|产品等级)$/.test(plain(header))?[]:[index]);
 rows=rows.map(original=>{
  const row=[...original];
  if(gradeIndex>0){
   let identity=row.findIndex((cell,index)=>index!==gradeIndex&&/class=["'][^"']*(?:prodname|dp-product|rp-identity)/.test(String(cell)));
   if(identity<0)identity=headers.findIndex((header,index)=>index!==gradeIndex&&/(?:产品|SPU|SKU)/.test(plain(header)));
   if(identity<0)identity=0;row[identity]=tableInlineProductGrade(row[identity],row[gradeIndex]);
  }
  return columns.map(index=>row[index]);
 });headers=columns.map(index=>headers[index]);
 return `<table class="${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}" class="empty">暂无符合条件的数据</td></tr>`}</tbody></table>`}
function titleProduct(p,{showBrand=true,subtitle,gradeMarkup=''}={}){return `<div class="prodname">${riskThumbnail(p.name)}<div>${gradeMarkup?'<div class="product-name-line"><strong>'+p.name+'</strong>'+gradeMarkup+'</div>':'<strong>'+p.name+'</strong>'}<small>${subtitle!=null?esc(subtitle):(p.spuCode?'SPU码：'+esc(p.spuCode):'型号：'+esc(p.model||'—'))+(showBrand?' · '+esc(p.brand):'')}</small></div></div>`}
function spark(i=0){let points=Array.from({length:22},(_,k)=>`${k*10},${25-Math.sin(k*.8+i)*5-k*.5}`).join(' ');return `<svg class="spark" viewBox="0 0 210 32" preserveAspectRatio="none" aria-hidden="true"><polyline points="${points} 210,32 0,32" fill="#eef1ff" stroke="none"/><polyline points="${points}" fill="none" stroke="#8594ff" stroke-width="1.5"/></svg>`}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,Math.min(10000,Math.max(3200,String(t).split('\n').length*900)))}
function downloadCsv(headers,rows,name){const cell=x=>'"'+String(x??'').replace(/<[^>]*>/g,'').replace(/^[=+@-]/,"'" ).replace(/"/g,'""')+'"';const blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
