function uiImportWorkbookParts(headers,rows,{required=[],conditional={},layout={},guide=[],example=[]}={}){
 const requiredNames=new Set(required),ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main';
 const headerRow=guide.length?guide.length+2:1,lastColumn=uiTemplateColumn(headers.length-1);
 const cell=(value,column,row,style,header=false)=>{
  // 仅显式指定的金额列写为数值；标识、年度和日期继续保留为文本。
  if(!header&&layout.numericColumns?.includes(column)&&/^-?\d+(?:\.\d+)?$/.test(String(value)))return `<c r="${uiTemplateColumn(column)}${row}" t="n" s="${style===2?9:style===5?10:8}"><v>${uiTemplateXml(value)}</v></c>`;
  return `<c r="${uiTemplateColumn(column)}${row}" t="inlineStr" s="${style}"><is>${header?uiTemplateHeaderXml(value,requiredNames.has(value)||!!conditional[value],conditional[value],'FFFFFFFF',true):'<t xml:space="preserve">'+uiTemplateXml(value)+'</t>'}</is></c>`;
 };
 const line=(values,row,style,height,header=false)=>`<row r="${row}" ht="${height}" customHeight="1">${values.map((value,column)=>cell(value,column,row,style,header)).join('')}</row>`;
 const instructions=guide.length?['填写说明',...guide]:[];
 const guideRows=instructions.map((text,index)=>line([text],index+1,index?7:6,index?30:38)).join('');
 const sample=example.length?[...example]:null;if(sample)sample[0]='【示例】'+String(sample[0]??'');
 const start=headerRow+(sample?2:1);
 const data=guideRows+line(headers,headerRow,4,guide.length?(layout.headerHeight||42):34,true)+(sample?line(sample,headerRow+1,5,layout.rowHeight||42):'')+(rows.length?rows:[headers.map(()=>'')]).map((values,index)=>line(values,start+index,layout.rowStyles?.[index]||0,layout.rowHeight||26)).join('');
 const merges=instructions.length?`<mergeCells count="${instructions.length}">${instructions.map((_,index)=>`<mergeCell ref="A${index+1}:${lastColumn}${index+1}"/>`).join('')}</mergeCells>`:'';
 const cols=headers.map((label,index)=>`<col min="${index+1}" max="${index+1}" width="${layout.widths?.[index]||Math.min(34,Math.max(14,label.length*2+4+(conditional[label]?12:0)))}" customWidth="1"/>`).join('');
 return {
  '[Content_Types].xml':`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>`,
  '_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',
  'xl/workbook.xml':`<workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="导入模板" sheetId="1" r:id="rId1"/></sheets></workbook>`,
  'xl/_rels/workbook.xml.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>',
  'xl/styles.xml':`<styleSheet xmlns="${ns}"><fonts count="3"><font><sz val="11"/><color rgb="FF304C70"/><name val="Microsoft YaHei"/></font><font><sz val="11"/><color rgb="FFFFFFFF"/><name val="Microsoft YaHei"/><b/></font><font><sz val="16"/><color rgb="FF1E3A5F"/><name val="Microsoft YaHei"/><b/></font></fonts><fills count="6"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill>${['FFF4F7FC','FF294D79','FFFFFCF3','FFDFEAF7'].map(color=>`<fill><patternFill patternType="solid"><fgColor rgb="${color}"/><bgColor indexed="64"/></patternFill></fill>`).join('')}</fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="11">${[[0,0],[0,2],[0,5],[0,0],[1,3],[0,4],[2,0],[0,2],[0,0],[0,5],[0,4]].map(([font,fill],index)=>`<xf numFmtId="${index>=8?4:49}" fontId="${font}" fillId="${fill}" borderId="0" xfId="0" applyNumberFormat="1" applyFill="1" applyFont="1"><alignment vertical="center" ${index>=8?'horizontal="right"':''} wrapText="1"/></xf>`).join('')}</cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`,
  'xl/worksheets/sheet1.xml':`<worksheet xmlns="${ns}"><sheetViews><sheetView workbookViewId="0"><pane ySplit="${headerRow}" ${layout.frozenColumns?`xSplit="${layout.frozenColumns}"`:""} topLeftCell="${uiTemplateColumn(layout.frozenColumns||0)}${headerRow+1}" activePane="${layout.frozenColumns?"bottomRight":"bottomLeft"}" state="frozen"/></sheetView></sheetViews><cols>${cols}</cols><sheetData>${data}</sheetData>${merges}</worksheet>`
 };
}
// 单表入口保持兼容，多表复用同一套单元格样式与填写说明布局。
function uiImportWorkbook(headers,rows,options={}){
 const sheets=options.sheets;if(!sheets)return uiTemplateZip(uiImportWorkbookParts(headers,rows,options));
 if(!sheets.length)throw Error('工作簿至少需要一个Sheet');
 const parts=uiImportWorkbookParts(headers,rows,options),ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main',names=new Set();
 delete parts['xl/worksheets/sheet1.xml'];
 for(const [index,sheet] of sheets.entries()){
  if(!sheet.name||sheet.name.length>31||/[\\/?*\[\]:]/.test(sheet.name)||names.has(sheet.name))throw Error('Sheet名称无效或重复');names.add(sheet.name);
  parts['xl/worksheets/sheet'+(index+1)+'.xml']=uiImportWorkbookParts(sheet.headers||headers,sheet.rows,{...options,...sheet,sheets:undefined})['xl/worksheets/sheet1.xml'];
 }
 parts['[Content_Types].xml']=parts['[Content_Types].xml'].replace(/<Override PartName="\/xl\/worksheets\/sheet1.xml"[^>]+\/>/,sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join(''));
 parts['xl/workbook.xml']=`<workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map((sheet,i)=>`<sheet name="${uiTemplateXml(sheet.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`;
 parts['xl/_rels/workbook.xml.rels']=`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId${sheets.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`;
 return uiTemplateZip(parts);
}
function downloadImportTemplate(headers,rows,name,options){
 const blob=uiImportWorkbook(headers,rows,options),url=URL.createObjectURL(blob),link=document.createElement('a');
 link.href=url;link.download=name+'.xlsx';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

// 导入边界统一日期和产品标识，内部日期键仍保持ISO。
function uiImportDate(value,label='日期'){
 const raw=String(value??'').trim();if(!/^\d{4}\/\d{2}\/\d{2}$/.test(raw))throw Error(label+'格式为YYYY/MM/DD');
 const iso=raw.replaceAll('/','-'),date=new Date(iso+'T00:00:00Z');
 if(!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==iso)throw Error(label+'不是有效日期');return iso;
}
function uiImportSpu(value){
 const code=String(value??'').trim();if(!code)throw Error('产品SPU码必填');
 const matches=sampleSpus.filter(product=>String(product.spuCode)===code);
 if(matches.length!==1)throw Error(matches.length?'SPU码对应多条档案，请核对产品档案':'SPU码不存在，请核对产品档案');return matches[0];
}
// 页长按列表保存；有 ID 的容器可重建，无 ID 的详情容器随抽屉快照保留。
const listPageSizes=new Map(),listAnonymousPageSizes=new WeakMap(),LIST_PAGE_SIZES=[10,20,50];
const listPageReuseHandlers=new Map();let listPageContext=null;
function listPageKey(key){
 const name=typeof key==='string'?key:key?.id||key||'';
 if(!name||typeof name!=='string'||!listPageContext)return name;
 const {scope,onPage}=listPageContext,scoped=scope+':'+name;
 listPageReuseHandlers.set(scoped,page=>onPage(page,name));return scoped;
}
function listWithPageScope(scope,onPage,render){
 const previous=listPageContext;listPageContext={scope,onPage};
 try{return render()}finally{listPageContext=previous}
}
function listPageSize(key,fallback=20){
 const initial=LIST_PAGE_SIZES.includes(fallback)?fallback:10;
 const name=listPageKey(key),store=typeof name==='object'?listAnonymousPageSizes:listPageSizes;
 return store.get(name)||initial;
}
function listSizeSelect(size){
 return '<select class="list-page-size" aria-label="每页条数">'+LIST_PAGE_SIZES.map(n=>'<option value="'+n+'" '+(n===size?'selected':'')+'>'+n+'条/页</option>').join('')+'</select>';
}
function listDelegatedPage(nav,page){
 const button=document.createElement('button');button.type='button';button.hidden=true;
 button.setAttribute(nav.dataset.listAttr,nav.dataset.listValue||((nav.dataset.listPrefix||'')+page));
 if(nav.dataset.listDelta)button.setAttribute(nav.dataset.listDelta,page-Number(nav.dataset.listCurrent));
 for(const [key,value] of Object.entries(JSON.parse(nav.dataset.listExtra||'{}')))button.setAttribute(key,value);
 nav.append(button);button.click();button.remove();
}
// 捕获阶段消费页长事件，避免它被业务筛选器的 change 委托误认为筛选条件。
document.addEventListener('change',e=>{
 const select=e.target;if(!select.matches('.list-pagination select.list-page-size'))return;
 e.stopPropagation();const nav=select.closest('.list-pagination'),size=Number(select.value);
 if(!LIST_PAGE_SIZES.includes(size))return;
 const key=nav.listSizeKey||nav.dataset.listSizeKey;if(!key)return;
 (typeof key==='object'?listAnonymousPageSizes:listPageSizes).set(key,size);
 const onPage=nav.listOnPage||listPageReuseHandlers.get(key);
 if(onPage)listNavigate(nav,1,onPage);
 else if(nav.dataset.listAttr)listNavigate(nav,1,page=>listDelegatedPage(nav,page));
},true);
const DRAWER_PAGE_SIZE=20;
function listPageNumbers(page,pages){
 const visible=new Set([1,pages,...Array.from({length:5},(_,i)=>page+i-2)].filter(n=>n>=1&&n<=pages));
 const result=[];for(const n of [...visible].sort((a,b)=>a-b)){const last=result.at(-1);if(typeof last==='number'&&n-last>1)result.push(n-last===2?last+1:'…');result.push(n)}return result;
}
function listPager(total,page,size=DRAWER_PAGE_SIZE,delegate={}){
 size=LIST_PAGE_SIZES.includes(size)?size:10;
 const pages=Math.max(1,Math.ceil(total/size));page=Math.max(1,Math.min(page,pages));
 const extra=Object.entries(delegate.extra||{}).map(([key,value])=>`${key}="${esc(String(value))}"`).join(' ');
 const attrs=n=>delegate.attr?`${delegate.attr}="${esc(String(delegate.value??((delegate.prefix||'')+n)))}" ${extra} ${delegate.delta?`${delegate.delta}="${n-page}"`:''}`:'';
 const button=(n,label,disabled=false,arrow=false)=>`<button type="button" class="list-page-button ${arrow?'list-page-arrow':''} ${!arrow&&n===page?'selected':''}" data-list-page="${n}" ${attrs(n)} ${disabled?'disabled':''} ${!arrow&&n===page?'aria-current="page"':''} aria-label="${arrow?(n<page?'上一页':'下一页'):'第'+n+'页'}">${label}</button>`;
 return `<nav class="list-pagination" aria-label="列表分页" data-list-size-key="${esc(listPageKey(delegate.sizeKey||''))}" data-list-total="${total}" data-list-current="${page}" data-list-pages="${pages}" data-list-size="${size}" data-list-prefix="${esc(delegate.prefix||'')}" data-list-attr="${delegate.attr||''}" data-list-value="${esc(String(delegate.value??''))}" data-list-delta="${delegate.delta||''}" data-list-extra="${esc(JSON.stringify(delegate.extra||{}))}"><span class="list-page-total">共 ${fmt(total)} 条</span>${listSizeSelect(size)}<div class="list-page-numbers">${button(page-1,'‹',page===1,true)}${listPageNumbers(page,pages).map(n=>n==='…'?'<span class="list-page-ellipsis">…</span>':button(n,n)).join('')}${button(page+1,'›',page===pages,true)}</div><label class="list-page-jump">前往<input type="number" min="1" max="${pages}" step="1" value="${page}" aria-label="跳转页码" inputmode="numeric">页</label></nav>`;
}
function listNavigate(nav,page,onPage){
 if(nav.dataset.listNavigating)return;nav.dataset.listNavigating='true';
 try{onPage(page)}finally{delete nav.dataset.listNavigating}
}
function listJump(nav,input,onPage){
 if(nav.dataset.listNavigating)return;
 const raw=input.value.trim(),n=Number(raw),current=Number(nav.dataset.listCurrent),pages=Number(nav.dataset.listPages);
 if(!raw||!Number.isInteger(n)){input.value=current;return}
 const page=Math.max(1,Math.min(n,pages));input.value=page;if(page!==current)listNavigate(nav,page,onPage);
}
function bindListPager(host,onPage,key=host){
 const nav=host.querySelector('.list-pagination');if(!nav)return;nav.dataset.listDirect='true';nav.listSizeKey=listPageKey(key);nav.listOnPage=onPage;
 if(typeof nav.listSizeKey==='string')nav.dataset.listSizeKey=nav.listSizeKey;
 nav.onclick=e=>{const b=e.target.closest('[data-list-page]');if(b&&!b.disabled){e.stopPropagation();const n=Number(b.dataset.listPage);if(n!==Number(nav.dataset.listCurrent))listNavigate(nav,n,onPage)}};
 const input=nav.querySelector('input');input.onchange=()=>listJump(nav,input,onPage);
 input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();e.stopPropagation();listJump(nav,input,onPage)}};
}
function mountListPager(host,total,page,onPage,key=host){host.innerHTML=listPager(total,page,listPageSize(key));bindListPager(host,onPage,key)}
// Delegated lists keep their existing page event contract; jumps dispatch once.
function listDelegatedJump(input){
 const nav=input.closest('.list-pagination');if(!nav||nav.dataset.listDirect||!nav.dataset.listAttr)return;
 listJump(nav,input,page=>listDelegatedPage(nav,page));
}
document.addEventListener('change',e=>{if(e.target.matches('.list-page-jump input'))listDelegatedJump(e.target)});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('.list-page-jump input')){e.preventDefault();listDelegatedJump(e.target)}});
// 项目详情由 project-detail/02.js 安装，保留共享闭包中的可变入口。
let projectDetail;

function draft(name,owner='对应链主'){openModal('工作项草稿',`<div class="detailgrid"><div class="detailitem wide"><small>工作内容</small>${esc(name)}</div><div class="detailitem"><small>建议责任人</small>${esc(owner)}</div><div class="detailitem"><small>状态</small><span class="tag orange">未下发</span></div></div><label for="drafttext" class="note">补充执行要求</label><textarea id="drafttext">核实当前问题、制定闭环计划，并记录责任人及完成时间。</textarea><div class="notice" style="margin-top:12px">本原型未连接任务系统。保存后仅生成本地草稿，不会通知责任人。</div>`);$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary small" id="savedraft">保存本地草稿</button>');$('#savedraft').onclick=()=>{try{const ds=JSON.parse(localStorage.getItem('pc-drafts')||'[]');ds.push({name,owner,content:$('#drafttext').value,date:new Date().toISOString()});localStorage.setItem('pc-drafts',JSON.stringify(ds));toast('草稿已保存到当前浏览器，尚未下发');closeModal()}catch{toast('浏览器未允许本地存储，未保存')}}}
function renderSales(){const all=[totalSales(),...sales()];$('#salescards').innerHTML=all.map((p,i)=>`<article class="salescard ${i===0?'company':''}"><h3>${p.name}<button class="link" data-sales="${i-1}" aria-label="查看${p.name}销售明细">↗</button></h3><div class="metriclabel" style="margin-top:12px">季度销售额</div><div class="amount num">${fmt(p.sale)}<span class="unit">万元</span></div><div class="salesrow"><span>季度规模达成率</span>${badge(p.sale/p.target*100)}</div><div class="track"><i style="width:${Math.min(p.sale/p.target*100,100)}%"></i></div><div class="salesrow"><span class="muted">SKU 总数</span><b class="num">${p.sku} 个</b></div><div class="salesrow"><span class="muted">季度利润率</span><b class="num">${fmt(p.profit,1)}%</b></div><div class="salesrow"><span class="muted">年度销售额差额</span><b class="num">${fmt(p.annual-p.ytd)}</b></div>${spark(i)}</article>`).join('');const s=sales(),max=Math.ceil(Math.max(...s.flatMap(p=>[p.sale,p.target]))/1000)*1000;$('#saleschart').innerHTML=`<svg viewBox="0 0 580 200" role="img" aria-label="四大链群季度销售额与目标比较">${[0,max/4,max/2,max*3/4,max].map(v=>`<line x1="48" y1="${165-v/max*140}" x2="568" y2="${165-v/max*140}" stroke="#edf0f6"/><text x="38" y="${169-v/max*140}" text-anchor="end">${v?fmt(v):0}</text>`).join('')}${s.map((p,i)=>{const x=100+i*128;return `<g class="chartclick" data-sales="${i}"><rect x="${x-15}" y="${165-p.target/max*140}" width="23" height="${p.target/max*140}" rx="3" fill="#e3e7fb"/><rect x="${x+13}" y="${165-p.sale/max*140}" width="23" height="${p.sale/max*140}" rx="3" fill="#7381fb"/><text x="${x+25}" y="${158-p.sale/max*140}" text-anchor="middle" style="fill:#6370da">${fmt(p.sale)}</text><text x="${x+8}" y="191" text-anchor="middle">${p.name}</text></g>`}).join('')}</svg>`;$('#attainchart').innerHTML=s.map(p=>{const r=p.sale/p.target*100;return `<div class="barrow"><span>${p.name}</span><div class="track"><i style="width:${Math.min(100,r)}%;background:var(--${status(r)})"></i></div><b class="${status(r)} num">${fmt(r,1)}%</b></div>`}).join('');$('#thresholdnote').textContent=brcBandText('attainment')}
function salesDetail(index,view='brand'){activeSales=index;salesView=view;const p=index<0?totalSales():sales()[index],labels=view==='brand'?brands:channels;const weights=labels.map((_,i)=>labels.length-i+3),ws=weights.reduce((a,b)=>a+b,0);const distribute=n=>{let a=weights.map(w=>Math.floor(n*w/ws));a[a.length-1]+=n-a.reduce((x,y)=>x+y,0);return a};const actual=distribute(p.sale),target=distribute(p.target),sku=distribute(p.sku),annual=distribute(p.annual-p.ytd);const rows=labels.map((l,i)=>[l,sku[i],fmt(actual[i]),fmt(target[i]),fmt(actual[i]/target[i]*100,1)+'%',fmt(p.profit,1)+'%',fmt(annual[i])]);openModal(p.name+' · 销售明细',`<div class="contextstrip"><div class="tabs"><button data-salesview="brand" class="${view==='brand'?'active':''}">分品牌</button><button data-salesview="channel" class="${view==='channel'?'active':''}">分渠道</button></div><span class="note">${periodLabel()} · 金额单位：万元 · 各维度合计与大盘一致</span></div><div class="tablewrap">${table([view==='brand'?'品牌':'销售渠道','SKU 总数','季度销售额','季度销售目标','季度规模达成率','季度利润率','年度销售额差额'],rows)}</div>`);}
function filteredProjects(){const chain=$('#projectchain').value,type=$('#projecttype').value;return projects().filter(p=>(chain==='全部'||p.chain===+chain)&&(type==='全部'||p.type===type))}
function renderProjects(){let list=filteredProjects(),tot=list.length,red=list.filter(p=>p.status==='红灯').length,yellow=list.filter(p=>p.status==='黄灯').length,green=tot-red-yellow,high=list.filter(p=>p.delay>config.delay).length;let s=[['项目总数量',tot,'all',''],['绿灯项目数',green,'绿灯','green'],['黄灯项目数',yellow,'黄灯','orange'],['红灯项目数',red,'红灯','red'],['高危红灯项目数',high,'high','red']];$('#projectstats').innerHTML=s.map(([l,n,id,c])=>`<button class="stat ${projectStatus===id?'selected':''}" data-status="${id}"><span>${c?`<i class="dot ${c}"></i>`:''}${l}</span><strong class="num ${c}">${n}<span class="unit">个</span></strong><small>${id==='all'?'覆盖 '+new Set(filteredProjects().map(p=>p.type)).size+' 类项目':id==='high'?'延期 > '+config.delay+' 天':'占当前项目 '+(tot?fmt(n/tot*100,1):'0')+'%'}</small></button>`).join('');$('#projectprogress').innerHTML=[['green',green],['orange',yellow],['red',red]].map(([c,n])=>`<span style="width:${tot?n/tot*100:0}%;background:var(--${c})"></span>`).join('');$('#projecttabs').innerHTML=[['all','全部项目'],['红灯','红灯项目'],['黄灯','黄灯项目'],['绿灯','绿灯项目']].map(([v,l])=>`<button data-status="${v}" class="${v===projectStatus?'active':''}">${l}</button>`).join('');const q=$('#projectsearch').value.trim();list=list.filter(p=>(projectStatus==='all'||(projectStatus==='high'?p.delay>config.delay:p.status===projectStatus))&&(!q||p.name.toLocaleLowerCase().includes(q.toLocaleLowerCase())));const pages=Math.max(1,Math.ceil(list.length/listPageSize('projectpages',10)));projectPage=Math.min(projectPage,pages);$('#projecttable').innerHTML=table(['产品 / 项目','项目类型','红绿灯状态','当前阶段','原计划量产','调整后计划量产','实际量产','计划调整','逾期天数','责任部门 / 项目经理','操作'],list.slice((projectPage-1)*listPageSize('projectpages',10),projectPage*listPageSize('projectpages',10)).map(p=>[titleProduct(p),esc(p.type),traffic(p.status),esc(p.stage),p.plan,p.revisedPlan||'—',esc(p.actual&&p.actual!=='—'?p.actual:'待补录'),p.plannedDelay===null?'—':p.plannedDelay===0?'未调整':`<span class="${p.plannedDelay>0?'orange':'green'}">${p.plannedDelay>0?'延后':'提前'} ${Math.abs(p.plannedDelay)} 天</span>`,p.delay?`<span class="red num">${p.delay} 天</span>`:'—',esc(p.dept)+'<small>'+esc(p.owner)+'</small>',`<button class="link" data-project="${p.id}">查看详情</button>`]));if(!list.length)$('#projecttable').innerHTML='<div class="empty">暂无匹配项目</div>';$('#projectcount').textContent='';$('#projectpages').innerHTML=listPager(list.length,projectPage,listPageSize('projectpages',10),{sizeKey:'projectpages',attr:'data-page'});$('#departments').innerHTML=depts.map(d=>{const all=filteredProjects().filter(p=>p.dept===d),r=all.filter(p=>p.status==='红灯'),h=r.filter(p=>p.delay>config.delay).length;return `<button class="dept" data-dept="${d}"><h3>${d} <span class="muted">›</span></h3><div class="depnum num">${r.length}<span class="unit">个红灯</span></div><small>高危 ${h} 个 · 占比 ${all.length?fmt(r.length/all.length*100,1):0}%</small><small>${r[0]?.cause||'暂无红灯卡点'}</small></button>`}).join('')}
const lifeNames=['自研上品计划','自选上品计划','自研立项规划','自选立项规划','产品迭代规划','品质整改规划','研发创新规划','产品下市规划'];
function newList(){let c=$('#newchain').value;return productRows(true).filter(p=>c==='全部'||p.chain===+c||pfCategory(p)===c)}
function renderNew(){const list=newList(),c=$('#newchain').value,{planned,ontime,sold}=newMetrics();const channelTotals=channels.map(ch=>list.filter(p=>p.channel===ch).reduce((a,p)=>a+p.sales,0)),max=Math.max(...channelTotals,1);$('#newtop').innerHTML=`<div class="newmetric"><span>新品销售成功率</span><strong class="num">${fmt(sold/planned*100,1)}<span class="unit">%</span></strong><small class="muted">按期上品且有销售 ${sold} / 计划 ${planned}</small>${spark(1)}</div><div class="newmetric"><span>新品上线及时率</span><strong class="num">${fmt(ontime/planned*100,1)}<span class="unit">%</span></strong><small class="muted">按期上线 ${ontime} / 计划 ${planned}</small>${spark(3)}</div><div class="donutwrap"><div class="donut" id="newdonut"><span class="num">${list.length}<small>新品样本</small></span></div><div class="donutleg">${['A','B','C','D'].map((g,i)=>`<div><i style="background:${['#5865f5','#9285fa','#6bc8f9','#fa803b'][i]}"></i>${g} 级　${list.filter(p=>p.grade===g).length}</div>`).join('')}</div></div><div><h3 style="margin-bottom:8px">各渠道新品季度销售额</h3><svg viewBox="0 0 290 110" role="img" aria-label="新品分渠道季度销售额，单位万元">${channelTotals.map((n,i)=>`<rect x="${i*35+10}" y="${85-n/max*65}" width="17" height="${n/max*65}" rx="2" fill="#93a0ff"/><text x="${i*35+18}" y="${79-n/max*65}" text-anchor="middle">${fmt(n)}</text><text x="${i*35+18}" y="104" text-anchor="middle">${channels[i]}</text>`).join('')}</svg></div>`;let start=0;const colors=['#5865f5','#9285fa','#6bc8f9','#fa803b'];$('#newdonut').style.background='conic-gradient('+['A','B','C','D'].map((g,i)=>{let end=start+list.filter(p=>p.grade===g).length/list.length*100;const s=colors[i]+' '+start+'% '+end+'%';start=end;return s}).join(',')+')';$('#newtable').innerHTML=table(['产品名称','上线天数','所属品类 / 渠道','季度销售额','单品利润率','总退货率','销售状态','产品等级','操作'],list.slice(0,5).map(p=>[titleProduct(p),p.days+' 天',chains[p.chain]+'<small>'+p.channel+'</small>',fmt(p.sales,1)+' 万',fmt(p.profit,1)+'%',fmt(p.returnRate,1)+'%',`<span class="tag ${p.state==='整改'?'orange':'green'}">${p.state}</span>`,`<span class="tag">${p.grade}</span>`,`<button class="link" data-product="new,${p.id}"><span class="ai-logo ai-logo--icon" aria-hidden="true"></span> AI 新品评估</button>`]));$('#newcount').textContent=`当前 ${list.length} 个新品样本 · 已展示 ${Math.min(5,list.length)} 条 · 新品等级为人工评级示例`}
function productDetail(isNew,id){const p=productRows(isNew).find(p=>p.id===+id),cat=category(p),strategies={A:'保障供货，推进迭代，扩充衍生产品矩阵。',B:'拆解采购成本与退货损耗，优先推动采购降本、品质改善及产品迭代。',C:'小范围测试渠道扩展与内容投放，结合需求验证追加备货。',D:'测算降本与迭代可行性，评估品牌调整、清仓及下市方案。',O:'处于中间观察区，持续跟踪动销及利润，不强行归入四类榜单。'};openModal((isNew?'新品评估':'老品经营策略')+' · '+p.name,`<div class="detailgrid">${[['型号',p.model],['所属品类',chains[p.chain]],['品牌 / 渠道',p.brand+' / '+p.channel],['上架时长',p.days+' 天'],[isNew?'季度销售额':'近30天销售额',fmt(p.sales,1)+' 万元'],['单品利润率',fmt(p.profit,1)+'%'],['总退货率',fmt(p.returnRate,1)+'%'],[isNew?'产品等级':'经营分层',isNew?p.grade:cat==='O'?'中间观察区':cat+' 类']].map(([a,b])=>`<div class="detailitem"><small>${a}</small>${b}</div>`).join('')}</div><h3>${isNew?'季度':'近30天'} GMV 趋势 · 演示分布（万元）</h3>${trend(p.sales,isNew?bounds():{start:shiftDate(bounds().cutoff,-29),cutoff:bounds().cutoff})}<div class="aitext"><h3>${isNew?'<span class="ai-logo ai-logo--icon" aria-hidden="true"></span> AI 新品经营建议':'标准化处置策略'}</h3><p>${isNew?(p.grade==='D'?'优先排查需求匹配、退货原因与渠道定位，验证优化方案后再扩大投入。':'结合当前渠道表现评估推广与供给，持续监测毛利和退货率，避免仅按销售额放大投放。'):strategies[cat]}</p><p class="source">证据来源：模拟销售、毛利与退货台账 · ${dateBack(0)}</p></div>`);$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary small" id="productdraft">生成工作草稿</button>');$('#productdraft').onclick=()=>draft(p.name+(cat==='B'?'降本评估':'经营优化'))}
function trend(total){let vals=[.07,.095,.085,.12,.105,.13,.145,.15,.1].map(n=>n*total),max=Math.max(...vals)*1.2;let pts=vals.map((v,i)=>`${50+i*63},${155-v/max*120}`).join(' ');return `<svg viewBox="0 0 590 195" role="img" aria-label="周期内分段销售额趋势，单位万元"><line x1="50" y1="155" x2="554" y2="155" stroke="#e8ecf5"/><text x="40" y="155" text-anchor="end">0</text><text x="40" y="35" text-anchor="end">${fmt(max,0)}</text><polyline points="${pts} 554,155 50,155" fill="#f0f3ff"/><polyline points="${pts}" fill="none" stroke="#7182fb" stroke-width="2.5"/>${vals.map((v,i)=>`<circle cx="${50+i*63}" cy="${155-v/max*120}" r="3" fill="#7182fb"><title>第${i+1}段：${pfMoneyYuan((v)*10000)}</title></circle>`).join('')}<text x="50" y="180">周期开始</text><text x="554" y="180" text-anchor="end">统计截止日</text></svg>`}
function renderMatrix(){let rows=productRows(false);let w=460,h=260,left=44,right=444,top=28,bottom=223,maxX=Math.max(140,config.high*1.4,...rows.map(p=>p.sales*1.1)),maxY=Math.max(26,config.profit*1.5,...rows.map(p=>p.profit*1.1));const x=v=>left+v/maxX*(right-left),y=v=>bottom-v/maxY*(bottom-top),low=x(config.low),high=x(config.high),mid=y(config.profit);$('#matrixchart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="老品销售利润矩阵：横轴近30天销售额万元，纵轴单品利润率百分比"><text x="44" y="15">单品利润率（%）</text><rect x="${left}" y="${top}" width="${low-left}" height="${mid-top}" fill="#f0f6ff"/><rect x="${left}" y="${mid}" width="${low-left}" height="${bottom-mid}" fill="#fff3f3"/><rect x="${low}" y="${top}" width="${high-low}" height="${bottom-top}" fill="#f6f7fa"/><rect x="${high}" y="${top}" width="${right-high}" height="${mid-top}" fill="rgba(0,154,41,0.08)"/><rect x="${high}" y="${mid}" width="${right-high}" height="${bottom-mid}" fill="var(--orange-soft)"/>${[config.low,config.high].map(v=>`<line x1="${x(v)}" x2="${x(v)}" y1="${top}" y2="${bottom}" stroke="#c7cedf" stroke-dasharray="4 4"/>`).join('')}<line x1="44" x2="444" y1="${mid}" y2="${mid}" stroke="#c7cedf" stroke-dasharray="4 4"/><text x="${left+8}" y="47">C</text><text x="${high+10}" y="47" style="fill:#009a29">A 高销高利</text><text x="${left+8}" y="${mid+19}">D</text><text x="${high+10}" y="${mid+19}" style="fill:var(--orange)">B 高销低利</text><text x="${(low+high)/2}" y="47" text-anchor="middle">观察区</text>${[0,config.low,config.high,maxX].map(v=>`<text x="${x(v)}" y="245" text-anchor="middle">${fmt(v)}</text>`).join('')}${[0,config.profit,maxY].map(v=>`<text x="35" y="${y(v)+4}" text-anchor="end">${fmt(v,1)}%</text>`).join('')}${rows.map(p=>`<circle class="chartclick" data-product="old,${p.id}" cx="${x(p.sales)}" cy="${y(p.profit)}" r="5" fill="${{A:'#009a29',B:'var(--orange)',C:'#718bf1',D:'#e2848d',O:'#afb6c8'}[category(p)]}" fill-opacity=".8"><title>${p.name}：${pfMoneyYuan((p.sales)*10000)} / 利润率${p.profit}%</title></circle>`).join('')}</svg>`;$('#matrixtabs').innerHTML=[['A','高销高利'],['B','高销低利'],['C','低销高利'],['D','低销低利']].map(([c,l])=>`<button class="${matrixTab===c?'active':''}" data-matrix="${c}">${c} ${l}</button>`).join('');const sorted=rows.filter(p=>category(p)===matrixTab).sort((a,b)=>b.sales-a.sales).slice(0,10);$('#matrixtable').innerHTML=table(['产品 / 品牌','近30天销售额','单品利润率','总退货率','操作'],sorted.map(p=>[titleProduct(p),fmt(p.sales,1)+' 万',`<span class="${p.profit<config.profit?'orange':'green'}">${fmt(p.profit,1)}%</span>`,fmt(p.returnRate,1)+'%',`<button class="link" data-product="old,${p.id}">AI 策略</button>`]));}
function renderSuppliers(){$('#suppliergrid').innerHTML=supplierData().map((p,i)=>`<article class="supplierpanel"><div class="charthead"><h3><span class="tier">TIER ${i+1}</span>${p.tier}供应商管控</h3><span class="note">${i?'备选与外协补充':'核心主力供货'}</span></div><div class="suppliernums"><button data-supplier="${i},reserve"><span class="muted">${p.tier}储备供应商总数</span><strong class="num">${p.reserve}<span class="unit">家</span></strong></button><button data-supplier="${i},active"><span class="muted">${p.tier}合作供应商总数</span><strong class="num">${p.active}<span class="unit">家</span></strong></button></div><div class="supplierprogress ${periodFor().mode==='year'?'single-period':''}"><div><div class="inline"><span>本季度新增</span>${badge(p.q/p.qt*100)}</div><div class="track"><i style="width:${p.q/p.qt*100}%"></i></div><div class="inline muted"><span>实际 ${p.q} 家</span><span>目标 ${p.qt} 家</span></div></div><div ${periodFor().mode==='year'?'hidden':''}><div class="inline"><span>本年度累计新增</span>${badge(p.y/p.yt*100)}</div><div class="track"><i style="width:${p.y/p.yt*100}%"></i></div><div class="inline muted"><span>实际 ${p.y} 家</span><span>目标 ${p.yt} 家</span></div></div></div></article>`).join('')}
function suppliersDetail(tier,kind){let n=supplierData()[tier][kind==='reserve'?'reserve':'active'],type=kind==='reserve'?'储备':'合作';const rows=Array.from({length:n},(_,i)=>[`${['华新','恒拓','盛川','瑞能','森源','科泰'][i%6]}${['智造','精密','电器','科技'][Math.floor(i/6)%4]} ${String(i+1).padStart(2,'0')}（示例）`,chains[i%4],type,'有效',dateBack(160+i),kind==='reserve'?'—':dateBack(120+i)]);openModal((tier?'物料供应商':'整机供应商')+' · '+type,`<div class="notice">供应商名称为虚构示例，共 ${n} 家。</div><div class="tablewrap">${table(['供应商名称','所属供应链群','类型','资质状态','入库时间','合作起始时间'],rows)}</div>`);}
function costDetail(i){let p=costs()[i],a=Math.round(p.a*.6),t=Math.round(p.t*.6);let rows=[['核心物料成本优化','采购',t,a,people[i],'推进中'],['工艺与包装改善','工艺 / 包装',p.t-t,p.a-a,people[i+1],'推进中']];openModal(p.name+' · 降本项目明细',`<p class="note" style="margin-bottom:15px">金额单位：万元 · 实际降本仅计入财务已确认金额</p><div class="tablewrap">${table(['降本项目名称','降本类型','计划降本金额','实际降本金额','责任人','状态'],rows)}</div>`);}
function showRules(){openModal('指标口径与演示阈值',`<div class="notice">可调整参数仅作用于本地原型。正式系统应由后台配置，并经过业务负责人确认。</div><div class="configgrid">${[['green','完成率绿灯阈值（%）'],['yellow','完成率黄灯下限（%）'],['high','老品销售额分界（万元）'],['profit','老品利润率分界（%）'],['delay','高危延期阈值（天）']].map(([k,l])=>`<label>${l}<input data-config="${k}" type="number" min="0" value="${config[k]}" required></label>`).join('')}</div><div style="margin-top:22px">${table(['指标','采用口径'],[['月／季／年规模达成率','所选周期销售额 ÷ 完整周期销售目标；红黄绿只绑定完成率，未结束周期显示数据截止日。'],['季度利润率','整体毛利 ÷ 整体销售额；公司层按销售额加权。'],['年度销售额差额','年度目标 − 年度累计销售额；正数为剩余缺口，负数为超额。文档正负号描述有冲突，本原型采用该公式。'],['延迟天数','未上线：快照日 − 计划上线日，最小为 0；已上线：实际上线日 − 计划上线日，最小为 0。'],['退货率环比增长率','（本期退货率 − 上期退货率）÷ 上期退货率；>5% 为相对增幅，与两个退货率直接相减不同。'],['新老品边界','上架≤120天且有销售为新品；>120天进入老品，避免第120天重复。'],['老品分层边界','销售额达到分界归为高销，低于分界归为低销；利润率达到分界归为高利，低于分界归为低利。A 高销高利、B 高销低利、C 低销高利、D 低销低利；阈值可调。'],['新品 ABCD 等级','按在售期间月均销售与品链群标、利润率与目标利润率分为 ABCD：两项达标为 A，仅销售达标为 B，仅利润达标为 C，两项未达标为 D；等于目标视为达标。总看板与产品部共用评级配置。'],['渠道维度','统一使用抖音、快手、视频号、天猫、京东、拼多多六个平台。'],['库存周转率','周期销售成本 ÷ 周期平均库存金额，单位随月／季／年切换；不将各期或各链群比率直接相加。'],['降本数据差额','实际 − 目标；负数为缺口，仅统计财务确认的成本节约。'],['演示范围','只设计总看板；筛选、抽屉及本地草稿可操作。未接入权限、业务数据、通知或真实AI服务。']])}</div>`);$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary small" id="saveconfig">应用演示阈值</button>');$('#saveconfig').onclick=()=>{const next={...config};for(const input of $$('[data-config]')){if(input.value.trim()===''){toast('请完整填写阈值');return}next[input.dataset.config]=Number(input.value)}if(Object.values(next).some(n=>!Number.isFinite(n)||n<0)||next.yellow>=next.green||next.high===0||next.green===0){toast('请确保完成率黄灯下限小于绿灯阈值，销售额分界大于 0');return}Object.assign(config,next);renderAll();closeModal();toast('已更新本地演示阈值')}}
// 全局日期统一取北京时间；每次加载按当天建立近30天默认范围。
const dashboardDateFormatter=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'});
function dashboardToday(){return dashboardDateFormatter.format(new Date())}
let DATA_CUTOFF=dashboardToday();
// 日历每次打开或应用快捷项都刷新，常驻页面跨午夜也不沿用昨天。
function dashboardSyncDate(){return DATA_CUTOFF=dashboardToday()}
function dashboardYears(ahead=0,selected=+dashboardToday().slice(0,4)){const first=Math.min(2025,selected),last=Math.max(+dashboardToday().slice(0,4)+ahead,selected);return Array.from({length:last-first+1},(_,i)=>first+i)}
