// 截至数据截止日的本月GSV（万元），覆盖多主营、单主营及未达标场景。
const sampleShopCoreDemoGsv={'306131028':950,'154894317':260,'446362993':180,'1000508586':85};
function sampleShopDemoMetrics(shop){
 const gsv=sampleShopCoreDemoGsv[shop.shopId];
 return gsv?{referenceGsv:gsv,demoSalesScale:gsv/shop.referenceGsv,source:'demo'}:{};
}
function sampleShopProducts(shop){
 const brandProducts=[...sampleSpus,...sampleShopDemoSpus].filter(p=>p.brand===shop.brand);
 const categoryProducts=brandProducts.filter(p=>p.chain===shop.chain);
 return categoryProducts.length?categoryProducts:brandProducts;
}
// 日销量和退货整数分摊至SPU，店铺净销量和SPU金额分摊共用这些明细。
function sampleShopDailySales(shop,date){
 return date>DATA_CUTOFF?0:Math.round((35+shop.id*4)*(shop.demoSalesScale||1)*riskDailyWeight(date,shop.id));
}
function sampleShopSpuSales(shop,start,end){
 const products=sampleShopProducts(shop);
 if(!products.length)return [];
 const rows=products.map(product=>({product,sales:0,returned:0,source:'demo'}));
 for(let date=start;date<=end&&date<=DATA_CUTOFF;date=shiftDate(date,1)){
  const day=Math.floor(Date.parse(date)/86400000),sales=sampleShopDailySales(shop,date);
  const weights=products.map((p,i)=>1+((shop.id*7+i*11)%9)+8*(1+Math.sin(day*.19+i*1.7+shop.id)));
  const total=weights.reduce((sum,n)=>sum+n,0);const returned=Math.round(sales*.095);let cumulative=0,allocated=0,returnedAllocated=0;
  rows.forEach((row,i)=>{
   cumulative+=weights[i];const next=i===rows.length-1?sales:Math.floor(sales*cumulative/total);
   const nextReturned=sales?Math.floor(returned*next/sales):0;
   row.sales+=next-allocated;row.returned+=nextReturned-returnedAllocated;
   allocated=next;returnedAllocated=nextReturned;
  });
 }
 return rows;
}
// 样例经营指标与SPU身份分离；每个产品视图按SPU唯一ID生成一条记录。
function sampleProductRows(isNew){
  return sampleSpus.filter(p=>!isNew||p.cohort==='new').map((p,i)=>{
    const mode=i%5,sale=isNew?26+i*6.4:mode===0?128-i:mode===1?96-i/2:mode===2?18-i/10:mode===3?12-i/10:35+i/2;
    const profit=isNew?8+i%12:mode===0?14.3+i%3:mode===1?7.2+i%2:mode===2?18+i%3:mode===3?6+i%3:11+i%4;
    const days=isNew?22+i%24*4:142+i*9,elapsed=Math.max(0,(Date.parse(bounds().cutoff)-Date.parse(bounds().start))/86400000+1);
    return {id:10000+p.sourceRow,...sampleSpuFields(p),channel:channels[i%channels.length],
      sales:Math.round(sale*snapshotFactor()*(isNew?Math.min(days,elapsed)/75:1)*10)/10,
      profit,returnRate:3.2+i%8*.55,days,grade:['A','B','A','C','D'][i%5],state:i%7===0?'整改':'在售'};
  });
}
function sampleQualityCatalog(){return sampleSpus.map((p,i)=>{
  const metric=+(Math.max(3,18.2-i*.2)*snapshotFactor()).toFixed(1);
  return {id:10000+p.sourceRow,...sampleSpuFields(p),channel:channels[i%channels.length],owner:people[i%people.length],
    metric,value:metric+'%',desc:i===0?'平台处罚 · 一票置顶':'高退货 / 差评'};
})}


