// 月度事实以品链为主；平台仅用于演示下钻分配，数量使用整数守恒分配。
function lifeChainMonthFacts(stage,month,p=periodFor()){
 const facts=lifecycleMonthlyFacts[p.year]||lifecycleMonthlyFacts[2024],future=`${p.year}-${String(month).padStart(2,'0')}-01`>lifecycleFactCutoff;
 return facts[stage][month-1].map(([target,actual])=>({target,actual:future?0:actual}));
}
function lifePlatformChainMonth(stage,platform,month,p=periodFor()){
 return lifeChainMonthFacts(stage,month,p).map((row,chain)=>{
  const weights=channels.map((_,i)=>channels.length-i+3+(stage+chain+i)%3);
  return {target:splitTarget(row.target,weights)[platform],actual:splitTarget(row.actual,weights)[platform]};
 });
}
function lifeChannelMonth(stage,channel,month,p=periodFor()){
 const rows=lifePlatformChainMonth(stage,channel,month,p);return{target:targetSum(rows.map(row=>row.target)),actual:targetSum(rows.map(row=>row.actual))};
}


// 期间汇总共读按品链月度事实；不保留旧八渠道的计划、完成率或拆分规则。
lifeMonth=function(stage,month,p=periodFor()){const items=channels.map((_,channel)=>lifeChannelMonth(stage,channel,month,p));return{target:targetSum(items.map(x=>x.target)),actual:targetSum(items.map(x=>x.actual))}};
function lifeChannelRows(stage,p=periodFor()){
 const b=bounds(p),actualMonths=months(p),yearMonths=months(p,true);
 return channels.map((name,c)=>({name,target:targetSum(Array.from({length:b.last-b.first+1},(_,i)=>lifeChannelMonth(stage,c,b.first+i,p).target)),actual:targetSum(actualMonths.map(m=>lifeChannelMonth(stage,c,m,p).actual)),yearTarget:targetSum(Array.from({length:12},(_,i)=>lifeChannelMonth(stage,c,i+1,p).target)),yearActual:targetSum(yearMonths.map(m=>lifeChannelMonth(stage,c,m,p).actual))}));
}
function lifeSumRows(rows,name='公司整体'){return{name,...Object.fromEntries(['target','actual','yearTarget','yearActual'].map(k=>[k,targetSum(rows.map(r=>r[k]))]))}}
lifeData=function(stage){return ltDashboardActive()?ltSelectedTotals(stage):lifeSumRows(lifeChannelRows(stage))};
function lifeChainRows(stage,p=periodFor()){return ltDashboardActive()?ltDashboardRows(stage,p):lifeBaseChainRows(stage,p)}
function lifeBaseChainRows(stage,p=periodFor()){
 const b=bounds(p),actualMonths=new Set(months(p)),yearMonths=new Set(months(p,true)),rows=chains.map(name=>({name,target:0,actual:0,yearTarget:0,yearActual:0}));
 for(let month=1;month<=12;month++){
  const facts=lifeChainMonthFacts(stage,month,p);
  rows.forEach((row,i)=>{const fact=facts[i];row.yearTarget+=fact.target;if(month>=b.first&&month<=b.last)row.target+=fact.target;if(actualMonths.has(month))row.actual+=fact.actual;if(yearMonths.has(month))row.yearActual+=fact.actual});
 }return rows;
}
// 年度累计以当前所选期间截止日为准，不能直接使用今天或全年视图的截止日。
function lifeAchievement(actual,target,annual=false){
 const b=bounds(),year=periodFor().year,start=annual?`${year}-01-01`:b.start,end=annual?`${year}-12-31`:b.end;
 const days=aiFlowDayDiff(start,end)+1,elapsed=Math.max(0,Math.min(days,aiFlowDayDiff(start,b.cutoff)+1));
 const progress=elapsed/days*100,rate=target>0?msAchievementRatio(actual,target):null;
 const deviation=rate===null?null:rate-progress,tone=elapsed?msTone(deviation):'muted';
 return {rate,progress,deviation,tone,started:elapsed>0};
}
function lifeAchievementCell(actual,target,annual=false){
 const f=lifeAchievement(actual,target,annual);
 return `<span class="tag ${f.tone} ${f.tone==='green'?'number-signal-plain':numberSignalClass(f.tone)}">${msPercent(f.rate)}</span>`;
}
function lifeAchievementCards(){
 if(ltDashboardActive())return ltMainCards();
 $$('#lifecards .lifecard').forEach((card,index)=>{
  const d=lifeData(index),f=lifeAchievement(d.actual,d.target),value=card.querySelector('strong'),track=card.querySelector('.track');
  value.className='num '+f.tone;value.innerHTML=f.rate===null?'--':`${fmt(f.rate,1)}<span class="unit">%</span>`;
  track.classList.add('life-achievement-track');
  track.innerHTML=`<i style="width:${f.rate??0}%;background:var(--${f.tone})"></i><b style="left:${f.progress}%" aria-hidden="true"></b>`;
  const counts=card.querySelector('p'),delta=d.actual-d.target;
  counts.classList.add('life-count-row');
  counts.innerHTML=`<span>${word()} ${fmt(d.actual)} / ${fmt(d.target)}</span><span class="life-count-gap">差额 ${delta>0?'+':''}${fmt(delta)}</span>`;
  if(periodFor().mode==='year')card.querySelector('p:last-child').textContent=`年度累计 ${fmt(d.yearActual)} / ${fmt(d.yearTarget)}`;
 });
}
const renderLifeBeforeDemo=renderLife;
renderLife=function(){ltRenderChainTabs();const combined=!$('#lifecycle').hidden;$('#lifetabs').style.display=combined?'none':'';if(combined)lifeView='chain';renderLifeBeforeDemo();withPeriod('lifecycle',()=>{
 const annual=periodFor().mode==='year',channelRows=lifeChannelRows(lifeIndex),summary=combined?lifeData(lifeIndex):lifeSumRows(channelRows),rows=lifeView==='summary'?[summary]:lifeView==='chain'?lifeChainRows(lifeIndex).filter((_,index)=>!combined||ltChainMatches(index)):channelRows;
 lifeAchievementCards();
 const headers=[combined?'链群':'业务维度',word()+'目标（项）',word()+'实际完成（项）',word()+'完成率',...(combined?[]:[word()+'数据差额（项）']),...(annual?[]:['年度目标（项）','年度累计完成（项）','年度完成率'])];
 function cells(r){if(combined)return ltMainCells(r,annual);const delta=r.actual-r.target;return[esc(r.name),fmt(r.target),fmt(r.actual),lifeAchievementCell(r.actual,r.target),`<span class="num ${delta>0?'green':delta<0?'orange':'muted'}">${delta>0?'+':''}${delta}</span>`,...(annual?[]:[fmt(r.yearTarget),fmt(r.yearActual),lifeAchievementCell(r.yearActual,r.yearTarget,true)])]}
 // 汇总固定在分类明细之前，与明细共用统计数据和下钻入口。
 let content=table(headers,rows.map(cells));
 if(combined&&ltChainScope()==='all'){
  const summaryRow=`<tr class="life-summary-row" data-life-summary>${cells({...summary,name:'汇总'}).map(v=>`<td>${v}</td>`).join('')}</tr>`;
  content=content.replace('<tbody>','<tbody>'+summaryRow);
 }else if(!combined&&lifeView!=='summary')content=content.replace('</table>',`<tfoot><tr>${cells({...summary,name:'合计'}).map(v=>`<td>${v}</td>`).join('')}</tr></tfoot></table>`);
 $('#lifetable').innerHTML=content;
 });};
window.dashboardLifecycleSnapshot=()=>withPeriod('lifecycle',()=>({period:{...periodFor()},stage:lifeIndex,view:lifeView,chainFilter:ltChainScope(),filteredChains:lifeChainRows(lifeIndex).filter((_,index)=>ltChainMatches(index)),summary:lifeData(lifeIndex),channels:lifeChannelRows(lifeIndex),chains:lifeChainRows(lifeIndex)}));
