productRows=function(isNew){return dpOriginalProducts(isNew).map(r=>({...r,grade:isNew?dpNewGrade(r):r.grade,state:dpStore.productStates[periodFor().year+':'+(isNew?'new':'matrix')+':'+(r.spuId||r.model)]?.state||r.state}))};
function dpProjects(){return projects().filter(dpInScope)}
function dpSalesCells(){return salesCrossData().flatMap((row,c)=>row.map((r,b)=>({...r,chain:c,brandIndex:b}))).filter(dpInScope)}
function dpSalesRows(dim='chain',brand='all'){
 const cells=dpSalesCells().filter(r=>pfIncludes(brand,r.brandIndex));
 if(dim==='channel'){
  return salesChannelData(sumSalesCells(cells,'当前范围'),cells).map((row,index)=>({...row,index}));
 }
 const labels=dim==='brand'?brands:chains;
 return labels.map((name,index)=>{const records=cells.filter(r=>dim==='brand'?r.brandIndex===index:r.chain===index);return{...sumSalesCells(records,name),index}}).filter(r=>dim==='brand'?(pfIncludes(brand,r.index)):(dpState.chain==='all'||r.index===+dpState.chain));
}
function dpLifeRows(stage,p=periodFor()){
 return lifeChainRows(stage,p).map((r,i)=>({...r,chain:i})).filter(dpInScope);
}
function dpLifeChannels(stage,p=periodFor()){
 const rows=dpChannelNames.map((name,index)=>({name,index,target:0,actual:0,yearTarget:0,yearActual:0})),b=bounds(p),ms=new Set(months(p)),ys=new Set(months(p,true));
 for(let month=1;month<=12;month++)for(let platform=0;platform<channels.length;platform++){
  const facts=lifePlatformChainMonth(stage,platform,month,p).filter((_,chain)=>dpState.chain==='all'||chain===+dpState.chain),row=rows[platform];
  const target=targetSum(facts.map(fact=>fact.target)),actual=targetSum(facts.map(fact=>fact.actual));
  row.yearTarget+=target;if(month>=b.first&&month<=b.last)row.target+=target;if(ms.has(month))row.actual+=actual;if(ys.has(month))row.yearActual+=actual;
 }
 return rows;
}
function dpLifeRecords(stage,scope,p,channel='all',chain='all'){
 return lifecycleCompletionProducts(stage,scope,p).filter(row=>dpInScope(row)&&(chain==='all'||row.chain===+chain)&&(channel==='all'||row.channel===+channel));
}
function dpDocuments(p=periodFor()){
 const rows=[];for(const month of months(p))for(let person=0;person<people.length;person++)for(let type=0;type<8;type++){
  const end=Math.min(new Date(Date.UTC(p.year,month,0)).getUTCDate(),month===+bounds(p).cutoff.slice(5,7)?+bounds(p).cutoff.slice(8):31),slots=type===0?Array.from({length:end},(_,i)=>i+1).filter(d=>![0,6].includes(new Date(Date.UTC(p.year,month-1,d)).getUTCDay())):type===1?[5,12,19,26].filter(d=>d<=end):[Math.min(end,10+type)];
  for(const day of slots){const date=`${p.year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`,seed=person*7+month*3+day+type*2,state=seed%17===0?'缺交':seed%11===0?'迟交':'按期提交',complete=state!=='缺交'&&seed%13!==0,approved=complete&&seed%9!==0;rows.push({id:`DOC-${p.year}-${month}-${type}-${person}-${day}`,type,chain:person%4,person,owner:people[person],date,state,complete,approved,title:dpDocNames[type]+' · '+names[person%4][type%6],issue:state==='缺交'?'应交文档缺失':!complete?'关键结论与附件不完整':!approved?'验收记录待补齐':state==='迟交'?'提交晚于约定时间':'无偏差'})}
 }return rows.filter(dpInScope).map(r=>{const closed=dpClosed('process:'+r.id,p);return closed?{...r,originalIssue:r.issue,originalComplete:r.complete,complete:true,approved:true,issue:'无偏差',verifiedTask:closed.id}:r}).sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id));
}
function dpDeviations(){return dpDocuments().filter(r=>r.issue!=='无偏差'||r.originalIssue).map(r=>({key:'process:'+r.id,name:r.title,model:r.id,chain:r.chain,owner:r.owner,type:r.state==='缺交'?'文档缺失':!(r.originalComplete??r.complete)?'资料不完整':!(r.verifiedTask?false:r.approved)?'闭环待验证':'交付延误',cause:r.originalIssue||r.issue,level:!r.approved&&r.complete?'高危':'中风险',metric:r.verifiedTask?'已验收':r.state==='缺交'?'缺交':!r.complete?'缺资料':!r.approved?'待核验':'迟交',dept:dpDepartmentName(),date:r.date,doc:r,kind:'process'}))}
function dpProjectSource(p){return{key:'project:'+periodFor().year+':'+(p.sourceKey||p.model),kind:'project',id:p.id,name:p.name,model:p.model,chain:p.chain,owner:p.owner,dept:p.dept,cause:p.cause,stage:p.stage,level:p.status==='红灯'?'高危':'中风险',metric:p.delay?p.delay+' 天':p.status,date:p.plan,project:p}}
function dpRiskLists(includeClosed=false){
 const ps=dpProjects().filter(p=>p.status!=='绿灯'),project=ps.filter(p=>p.status==='红灯').sort((a,b)=>b.delay-a.delay).map(dpProjectSource),quality=riskRows(0).filter(dpInScope).map(r=>({...r,key:'quality:'+periodFor().year+':'+(r.spuId||r.model),kind:'quality',level:'高危',cause:r.desc,metric:r.value,dept:'品质部',date:bounds().cutoff}));
 const channel=dpSalesRows('channel').filter(r=>r.target&&r.sale/r.target<.9).map(r=>({key:'channel:'+periodKey()+':'+dpState.chain+':'+r.index,kind:'channel',name:r.name+'销售偏差',model:'CH-'+r.index,chain:dpState.chain==='all'?0:+dpState.chain,owner:dpState.chain==='all'?'林悦':aiOwners[+dpState.chain],dept:dpDepartmentName(),level:r.sale/r.target<.8?'高危':'中风险',cause:'销售达成 '+dpPct(r.sale,r.target)+'，请核对产品供给、渠道转化与投放效率。',metric:fmt((r.sale/r.target-1)*100,1)+'%',sale:r,date:bounds().cutoff}));
 const list=[ps.filter(p=>p.type.includes('上品')).sort((a,b)=>b.delay-a.delay).map(dpProjectSource),ps.filter(p=>p.type.includes('立项')).sort((a,b)=>b.delay-a.delay).map(dpProjectSource),project,quality,channel,dpDeviations().sort((a,b)=>(b.level==='高危')-(a.level==='高危'))];
 return list.map(rows=>includeClosed?rows:rows.filter(r=>!dpClosed(r)));
}
function dpUniqueRisks(){return [...new Map(dpRiskLists().flat().map(r=>[r.key,r])).values()]}
function dpScoreRows(){
 const docs=dpDocuments(),salesRows=dpSalesRows(),rows=people.map((name,i)=>{const chain=i%4;if(dpState.chain!=='all'&&chain!==+dpState.chain)return null;const personal=docs.filter(r=>r.person===i),salesRow=salesRows.find(r=>r.index===chain),life=lifeSumRows([0,1,2,3].flatMap(s=>dpLifeRows(s).filter(r=>r.chain===chain))),rate=salesRate(salesRow),newRows=productRows(true).filter(r=>r.chain===chain),own=dpProjects().filter(r=>r.owner===name),falseClose=personal.some(r=>r.type===2&&r.complete&&!r.approved),factors=[rate<80?0:Math.min(rate/100,1),(()=>{const n=dpNewMetrics(String(chain));return n.planned?n.sold/n.planned:0})(),life.target?Math.min(1,life.actual/life.target):0,Math.min(1,salesRow.profit/dpStore.marginTarget),personal.length?personal.reduce((n,r)=>n+(r.state==='按期提交'?1:r.state==='迟交'?.5:0),0)/personal.length:0,falseClose?0:own.length?own.filter(r=>r.status==='绿灯').length/own.length:1,Math.max(0,1-personal.filter(r=>!r.complete).length*.02),personal.length?personal.filter(r=>r.complete).length/personal.length:0];const scores=factors.map((f,j)=>Math.max(0,f*dpStore.weights[j])),override=dpStore.overrides[periodKey()+':'+name],result=dpSum(scores.slice(0,4).map(v=>({v})),'v'),process=dpSum(scores.slice(4).map(v=>({v})),'v');return{name,chain,role:i<4?'品类链主':'产品专员',factors,scores,result,process,total:override?.score??result+process,override,docs:personal,issues:personal.filter(r=>r.issue!=='无偏差').length}}).filter(Boolean).sort((a,b)=>b.total-a.total);
 return rows.map((r,i)=>({...r,improve:i>=Math.floor(rows.length*.8)}));
}
function dpPlan(source){
 const kind=source.kind;
 return kind==='project'?`1. ${source.dept}复核「${source.stage}」卡点：${source.cause}，形成问题清单及影响范围。\n2. ${source.owner}牵头确认修复方案、所需资源、交付物和节点日期；跨部门资源由对应部门负责人确认。\n3. 同步更新项目台账及后续依赖排期，按日跟进风险变化。\n4. 提交测试报告、评审结论和节点放行记录，由${dpDepartmentName()}负责人验证后解除卡点。`:kind==='quality'?`1. 核对退货与差评订单，按型号、批次、渠道分析原因，必要时暂停异常批次。\n2. 品质部与链主复现问题，输出纠正措施、测试计划和受影响库存清单。\n3. 小批量验证后再扩大修复，跟踪退货率及问题复发情况。\n4. 提交复测报告、整改前后对比、验收结论，验证通过后解除风险。`:kind==='channel'?`1. 分解渠道销售目标差额，核对价格、流量、转化、供货四类原因。\n2. 对照立项及上品计划确定供给缺口，负责人确认资源与上线排期。\n3. 小范围试行内容、组合销售或定价优化，控制预算并每日跟踪。\n4. 提交前后对比与复盘；任务验收后继续跟踪实际销售达成，不直接改写经营数据。`:kind==='process'?`1. 补齐「${source.name}」的缺失内容：${source.cause}。\n2. 责任人提交原始交付物、文档版本和对应项目关联。\n3. 复核完成条件及审阅记录，未验证的问题保持待办。\n4. 由${dpDepartmentName()}负责人验收并留存依据，纳入人员过程评分复盘。`:`1. 确认${source.name}的${source.cause||'经营改善'}问题与现状。\n2. 与品类链主确认可执行方案、责任人、交付时间及资源边界。\n3. 跟进策略试点效果并提交交付物和量化对比。\n4. 由独立验收人复核效果，未达标退回整改；经营指标仍以业务台账为准。`;
}
function dpTaskFor(source){return dpStore.tasks.find(t=>dpSameSource(t.source,source)&&t.state!=='已验收')}

function dpDispatch(source){
 const existing=dpTaskFor(source);if(existing){dpTaskDetail(existing.id);return}
 const period={...(source.period||periodFor())},date=bounds(period).cutoff;
 openModal('下发工作任务 · '+source.name,`<div class="dp-callout"><b>来源已关联</b> · ${esc(source.model||source.key)}<br>${esc(source.cause||'按经营建议执行')}<br>验收结果将回写来源风险，可在对应记录中跟进处理。</div><form class="dp-form" id="dp-dispatch-form"><label>责任人员<select name="owner" required>${people.map(n=>`<option ${n===source.owner?'selected':''}>${n}</option>`).join('')}</select></label><label>验收人员<select name="verifier" required><option>${dpDepartmentName()}负责人</option>${people.map(n=>`<option>${n}</option>`).join('')}</select></label><label>预计完成日期<input name="due" type="date" required min="${date}" value="${shiftDate(date,7)}"></label><label>优先级<select name="priority"><option ${source.level==='高危'?'selected':''}>P0</option><option ${source.level!=='高危'?'selected':''}>P1</option><option>P2</option></select></label><label class="full">处理方案（可编辑）<textarea name="plan" required minlength="15">${esc(dpPlan(source))}</textarea></label><label class="full">验收标准<textarea name="criteria" required minlength="10">交付物完整可复核，问题整改验证通过，相关依赖已确认；提供整改前后数据或节点放行记录。</textarea></label><label class="dp-check full"><input name="notify" type="checkbox" checked>生成钉钉通知内容（本地演示，提交后可复制给责任人）</label><p class="red full" id="dp-form-error" role="alert"></p></form>`,false,'责任人、期限、方案、验收标准一并下发');
 $('#dialogactions').innerHTML='<button class="btn" id="dp-cancel">取消</button><button class="btn primary" type="submit" form="dp-dispatch-form">确认下发</button>';$('#dp-cancel').onclick=closeModal;
 $('#dp-dispatch-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),owner=f.get('owner'),verifier=f.get('verifier');if(owner===verifier){$('#dp-form-error').textContent='执行人与验收人需为不同人员。';return}const id='DBS-'+Date.now().toString(36).toUpperCase(),audit=dpAudit('下发任务',id,'指派 '+owner+'；完成期限 '+f.get('due')),task={id,source:JSON.parse(JSON.stringify(source)),period,state:'待执行',owner,verifier,due:f.get('due'),priority:f.get('priority'),plan:f.get('plan').trim(),criteria:f.get('criteria').trim(),notify:f.has('notify')?'待复制通知':'不通知',createdDate:date,createdAt:audit.at,logs:[audit],evidence:'',closedDate:''};const next={...dpStore,tasks:[task,...dpStore.tasks],audit:[audit,...dpStore.audit]};if(dpSave(next)){renderDepartment();toast('任务已下发，可在来源记录中跟进');dpTaskDetail(id)}};
}
function dpTaskDetail(id){
 const t=dpStore.tasks.find(t=>t.id===id);if(!t)return;
 const steps=['待执行','执行中','待验收','已验收'],idx=steps.indexOf(t.state);
 openModal('DBS 任务 · '+t.source.name,`<div class="dp-toolbar-row"><span class="dp-pagebadge">${esc(t.id)}</span><span class="tag ${t.state==='已验收'?'green':t.state==='待验收'?'orange':''}">${esc(t.state)}</span></div><div class="dp-flow">${steps.map((s,i)=>`<span class="${i<=idx?'active':''}">${i+1} ${s}</span>${i<3?'→':''}`).join('')}</div><div class="dp-detail-grid">${[['来源',t.source.model||t.source.key],['责任人',t.owner],['验收人',t.verifier],['完成期限',t.due],['业务周期',periodLabel(t.period)],['通知状态',t.notify]].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="dp-callout"><b>执行方案</b><div style="white-space:pre-wrap">${esc(t.plan)}</div><br><b>验收标准</b><div style="white-space:pre-wrap">${esc(t.criteria)}</div></div>${t.state!=='已验收'?`<form class="dp-form" id="dp-task-form"><label class="full">${t.state==='待验收'?'复核意见':'执行进展 / 交付凭证（文档编号、附件地址或验证结果）'}<textarea name="evidence" required minlength="10" placeholder="请填写可核验的交付物、验证数据和结论">${t.state==='待验收'?'':esc(t.evidence||'')}</textarea></label>${t.state==='待验收'?`<label>实际整改日期<input type="date" name="actual" required max="${DATA_CUTOFF}" min="${t.createdDate}" value="${t.actualDate||DATA_CUTOFF}"></label><label>闭环验证日期<input type="date" name="closed" required max="${DATA_CUTOFF}" min="${t.createdDate}" value="${DATA_CUTOFF}"></label>${t.source.kind==='project'?`<label class="full">经确认的恢复计划上线日期<input name="recovery" type="date" required min="${DATA_CUTOFF}" value="${t.recoveryPlan||shiftDate(DATA_CUTOFF,7)}"></label>`:''}<label class="dp-check full"><input type="checkbox" name="verified" required>已复核交付物及验收标准，关键卡点解除、依赖放行条件满足。</label>`:''}<div class="red full" id="dp-task-error" role="alert"></div></form>`:`<div class="dp-callout">实际整改 ${esc(t.actualDate)} · 闭环验证 ${esc(t.closedDate)}<br>验收结论：${esc(t.review)}</div>`}${t.evidence?`<div class="dp-callout"><b>已提交凭证</b><p style="white-space:pre-wrap">${esc(t.evidence)}</p></div>`:''}<h3>完整操作轨迹</h3>${t.logs.map(l=>`<div class="dp-log"><b>${esc(l.action)}</b> · ${esc(l.actor)}<br>${esc(l.detail)}<br><small>${esc(new Date(l.at).toLocaleString('zh-CN'))}</small></div>`).join('')}`,false,'演示业务日 '+DATA_CUTOFF+' · 操作与验证均留痕');
 $('#dialogactions').innerHTML=`<button class="btn" id="dp-task-close">关闭</button><button class="btn" id="dp-copy-notice">复制钉钉通知</button>${t.state==='待执行'?'<button class="btn primary" id="dp-start-task">开始处理</button>':t.state==='执行中'?'<button class="btn primary" type="submit" form="dp-task-form">提交验收</button>':t.state==='待验收'?'<button class="btn" id="dp-reject-task">退回整改</button><button class="btn primary" type="submit" form="dp-task-form">验收通过并回写</button>':''}`;
 $('#dp-task-close').onclick=closeModal;
 $('#dp-copy-notice').onclick=async()=>{const notice=`【${dpDepartmentName()} DBS 工作通知】\n任务：${t.source.name}（${t.id}）\n责任人：${t.owner}\n预计完成日期：${t.due}\n验收人：${t.verifier}\n优先级：${t.priority}\n处理方案：\n${t.plan}\n验收标准：${t.criteria}\n来源：${t.source.model||t.source.key}`;try{await navigator.clipboard.writeText(notice);dpTaskMutate(t,'复制通知',{notify:'已复制，待人工发送'},'通知内容已复制，未实际发送');toast('已复制通知内容，请粘贴至钉钉发送')}catch(_){openModal('钉钉通知内容',`<textarea style="width:100%;height:330px" readonly>${esc(notice)}</textarea>`,false,'浏览器未允许自动复制，请选中全文复制。')}};
 if($('#dp-start-task'))$('#dp-start-task').onclick=()=>dpTaskMutate(t,'开始处理',{state:'执行中'},'责任人开始执行整改方案');
 if($('#dp-reject-task'))$('#dp-reject-task').onclick=()=>{const reason=$('#dp-task-form textarea').value.trim();if(reason.length<10){$('#dp-task-error').textContent='请填写至少 10 字的退回原因及补充要求。';return}dpTaskMutate(t,'退回整改',{state:'执行中',review:reason},reason)};
 if($('#dp-task-form'))$('#dp-task-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),evidence=f.get('evidence').trim();if(evidence.length<10){$('#dp-task-error').textContent='请补充可核验的内容，至少 10 字。';return}if(t.state==='执行中')dpTaskMutate(t,'提交验收',{state:'待验收',evidence,actualDate:DATA_CUTOFF},evidence);else if(t.state==='待验收'){if(f.get('closed')<f.get('actual')){$('#dp-task-error').textContent='闭环验证日期不能早于实际整改日期。';return}dpTaskMutate(t,'验收通过',{state:'已验收',review:evidence,actualDate:f.get('actual'),closedDate:f.get('closed'),recoveryPlan:f.get('recovery')||''},evidence+(f.get('recovery')?'；确认恢复排期 '+f.get('recovery'):''))}};
}
function dpTaskMutate(t,action,change,detail){const actor=action==='验收通过'||action==='退回整改'?t.verifier:t.owner,audit={...dpAudit(action,t.id,detail),actor},next={...dpStore,tasks:dpStore.tasks.map(x=>x.id===t.id?{...x,...change,logs:[audit,...x.logs]}:x),audit:[audit,...dpStore.audit]};if(dpSave(next)){renderAll();renderDepartment();dpTaskDetail(t.id)}}
function dpOpenRisk(source){
 const task=dpTaskFor(source),done=dpClosed(source),isProject=source.kind==='project';
 openModal(source.name+' · 风险与处理',`<div class="dp-detail-head">${riskThumbnail(source.name)}<div><span class="tag ${done?'green':'red'}">${done?'已验收闭环':esc(source.level||'待跟进')}</span><h2>${esc(source.name)}</h2><p>${esc(source.model)} · ${esc(chains[source.chain])} · ${esc(source.owner)}</p></div></div><div class="dp-detail-grid">${[['所属部门',source.dept||dpDepartmentName()],['责任链主',aiOwners[source.chain]],['当前风险',source.metric||source.cause],['发生 / 计划日期',source.date||bounds().cutoff],['关联链路',source.stage||source.kind],['当前处理状态',task?.state|| (done?'已验收':'待分配')]].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="dp-callout danger"><b>偏差与业务影响</b><br>${esc(source.cause)}${isProject?'<br>影响后续量产、上架及销售供给；具体延期归因以项目任务台账为依据。':''}</div><div class="dp-callout"><b><span class="ai-logo ai-logo--icon" aria-hidden="true"></span> AI 建议处理方案</b><div style="white-space:pre-wrap">${esc(dpPlan(source))}</div></div><p class="dp-notice">建议需负责人确认；验收前保留风险。来源 ${esc(source.key)}</p>`);
 $('#dialogactions').insertAdjacentHTML('afterbegin',`${isProject?'<button class="btn" id="dp-shared-project">项目全链路详情</button>':''}${source.kind==='quality'?'<button class="btn" id="dp-shared-quality">品质指标与趋势</button>':''}<button class="btn primary" id="dp-risk-dispatch">${task?'查看执行进展':done?'查看验收记录':'下发处理任务'}</button>`);
 $('#dp-risk-dispatch').onclick=()=>task?dpTaskDetail(task.id):done?dpTaskDetail(done.id):dpDispatch(source);
 if($('#dp-shared-project'))$('#dp-shared-project').onclick=()=>dpLegacy('projects','risk',()=>projectDetail(source.id));
 if($('#dp-shared-quality'))$('#dp-shared-quality').onclick=()=>dpLegacy('risk','risk',()=>riskDetail(0,source.id));
}
function dpPeriodHTML(id){const p=dpP(id),limit=dashboardPeriodLimit(p);return`<div class="dp-period" data-dp-period="${id}"><div class="period-segment">${[['month','月'],['quarter','季'],['year','年']].map(([m,l])=>`<button type="button" data-dp-mode="${m}" aria-pressed="${m===p.mode}">${l}</button>`).join('')}</div><select data-dp-year aria-label="${id}统计年份">${dashboardYears(0,p.year).reverse().map(y=>`<option ${y===p.year?'selected':''}>${y}</option>`).join('')}</select>${p.mode==='year'?'':`<select data-dp-value aria-label="${id}统计周期">${Array.from({length:limit},(_,i)=>`<option value="${i+1}" ${p.value===i+1?'selected':''}>${p.mode==='month'?i+1+' 月':'Q'+(i+1)}</option>`).join('')}</select>`}${['global','ai'].includes(id)?'':`<button class="link" data-dp-follow="${id}" ${dpState.periods[id]?'':'disabled'}>${dpState.periods[id]?'恢复跟随':'跟随全局'}</button>`}</div>`}
function dpChangePeriod(id,key,value){const p={...(id==='global'?dpState.global:dpP(id))};if(key==='mode'){const m=p.mode==='month'?p.value:p.mode==='quarter'?p.value*3:(p.year===+dashboardToday().slice(0,4)?+dashboardToday().slice(5,7):12);p.mode=value;p.value=value==='year'?1:value==='quarter'?Math.ceil(m/3):m}else p[key]=+value;normalizePeriod(p);if(id==='global')dpState.global=p;else dpState.periods[id]=p;dpState.pages={};renderDepartment()}
function dpField(id,name,options,label){const value=dpState.filters[id]?.[name]??'all';return`<select ${name==='brand'?'multiple data-pf-multiple':''} data-dp-filter="${id}" data-field="${name}" aria-label="${label}"><option value="all">全部${label}</option>${options.map((n,i)=>`<option value="${i}" ${pfOptionSelected(value,i)?'selected':''}>${esc(n)}</option>`).join('')}</select>`}
