function dpProduct(p){return`<div class="dp-product">${riskThumbnail(p.name)}<div><b>${esc(p.name)}</b><small>${esc(p.model)} · ${esc(typeof p.brand==='number'?brands[p.brand]:p.brand||chains[p.chain])}</small></div></div>`}
