function pbDetails(r){if(!r)return;if(r.kind==='person')return pbPerson(r);const t=pbTask(r),order=r.kind==='order'||r.kind==='cost',s=pbSupplierLedger().find(s=>s.key===r.supplierKey);pbRemember(r);const items=[['品类',chains[r.chain]],['责任采购',r.owner],['供应商',r.supplier||s?.name||r.name],['证据来源',r.source||'采购过程台账'],['记录日期',r.date||pbDate()],['当前状态',t?.state||'待下发']];if(order){const batch=pbOrders().filter(x=>x.type===r.type),ontime=batch.filter(x=>x.actual!=='—'&&x.actual<=x.due).length;items.push(['本期同类型交付及时率',pbPct(ontime,batch.length)],['平均延期天数',fmt(pbSum(batch,'delay')/Math.max(1,batch.length),1)+' 天']);}if(order)items.push(['订单类型',r.type],['订单数量',r.qty+' 件'],['计划交付',r.due],['实际交付',r.actual],['延期天数',r.delay+' 天'],['目标单价',fmt(r.target,2)+' 元'],['实际单价',fmt(r.actualCost,2)+' 元'],['成本偏差率',fmt(r.rate,1)+'%'],['综合费率 / 标准',r.fee+'% / '+r.feeTarget+'%']);if(r.kind==='cost')items.push(['降本目标进度','80%'],['降本实际进度',Math.max(20,80-Math.round(r.rate*2))+'%'],['降本措施','议价复核、替代料评审、物流与损耗拆解']);if(r.kind==='supplier'&&s)items.push(['供应商类型',['整机供应商','物料供应商'][s.kind]],['星级',s.stars+' 星'],['资质有效期',s.expiry],['缺失资料',s.missing.join('、')||'当前资料齐全'],['开发延期',s.delay+' 天']);if(r.kind==='project')items.push(['计划上线',r.plan],['实际上线',r.actual],['责任链主',aiOwners[r.chain]],['项目负责人',r.originalOwner],['卡点阶段',r.stage],['红绿灯',r.status],['单品成本',r.cost+' 元'],['单品售价',r.price+' 元']);if(r.kind==='quality')items.push(['总退货率',fmt(r.returnRate,1)+'%'],['已签收退率',fmt(r.returnRate*.78,1)+'%'],['采购批次','BATCH-'+r.model+'-'+pbDate().slice(0,7)],['退货原因 TOP3','功能不良 / 运输破损 / 使用体验'],['抽检结论','需复核异常批次并形成复测报告']);if(r.kind==='selection'&&r.target!==undefined)items.push(['计划数量',r.target+' 个'],['实际完成',r.actual+' 个'],['缺口数量',r.gap+' 个'],['完成率',r.metric]);if(r.kind==='sample')items.push(['当前阶段',pbStages[r.stage]],['运营部门',r.ops],['运营类型',r.origin],['累计销量',r.volume+' 件'],...r.dates.map((d,i)=>[pbStages[i]+'日期',d||'未达到']));
 pbModal(r.name+' · 采购详情',`<div class="dp-detail-head">${['supplier','process','person','manual'].includes(r.kind)?'<span class="pb-supplier-icon">采</span>':riskThumbnail(r.name)}<div><h2>${esc(r.name)}</h2><p>${esc(r.model||r.code||r.key)}</p></div>${pbTag(r)}</div><div class="dp-detail-grid">${items.map(([l,v])=>`<div><small>${l}</small><strong>${esc(String(v??'—'))}</strong></div>`).join('')}</div><div class="dp-callout ${r.level==='高危'?'danger':''}"><b>核心卡点与影响</b><p>${esc(r.issue||'按计划跟踪开发、交付与验收。')}</p></div><h3>AI 根因分析与闭环方案</h3><div class="pb-plan">${esc(pbPlan(r))}</div><div class="pb-analysis"><b>资源与验收</b><p>责任采购牵头，按计划日期提交凭证；部长核对风险是否解除，确认后才能验收。协调资源需对方确认，不自动修改经营实际。</p></div>${r.kind==='quality'?pbTrend([r.returnRate*.75,r.returnRate*.82,r.returnRate],chartPeriodDates(3)):''}`);
 $('#dialogactions').insertAdjacentHTML('afterbegin',pbBtn(t?'跟进任务':'编辑方案并下发','dispatch',r.key,'btn primary')+(s?pbBtn('供应商详情','supplier',s.key,'btn'):'')+(r.kind==='project'?pbBtn('查看项目全流程','project',r.id,'btn'):r.kind==='sample'&&r.stage>=4?pbBtn('关联项目详情','project',r.projectId,'btn'):''));}
function pbSupplierDetail(key){const s=pbSupplierLedger().find(s=>s.key===key);if(!s||!pbScope(s))return;const risks=pbSupplierRisks().filter(r=>r.supplierKey===s.key);pbModal(s.name+' · 供应商资料',`<div class="dp-detail-head"><span class="pb-supplier-icon">供</span><div><h2>${esc(s.name)}</h2><p>${s.code} · ${['整机供应商','物料供应商'][s.kind]} · ${s.grade} 级 · ${s.stars} 星</p></div><span class="tag">${s.state}</span></div><div class="dp-detail-grid">${[['供应品类',chains[s.chain]],['责任采购',s.owner],['创建时间',s.date],['准入时间',s.admitted],['合作开始',s.cooperation],['资质有效期',s.expiry],['必备资料',s.missing.length?s.missing.join('、'):'当前必备资料齐全'],['合格工厂储备',s.qualified+' 家'],['交付及时率',s.delivery+'%']].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="pb-subheading"><h3>合作范围与关联台账</h3></div><div class="pb-inline-actions">${pbBtn('合作产品','supplier-products',key,'btn')}${pbBtn('历史订单','supplier-orders',key,'btn')}${pbBtn('风险记录 '+risks.length,'supplier-risks',key,'btn')}</div>${dpTable(['风险维度','指标','原因','状态','操作'],risks.map(r=>{pbRemember(r);return[r.dimension,r.metric,r.issue,pbTask(r)?.state||'待处理',pbActions(r)]}))}`);}
function pbPerson(r){pbRemember(r);const labels=['工作事项闭环率','日报规范与完整性','关键业务目标达成','跨部门协同表现','风险前置识别'],weights=[30,15,25,15,15];pbModal(r.name+' · 五维得分与依据',`<div class="dp-grid">${pbMetric('个人 AI 得分',fmt(r.score,1)+'<em>分</em>','原始计算 '+fmt(r.base,1))}${pbMetric('任务闭环率',pbPct(r.closed,r.planned),r.closed+' / '+r.planned)}${pbMetric('周期报告天数',r.raw.length+'<em>天</em>',periodLabel())}${pbMetric('当前状态',r.score>=80?'绿灯':r.score>=60?'黄灯':'红灯',r.role)}</div>${dpTable(['评分维度','权重上限','周期日均得分','计算与扣分依据'],labels.map((l,i)=>[l,weights[i],fmt(r.parts[i],2),['30×按期闭环率；逾期每项−3，缺交付物−2，无理由搁置−5，下限0。','迟报−5，缺卡点/成果−3，无量化−5；未交当日计0。','按目标比例×25；达成率低于50%时本项不超过10。','采购根因红灯−8，响应超时−4，漏传返工−5，下限0。','基础9分；重大主动预警+6，暴露未上报−6，限0–15。'][i]]))}<div class="pb-analysis"><b>AI 改进建议</b><p>${esc(r.issue)} 每周复核关键事项的交付物与闭环证据，优先保障影响供应商准入和采购交付的工作。</p></div><h3>日报 / 任务原始依据</h3><div id="pb-person-proof"></div>${pbState.role==='manager'?`<form class="dp-form" id="pb-score-form"><label>部长复核得分<input name="score" type="number" min="0" max="100" step=".1" required value="${r.score.toFixed(1)}"></label><label>备注 / 调整依据<input name="reason" required minlength="5" value="${esc(r.override?.reason||'')}"></label><button class="btn" type="submit">保存复核备注</button></form>`:''}`);let page=1;const render=()=>{const list=r.raw.slice((page-1)*listPageSize('pb-person-proof',20),page*listPageSize('pb-person-proof',20));$('#pb-person-proof').innerHTML=dpTable(['日期','计划 / 按期闭环','迟报','缺交付物','日报提交','跨部门红灯','五维得分'],list.map(d=>[d.date,d.planned+' / '+d.closed,d.late,d.missing,d.noReport?'未交':'已交',d.red,d.points.map(v=>fmt(v,1)).join(' / ')]))+listPager(r.raw.length,page,listPageSize('pb-person-proof',20));bindListPager($('#pb-person-proof'),next=>{page=next;render()});};render();if($('#pb-score-form'))$('#pb-score-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),key=periodKey(pbPeriod(pbModalSection))+':'+r.name;pbAudit('人员评分复核',key,pbStore.scores[key]||r.base,{score:+f.get('score'),reason:f.get('reason')});pbStore.scores[key]={score:+f.get('score'),reason:f.get('reason')};if(pbSave()){renderPurchasing();toast('复核结果与依据已保存');closeModal()}};$('#dialogactions').insertAdjacentHTML('afterbegin',pbBtn('下发改进任务','dispatch',r.key,'btn primary'));}
function pbOpenAI(tab){pbState.aiTab=tab;const all=pbAIRows(),range=pbState.aiRange,end=pbDate(),start=range==='day'?end:range==='week'?shiftDate(end,-6):end.slice(0,7)+'-01',rows=all.filter(r=>(r.date||end)>=start&&(r.date||end)<=end),types=pbDeviationTypes,list=tab==='pending'?pbAllRisks():tab==='deviation'?pbRiskLists()[6]:rows,pageKey='ai-'+tab+'-'+range,pages=Math.max(1,Math.ceil(list.length/listPageSize('pb-ai',20))),page=Math.max(1,Math.min(pbState.pages[pageKey]||1,pages));pbState.pages[pageKey]=page;
 const content=tab==='deviation'?types.map(name=>{const group=list.slice((page-1)*listPageSize('pb-ai',20),page*listPageSize('pb-ai',20)).filter(r=>r.dimension===name);return `<div class="pb-subheading"><b>${name}</b><small>${group.length} 项</small></div>`+group.map(r=>`<article class="pb-ai-item"><h3>${esc(r.name)}</h3><p>${esc(r.issue)}</p><small>来源：${esc(r.source)} · 责任人 ${r.owner}</small><div>${pbActions(r)}</div></article>`).join('')}).join(''):list.slice((page-1)*listPageSize('pb-ai',20),page*listPageSize('pb-ai',20)).map(r=>{pbRemember(r);return `<article class="pb-ai-item"><div class="pb-subheading"><span class="tag ${r.level==='高危'?'red':'orange'}">${r.priority||'P1'} · ${r.level}</span><small>${chains[r.chain]}</small></div><h3>${esc(r.name)}</h3><p>${esc(r.issue)}</p>${tab==='advice'?`<div class="pb-plan">${esc(pbPlan(r))}</div>`:''}<dl><dt>责任采购</dt><dd>${r.owner}</dd><dt>计划完成</dt><dd>${r.due||shiftDate(end,3)}</dd><dt>证据来源</dt><dd>${esc(r.source||'人工新增关键事项')}</dd></dl><div class="pb-inline-actions">${pbActions(r)}${pbState.role==='manager'?pbBtn('编辑','ai-edit',r.key)+pbBtn('移除','ai-remove',r.key):''}</div></article>`}).join('');
 pbModal('采购部 AI 智能诊断',`<div class="pb-ai-drawer"><div class="pb-subheading"><small>更新至 ${end}</small>${pbBtn('刷新诊断','ai-refresh',tab)}</div><div class="pb-tabs tabs">${[['key','关键事项'],['deviation','偏差诊断'],['advice','输出建议'],['pending','待闭环']].map(([k,n])=>`<button data-pb-ai-tab="${k}" class="${tab===k?'active':''}">${n}</button>`).join('')}</div><div class="pb-tabs tabs">${[['day','本日'],['week','本周'],['month','本月']].map(([k,n])=>`<button data-pb-ai-range="${k}" class="${range===k?'active':''}">${n}</button>`).join('')}</div><div class="pb-subheading"><small>${start} — ${end}</small>${pbState.role==='manager'?pbBtn('＋ 新增事项','ai-add','new'):''}</div>${content||'<div class="dp-empty">当前范围暂无诊断事项</div>'}${listPager(list.length,page,listPageSize('pb-ai',20),{sizeKey:"pb-ai",attr:"data-key",extra:{"data-pb-action":"ai-page"}})}</div>`,true);$('#dialogactions').insertAdjacentHTML('afterbegin','');}
function pbEditAI(r){if(pbState.role!=='manager')return;pbModal(r?'编辑关键事项':'新增关键事项',`<form class="dp-form" id="pb-ai-edit-form"><label class="full">事项内容<input name="name" required minlength="3" value="${esc(r?.name||'')}"></label><label>所属品类<select name="chain">${chains.map((n,i)=>`<option value="${i}" ${i===(r?.chain??+(pbState.chain==='all'?0:pbState.chain))?'selected':''}>${n}</option>`).join('')}</select></label><label>优先级<select name="priority">${['P0','P1','P2'].map(n=>`<option ${n===(r?.priority||'P1')?'selected':''}>${n}</option>`).join('')}</select></label><label>责任采购<select name="owner">${pbPeople.map(n=>`<option ${n===r?.owner?'selected':''}>${n}</option>`).join('')}</select></label><label>计划完成<input type="date" name="due" required min="${pbDate()}" value="${r?.due&&r.due>=pbDate()?r.due:shiftDate(pbDate(),3)}"></label><label class="full">问题及行动要求<textarea name="issue" required minlength="10">${esc(r?.issue||'')}</textarea></label><label class="full">修改原因<input name="reason" required minlength="5"></label><button class="btn primary" type="submit">保存事项</button></form>`);$('#pb-ai-edit-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),next={...r,key:r?.key||'MANUAL-'+Date.now(),kind:r?.kind||'manual',name:f.get('name'),chain:+f.get('chain'),owner:f.get('owner'),priority:f.get('priority'),level:f.get('priority')==='P0'?'高危':'中风险',due:f.get('due'),issue:f.get('issue'),date:bounds(pbPeriod(pbModalSection)).cutoff,tier:r?.tier??0,period:{...pbPeriod(pbModalSection)},source:r?.source||'部长新增事项'};if(pbPeople.indexOf(next.owner)%4!==next.chain){toast('责任采购与所属品类不一致，请调整后保存');return}pbAudit(r?'编辑关键事项':'新增关键事项',next.key,r||null,{...next,reason:f.get('reason')});if(r)pbStore.edits[r.key]=next;else pbStore.custom.unshift(next);if(pbSave()){renderPurchasing();pbWith('ai',()=>pbOpenAI('key'))}};}
function pbRemoveAI(r){if(pbState.role!=='manager'||!r)return;pbModal('移除关键事项',`<form class="dp-form" id="pb-ai-remove-form"><div class="full dp-callout">${esc(r.name)}<br>仅移出关键事项清单，原始风险台账保留。</div><label class="full">移除原因<input name="reason" required minlength="5"></label><button type="submit" class="btn primary">确认移除并留痕</button></form>`);$('#pb-ai-remove-form').onsubmit=e=>{e.preventDefault();pbStore.removed.push(r.key);pbAudit('移除关键事项',r.key,r,new FormData(e.target).get('reason'));if(pbSave()){renderPurchasing();pbWith('ai',()=>pbOpenAI('key'))}}}
function pbDispatch(r){if(!r)return;const existing=pbTask(r);if(existing)return pbTaskDetail(existing.id);const selected=pbPeople.filter(n=>pbPeople.indexOf(n)%4===r.chain);pbRemember(r);pbModal('下发采购整改任务',`<form class="dp-form" id="pb-dispatch-form"><div class="full dp-callout"><b>${esc(r.name)}</b><br>${esc(r.issue||'采购执行与交付跟进')}</div><label>指派责任采购<select name="owner">${selected.map(n=>`<option ${n===r.owner?'selected':''}>${n}</option>`).join('')}</select></label><label>预计完成日期<input name="due" type="date" required min="${pbDate()}" value="${r.due>=pbDate()?r.due:shiftDate(pbDate(),3)}"></label><label class="full">整改方案（可编辑）<textarea name="plan" required minlength="15">${esc(pbPlan(r))}</textarea></label><label class="full">验收标准<textarea name="criteria" required minlength="10">交付对应业务凭证，核实卡点解除，原始台账有明确验证结论。</textarea></label><label class="dp-check full"><input type="checkbox" name="notify" checked>钉钉通知责任人</label><small class="full dp-notice">当前为演示通知，保存通知记录；未连接真实钉钉服务。</small><button class="btn primary" type="submit">确认下发</button></form>`);$('#pb-dispatch-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),source={...r};delete source.raw;const t={id:'PB-TASK-'+Date.now(),key:r.key,name:r.name,chain:r.chain,tier:r.tier??0,owner:f.get('owner'),due:f.get('due'),plan:f.get('plan'),criteria:f.get('criteria'),state:'待执行',notify:f.get('notify')?'演示通知已记录':'未通知',source,period:{...pbPeriod(pbModalSection)},createdDate:bounds(pbPeriod(pbModalSection)).cutoff,logs:[{at:new Date().toISOString(),actor:pbActor(),action:'下发任务'}]};pbStore.tasks.unshift(t);pbAudit('下发采购任务',t.id,null,t);if(pbSave()){renderPurchasing();pbTaskDetail(t.id);toast('已写入整改任务')}};}
function pbTaskDetail(id){const t=pbStore.tasks.find(t=>t.id===id);if(!t||!pbScope(t))return;const accept=t.state==='待验收'&&pbState.role==='manager',done=t.state==='已验收';pbModal(t.name+' · 执行与验收',`<div class="dp-flow">${['待执行','执行中','待验收','已验收'].map(s=>`<span class="${t.state===s?'active':''}">${s}</span>`).join('')}</div><div class="dp-detail-grid">${[['任务编号',t.id],['责任采购',t.owner],['预计完成',t.due],['当前状态',t.state],['通知状态',t.notify],['业务范围',chains[t.chain]]].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><h3>执行方案</h3><div class="pb-plan">${esc(t.plan)}</div><div class="dp-callout"><b>验收标准</b><p>${esc(t.criteria)}</p>${t.evidence?'<p>交付凭证：'+esc(t.evidence)+'</p>':''}</div>${done?`<div class="tag green">已于 ${t.closedDate} 验收，来源预警已销项</div>`:`<form class="dp-form" id="pb-task-form"><label class="full">${accept?'验收意见':'执行进展 / 交付凭证'}<textarea name="evidence" required minlength="10">${esc(accept?'':t.evidence||'')}</textarea></label>${accept?`<label>实际完成日期<input type="date" name="actual" required min="${t.createdDate}" max="${DATA_CUTOFF}" value="${t.actualDate||DATA_CUTOFF}"></label><label>闭环验证日期<input type="date" name="closed" required min="${t.actualDate||t.createdDate}" max="${DATA_CUTOFF}" value="${DATA_CUTOFF}"></label>${t.source.kind==='project'?`<label class="full">恢复计划上线日期<input name="recovery" type="date" required min="${DATA_CUTOFF}" value="${shiftDate(DATA_CUTOFF,7)}"></label>`:''}<label class="dp-check full"><input type="checkbox" name="verified" required>已核对交付凭证，风险解除并满足验收条件</label>`:''}<div class="full pb-inline-actions">${accept?'<button class="btn primary" type="submit" name="action" value="accept">验收通过并销项</button><button class="btn" type="submit" name="action" value="reject" formnovalidate>退回整改</button>':t.state==='待验收'?'<span class="dp-notice">已提交，等待采购部部长验收。</span>':'<button class="btn" type="submit" name="action" value="progress">保存执行进展</button><button class="btn primary" type="submit" name="action" value="submit">提交验收</button>'}</div></form>`}<h3 style="margin-top:20px">操作轨迹</h3>${t.logs.map(l=>`<div class="dp-log">${esc(l.action)} · ${esc(l.actor)}<small>${l.at}</small></div>`).join('')}`);if($('#pb-task-form'))$('#pb-task-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),action=e.submitter?.value,text=f.get('evidence')?.trim();if(!text||text.length<10){toast('请填写至少 10 字的进展或审核依据');return}const before={...t};if(action==='accept'){if(pbState.role!=='manager')return;if(f.get('closed')<f.get('actual')){toast('验证日期不能早于实际完成日期');return}t.state='已验收';t.actualDate=f.get('actual');t.closedDate=f.get('closed');t.review=text;t.recovery=f.get('recovery')}else if(action==='reject'){if(pbState.role!=='manager')return;t.state='退回整改';t.review=text}else{t.evidence=text;t.state=action==='submit'?'待验收':'执行中'}t.logs.push({at:new Date().toISOString(),actor:pbActor(),action:t.state+'：'+text});pbAudit('采购任务状态变更',t.id,before,t);if(pbSave()){renderAll();renderPurchasing();pbTaskDetail(id);toast(t.state==='已验收'?'验收完成，来源预警已同步销项':'执行状态已更新')}};}
function pbLifeDetail(key){const [stage,scope,channel,chain]=key.split('|'),rows=pbLifeRecords(+stage,scope,channel,chain);pbModalList(lifeNames[+stage]+' · '+(scope==='year'?'年度累计':'周期')+'完成明细',rows,['产品图片 / 名称','型号','品类','品牌','完成日期','对应供应商','责任采购','完成记录'],r=>[pbProduct(r),r.model,chains[r.chain],r.brand,r.date,r.supplier,r.owner,r.id])}
function pbQuoteTable(){const rows=pbOrders().map((r,i)=>({...r,key:r.key+':quote',kind:'quote',phase:['首轮报价','样机报价','量产报价'][i%3],due:shiftDate(r.due,-7),quoted:i%4!==0,issue:i%4===0?'报价资料不完整，待核对模具费、翻新费与物料清单。':'报价已提交，等待成本复核。'}));rows.forEach(pbRemember);return `<div class="pb-grid-three">${pbMetric('待报价任务',rows.filter(r=>!r.quoted).length+'<em>项</em>','按采购订单关联报价')}${pbMetric('超期待报价',rows.filter(r=>!r.quoted&&r.due<pbDate()).length+'<em>项</em>','需补齐成本构成')}${pbMetric('报价及时率',pbPct(rows.filter(r=>r.quoted).length,rows.length),'已报价 / 全部报价任务')}</div>${pbPage('quotes',rows,['报价任务','供应商','报价阶段','计划报价日期','当前状态','责任采购','操作'],r=>[r.name,r.supplier,r.phase,r.due,r.quoted?'已报价':'待报价',r.owner,pbActions(r)])}`}
function pbDocumentsTable(){const kinds=['日报','周报','会议记录','供应商台账','样品台账','报价台账','翻新费台账','模具费台账'],kind=pbState.tabs.document||'0',rows=pbScores().flatMap(r=>r.raw.filter((d,i)=>kind==='0'||kind==='1'?kind==='0'||i%7===0:i%14===0).map(d=>({key:'PB-DOC-'+kind+'-'+r.name+'-'+d.date,kind:'document',name:kinds[+kind]+' · '+r.name,owner:r.name,chain:r.chain,tier:r.tier,date:d.date,level:d.noReport?'高危':d.missing?'中风险':'低风险',issue:d.noReport?'记录未提交':d.missing?'交付附件待补齐':'事项、量化结果与凭证完整',source:'采购过程记录 · '+kinds[+kind],state:d.noReport?'缺交':d.late?'迟交':'按期提交'})));rows.forEach(pbRemember);return pbTabs('document',kinds.map((n,i)=>[String(i),n]))+pbPage('documents',rows,['过程记录','责任采购','品类','日期','提交状态','完整性','操作'],r=>[r.name,r.owner,chains[r.chain],r.date,r.state,r.issue,pbActions(r)])}
function pbTargets(type){if(pbState.role!=='manager'){toast('目标配置由采购部部长维护');return}const stages=type==='supplier'?[0,1]:[0,1,2,3,4,5,6];pbModal(type==='supplier'?'供应商建设目标':'选品目标与爆品标准',`<form class="dp-form" id="pb-target-form">${stages.map(i=>{const key=periodKey()+':'+type+':'+i+':'+pbState.chain,value=pbStore.targets[key]??(type==='supplier'?Math.round(supplierData()[i].qt*(pbState.chain==='all'?1:.25)):pbSelectionTarget(i));return `<label>${type==='supplier'?['整机供应商','物料供应商'][i]+'新增':pbStages[i]+'目标'}<input type="number" min="0" step="1" required name="target-${i}" value="${value}"></label>`}).join('')}${type==='selection'?chains.map((n,i)=>`<label>${n}爆品销量标准<input type="number" min="1" step="1" required name="hot-${i}" value="${pbStore.hot[i]}"></label>`).join(''):''}<label class="full">配置原因<input name="reason" required minlength="5"></label><button class="btn primary">保存配置</button></form>`);$('#pb-target-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),before=JSON.parse(JSON.stringify(pbStore.targets));for(const i of stages)pbStore.targets[periodKey(pbPeriod(pbModalSection))+':'+type+':'+i+':'+pbState.chain]=+f.get('target-'+i);if(type==='selection')pbStore.hot=chains.map((_,i)=>+f.get('hot-'+i));pbAudit('更新采购目标',type,before,{targets:pbStore.targets,reason:f.get('reason')});if(pbSave()){renderPurchasing();closeModal();toast('已保存目标，实际数量按台账计算')}};}
function pbRules(){pbModal('采购部指标口径',dpTable(['指标','口径'],[['角色范围','部长查看全品类；产品链主按所属品类展示。当前为演示视角，正式权限需由服务端校验。'],['项目灯色','直接沿用总看板项目状态；文档的3/10天采购预警建议仅作采购关注阈值，不覆盖统一项目灯色。'],['新品口径','统一复用总看板上架≤120天的新品台账，保持跨看板退货率一致。'],['供应商数量','有效供应商储备 / 合作与总看板一致；采购总览另展示已淘汰历史记录。'],['人员五维评分','30 / 15 / 25 / 15 / 15 分；逐日计算，周期得分为每日五维得分平均。复核保留原始值与修改原因。'],['供应商质量','抽检质量问题比例≥0.5%预警，与销售总退货率分开计算。'],['选品转化','统计本期到达节点的记录；跨期转化可能超过100%，不强制截断。'],['生命周期','完成项、目标及分渠道分配复用总看板与产品部，不独立虚构完成数量。'],['通知与验收','演示通知只保存本地记录；验收需交付凭证与部长确认，不把点击完成直接视为业务指标达标。']]))}

// Mount procurement beside the existing director and product workspaces.
const pbRenderers={risk:pbRenderRisk,ai:pbRenderAI,management:pbRenderManagement,suppliers:pbRenderSuppliers,selection:pbRenderSelection,lifecycle:pbRenderLifecycle,channels:pbRenderChannels,tasks:pbRenderTasks};
pbState.tabs.process='supplier';pbState.tabs.document='0';pbState.tabs.selectionGran='month';
const pbLedgerOriginal=pbSupplierLedger,pbLedgerCache=new Map();pbSupplierLedger=function(){const key=periodKey();if(!pbLedgerCache.has(key))pbLedgerCache.set(key,pbLedgerOriginal());return pbLedgerCache.get(key)};
pbView=document.createElement('div');pbView.id='purchasing-view';pbView.className='dp-view pb-view';pbView.hidden=true;dpMain.appendChild(pbView);
function renderPurchasing(){
 const scope=`<div class="dp-top-filters"><div class="dp-scope"><label>管理视角<select id="pb-role"><option value="manager" ${pbState.role==='manager'?'selected':''}>采购部部长</option><option value="owner" ${pbState.role==='owner'?'selected':''}>产品链主</option></select></label><label>品类<select id="pb-chain">${pbState.role==='manager'?'<option value="all">全部品类</option>':''}${chains.map((n,i)=>`<option value="${i}" ${String(i)===pbState.chain?'selected':''}>${n}</option>`).join('')}</select></label><label>供应商类型<select id="pb-tier"><option value="all">全部类型</option>${['整机供应商','物料供应商'].map((n,i)=>`<option value="${i}" ${pbState.tier===String(i)?'selected':''}>${n}</option>`).join('')}</select></label><label>责任采购<select id="pb-owner"><option value="all">全部人员</option>${pbPeople.filter((n,i)=>pbState.chain==='all'||i%4===+pbState.chain).map(n=>`<option ${n===pbState.owner?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="dp-controls">${pbPeriodHTML('global')}${pbBtn('全部同步','sync','all')}</div></div>`;
 pbView.innerHTML=scope+`<nav class="dp-nav pb-nav" aria-label="采购部模块"><div class="dp-nav-links">${pbModules.map(([id,title,label])=>`<a href="#pb-${id}">${label}${id==='tasks'?` <span class="dp-task-count">${pbStore.tasks.filter(pbScope).filter(t=>t.state!=='已验收').length}</span>`:''}</a>`).join('')}</div><div class="dp-nav-actions">${pbBtn('⚙ 指标口径','rules','all','btn small')}</div></nav>`+pbModules.map(([id,title],i)=>`<section class="section dp-section" id="pb-${id}" data-pb-section="${id}"><div class="sectionhead"><div class="titlegroup"><span class="${id==='ai'?'ai-logo':'dp-number'}">${id==='ai'?'<b>AI</b>':String(i+1).padStart(2,'0')}</span><h2>${title}</h2></div>${pbPeriodHTML(id)}</div>${id==='ai'?'':`<div class="dp-range">${periodLabel(pbPeriod(id))} · 截至 ${bounds(pbPeriod(id)).cutoff}${['lifecycle','channels'].includes(id)?' · 品类范围':''}</div>`}<div class="pb-content">${pbWith(id,pbRenderers[id])}</div></section>`).join('');
 if(pbObserver)pbObserver.disconnect();pbObserver=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(visible.length)pbView.querySelectorAll('.pb-nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+visible[0].target.id))},{rootMargin:'-80px 0px -65% 0px'});pbView.querySelectorAll('.dp-section').forEach(n=>pbObserver.observe(n));
}
let pbObserver=null;
const pbPreviousSwitch=dpSwitchView;dpSwitchView=function(view,hash=true){pbView.hidden=true;dpNavButtons[5].classList.remove('active');dpNavButtons[5].removeAttribute('aria-current');pbPreviousSwitch(view,hash)};
function pbSwitchView(hash=true){pbPreviousSwitch('director',false);dpDirectorNodes.forEach(n=>n.hidden=true);dpView.hidden=true;pbView.hidden=false;dpState.view='procurement';dpNavButtons.forEach((n,i)=>{n.classList.toggle('active',i===5);if(i===5)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});if($('.headright .optional'))$('.headright .optional').textContent='采购经营与协同中心';if(hash)history.replaceState(null,'','#procurement');renderPurchasing();window.scrollTo({top:0,behavior:'instant'})}
dpNavButtons[5].disabled=false;dpNavButtons[5].removeAttribute('title');dpNavButtons[5].onclick=()=>pbSwitchView();
function pbChangePeriod(id,field,value){const p={...pbPeriod(id)};if(field==='mode'){const m=p.mode==='quarter'?(p.value-1)*3+1:p.mode==='month'?p.value:1;p.mode=value;p.value=value==='quarter'?Math.ceil(m/3):value==='month'?m:1}else p[field]=+value;const max=dashboardPeriodLimit(p);p.value=p.mode==='year'?1:Math.max(1,Math.min(p.value,max));if(id==='global'){pbState.global=p;pbState.periods={}}else pbState.periods[id]=p;pbState.pages={};renderPurchasing()}
function pbSupplierSet(rows,title='供应商明细'){pbModalList(title,rows,['供应商 / 编码','供应商类型','品类','等级 / 星级','合作状态','责任采购','创建日期','操作'],pbSupplierCells)}
function pbCurrentSuppliers(){const t=pbState.tabs.suppliers,s=pbState.tabs.supplierStatus;return pbSuppliers().filter(r=>(!['machine','material'].includes(t)||r.kind===(t==='machine'?0:1))&&(s==='all'||r.state===s))}
function pbSampleSet(rows,title='选品明细'){pbModalList(title,rows,['产品 / 型号','供应商','品类','责任采购','当前节点','运营部门','到样日期','操作'],r=>[pbProduct(r),r.supplier,chains[r.chain],r.owner,pbStages[r.stage],r.ops,r.date,pbActions(r)])}
function pbRiskSet(rows,title='采购风险明细'){pbModalList(title,rows,['风险','事项 / 产品','品类','责任采购','核心指标','卡点原因','操作'],r=>[pbTag(r),esc(r.name),chains[r.chain],r.owner,r.metric||'—',esc(r.issue),pbActions(r)])}
function pbProjectOpen(id){const old=localPeriods.projects;localPeriods.projects={...pbPeriod(pbModalSection)};try{projectDetail(+id)}finally{if(old)localPeriods.projects=old;else delete localPeriods.projects}}

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const section=b.closest('[data-pb-section]');if(section)pbModalSection=section.dataset.pbSection;
 if(b.hasAttribute('data-pb-mode'))return pbChangePeriod(b.closest('[data-pb-period]').dataset.pbPeriod,'mode',b.dataset.pbMode);
 if(b.dataset.pbTab){pbState.tabs[b.dataset.pbTab]=b.dataset.value;pbState.pages={};renderPurchasing();return}
 if(b.dataset.pbAiTab){pbWith('ai',()=>pbOpenAI(b.dataset.pbAiTab));return}if(b.dataset.pbAiRange){pbState.aiRange=b.dataset.pbAiRange;pbWith('ai',()=>pbOpenAI(pbState.aiTab));return}
 const action=b.dataset.pbAction,key=b.dataset.key;if(!action||b.classList.contains('pb-disabled'))return;pbWith(pbModalSection,()=>{const r=pbCache.get(periodKey()+'|'+key);
 switch(action){
 case 'page':{const [id,page]=key.split('|');pbState.pages[id]=+page;renderPurchasing();break}
 case 'sync':pbState.periods={};pbState.pages={};renderPurchasing();toast('全部采购模块已同步当前周期');break;
 case 'rules':pbRules();break;case 'risk-list':pbOpenRiskList(+key);break;
 case 'detail':pbDetails(r);break;case 'dispatch':pbDispatch(r);break;case 'task':pbTaskDetail(key);break;
 case 'person':pbPerson(r);break;case 'supplier':pbSupplierDetail(key);break;case 'project':pbProjectOpen(key);break;
 case 'ai':pbModalSection='ai';pbWith('ai',()=>pbOpenAI(key));break;
 case 'ai-page':pbState.pages['ai-'+pbState.aiTab+'-'+pbState.aiRange]=+key;pbOpenAI(pbState.aiTab);$('#dialogbody').scrollTop=0;break;
 case 'ai-refresh':pbOpenAI(pbState.aiTab);toast('已根据当前业务台账重新生成诊断');break;
 case 'ai-add':pbEditAI();break;case 'ai-edit':pbEditAI(r);break;case 'ai-remove':pbRemoveAI(r);break;
 
 case 'targets':pbTargets(key);break;
 case 'supplier-type':pbSupplierSet(pbSuppliers().filter(r=>key==='all'||r.kind===(key==='machine'?0:1)),key==='all'?'全部供应商':key==='machine'?'整机供应商':'物料供应商');break;
 case 'supplier-state':pbSupplierSet(pbSuppliers().filter(r=>r.state===key),key+'供应商');break;
 case 'supplier-filter':{const [kind,grade]=key.split('|');pbSupplierSet(pbSuppliers().filter(r=>r.kind===+kind&&r.grade===grade),grade+'级供应商');break}
 case 'supplier-current':pbSupplierSet(pbCurrentSuppliers().filter(r=>key==='new'?r.date>=bounds().start:key==='low'?r.stars<2&&r.state!=='已淘汰':true));break;
 case 'supplier-star':case 'supplier-chain':case 'supplier-owner':{const rows=section?.dataset.pbSection==='suppliers'&&['machine','material'].includes(pbState.tabs.suppliers)?pbCurrentSuppliers():pbSuppliers();pbSupplierSet(rows.filter(r=>action==='supplier-star'?r.stars===parseInt(key):action==='supplier-chain'?chains[r.chain]===key:r.owner===key),key+' · 供应商明细');break}
 case 'supplier-products':{const s=pbSupplierLedger().find(r=>r.key===key);pbModalList('合作产品 · '+s.name,productRows(false).filter(r=>r.chain===s.chain).slice(0,8),['产品 / 型号','品类','品牌','供应商'],r=>[pbProduct(r),chains[r.chain],r.brand,s.name]);break}
 case 'supplier-orders':pbRiskSet(pbOrders().filter(r=>r.supplierKey===key),'供应商历史订单');break;
 case 'supplier-risks':pbRiskSet(pbSupplierRisks().filter(r=>r.supplierKey===key),'供应商全部风险记录');break;
 case 'selection-stage':pbState.tabs.stage=String(key);pbSampleSet(pbStageRows(+key),pbStages[+key]+'产品明细');break;
 case 'sample-owner':case 'sample-chain':case 'sample-supplier':case 'sample-ops':pbSampleSet(pbStageRows(+pbState.tabs.stage).filter(r=>action==='sample-owner'?r.owner===key:action==='sample-chain'?chains[r.chain]===key:action==='sample-supplier'?r.supplierState===key:r.ops===key),key+' · 选品明细');break;
 case 'life-stage':pbState.tabs.lifecycle=String(key);renderPurchasing();break;case 'life-detail':pbLifeDetail(key);break;
 case 'channel-detail':pbModal(dpChannelNames[+key]+' · 采购交付',dpTable(['规划类型','周期目标','周期完成','完成率','年度目标','年度完成'],[0,1,2,3,4,6].map(i=>{const d=pbLifeChannels(i)[+key];return[lifeNames[i],d.target,pbBtn(d.actual+'','life-detail',i+'|period|'+key+'|all'),pbPct(d.actual,d.target),d.yearTarget,pbBtn(d.yearActual+'','life-detail',i+'|year|'+key+'|all')]})));break;
 case 'scope':pbState.role='owner';pbState.chain=key;pbState.owner='all';pbState.pages={};renderPurchasing();$('#pb-lifecycle').scrollIntoView({block:'start'});break;
 case 'tasks':pbState.tabs.tasks=key;pbOpenTaskRecords();break;
 case 'modal-set':if(key==='people')pbModalList('采购人员与评分',pbScores(),['姓名 / 岗位','品类','AI得分','状态','任务闭环率','关键问题','过程问题','操作'],pbScoreCells);else pbRiskSet(key==='projects'?pbProjectRows():pbRiskLists(true)[6],key==='projects'?'采购责任项目':'工作过程偏差');break;
 }
 });
});
document.addEventListener('change',e=>{const b=e.target;if(b.hasAttribute('data-pb-year')||b.hasAttribute('data-pb-value')){pbChangePeriod(b.closest('[data-pb-period]').dataset.pbPeriod,b.hasAttribute('data-pb-year')?'year':'value',b.value);return}if(b.dataset.pbFilter){(pbState.filters[b.dataset.pbFilter]??={})[b.dataset.field]=b.value;pbState.pages={};renderPurchasing();return}if(!['pb-role','pb-chain','pb-tier','pb-owner'].includes(b.id))return;pbState[b.id.slice(3)]=b.value;if(pbState.role==='owner'&&pbState.chain==='all')pbState.chain='0';if(b.id!=='pb-owner')pbState.owner='all';pbState.pages={};renderPurchasing()});
// Verification changes the operational project status only after acceptance.
const pbPreviousProjects=projects;projects=function(){return pbPreviousProjects().map(r=>{const task=pbStore.tasks.find(t=>t.source.kind==='project'&&t.source.id===r.id&&t.period.year===periodFor().year&&t.state==='已验收');return task?{...r,status:'绿灯',delay:0,cause:'采购整改已验收：'+task.review,recoveryPlan:task.recovery}:r})};
window.procurementSnapshot=()=>({scope:{...pbState,periods:{...pbState.periods}},suppliers:pbWith('suppliers',()=>({shared:supplierData(),rows:pbSuppliers()})),risks:pbWith('risk',()=>pbRiskLists().map((rows,i)=>({title:pbRiskTitles[i],count:rows.length,keys:rows.map(r=>r.key)}))),lifecycle:pbWith('lifecycle',()=>lifeNames.map((name,i)=>({...lifeSumRows(pbLifeRows(i)),name,records:pbLifeRecords(i,'period').length,yearRecords:pbLifeRecords(i,'year').length}))),channels:pbWith('channels',()=>[0,1,2,3,4,6].map(i=>({stage:i,rows:pbLifeChannels(i).map((r,c)=>({...r,records:pbLifeRecords(i,'period',String(c)).length}))}))),tasks:JSON.parse(JSON.stringify(pbStore.tasks))});
requestAnimationFrame(()=>{if(location.hash==='#procurement'||location.hash.startsWith('#pb-'))pbSwitchView(false)});

// Director quality risk: one dated observation per SPU and platform.
const qrPlatforms=filterCatalog.platforms;
const qrState={platform:'抖音',listPlatform:'all',listPage:1,sort:'risk'},qrDrafts=new Map();let qrDetailState=null;
const qrSum=(rows,key)=>rows.reduce((n,r)=>n+r[key],0),qrRate=(n,d)=>d?n/d*100:0;
function qrCatalog(){return riskRows(0)}
function qrWindow(){const end=bounds().cutoff;return {start:shiftDate(end,-29),end}}
const qrObservationPoints=boundedCache(1600,100000);
function qrObservation(p,platform,start,end,includePoints=true){
 const ci=qrPlatforms.indexOf(platform),days=Math.round((Date.parse(end)-Date.parse(start))/86400000)+1,seed=p.id*19+ci*31,profile=(p.id+ci)%6,normal=profile>=3,key=p.id+'|'+platform+'|'+start+'|'+end;
 // 月度适配器只取身份和原因时，不重复展开已被统一台账替代的旧逐日数据。
 let points=includePoints?qrObservationPoints.get(key):[];
 if(!points){points=[];
 for(let i=0;i<days;i++){const date=shiftDate(start,i),ordinal=Math.floor(Date.parse(date)/86400000),wave=Math.sin((ordinal+seed)*.31),orders=Math.max(8,Math.round((43+(p.id%9)*7)*[1.18,.69,.48,1.06,.91,.83][ci]*(1+wave*.22))),sales=orders+Math.floor(orders*.14),returned=Math.round(sales*(normal?.02+(seed%3)*.007:profile===0?.13+Math.max(0,wave)*.015:.055+(seed%7)*.015+Math.max(0,wave)*.015)),contacts=Math.round(orders*(normal?.05+(seed%4)*.012:profile===2?.20+Math.max(0,wave)*.025:.08+(seed%9)*.018+Math.max(0,wave)*.025)),reviews=Math.max(1,Math.round(orders*.52)),bad=Math.round(reviews*(normal?.02+(seed%3)*.008:profile===1?.14:.04+(seed%6)*.021));
  points.push({date,orders,sales,returned,contacts,reviews,bad,returnRate:qrRate(returned,sales),contactRate:qrRate(contacts,orders)});
 }
 qrObservationPoints.set(key,points,points.length);}
 const o={...p,platform,key:p.id+':'+ci,start,end,points,orders:qrSum(points,'orders'),sales:qrSum(points,'sales'),returned:qrSum(points,'returned'),contacts:qrSum(points,'contacts'),reviews:qrSum(points,'reviews'),bad:qrSum(points,'bad')};
 o.returnRate=qrRate(o.returned,o.sales);o.contactRate=qrRate(o.contacts,o.orders);o.badRate=qrRate(o.bad,o.reviews);
 o.penalty=!normal&&seed%11===0;o.offShelf=!normal&&seed%17===0;o.risks=[...(o.penalty?['平台处罚']:[]),...(o.offShelf?['下架']:[]),...(o.returnRate>=10?['高退货']:[]),...(o.badRate>=8?['高差评']:[]),...(o.contactRate>=15?['高进线']:[])];
 o.cause=['功能异常与批次一致性待复测','包装防护不足，运输破损集中','商品描述与使用预期存在偏差','温升、噪声体验引发售后咨询'][p.chain];o.platformCause=o.penalty?'平台品质投诉处罚，待提交申诉材料':o.offShelf?'商品因品质投诉下架，待整改审核':'售后问题集中，需结合订单与实物复核';
 if(!o.risks.length)o.platformCause='当前平台未触发预警阈值，保持趋势跟踪';o.score=(o.penalty?1000:0)+(o.offShelf?500:0)+o.returnRate*3+o.badRate*2+o.contactRate;return o;
}
function qrRows(platform=qrState.platform,start=qrWindow().start,end=qrWindow().end){return qrCatalog().flatMap(p=>(platform==='all'?qrPlatforms:[platform]).map(c=>qrObservation(p,c,start,end))).filter(r=>r.risks.length).sort((a,b)=>b.score-a.score||a.id-b.id||qrPlatforms.indexOf(a.platform)-qrPlatforms.indexOf(b.platform))}
function qrPlatformOptions(value,includeAll=false){return [...(includeAll?['all']:[]),...qrPlatforms].map(n=>`<option value="${n}" ${value===n?'selected':''}>${n==='all'?'全平台':n}</option>`).join('')}
function qrRiskTags(o){return o.risks.length?o.risks.map(n=>`<span class="tag red">${n}</span>`).join(' '):'<span class="tag green">正常</span>'}
function qrCard(){const rows=qrRows(),w=qrWindow();return `<div class="rhead"><h3><i class="riskbadge"></i>高危品质风险榜</h3><button class="link" data-risk="0">全部 ${rows.length} ›</button></div><div class="qr-card-filter"><select id="qr-card-platform" aria-label="品质风险平台">${qrPlatformOptions(qrState.platform)}</select><span>近30天 · 进线率</span></div>${rows.slice(0,6).map((o,i)=>`<button class="qr-rank-row" title="${esc(o.risks.join(' / ')+'；'+o.cause)}" data-qr-detail="${o.key}"><span class="rank ${i<3?'top':''}">${String(i+1).padStart(2,'0')}</span>${riskThumbnail(o.name)}<span class="qr-rank-info"><b>${esc(o.name)}</b><small>${o.platform} · ${o.model}</small><em>${o.penalty?'处罚 · ':o.offShelf?'下架 · ':''}退货 ${fmt(o.returnRate,1)}% · 差评 ${fmt(o.badRate,1)}%</em></span><strong class="red">${fmt(o.contactRate,1)}%</strong></button>`).join('')||'<div class="empty">当前平台暂无风险</div>'}<div class="qr-card-date">${w.start} — ${w.end}</div>`}
const qrOriginalRender=renderRisks;renderRisks=function(){qrOriginalRender();withPeriod('risk',()=>{const card=$('#riskrail .riskcard');card.classList.add('qr-card');card.innerHTML=qrCard()})};
const qrOriginalOpen=openRisk;openRisk=function(k){if(k!==0)return qrOriginalOpen(k);withPeriod('risk',qrOpenList)};
// Platform disposition is separate from abnormal quality metrics.
function qrPenaltyLevel(o){return o.penalty?{label:'高风险 · 已处罚',color:'red'}:o.offShelf?{label:'中风险 · 下架',color:'orange'}:{label:'无处罚',color:'green'}}
function qrListRate(value,threshold){return `<b class="${value>=threshold?'red':'green'}">${fmt(value,1)}%</b>`}
function qrOpenList(){
 openModal('高危品质风险榜 · 完整榜单',`<div class="qr-list-tools"><label>平台 <select id="qr-list-platform">${qrPlatformOptions(qrState.platform)}</select></label><label>排序 <select id="qr-list-sort"><option value="risk">平台处罚 / 下架优先</option><option value="bad">差评率从高到低</option><option value="returns">退货率从高到低</option><option value="contact">进线率从高到低</option></select></label><span class="note">${qrWindow().start} — ${qrWindow().end}</span></div><div id="qr-list-table"></div><details class="qr-rules"><summary>指标口径</summary><p>差评率＝差评条数 ÷ 有效评价条数；退货率＝退货件数 ÷ 发货件数；进线率＝售后进线订单数 ÷ 发货订单数。平台处罚风险等级采用演示管理分级：已处罚为高风险，下架为中风险，无处罚或下架记录时显示绿色“无处罚”；品质指标异常与平台处罚分开判断，分级不代表平台官方规则。</p></details>`,false,'按产品 SPU × 平台展示风险');
 const fill=()=>withPeriod('risk',()=>{
  let rows=qrRows();const sortKey={contact:'contactRate',returns:'returnRate',bad:'badRate'}[qrState.sort];if(sortKey)rows.sort((a,b)=>b[sortKey]-a[sortKey]);
  const pages=Math.max(1,Math.ceil(rows.length/listPageSize('qr-list-table',20)));qrState.listPage=Math.max(1,Math.min(qrState.listPage,pages));
  $('#qr-list-table').innerHTML=table(['序号','产品 SPU 名称','产品缩略图','型号','所属渠道','差评率','退货率','进线率','平台处罚风险等级','操作'],rows.slice((qrState.listPage-1)*listPageSize('qr-list-table',20),qrState.listPage*listPageSize('qr-list-table',20)).map((o,i)=>{const penalty=qrPenaltyLevel(o);return [(qrState.listPage-1)*listPageSize('qr-list-table',20)+i+1,`<b>${esc(o.name)}</b>`,riskThumbnail(o.name),o.model,o.platform,qrListRate(o.badRate,8),qrListRate(o.returnRate,10),qrListRate(o.contactRate,15),`<span class="tag ${penalty.color}">${penalty.label}</span>`,`<button class="link" data-qr-detail="${o.key}">查看详情</button>`]}))+listPager(rows.length,qrState.listPage,listPageSize('qr-list-table',20));
  bindListPager($('#qr-list-table'),next=>{qrState.listPage=next;fill()});
  
 });
 $('#qr-list-sort').value=qrState.sort;$('#qr-list-sort').onchange=e=>{qrState.sort=e.target.value;qrState.listPage=1;fill()};$('#qr-list-platform').onchange=e=>{qrState.platform=e.target.value;qrState.listPage=1;renderRisks();fill()};fill();
}
function qrChart(o,kind){const percent=kind==='returnRate',points=o.points,max=Math.max(1,...points.map(r=>r[kind]))*1.15,x=i=>44+i*470/Math.max(1,points.length-1),y=v=>164-v/max*123,step=Math.max(1,Math.ceil(points.length/6)),color=percent?(o.risks.length?'#e56570':'#009a29'):'#7885f5';return `<svg viewBox="0 0 548 207" role="img" aria-label="${o.platform}${percent?'退货率':'销量'}趋势"><text x="12" y="15">${percent?'%':'件'}</text>${[0,max/2,max].map(n=>`<line x1="44" x2="520" y1="${y(n)}" y2="${y(n)}" stroke="#eaf0f7"/><text x="36" y="${y(n)+4}" text-anchor="end">${fmt(n,percent?1:0)}</text>`).join('')}<path d="M44,164 L${points.map((p,i)=>x(i)+','+y(p[kind])).join(' L')} L514,164Z" fill="${color}" opacity=".07"/><polyline points="${points.map((p,i)=>x(i)+','+y(p[kind])).join(' ')}" fill="none" stroke="${color}" stroke-width="2"/>${points.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p[kind])}" r="${points.length>70?1.8:3}" fill="${color}"><title>${p.date} · ${o.platform} · ${percent?'退货率 '+fmt(p.returnRate,1)+'%（'+p.returned+' / '+p.sales+' 件）':'销量 '+p.sales+' 件'}</title></circle>${i%step===0||i===points.length-1?`<text x="${x(i)}" y="192" text-anchor="middle">${p.date.slice(5)}</text>`:''}`).join('')}</svg>`}
function qrAnalysis(o){if(!o.risks.length)return `${o.platform}平台进线率 ${fmt(o.contactRate,1)}%、退货率 ${fmt(o.returnRate,1)}%、差评率 ${fmt(o.badRate,1)}%，均在正常范围内；未发现平台处罚或下架记录。当前无需整改，保持日常监测。`;return `${o.platform}平台：${o.contacts} 笔售后进线 / ${o.orders} 笔发货订单，进线率 ${fmt(o.contactRate,1)}%；退货 ${o.returned} / 发货 ${o.sales} 件，退货率 ${fmt(o.returnRate,1)}%；差评 ${o.bad} / 有效评价 ${o.reviews} 条，差评率 ${fmt(o.badRate,1)}%。${o.penalty?'存在平台处罚，优先核对处罚单与申诉截止时间。':''}${o.offShelf?'商品处于下架风险，整改审核通过前应暂停相关投放。':''}${o.risks.length?'售后标签显示“'+o.cause+'”':'当前平台未触发预警阈值，持续观察后续订单'}，需结合订单、批次与复测证据确认根因，不能仅凭比率认定产品缺陷。`}
function qrPlan(o){return `处理范围：${o.name} / ${o.model} / ${o.platform}\n统计区间：${o.start} 至 ${o.end}\n\n1. 核实订单与平台风险（负责人牵头，运营 / 客服协同）\n整理 ${o.platform} 进线、退货及差评订单，去重后按问题、批次、仓库分类；${o.penalty||o.offShelf?'核对处罚或下架通知及申诉截止时间，保留平台凭证。':'核对平台工单，确认异常影响范围。'}交付：异常订单清单与风险凭证。\n\n2. 定位根因（品质 / 研发协同）\n针对“${o.cause}”抽取关联批次复测，分别排查产品功能、运输包装和描述预期差异。交付：复测记录、确认根因及批次影响范围。\n\n3. 执行整改（处理负责人组织）\n根据验证结论修订工艺、包装或商品说明；安排异常客户处理与相关批次复检。${o.penalty||o.offShelf?'补齐整改材料，提交平台申诉或恢复上架审核；未经审核不得自行认定恢复。':''}交付：整改前后证据、客户处理记录及平台回执。\n\n4. 验证与复盘（品质负责人验收）\n复测通过后观察后续7天进线率、退货率和差评率，按同口径复核订单样本；仍异常则升级处理。交付：验收结论、趋势对比及未解决问题清单。\n\n各步骤由负责人按预计处理日期倒排节点，协调人员确认后执行。`}
function qrTaskKey(o){return `quality:${o.model}:${o.platform}:${o.start}:${o.end}`}
function qrValues(){return {plan:$('#qr-plan').value.trim(),assignee:$('#qr-assignee').value,due:$('#qr-due').value,collaborators:$$('[name="qr-collaborator"]:checked').map(n=>n.value).filter(n=>n!==$('#qr-assignee').value),notify:$('#qr-notify').checked}}
function qrPreserve(){if(qrDetailState&&$('#qr-plan'))qrDrafts.set(qrTaskKey(qrCurrent()),qrValues())}
function qrCurrent(){const s=qrDetailState;return qrObservation(s.product,s.platform,s.start,s.end)}
function qrNotify(v,o){return `【品质风险处理】${o.name}（${o.model}）\n平台：${o.platform}\n统计区间：${o.start} — ${o.end}\n风险：${o.risks.join('、')||'持续观察'}\n进线率 ${fmt(o.contactRate,1)}% / 退货率 ${fmt(o.returnRate,1)}% / 差评率 ${fmt(o.badRate,1)}%\n处理负责人：${v.assignee||'待选择'}\n协调人员：${v.collaborators.join('、')||'无'}\n预计处理日期：${v.due||'待填写'} 23:59（北京时间）\n\n处理方案：\n${v.plan}`}
function qrOpenDetail(key){const [id,ci]=key.split(':').map(Number),product=qrCatalog().find(p=>p.id===id);if(!product)return;const w=qrWindow();qrDetailState={product,platform:qrPlatforms[ci],...w,limit:bounds().cutoff,mode:'30'};qrRenderDetail()}
function qrRenderDetail(){
 const s=qrDetailState,o=qrCurrent(),key=qrTaskKey(o),saved=riskTasks[key],v=qrDrafts.get(key)||saved||{plan:qrPlan(o),assignee:aiAssignees.some(a=>a[0]===o.owner)?o.owner:'',due:'',collaborators:[],notify:true};
 openModal(o.name+(o.risks.length?' · 品质风险详情':' · 品质详情'),`<div class="qr-detail dp-detail-head">${riskThumbnail(o.name)}<div><h2>${esc(o.name)}</h2><p>${o.model} · ${o.brand} · ${chains[o.chain]}</p></div><span class="tag ${o.risks.length?'red':'green'}">${o.platform} · ${o.risks.length?'品质风险':'正常'}</span></div><div class="qr-platform-tabs" aria-label="产品风险平台">${qrPlatforms.map(n=>{const r=qrObservation(s.product,n,s.start,s.end);return `<button data-qr-platform="${n}" class="${n===s.platform?'active ':''}${r.risks.length?'has-risk':'is-normal'}" aria-pressed="${n===s.platform}"><i></i>${n}<small>${r.risks.length?'风险':'正常'}</small></button>`}).join('')}</div><div class="qr-time-row"><div class="period-segment"><button id="qr-last30" class="${s.mode==='30'?'active':''}">近30天</button><button id="qr-custom" class="${s.mode==='custom'?'active':''}">自定义时间</button></div><div id="qr-custom-range" ${s.mode==='30'?'hidden':''}><input type="date" id="qr-start" aria-label="统计开始日期" min="2025-01-01" max="${s.limit}" value="${s.start}"><span>至</span><input type="date" id="qr-end" aria-label="统计结束日期" min="2025-01-01" max="${s.limit}" value="${s.end}"><button class="btn small" id="qr-apply">查询</button></div><span class="note">${s.start} — ${s.end} · ${o.points.length} 天</span></div><p id="qr-date-error" class="red" role="alert"></p><div class="qr-detail-metrics">${[['进线率',fmt(o.contactRate,1)+'%',o.contacts+' / '+o.orders+' 笔发货订单',o.contactRate>=15],['退货率',fmt(o.returnRate,1)+'%',o.returned+' / '+o.sales+' 件发货',o.returnRate>=10],['差评率',fmt(o.badRate,1)+'%',o.bad+' / '+o.reviews+' 条有效评价',o.badRate>=8],['销量',fmt(o.sales)+'<em>件</em>','按发货件数统计',false]].map(([label,value,note,bad])=>`<div><small>${label}</small><strong class="${bad?'red':label!=='销量'?'green':''}">${value}</strong><span>${note}</span></div>`).join('')}</div><div class="qr-risk-line ${o.risks.length?'':'qr-normal'}">${qrRiskTags(o)}<span>${o.platformCause}</span></div><div class="qr-charts"><div><h3>${s.mode==='30'?'近30天':'所选时间'}退货率趋势 <span class="${o.risks.length?'red':'green'}">${o.platform}</span></h3>${qrChart(o,'returnRate')}</div><div><h3>${s.mode==='30'?'近30天':'所选时间'}销量趋势 <span>${o.platform}</span></h3>${qrChart(o,'sales')}</div></div><details class="qr-rules"><summary>指标口径与数据说明</summary><p>进线率＝售后进线订单数 ÷ 发货订单数（同一订单周期内去重）；退货率＝退货件数 ÷ 发货件数；差评率＝差评条数 ÷ 有效评价条数。周期指标按分子、分母累计计算，不取每日百分比的简单平均。演示预警阈值：进线率≥15%、退货率≥10%、差评率≥8%；平台处罚、下架优先。平台状态为截止日演示快照，经营趋势为演示数据。</p></details><div class="risk-analysis"><h3><span class="ai-logo ai-logo--icon" aria-hidden="true"></span> AI ${o.risks.length?'风险':'品质'}分析 · ${o.platform}</h3><p>${qrAnalysis(o)}</p><small>${o.risks.length?'基于当前平台与时间范围的规则分析示例，实际根因需凭证验证。':'按所选平台与时间区间评估，当前各项指标正常。'}</small></div><form id="qr-handle-form"><div class="risk-plan-head"><h3>详细处理方案</h3><div class="inline"><button type="button" class="link" id="qr-edit">✎ 编辑方案</button><button type="button" class="link" id="qr-reset">恢复建议方案</button></div></div><textarea id="qr-plan" aria-label="品质风险处理方案" maxlength="6000" rows="12" readonly>${esc(v.plan)}</textarea><div class="risk-assign-grid"><label><span class="ui-field-caption">处理负责人 <span class="red">*</span></span><select id="qr-assignee" required><option value="">请选择处理负责人</option>${aiAssignees.map(([name,role])=>`<option value="${name}" ${name===v.assignee?'selected':''}>${name} · ${role}</option>`).join('')}</select></label><label><span class="ui-field-caption">预计处理日期 <span class="red">*</span></span><input type="date" id="qr-due" aria-label="预计处理日期" required min="${aiToday()}" value="${esc(v.due||'')}"><small>北京时间，当天 23:59 前完成</small></label></div><fieldset class="risk-collaborators"><legend>协调人员（可多选）</legend>${aiAssignees.map(([name,role])=>`<label><input type="checkbox" name="qr-collaborator" value="${name}" ${v.collaborators?.includes(name)?'checked':''}>${name}<span>${role}</span></label>`).join('')}</fieldset><div class="risk-ding"><div class="risk-ding-head"><label><input type="checkbox" id="qr-notify" ${v.notify?'checked':''}>通过钉钉通知处理负责人及协调人员</label><span class="tag orange">未接入</span></div><p class="note">当前保存本地任务与通知待发记录，尚未向人员发送真实消息。</p><details id="qr-notification"><summary>预览钉钉通知内容与接收人员</summary><pre id="qr-notification-text"></pre></details></div><div id="qr-save-feedback" role="status">${saved?`<div class="risk-task-receipt">${saved.status==='draft'?'方案草稿已保存':'处理任务已保存'} · ${esc(saved.assignee||'待指派')} · ${esc(saved.due||'待填写日期')}<br>${saved.status!=='draft'&&saved.notify?'钉钉通知待发送（未接入）':'通知未入待发队列'}</div>`:''}</div><p id="qr-form-error" class="red" role="alert"></p></form>`,false,`${o.platform} · ${o.start} — ${o.end}`);
 $('#dialogactions').innerHTML='<button class="btn small" id="qr-back">返回榜单</button><button class="btn small" id="qr-save">保存方案</button><button class="btn primary small" type="submit" form="qr-handle-form" id="qr-submit">分配并加入钉钉待发</button><button class="btn small" id="qr-close">关闭</button>';
 const preview=()=>{const v=qrValues();$('#qr-notification-text').textContent=qrNotify(v,o);$('#qr-notification').hidden=!v.notify;$('#qr-submit').textContent=v.notify?'分配并加入钉钉待发':'保存处理任务'};$('#qr-handle-form').oninput=preview;$('#qr-handle-form').onchange=preview;preview();
 $('#qr-edit').onclick=()=>{$('#qr-plan').readOnly=false;$('#qr-plan').focus();$('#qr-edit').textContent='方案可编辑'};$('#qr-reset').onclick=()=>{$('#qr-plan').value=qrPlan(o);preview()};$('#qr-close').onclick=()=>{qrPreserve();closeModal()};$('#qr-back').onclick=()=>{qrPreserve();withPeriod('risk',qrOpenList)};
 $('#qr-last30').onclick=()=>{qrPreserve();s.start=shiftDate(s.limit,-29);s.end=s.limit;s.mode='30';qrRenderDetail()};$('#qr-custom').onclick=()=>{qrPreserve();s.mode='custom';qrRenderDetail()};$('#qr-apply').onclick=()=>{const start=$('#qr-start').value,end=$('#qr-end').value;if(!start||!end||start>end||start<'2025-01-01'||end>s.limit){$('#qr-date-error').textContent='请选择有效时间区间，开始日期不得晚于结束日期，结束日期不得超过数据截止日 '+s.limit+'。';return}qrPreserve();s.start=start;s.end=end;s.mode='custom';qrRenderDetail()};
 $('#qr-handle-form').hidden=!o.risks.length;$('#qr-save').hidden=!o.risks.length;$('#qr-submit').hidden=!o.risks.length;
 $('#qr-save').onclick=()=>qrSave('draft');$('#qr-handle-form').onsubmit=e=>{e.preventDefault();qrSave('assigned')};
}
function qrSave(status){const o=qrCurrent(),key=qrTaskKey(o),v=qrValues();if(!o.risks.length){toast('当前平台正常，无需分配整改任务');return}if(v.plan.length<15){$('#qr-form-error').textContent='请填写至少15字的处理方案。';$('#qr-plan').readOnly=false;$('#qr-plan').focus();return}if(status!=='draft'&&(!aiAssignees.some(a=>a[0]===v.assignee)||!v.due||v.due<aiToday())){$('#qr-form-error').textContent='请选择处理负责人，并填写不早于今天的预计处理日期。';return}const old=riskTasks[key],task={...v,key,id:old?.id||'QUALITY-'+Date.now().toString(36).toUpperCase(),kind:0,objectId:o.id,objectName:o.name,model:o.model,platform:o.platform,start:o.start,cutoff:o.end,status,notificationStatus:status==='draft'?'not_queued':v.notify?'pending_integration':'not_requested',notificationText:status==='draft'?'':qrNotify(v,o),createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};try{localStorage.setItem(riskTaskKey,JSON.stringify({...riskTasks,[key]:task}))}catch(_){$('#qr-form-error').textContent='本地保存失败，请检查浏览器存储空间。';return}riskTasks[key]=task;qrDrafts.set(key,v);$('#qr-form-error').textContent='';$('#qr-save-feedback').innerHTML=`<div class="risk-task-receipt"><b>${status==='draft'?'方案草稿已保存':'处理任务已分配'}</b> · ${task.id}<br>平台：${o.platform} · 处理负责人：${esc(v.assignee||'待选择')} · 协调人员：${esc(v.collaborators.join('、')||'无')}<br>预计处理日期：${esc(v.due||'待填写')}<br>${status==='draft'?'草稿未加入通知队列。':v.notify?'钉钉通知已加入本地待发记录，尚未真实发送。':'本次未开启钉钉通知。'}</div>`;toast(status==='draft'?'处理方案已保存':'处理任务与通知状态已保存')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-qr-detail],[data-qr-platform]');if(!b)return;if(b.dataset.qrDetail)withPeriod('risk',()=>qrOpenDetail(b.dataset.qrDetail));else{qrPreserve();qrDetailState.platform=b.dataset.qrPlatform;qrRenderDetail()}});
document.addEventListener('change',e=>{if(e.target.id==='qr-card-platform'){qrState.platform=e.target.value;qrState.listPage=1;renderRisks()}});
window.qualityRiskSnapshot=()=>withPeriod('risk',()=>({platform:qrState.platform,rows:qrRows().map(({points,...o})=>o),detail:qrDetailState?qrCurrent():null}));

// Shop and loss rankings share their data with the existing risk detail flow.
const brPlatforms=filterCatalog.platforms,brState={platform:'all',shopPage:1,lossPage:1};
const brOriginalRows=riskRows;
function brShopRows(){return sampleShopRows()}
function brLossAmount(value){const amount=Math.round(Math.abs(Number(value)||0)*100)/100;return (amount?'-':'')+fmt(amount,2)}
function brLossRows(){return brOriginalRows(2).map((r,i)=>{const monthlySales=+(48+i*13).toFixed(2),loss=Math.abs(+parseFloat(r.value)),lossRate=loss/monthlySales*100;const base={...r,loss,monthlySales,sourceLoss:loss,sourceMonthlySales:monthlySales},period=riskLossPeriod(base);return {...base,value:brLossAmount(period.loss)+'万',loss:period.loss,monthlySales:period.gmv,lossRate:period.gsv?period.loss/period.gsv*100:0,level:period.loss>=10||(period.gsv?period.loss/period.gsv*100:0)>=20?'P1':period.loss>=6||(period.gsv?period.loss/period.gsv*100:0)>=10?'P2':'P3'}}).sort((a,b)=>b.loss-a.loss)}
riskRows=function(k){return k===1?brShopRows():k===2?brLossRows():brOriginalRows(k)};
function brLevel(level){return `<span class="tag ${level==='P1'?'red':level==='P2'?'orange':'br-p3'}">${level}</span>`}
function brScore(score){return `<span class="${score<3.5?'red':score<4.2?'orange':''}">${score.toFixed(2)}</span>`}
function brOptions(value){return `<option value="all" ${value==='all'?'selected':''}>全部平台</option>`+brPlatforms.map(n=>`<option ${n===value?'selected':''}>${n}</option>`).join('')}
function brFilteredShops(){return brShopRows().filter(r=>brState.platform==='all'||r.channel===brState.platform)}
const brOriginalRender=renderRisks;renderRisks=function(){brOriginalRender();withPeriod('risk',()=>{const rows=brFilteredShops(),card=$$('#riskrail .riskcard')[1];card.classList.add('br-shop-card');card.innerHTML=`<div class="rhead"><h3><i class="riskbadge"></i>高危劣质店铺榜</h3><button class="link" data-risk="1">全部 ${rows.length} ›</button></div><div class="qr-card-filter"><select id="br-card-platform" aria-label="店铺风险平台">${brOptions(brState.platform)}</select><span>风险店铺 · 店铺分</span></div>${rows.slice(0,6).map((r,i)=>`<button class="br-shop-row" data-riskitem="1,${r.id}" title="${esc(r.name+' · '+r.desc)}"><span class="rank ${i<3?'top':''}">${String(i+1).padStart(2,'0')}</span>${riskThumbnail(r.name,true)}<span class="br-shop-title"><b>${esc(r.name)}</b><small>${r.channel} · ${r.level} · ${r.risks[0]}</small></span><strong class="${r.level==='P1'?'red':'orange'}">${r.score.toFixed(2)}</strong></button>`).join('')}`})};
const brOriginalOpen=openRisk;openRisk=function(k){if(k!==1&&k!==2)return brOriginalOpen(k);withPeriod('risk',()=>brOpenList(k))};
function brOpenList(k,context=null){const run=fn=>context?drRun(context,fn):withPeriod('risk',fn);const shop=k===1,pageKey=shop?'shopPage':'lossPage',heads=shop?['序号','店铺名称','所属渠道','店铺分','商品分','物流分','服务分','核心主营产品','核心风险类型','风险等级','操作']:['序号','产品名称','型号','品类','品牌','月度亏损金额','亏损率','风险等级','操作'];
 openModal(riskTitles[k]+' · 完整榜单',`<div class="br-list-tools">${shop?`<label>平台 <select id="br-list-platform">${brOptions(brState.platform)}</select></label><span class="note">P1 优先处理 · P2 重点跟进 · P3 持续改善</span>`:`<span class="note">${bounds().cutoff.slice(0,7)} 月度亏损 · 金额单位：万元</span><span class="note">按亏损绝对值从高到低排序</span>`}</div><div class="br-table ${shop?'br-shop-table':'br-loss-table'}" id="br-list-table"></div><div id="br-pagination"></div><details class="br-rules"><summary>指标口径</summary><p>${shop?'店铺分、商品分、物流分、服务分为 5 分制演示值；店铺分按商品 40%、物流 30%、服务 30% 加权。P1：平台处罚或店铺分低于 3.5；P2：任一分项低于 4.0；其他预警店铺为 P3。正式接入时按各平台实际评分口径映射。':'亏损金额以负数展示；按亏损绝对值排序、分级；亏损率＝亏损绝对值 ÷ 同期销售收入。P1：亏损绝对值≥10万元或亏损率≥20%；P2：亏损绝对值≥6万元或亏损率≥10%；其余为 P3。当前为演示数据，等级用于处置优先级。'}</p></details>`,false,shop?'店铺经营评分与风险分级':'产品经营亏损与风险分级');
 
 const fill=()=>run(()=>{const rows=(shop?brFilteredShops():brLossRows()).filter(r=>!context?.ids||context.ids.includes(r.id)),pages=Math.max(1,Math.ceil(rows.length/listPageSize('br-pagination',20)));brState[pageKey]=Math.max(1,Math.min(brState[pageKey],pages));const page=brState[pageKey];$('#br-list-table').innerHTML=table(heads,rows.slice((page-1)*listPageSize('br-pagination',20),page*listPageSize('br-pagination',20)).map((r,i)=>shop?[(page-1)*listPageSize('br-pagination',20)+i+1,`<div class="br-shop-name">${riskThumbnail(r.name,true)}<b>${esc(r.name)}</b></div>`,r.channel,brScore(r.score),brScore(r.productScore),brScore(r.logisticsScore),brScore(r.serviceScore),esc(r.mainProducts),`<div class="br-risk-tags">${r.risks.map(n=>`<span class="tag ${r.level==='P1'?'red':r.level==='P2'?'orange':'br-p3'}">${n}</span>`).join('')}</div>`,brLevel(r.level),`<button class="link" data-riskitem="1,${r.id}">查看详情</button>`]:[(page-1)*listPageSize('br-pagination',20)+i+1,`<div class="br-product-name">${riskThumbnail(r.name)}<b>${esc(r.name)}</b></div>`,r.model,chains[r.chain],r.brand,`<strong class="red">${brLossAmount(r.loss)}<small> 万元</small></strong>`,`<strong class="red">${fmt(r.lossRate,1)}%</strong>`,brLevel(r.level),`<button class="link" data-riskitem="2,${r.id}">查看详情</button>`]));mountListPager($('#br-pagination'),rows.length,brState[pageKey],next=>{brState[pageKey]=next;fill()});});
 if(shop)$('#br-list-platform').onchange=e=>{brState.platform=e.target.value;brState.shopPage=1;renderRisks();fill()};fill();
 if(context)$('#br-list-table').onclick=e=>{const b=e.target.closest('[data-riskitem]');if(!b)return;e.stopPropagation();run(()=>riskDetail(k,+b.dataset.riskitem.split(',')[1]))};
}
// Existing task and notification forms remain attached to the same shop IDs.
const brOriginalObservation=riskObservation;riskObservation=function(k,p){return brOriginalObservation(k,k===1?{...p,id:p.id%8}:p)};
const brOriginalDetail=riskDetail;riskDetail=function(k,id){brOriginalDetail(k,id);if(k!==1&&k!==2)return;withPeriod('risk',()=>{const r=riskRows(k).find(r=>r.id===+id);if(!r)return;const tag=$('.risk-alert-header .tag');if(tag){tag.className='tag '+(r.level==='P1'?'red':r.level==='P2'?'orange':'br-p3');tag.textContent=r.level+' · '+(r.level==='P1'?'优先处理':r.level==='P2'?'重点跟进':'持续改善')}if(k===1){$('.risk-detail-metrics').innerHTML=[['店铺分',r.score],['商品分',r.productScore],['物流分',r.logisticsScore],['服务分',r.serviceScore]].map(([n,v])=>`<div><small>${n}</small><strong>${brScore(v)}</strong></div>`).join('');$('.risk-context').insertAdjacentHTML('beforeend',`<span class="br-main-products">核心主营产品：<b>${esc(r.mainProducts)}</b></span>`)}else $('.risk-context').insertAdjacentHTML('beforeend',`<span>型号：<b>${r.model}</b></span><span>亏损率：<b class="red">${fmt(r.lossRate,1)}%</b></span><span>风险等级：${brLevel(r.level)}</span>`)})};
document.addEventListener('change',e=>{if(e.target.id==='br-card-platform'){brState.platform=e.target.value;brState.shopPage=1;renderRisks()}});
window.businessRiskSnapshot=()=>withPeriod('risk',()=>({platform:brState.platform,shops:brFilteredShops(),losses:brLossRows()}));

// Pinduoduo product-link diagnostics: only explicit red rankings qualify.
function brPddLinks(shop){
 if(shop.channel!=='拼多多')return [];
 const labels=['近30天用户品质评价分排名','近30天品质退款率','近30天品质求助平台率','近30天品质文本情感分'];
 return Array.from({length:9},(_,i)=>{
  const product=names[shop.chain][i%names[shop.chain].length],seed=shop.id+i;
  const metrics=labels.map((name,j)=>{
   const abnormal=i%4!==0&&(j===(seed%4)||(i%3===1&&j===3));
   const thirdRed=abnormal&&i%3!==2,mainRed=abnormal&&i%3!==1;
   return {name,value:j===0?(32+i*2.18).toFixed(1)+'%':j===1?(i%4===0?.00:1.05+i*.32).toFixed(1)+'%':j===2?(1.7+i*.28).toFixed(1)+'%':(1.12+i*.13).toFixed(2)+'分',thirdRed,mainRed,third:thirdRed?'处于同行后30%':j===0?'--':'已超过50%同行',main:mainRed?(i%2?'处于同行后30%':'处于同行后10%'):j===0?'--':'已超过50%同行'};
  });
  return {id:'PDD-DEMO-'+shop.id+'-'+String(i+1).padStart(3,'0'),name:product+(i>=6?' · 升级款':''),product,model:sampleSpuByName(product)?.model||'—',category:chains[shop.chain],thirdCategory:product,mainCategory:chains[shop.chain],thirdScore:i%4===0?'已超过50%同行':'需改善',mainScore:i%4===0?'已超过50%同行':'需改善',metrics};
 });
}
function brPddAbnormalLinks(shop){return brPddLinks(shop).map(link=>({...link,metrics:link.metrics.filter(m=>m.thirdRed||m.mainRed)})).filter(link=>link.metrics.length)}
function brPddPanel(shop){
 const rows=brPddAbnormalLinks(shop),count=rows.reduce((n,r)=>n+r.metrics.length,0),cutoff=bounds().cutoff;
 return `<section class="pdd-link-panel" aria-label="拼多多产品链接异常"><div class="pdd-link-heading"><h3>产品链接异常 <span class="tag red">${rows.length} 条链接</span></h3><span class="muted">${shiftDate(cutoff,-29)} — ${cutoff} · 演示数据</span></div><p class="pdd-link-note">仅展示按三级分类或主营链群排序标红的链接，共 ${count} 项异常；全部异常链接均在下方展示。</p>${rows.length?`<div class="pdd-link-scroll"><table class="pdd-link-table"><thead><tr>${['商品信息','综合分（按三级分类）','综合分（按主营链群）','考核指标','商品表现','排序（按三级分类）','排序（按主营链群）'].map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${rows.map(link=>link.metrics.map((m,i)=>`<tr data-pdd-link="${link.id}">${i===0?`<td rowspan="${link.metrics.length}"><div class="pdd-link-product">${riskThumbnail(link.product)}<div><b>${esc(link.name)}</b><small>ID：${link.id}</small><small>型号：${link.model}</small><small>三级分类：${esc(link.thirdCategory)}</small><small>主营链群：${esc(link.mainCategory)}</small></div></div></td><td rowspan="${link.metrics.length}">${link.thirdScore}</td><td rowspan="${link.metrics.length}">${link.mainScore}</td>`:''}<td>${m.name}</td><td>${m.value}</td><td class="${m.thirdRed?'red pdd-rank-alert':'green'}" data-pdd-rank="third" data-abnormal="${m.thirdRed}">${m.third}</td><td class="${m.mainRed?'red pdd-rank-alert':'green'}" data-pdd-rank="main" data-abnormal="${m.mainRed}">${m.main}</td></tr>`).join('')).join('')}</tbody></table></div>`:'<div class="dp-empty green">当前无链群排序标红的产品链接</div>'}<div class="pdd-link-advice"><b>AI 链接处理建议</b><p>先按标红指标逐链接核对平台明细：品质退款排查异常批次与退货原因，平台求助优先处理未解决售后，评价与文本情感回查差评内容及商品描述。由店铺运营牵头，品质与客服协同，按链接 ID 留存整改证据，并复核两种链群排序是否恢复。</p></div></section>`;
}
const brPddOriginalDetail=riskDetail;
riskDetail=function(k,id){brPddOriginalDetail(k,id);if(k!==1)return;withPeriod('risk',()=>{const shop=brShopRows().find(r=>r.id===+id);if(shop?.channel==='拼多多')$('.risk-context')?.insertAdjacentHTML('afterend',brPddPanel(shop))})};
window.pddShopLinksSnapshot=id=>withPeriod('risk',()=>{const shop=brShopRows().find(r=>r.id===+id);return shop?{shop:shop.name,all:brPddLinks(shop),abnormal:brPddAbnormalLinks(shop)}:null});

// High-risk inventory: valuation is independent of the priority of matched causes.
const irOriginalRows=riskRows;
const irReasonLabels=['当月下架＋冻结'+brcDescribe('stock.violations')+'','利润率'+brcDescribe('stock.profit')+'','退货率'+brcDescribe('stock.return')+'','已收退货率'+brcDescribe('stock.received')+'','滞销品'];
const irPlatforms=filterCatalog.platforms;
const irPlatformRules=[{key:'profitRate',name:'利润率',get threshold(){return ''+brcDescribe('stock.profit')+''},priority:2,hit:(v,metrics)=>brcMatch('stock.profit',v,metrics)},{key:'returnRate',name:'退货率',get threshold(){return ''+brcDescribe('stock.return')+''},priority:3,hit:(v,metrics)=>brcMatch('stock.return',v,metrics)},{key:'receivedRate',name:'已收退货率',get threshold(){return ''+brcDescribe('stock.received')+''},priority:4,hit:(v,metrics)=>brcMatch('stock.received',v,metrics)}];
function irReasons(r){
 const keys={profitRate:'stock.profit',returnRate:'stock.return',receivedRate:'stock.received'},active=new Set(brcResultMembers('stock-platform'));
 const condition=brcResultCondition('stock-platform'),qualifies=metrics=>brcPredicateTest(condition,'value',metrics);
 const contexts=(r.platformMetrics||[r]).map(metrics=>{const count=metrics.violationCount??r.violationCount??null;return {...metrics,violationCount:count,value:count}}),eligible=contexts.filter(qualifies);
 const matched=irPlatformRules.map(rule=>active.has(keys[rule.key])?eligible.filter(p=>rule.hit(p[rule.key],p)):[]),platformHits=matched.map(rows=>rows.map(p=>p.platform).filter(Boolean));
 const violationHit=active.has('stock.violations')&&eligible.some(metrics=>brcMatch('stock.violations',metrics.violationCount,metrics));
 const hits=[violationHit,...matched.map(rows=>rows.length>0),r.slow];
 return hits.flatMap((hit,i)=>hit?[{priority:i+1,label:irReasonLabels[i],platforms:i>=1&&i<=3?platformHits[i-1]:[]}]:[]);
}
function irReasonText(reason){return reason.label+(reason.platforms?.length?'（'+reason.platforms.join('、')+'）':'')}
function irPlatformData(facts,index){return irPlatforms.map((platform,j)=>{const slot=(j+index)%6,returnRate=Math.max(0,facts.returnRate+[0,-11,-5,-18,-12,-8][slot]);return{platform,profitRate:+(facts.profitRate+[0,3.2,1.4,4.6,5.2,2.8][slot]).toFixed(2),returnRate,receivedRate:Math.min(returnRate,Math.max(0,facts.receivedRate+[0,-8,-3,-12,-9,-6][slot]))}})}
function irPlatformFacts(r){return `<div class="ir-platform-heading"><h4>平台指标对照</h4><span>${shiftDate(r.cutoff,-29)} — ${r.cutoff} · 近30天</span></div><div class="ir-platform-table">${table(['判定指标 / 高危条件',...irPlatforms],irPlatformRules.map(rule=>[`<strong>${rule.name}</strong><small>${rule.threshold}</small>`,...r.platformMetrics.map(p=>`<div data-ir-platform="${p.platform}" data-ir-metric="${rule.key}" data-hit="${rule.hit(p[rule.key],p)}" class="ir-platform-value ${rule.hit(p[rule.key],p)?'red':'green'}"><b>${fmt(p[rule.key],1)}%</b><small>${rule.hit(p[rule.key],p)?'命中':'未命中'}</small></div>`)]))}</div><p class="ir-platform-note">红色表示该平台触发对应条件，绿色表示未触发；同一条件在多个平台命中仍计为1项，库存和货值按SPU计一次。</p>${table(['其他判定指标','当前值','高危条件','判定结果'],[['当月下架与冻结次数',Number.isFinite(r.violationCount)?r.violationCount+'次':'—',brcDescribe('stock.violations'),irReasons(r).some(reason=>reason.priority===1)],['滞销品',r.slow?'是':'否','是',r.slow]].map(([n,v,t,hit])=>[n,`<span class="${hit?'red':'green'}">${v}</span>`,t,`<span class="tag ${hit?'red':'green'}">${hit?'命中':'未命中'}</span>`]))}`}
function irRules(){return '高危品库存＝仓内库存＋工厂库存＋在制物料；在制物料取值为新机未交付数量。三类数量按独立库存范围计入，避免重复。高危品货值＝高危品库存×财务价（含税含品牌）。货值按各SPU逐项计算后汇总，金额单位为万元，财务价单位为元/件。利润率、退货率、已收退货率分别按抖音、快手、视频号、天猫、京东、拼多多计算；任一平台触发对应条件即命中该项，界面列出触发平台。满足任一类即入榜：高危库存条件组（'+brcResultText('stock-platform')+'）；滞销品。原因优先级：违规红色＞利润率'+brcDescribe('stock.profit')+'＞退货率'+brcDescribe('stock.return')+'＞已收退货率'+brcDescribe('stock.received')+'＞滞销品；列表始终按高危品货值降序排列。多项命中只计一次库存与货值。风险等级沿用演示分级：违规红色为P1，其他比率异常为P2，仅滞销为P3。仓内库存沿用产品台账，工厂、在制、财务价及风险判定指标为补充演示数据。'}
function irLedger(){const slowIds=new Set(srRows().map(r=>r.ledgerId));return inventoryProductLedger().map((r,i)=>{
 const warehouse=r.num,factory=Math.round(r.num*(.12+(i%4)*.04)),undelivered=Math.round(r.num*(.06+(i%3)*.03)),totalUnits=warehouse+factory+undelivered,financePriceCents=r.num?Math.round(r.amountCents*10000/r.num):0,goodsValueCents=totalUnits*financePriceCents;
 const facts={violation:i%8===0?'红色':i%8===1?'黄色':'正常',profitRate:[8,10,14,9,16,7,11,13][i%8],returnRate:[62,55,40,58,22,18,50,25][i%8],receivedRate:[32,30,20,35,12,8,29,15][i%8],slow:slowIds.has(r.id)};
 facts.violationCount=i%8===0?3:i%8===1?1:0;
 facts.platformMetrics=irPlatformData(facts,i);
 const reasons=irReasons(facts),amount=goodsValueCents/1000000,stale=r.staleCents/100,staleRatio=amount?stale/amount*100:0,level=reasons.some(x=>x.priority===1)?'P1':reasons.some(x=>x.priority<5)?'P2':'P3';
 return {...r,...facts,id:1000+i,ledgerId:r.id,spu:r.spuCode||r.model,attribute:srAttribute(r.name),brandIndex:r.brand,brand:brands[r.brand],channel:'多渠道',owner:aiOwners[r.chain],warehouse,factory,undelivered,totalUnits,financePriceCents,goodsValueCents,reasons,amount,stale,staleRatio,level,metric:amount,value:fmt(amount,2)+' 万元',desc:reasons.map(irReasonText).join('；'),cutoff:bounds().cutoff};
 })}
function irRows(){return irLedger().filter(r=>r.reasons.length&&r.totalUnits>0).sort((a,b)=>b.goodsValueCents-a.goodsValueCents||a.id-b.id)}
riskRows=function(k){return k===3?srSeasonFilter(3,irRows()):irOriginalRows(k)};
function irSum(rows){const sum=k=>rows.reduce((n,r)=>n+r[k],0);return{count:rows.length,warehouse:sum('warehouse'),factory:sum('factory'),undelivered:sum('undelivered'),totalUnits:sum('totalUnits'),goodsValueCents:sum('goodsValueCents')}}
function irGroups(rows,dimension){const groups=new Map();rows.forEach(r=>{const key=dimension==='chain'?r.chain:dimension==='brand'?r.brand:r.spuId;if(!groups.has(key))groups.set(key,{key,name:dimension==='chain'?chains[r.chain]:dimension==='brand'?r.brand:r.name,rows:[]});groups.get(key).rows.push(r)});return [...groups.values()].map(g=>({...g,...irSum(g.rows)})).sort((a,b)=>b.goodsValueCents-a.goodsValueCents||String(a.key).localeCompare(String(b.key)))}
function irTabs(active){return `<div class="ir-dimensions" role="group" aria-label="库存汇总维度">${[['spu','按 SPU'],['chain','按链群（链条）'],['brand','按品牌']].map(([key,label])=>`<button class="btn small ${key===active?'primary':''}" data-ir-dimension="${key}" aria-pressed="${key===active}">${label}</button>`).join('')}</div>`}
function irReasonTags(r){return r.reasons.map((x,i)=>`<span class="tag ir-reason-tag ${i===0?'red':'orange'}">${esc(x.label)}${x.platforms?.length?`<small>平台：${x.platforms.join('、')}</small>`:''}</span>`).join(' ')}
const irOriginalOpen=openRisk;
openRisk=function(k){if(k!==3)return irOriginalOpen(k);withPeriod('risk',()=>irOpenList())};
function irOpenList(){const rows=riskRows(3),b=bounds(),sum=irSum(rows);let page=1,dimension='spu';
 openModal('库存风险榜 · 完整榜单',`<div class="br-list-tools"><label>产品属性 <select data-risk-season="3" data-season-list="true">${srSeasonOptions(3)}</select></label><span class="note">库存截至 ${b.cutoff} · 按高危品货值从高到低排序</span></div><div class="ir-summary-metrics"><div><small>高危产品</small><strong>${sum.count}<em>个 SPU</em></strong></div><div><small>高危品库存</small><strong>${fmt(sum.totalUnits)}<em>件</em></strong></div><div><small>高危品货值</small><strong class="red">${fmt(sum.goodsValueCents/1000000,2)}<em>万元</em></strong></div></div><div id="ir-dimension-tabs"></div><div class="br-table ir-new-table" id="ir-list-table"></div><div id="ir-pagination"></div><details class="br-rules"><summary>指标口径与高危品判定</summary><p>${irRules()}</p></details>`,false,'任一风险命中即入榜 · 金额按财务价（含税含品牌）计算');
 
 const headers=()=>dimension==='spu'?['序号','产品 / SPU / 型号','链群（链条）','品牌','高危品库存','财务价（含税含品牌）','高危品货值','库存周转率','呆滞占比','风险等级','风险原因（按优先级）','详情']:['序号',dimension==='chain'?'链群（链条）':'品牌','高危SPU数','仓内库存','工厂库存','在制物料','高危品库存','高危品货值','详情'];
 function fill(){const data=irGroups(rows,dimension),pages=Math.max(1,Math.ceil(data.length/listPageSize('ir-pagination',20)));page=Math.max(1,Math.min(page,pages));$('#ir-dimension-tabs').innerHTML=irTabs(dimension);$('#ir-list-table').innerHTML=data.length?table(headers(),data.slice((page-1)*listPageSize('ir-pagination',20),page*listPageSize('ir-pagination',20)).map((g,i)=>{const r=g.rows[0];return dimension==='spu'?[(page-1)*listPageSize('ir-pagination',20)+i+1,`<div class="br-product-name">${riskThumbnail(r.name)}<div><b>${esc(r.name)}</b><small>${r.spu}</small></div></div>`,chains[r.chain],r.brand,fmt(g.totalUnits)+' 件',fmt(r.financePriceCents/100,2)+' 元/件',`<b class="red">${pfMoneyYuan((g.goodsValueCents/1000000)*10000)}</b>`,r.turn===null?'—':fmt(r.turn,2)+' 次/'+({day:'期间',month:'月',quarter:'季',year:'年'}[periodFor('risk').mode]),fmt(r.staleRatio,1)+'%',brLevel(r.level),`<div class="br-risk-tags">${irReasonTags(r)}</div>`,`<button class="link" data-riskitem="3,${r.id}">查看详情</button>`]:[(page-1)*listPageSize('ir-pagination',20)+i+1,g.name,g.count,fmt(g.warehouse)+' 件',fmt(g.factory)+' 件',fmt(g.undelivered)+' 件',fmt(g.totalUnits)+' 件',`<b class="red">${pfMoneyYuan((g.goodsValueCents/1000000)*10000)}</b>`,`<button class="link" data-ir-group="${esc(String(g.key))}">查看明细</button>`]})):'<div class="empty">当前范围暂无高危库存产品</div>';mountListPager($('#ir-pagination'),data.length,page,next=>{page=next;fill()});$('#ir-dimension-tabs').onclick=e=>{const bt=e.target.closest('[data-ir-dimension]');if(bt){dimension=bt.dataset.irDimension;page=1;fill()}};$('#ir-list-table').onclick=e=>{const bt=e.target.closest('[data-ir-group]');if(bt){const group=data.find(g=>String(g.key)===bt.dataset.irGroup);withPeriod('risk',()=>irGroupDetail(group))}};
 
 }fill();
}
function irSummaryMarkup(){return '<section class="ir-detail-summary"><h3>高危库存汇总明细</h3><div id="ir-detail-tabs"></div><div id="ir-detail-scope" class="note"></div><div id="ir-detail-totals" class="ir-summary-metrics"></div><div class="br-table ir-breakdown" id="ir-detail-table"></div><div id="ir-detail-pages"></div></section>'}
function irMountSummary(rows,scopeLabel='当前范围'){let dimension='spu',page=1;function render(){const groups=irGroups(rows,dimension),total=irSum(rows),pages=Math.max(1,Math.ceil(groups.length/listPageSize('ir-detail-pages',20)));page=Math.min(page,pages);$('#ir-detail-tabs').innerHTML=irTabs(dimension);$('#ir-detail-scope').textContent=`${scopeLabel} ${total.count} 个高危 SPU · 按高危品货值降序 · 同一 SPU 多风险不重复计数`;$('#ir-detail-totals').innerHTML=[['仓内库存',fmt(total.warehouse)+' 件'],['工厂库存',fmt(total.factory)+' 件'],['在制物料（新机未交付）',fmt(total.undelivered)+' 件'],['高危品库存',fmt(total.totalUnits)+' 件'],['高危品货值',fmt(total.goodsValueCents/1000000,2)+' 万元']].map(([n,v])=>`<div><small>${n}</small><strong>${v}</strong></div>`).join('');$('#ir-detail-table').innerHTML=table([dimension==='spu'?'产品 / SPU':dimension==='chain'?'链群（链条）':'品牌','高危SPU数','仓内','工厂','在制物料','高危品库存','高危品货值'],groups.slice((page-1)*listPageSize('ir-detail-pages',20),page*listPageSize('ir-detail-pages',20)).map(g=>[dimension==='spu'?`<div class="br-product-name">${riskThumbnail(g.rows[0].name)}<span>${esc(g.name)}<small>${g.key} · ${g.rows[0].brand}</small></span></div>`:g.name,g.count,stockQuantity(g.warehouse),stockQuantity(g.factory),stockQuantity(g.undelivered),stockQuantity(g.totalUnits),`<b class="red">${pfMoneyYuan((g.goodsValueCents/1000000)*10000)}</b>`]));mountListPager($('#ir-detail-pages'),groups.length,page,next=>{page=next;render()});$('#ir-detail-tabs').onclick=e=>{const bt=e.target.closest('[data-ir-dimension]');if(bt){dimension=bt.dataset.irDimension;page=1;render()}}}render()}
