 const days=Math.max(0,[145,105,82,61,46,33][i%6]+elapsed),amount=r.staleCents/100,attribute=srAttribute(r.name),level=days>=90?'P1':days>=60?'P2':'P3',staleUnits=Number.isFinite(r.staleUnits)?r.staleUnits:Math.round(r.num*r.staleCents/Math.max(1,r.amountCents));
