 function fill(){const pages=Math.max(1,Math.ceil(rows.length/listPageSize('sr-pagination',20)));page=Math.max(1,Math.min(page,pages));$('#sr-list-table').innerHTML=rows.length?table(heads,rows.slice((page-1)*listPageSize('sr-pagination',20),page*listPageSize('sr-pagination',20)).map((r,i)=>[(page-1)*listPageSize('sr-pagination',20)+i+1,`<div class="br-product-name">${riskThumbnail(r.name)}<b>${esc(r.name)}</b></div>`,r.model,chains[r.chain],`<span class="tag ${r.attribute!=='四季品'?'orange':''}">${r.attribute}</span>`,`<strong class="red">${pfMoneyYuan((r.amount)*10000)}</strong>`,`<strong class="${r.level==='P1'?'red':'orange'}">${r.days} 天</strong>`,brLevel(r.level),`<button class="link" data-riskitem="4,${r.id}">查看详情</button>`])):'<div class="empty">当前周期暂无滞销风险产品</div>';mountListPager($('#sr-pagination'),rows.length,page,next=>{page=next;fill()});}
