function ipRefurbSampleOrders(record,index,month){
 const spuId=String(record.spuId||record.model||record.id),start=month+'-01';
 return Array.from({length:2+index%2},(_,i)=>{
  const completedAt=shiftDate(start,(index+i*7)%18),days=[12,20,32,39,40,44,45,59,60,72][(index+i)%10];
  const quotedAt=shiftDate(completedAt,-days),initiatedAt=shiftDate(quotedAt,-2);
  return {requisitionId:'REF-'+spuId+'-'+month+'-'+(i+1),spuId,initiatedAt,quotedAt,completedAt:(index+i)%7===0?null:completedAt};
 });
}


// Inventory balances retain the original ledger; service metrics share dated facts.
function ipPeriod(){const p=periodFor(),b=bounds(p),monthStart=b.cutoff.slice(0,7)+'-01';const factor=months(p).reduce((n,m)=>{const last=new Date(Date.UTC(p.year,m,0)).getUTCDate(),elapsed=`${p.year}-${String(m).padStart(2,'0')}`===b.cutoff.slice(0,7)?+b.cutoff.slice(8):last;return n+elapsed/last},0);return{...b,monthStart,monthLabel:b.cutoff.slice(0,7),factor,unit:{recent30:'30天',month:'月',quarter:'季',year:'年'}[p.mode]}}
const ipBaseLedger=inventoryProductLedger;
inventoryProductLedger=function(){
 const scope=ipPeriod(),rows=ipBaseLedger(),key='inventory-month-service',previous=localPeriods[key];let monthly=[];
 if(scope.start<=scope.cutoff){localPeriods[key]={year:+scope.cutoff.slice(0,4),mode:'month',value:+scope.cutoff.slice(5,7)};try{monthly=withPeriod(key,()=>ipBaseLedger())}finally{if(previous)localPeriods[key]=previous;else delete localPeriods[key]}}
 const monthlyMap=new Map(monthly.map(r=>[r.id,r]));
 return rows.map((r,i)=>{const month=monthlyMap.get(r.id),active=scope.start<=scope.cutoff&&r.refDue>0;
  const refurbOrders=active?ipRefurbSampleOrders(r,i,scope.monthLabel):[];
  // 保留原未翻新SKU样例及占比，不能用未完成请购单数量替代。
  const unrefurbishedSkus=active?upStockSkus(r).map((sku,j)=>({skuId:sku.skuId,pending:(i*4+j)%11===10})):[];
  return{...r,refurbOrders,unrefurbishedSkus,monthOn:month?.on||0,monthDue:month?.due||0,monthlyDelivery:month?.due?month.on/month.due*100:null};
 });
};
const ipBaseSum=inventoryProductSum;
inventoryProductSum=function(rows){const base=ipBaseSum(rows),monthOn=targetSum(rows.map(r=>r.monthOn||0)),monthDue=targetSum(rows.map(r=>r.monthDue||0));return{...base,monthOn,monthDue,monthlyDelivery:monthDue?monthOn/monthDue*100:null}};
// 库存余额保持最新，周转/交付/翻新取所选期间。
const ipDefaultMetricPeriod=()=>({mode:'quarter',year:+DATA_CUTOFF.slice(0,4),value:Math.ceil(+DATA_CUTOFF.slice(5,7)/3)});
let ipMetricPeriod=ipDefaultMetricPeriod();
function ipWithMetricPeriod(period,run){
 const key='inventory-metrics',prior=localPeriods[key];localPeriods[key]={...period};
 try{return withPeriod(key,run)}finally{if(prior)localPeriods[key]=prior;else delete localPeriods[key]}
}
function ipMetricPeriodMarkup(period){
 const html=periodControls('inventory',{period,label:'库存指标',follow:false});
 return `<div class="ip-metric-period"><small class="ip-metric-scope">筛选影响：库存周转率、交付及时率、翻新闭环率</small>${html.replaceAll('data-time-','data-ip-time-')}</div>`;
}
function ipMountMetricPeriod(host,period,onChange){
 host.onclick=event=>{
  const button=event.target.closest('[data-ip-time-mode]');if(!button)return;
  event.preventDefault();event.stopPropagation();
  const end=bounds(period).cutoff,month=period.mode==='quarter'?period.value*3:period.mode==='year'?12:+end.slice(5,7),mode=button.dataset.ipTimeMode;
  onChange(normalizePeriod({mode,year:period.year,value:mode==='month'?month:mode==='quarter'?Math.ceil(month/3):1}));
 };
 host.onchange=event=>{
  const select=event.target;if(!select.matches('[data-ip-time-year],[data-ip-time-value]'))return;
  event.stopPropagation();const next={...period};next[select.hasAttribute('data-ip-time-year')?'year':'value']=+select.value;onChange(normalizePeriod(next));
 };
}
// 期间成本/交付/翻新从日期台账读取，库存余额保持最新。
const ipMetricMonthCache=boundedCache(36),ipMetricCostCache=boundedCache(24);
function ipMetricMonths(start,end){
 const keys=[];let cursor=start.slice(0,7)+'-01';
 while(cursor<=end){keys.push(cursor.slice(0,7));const d=new Date(cursor+'T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);cursor=iso(d)}return keys;
}
function ipMetricMonth(month){
 const cached=ipMetricMonthCache.get(month);if(cached)return cached;
 const period={mode:'month',year:+month.slice(0,4),value:+month.slice(5,7)},range=bounds(period);
 const rows=ipWithMetricPeriod(period,()=>upWithRange({start:range.start,end:range.cutoff},()=>inventoryProductLedger()));
 const days=aiFlowDayDiff(range.start,range.cutoff)+1;
 const result={...range,rows:new Map(rows.map(row=>{
  // 本地台账的本月累计交付按有效日整数分配，切换期间不改变已生成的日期事实。
  const planned=splitTarget(row.monthDue,Array(days).fill(1)),delivered=splitTarget(row.monthOn,planned);
  return [row.spuId,{...row,planned,delivered}];
 }))};ipMetricMonthCache.set(month,result);return result;
}
function ipMetricRecords(records,period){
 const range=bounds(period),months=ipMetricMonths(range.start,range.cutoff).map(ipMetricMonth);
 const key=range.start+'|'+range.cutoff;let costs=ipMetricCostCache.get(key);
 if(!costs){costs=new Map(upWithRange({start:range.start,end:range.cutoff},()=>inventoryProductLedger()).map(row=>[row.spuId,{cost:row.cost,avg:row.avg}]));ipMetricCostCache.set(key,costs)}
 return records.map(record=>{
  let deliveryOn=0,deliveryDue=0;
  for(const month of months){
   const row=month.rows.get(record.spuId);if(!row)continue;
   const start=range.start>month.start?range.start:month.start,end=range.cutoff<month.cutoff?range.cutoff:month.cutoff;
   const first=aiFlowDayDiff(month.start,start),last=aiFlowDayDiff(month.start,end);
   deliveryDue+=targetSum(row.planned.slice(first,last+1));deliveryOn+=targetSum(row.delivered.slice(first,last+1));
  }
  const refurbOrders=ipRefurbPeriodOrders(months.flatMap(month=>month.rows.get(record.spuId)?.refurbOrders||[]),range.start,range.cutoff);
  const {cost=0,avg=0}=costs.get(record.spuId)||{};
  const row={...record,cost,avg,deliveryOn,deliveryDue,refurbOrders,refurbEnd:range.cutoff};
  return {...row,...ipStockSum([row])};
 });
}
