function cwProduct(r){return `<div class="cw-product">${cwProductImage(r)}<span>${esc(r.name)}<small>${esc(r.model||'')}</small></span></div>`;}
function cwMetrics(items){return `<div class="cw-metrics">${items.map(([label,value,tone=''])=>`<div><small>${label}</small><span class="${tone}">${value}</span></div>`).join('')}</div>`;}
