function cwResultHTML(result,detailed=false){return `<div class="cw-result">${result.alerts?.length?result.alerts.map(a=>`<div class="cw-alert"><span>${esc(a.label)}</span><b>${esc(a.value)}</b>${a.extra?`<small>${esc(a.extra)}</small>`:''}${detailed?`<small class="cw-basis">${esc(a.basis)}</small>`:''}</div>`).join(''):`<span class="tag ${result.status==='正常'?'green':'orange'}">${result.status}</span>`}${result.pending.map(h=>`<small class="orange">${esc(h)}</small>`).join('')}</div>`;}

