function cwOpen(type=cwSelected){cwSelected=type;let status='预警',query='',page=1;const period={...pbPeriod('risk')};const paint=()=>{const all=cwRows(type,period),rows=all.filter(r=>(status==='全部'||(status==='待补数据'?r.result.pending.length>0:r.result.status===status))&&(!query||[r.owner,r.name,r.model,r.supplier,r.category].join(' ').includes(query))),pages=Math.max(1,Math.ceil(rows.length/listPageSize('cw-pages',20)));page=Math.min(page,pages);$('#cw-summary').innerHTML=`<span>${cwDataMode==='demo'?'测试数据':'已导入'} <b>${all.length}</b> 条</span><span class="red">预警 ${all.filter(r=>r.result.status==='预警').length}</span><span class="orange">待补数据 ${all.filter(r=>r.result.pending.length).length}</span><span class="green">正常 ${all.filter(r=>r.result.status==='正常').length}</span>`;$('#cw-rules').textContent=cwRules[type]+' 数据来源：'+cwSources[type];$('#cw-table').innerHTML=dpTable(cwHeaders(type),rows.slice((page-1)*listPageSize('cw-pages',20),page*listPageSize('cw-pages',20)).map(cwCells));const heads=cwHeaders(type);$$('#cw-table tbody tr').forEach(tr=>[...tr.cells].forEach((td,i)=>td.dataset.label=heads[i]||''));if(!all.length)$('#cw-table').innerHTML='<div class="cw-empty"><b>当前范围尚无导入数据</b><p>下载本类模板，填写后导入即可自动判定预警。</p><button class="btn primary" id="cw-empty-import">导入数据</button></div>';else if(!rows.length)$('#cw-table').innerHTML='<div class="cw-empty">当前筛选无匹配记录，可切换“全部”查看已导入数据。</div>';mountListPager($('#cw-pages'),rows.length,page,next=>{page=next;paint()});$('#cw-empty-import')?.addEventListener('click',()=>cwImport(type));$('#cw-table').onclick=e=>{const b=e.target.closest('[data-cw-detail]');if(b){const r=rows.find(r=>cwIdentity(type,r)===b.dataset.cwDetail);if(r)cwDetail(r)}};$('#dialogsub').textContent=periodLabel(period)+' · 截至 '+cwRange(period).cutoff+(cwDataMode==='demo'?' · 模拟数据，仅供演示':' · 手工导入台账');};
 openModal('成本管控预警 · 全部',`<div class="cw-toolbar"><label>数据来源<select id="cw-source"><option value="demo" ${cwDataMode==='demo'?'selected':''}>测试数据</option><option value="imported" ${cwDataMode==='imported'?'selected':''}>导入数据</option></select></label><label>预警类型<select id="cw-type">${cwTypes.map((n,i)=>`<option value="${i}" ${i===type?'selected':''}>${n}</option>`).join('')}</select></label><label>判定结果<select id="cw-status">${['预警','全部','正常','待补数据'].map(n=>`<option>${n}</option>`).join('')}</select></label><input id="cw-query" type="search" placeholder="采购人员 / 产品 / 供应商"><button class="btn" id="cw-template">下载模板</button><button class="btn" id="cw-demo-file">下载测试数据</button><button class="btn primary" id="cw-import">导入数据</button><button type="button" class="link" data-ui-import-history="成本预警">导入记录</button></div><div class="cw-summary" id="cw-summary"></div><details class="cw-rulebox"><summary>指标口径</summary><p id="cw-rules"></p><p>金额单位：元；百分比5%填5或5%。按记录编号、报价阶段和数据日期识别重复，同日重导更新；历史快照保留。</p></details><div id="cw-table"></div><div id="cw-pages"></div>`);$('#dialog').classList.add('cw-dialog');$('#cw-type').onchange=e=>{type=+e.target.value;cwSelected=type;page=1;paint()};$('#cw-status').onchange=e=>{status=e.target.value;page=1;paint()};$('#cw-query').oninput=e=>{query=e.target.value.trim();page=1;paint()};$('#cw-source').onchange=e=>{cwSetDataMode(e.target.value);page=1;renderPurchasing();paint()};$('#cw-demo-file').onclick=()=>cwDownloadDemo(type);$('#cw-template').onclick=()=>cwTemplate(type);$('#cw-import').onclick=()=>cwImport(type);paint();}
function cwDetail(r){const result=r.result,fields=cwFields[r.type].filter(f=>!['image','name','model'].includes(f.key)&&!f.computed),plan=[['核对立项目标与当前报价阶段的成本、四项费率。','与供应商复核报价差额并提交议价方案。','更新审批台账，成本与费率达标后复核。'],['确认年度降本目标与实际完成额。','按进度缺口拆解议价、替代料及采购量计划。','回填降本台账，复核实际进度是否追平。'],['核对约定台数、提货及已摊销金额。','通知供应商停止继续分摊，确认后续采购单价。','核对结算；对超摊部分办理冲回。'],['复核联检确认费与预估费差额。','核查工厂退货及分摊凭证，确认降费方案。','更新实际分摊翻新费，复核费率达标。'],['核对物料规格、价格单位与取价日期。','采购评估备货节奏、替代料及锁价方案。','更新同口径价格记录并复查波动。']][r.type];openModal(r.name+' · 成本预警详情',`<div class="cw-detail-top">${r.type===4?`<h2>${esc(r.name)}</h2>`:cwProduct(r)}${cwResultHTML(result,true)}</div><div class="cw-rulebox"><b>判定依据</b><p>${esc(cwRules[r.type])}</p>${r.type===2&&result.d.excess?`<p class="red">已超摊 ${cwNumber(result.d.excess,'元')}，需核对结算。</p>`:''}</div><div class="cw-detail-fields">${fields.map(f=>`<div><small>${f.label}</small><b>${esc(String(r[f.key]??'—'))}${f.type==='percent'?'%':''}</b></div>`).join('')}${Object.entries(result.d).map(([key,v])=>`<div><small>${({costDelta:'实际－目标成本（元）',unitSavingRate:'单台累计降本率（%）',actualProgress:'实际完成进度（%）',expectedProgress:'应完成进度（%）',remainingUnits:'剩余摊销台数',remainingAmount:'剩余摊销金额（元）',excess:'超摊金额（元）',actualRefurbRate:'实际翻新费率（%）',change:'涨跌金额',changeRate:'当日涨跌幅度（%）',averageChange:'30天均价波动（%）'})[key]}</small><b>${cwNumber(v)}</b></div>`).join('')}</div><div class="cw-plan"><b>处理建议</b>${plan.map((line,i)=>`<p>${i+1}. ${line}</p>`).join('')}</div>`,false,r.date+' · '+cwTypes[r.type]+(r.demo?' · 模拟数据，仅供演示':''));$('#dialog').classList.add('cw-dialog');$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn" id="cw-back">返回列表</button>');$('#cw-back').onclick=()=>cwOpen(r.type);}
