function prSharedCard(k,rows,procurement=false){const delayed=k===5,title=procurement?(delayed?'项目延期预警':'亏损产品预警'):riskTitles[k],season=procurement?pdrSeason:riskSeasonState[5];return `<div class="rhead"><h3><i class="riskbadge"></i>${title}</h3><button class="link" ${procurement?`data-pr-open="${k}"`:`data-risk="${k}"`}>全部 ${rows.length} ›</button></div>${delayed?`<div class="qr-card-filter"><label class="sr-filter-label">产品属性 <select ${procurement?'data-pdr-season':'data-risk-season="5"'} aria-label="延期项目产品属性">${srSeasonOptions(5,season,!procurement)}</select></label></div>`:''}<div class="riskfoot" style="margin:0 0 3px"><span>风险对象</span><span>${delayed?'延迟天数':'月度亏损金额'}</span></div>${rows.slice(0,6).map((r,i)=>`<button class="riskline" ${procurement?`data-pr-detail="${k},${r.id}"`:`data-riskitem="${k},${r.id}"`}><span class="rank ${i<3?'top':''}">${String(i+1).padStart(2,'0')}</span>${riskThumbnail(r.name)}<span class="rname" title="${esc(r.name)}">${esc(r.name)}</span><span class="rvalue">${r.value}</span></button>`).join('')||'<div class="empty">当前范围暂无风险项目</div>'}`;}
