// Daily sales/returns are shared with the new-product trend generator.
let pnrState=null;
function pnrDecision(rate,target){
 if(!Number.isFinite(rate)||!Number.isFinite(target)||target<0)return {light:'暂无数据',tone:'muted',warning:false,delta:null};
 const delta=rate-target,tone=brcBandTone('return.return',delta);
 return {light:({red:'红灯',yellow:'黄灯',green:'绿灯'})[tone],tone:tone==='yellow'?'orange':tone,warning:['red','yellow'].includes(tone),delta};
}
function pnrGap(r){if(r.delta===null)return '无销量，不判灯';if(Math.abs(r.delta)<1e-9)return '已达目标上限';const gap=Math.abs(r.delta),value=gap<.05?'＜0.1%':fmt(gap,1)+'%';return (r.delta>0?'超目标 ':'低于目标 ')+value;}
function pnrRateHTML(r){return `<strong class="pnr-value ${r.tone}">${r.returnRate===null?'—':fmt(r.returnRate,1)+'%'}</strong><small class="pnr-light ${r.tone}">● ${r.light} · ${pnrGap(r)}</small>`;}
function pnrContext(){const period={...pbPeriod('risk')},key=periodKey(period),limit=bounds(period).cutoff;if(!pnrState||pnrState.key!==key)pnrState={key,period,limit,mode:'30',start:shiftDate(limit,-29),end:limit,platform:'all'};return pnrState;}
