function pnrRows(context=pnrContext(),includeNormal=false){return pnrRun(context,()=>newLaunchFacts(productRows(true)).map(p=>{const s=pbSupplierFor(p.chain,p.id),series=pnrSeries(p,context.start,context.end,p.actualLaunch),totals=newTrendTotals([series]),target=qrbTarget(p,p.channel),decision=pnrDecision(totals.returnRate,target);return {...p,key:'NEW-RETURN-'+context.start+'-'+context.end+'-'+p.id,kind:'new-return',baseReturnRate:p.returnRate,owner:s.owner,tier:s.tier,supplier:s.name,supplierKey:s.key,launch:p.actualLaunch,days:Math.max(0,pnrDays(p.actualLaunch,context.end)),volume:totals.volume,returned:totals.returned,returnRate:totals.returnRate,target,...decision,metric:totals.returnRate===null?'—':fmt(totals.returnRate,1)+'%',level:decision.tone==='red'?'高危':decision.tone==='orange'?'中风险':'低风险',date:context.end,due:shiftDate(context.end,7),series,context:{...context,period:{...context.period}},source:'新品趋势每日销量与退货件数 · 演示数据',issue:`${p.channel}总退货率 ${totals.returnRate===null?'—':fmt(totals.returnRate,1)+'%'}，目标 ${fmt(target,1)}%，${decision.light}；销量 ${fmt(totals.volume)} 件，退货 ${fmt(totals.returned)} 件。`};}).filter(pbScope).filter(r=>includeNormal||r.warning).sort((a,b)=>(b.tone==='red')-(a.tone==='red')||(b.delta??-Infinity)-(a.delta??-Infinity)||b.volume-a.volume));}
