function pnrDateControls(context){return `<div class="pnr-time"><div class="nt-range-picker"><button id="pnr-recent" aria-pressed="${context.mode==='30'}">近30天</button><button id="pnr-custom" aria-pressed="${context.mode==='custom'}">自定义日期</button></div><form id="pnr-date-form" ${context.mode==='30'?'hidden':''}><label>开始日期<input type="date" id="pnr-start" value="${context.start}" min="${context.period.year-1}-01-01" max="${context.limit}" required></label><span>至</span><label>结束日期<input type="date" id="pnr-end" value="${context.end}" min="${context.period.year-1}-01-01" max="${context.limit}" required></label><button type="submit" class="btn small">查询</button></form><span class="note">${context.start} — ${context.end}</span></div><p id="pnr-date-error" class="red" role="alert"></p>`;}
