function pnrOpen(context=pnrContext()){pbModalSection='risk';const productFilters=pfDefaults();let page=1;const heads=['序号','产品名称 / 型号','上线天数','销量','总退货率','总退货率目标','平台','操作'];openModal('新品高退货率 · 全部',`${pnrDateControls(context)}<div class="pnr-tools"><label>平台 <select id="pnr-platform"><option value="all">全部平台</option>${channels.map(n=>`<option ${context.platform===n?'selected':''}>${n}</option>`).join('')}</select></label><span class="note">红灯优先 · 按目标差额排序 · 演示数据</span></div><div id="pnr-table"></div><div id="pnr-pages"></div><details class="pnr-rules"><summary>指标口径</summary><p>总退货率＝所选日期内退货件数 ÷ 同期销量，按件数加权。上线天数统计至所选结束日期。按产品、平台的总退货率目标判灯：偏差＝实际总退率－目标总退率（%）；${brcBandText('return.return')}。本榜只展示红、黄灯；无销量不判灯。目标沿用总退货率目标配置，未设置时使用演示目标。详情趋势展示截至所选结束日期的近30天，每日数据与新品趋势图共用。</p></details>`,false,`${context.start} — ${context.end} · 新品销售与退货`);$('#dialog').classList.add('pnr-dialog');
 function fill(){const rows=pnrFiltered(context).filter(r=>pfMatches(r,productFilters)),pages=Math.max(1,Math.ceil(rows.length/listPageSize('pnr-pages',20)));page=Math.max(1,Math.min(page,pages));$('#pnr-table').innerHTML=rows.length?table(heads,rows.slice((page-1)*listPageSize('pnr-pages',20),page*listPageSize('pnr-pages',20)).map((r,i)=>[(page-1)*listPageSize('pnr-pages',20)+i+1,pbProduct(r),r.days+' 天',fmt(r.volume)+' 件',pnrRateHTML(r),fmt(r.target,1)+'%',esc(r.channel),`<button class="link" data-pnr-detail="${r.id}">查看详情</button>`])):'<div class="empty">当前日期及平台暂无新品高退货率预警</div>';$('#pnr-table').querySelectorAll('table').forEach(rdTable);mountListPager($('#pnr-pages'),rows.length,page,next=>{page=next;fill()});$('#pnr-table').onclick=e=>{const b=e.target.closest('[data-pnr-detail]');if(b)pnrDetail(rows.find(r=>r.id===+b.dataset.pnrDetail),context)};}
 $('#pnr-platform').onchange=e=>{context.platform=e.target.value;page=1;fill();renderPurchasing()};pnrBindDates(context,()=>pnrOpen(context));pfMount($('.pnr-tools'),productFilters,()=>{page=1;fill()});fill();
}
function pnrDetail(r,context=r?.context){if(!r)return;pbModalSection='risk';const trendStart=shiftDate(context.end,-29),series=pnrSeries(r,trendStart,context.end,r.launch),metrics=[['上线天数',r.days+' 天'],['销量',fmt(r.volume)+' 件'],['总退货率',r.returnRate===null?'—':fmt(r.returnRate,1)+'%'],['总退货率目标',fmt(r.target,1)+'%'],['平台',esc(r.channel)]];
 openModal(r.name+' · 新品高退货率详情',`<div class="dp-detail-head pnr-hero">${riskThumbnail(r.name)}<div><h2>${esc(r.name)}</h2><p>${esc(r.model)} · ${esc(chains[r.chain])} · ${esc(r.brand)}</p><small>上线日期 ${r.launch}</small></div></div>${pnrDateControls(context)}<p class="note">核心指标统计：${context.start} — ${context.end}</p><div class="pnr-metrics">${metrics.map(([n,v])=>`<div><small>${n}</small><strong class="${n==='总退货率'?r.tone:''}">${v}</strong></div>`).join('')}</div><div class="pnr-caption"><span>采购责任人：${esc(r.owner)}</span><span>退货件数：${fmt(r.returned)} 件</span><span class="pnr-light ${r.tone}">● ${r.light} · ${pnrGap(r)}</span></div><div class="pnr-charts">${[{key:'returnRate',name:'总退货率',unit:'%',digits:2},{key:'volume',name:'销量',unit:'件',digits:0}].map(m=>`<section class="nt-chart"><div class="nt-chart-heading"><h3>近30天${m.name}趋势</h3><span>${esc(r.channel)}</span></div><p class="note">${trendStart} — ${context.end}</p>${newTrendChart([{...series,color:m.key==='returnRate'?'#e56570':'#7885f5'}],m)}</section>`).join('')}</div>`,false,`${r.channel} · ${context.start} — ${context.end} · 演示数据`);$('#dialog').classList.add('pnr-dialog');$('#dialogactions').insertAdjacentHTML('afterbegin','<button id="pnr-back" class="btn small">返回列表</button><button id="pnr-dispatch" class="btn primary small">下发任务</button>');$('#pnr-dispatch').textContent=pbTask(r)?'跟进任务':'下发任务';$('#pnr-dispatch').onclick=()=>pnrRun(context,()=>{pbRemember(r);pbDispatch(r)});$('#pnr-back').onclick=()=>pnrOpen(context);pnrBindDates(context,()=>{const next=pnrRows(context,true).find(p=>p.id===r.id);if(next)pnrDetail(next,context);else pnrOpen(context)});
}
const pnrPreviousLists=pbRiskLists;pbRiskLists=function(includeClosed=false){const lists=pnrPreviousLists(includeClosed);lists[4]=pnrRows().filter(r=>includeClosed||!pbClosed(r));lists[4].forEach(pbRemember);return lists;};
