function paiSync(){const period=pbPeriod('ai'),key=periodKey(period),limit=bounds(period).cutoff;if(paiState.key!==key){Object.assign(paiState,{key,date:limit,month:limit.slice(0,7),page:1});}return {period,limit,min:period.year+'-01-01'};}
function paiRange(){const {limit,min}=paiSync();let start,end;if(paiState.mode==='all'){start=min;end=limit;}else if(paiState.mode==='month'){start=paiState.month+'-01';const [y,m]=paiState.month.split('-').map(Number);end=iso(new Date(Date.UTC(y,m,0)));}else if(paiState.mode==='week'){const day=new Date(paiState.date+'T00:00:00Z'),offset=(day.getUTCDay()+6)%7;start=shiftDate(paiState.date,-offset);end=shiftDate(start,6);}else start=end=paiState.date;return {start:start<min?min:start,end:end>limit?limit:end,plannedEnd:end,limit,min};}
function paiRun(range,fn){const oldBounds=bounds,oldRisk=pbState.periods.risk,oldAI=pbState.periods.ai,oldLocal=localPeriods['pb-ai'],period={year:+range.end.slice(0,4),mode:paiState.mode==='all'?'year':'month',value:paiState.mode==='all'?1:+range.end.slice(5,7)};pbState.periods.risk=period;pbState.periods.ai=period;localPeriods['pb-ai']=period;
 bounds=function(p=periodFor()){const b=oldBounds(p),cutoff=b.cutoff>range.end?range.end:b.cutoff;return {...b,cutoff,partial:b.end>cutoff};};
 try{return withPeriod('pb-ai',fn);}finally{bounds=oldBounds;if(oldRisk)pbState.periods.risk=oldRisk;else delete pbState.periods.risk;if(oldAI)pbState.periods.ai=oldAI;else delete pbState.periods.ai;if(oldLocal)localPeriods['pb-ai']=oldLocal;else delete localPeriods['pb-ai'];}
}
