function paiSelected(rows){return rows.filter(r=>r.kind===paiState.kind&&(r.kind!=='deviation'||((paiState.report==='all'||r.report.type===paiState.report)&&(paiState.finding==='all'||r.finding===paiState.finding))));}
function paiActions(r){return `<div class="ai-row-actions"><button class="link" data-pai-detail="${esc(r.id)}">查看详情</button><button class="btn soft small" data-pai-handle="${esc(r.id)}">${pbTask(r.raw)?'跟进任务':'立即处理'}</button></div>`;}
function paiTable(rows){const dev=paiState.kind==='deviation',heads=dev?['来源记录','链群 / 责任采购','工作记录摘要','AI 偏差分析','建议行动','操作']:['风险 / 优先级','链群','对应部门','责任采购','诊断明细与业务影响',paiState.kind==='priority'?'行动要求 / 计划完成':'建议行动','记录时间','操作'];const cells=rows.map(r=>dev?[`<span class="tag">${{daily:'日报',weekly:'周报',meeting:'会议记录'}[r.report.type]}</span><strong>${esc(r.report.title)}</strong><small>${esc(r.report.period)}</small>`,`${esc(chains[r.chain])}<small>采购部 · ${esc(r.owner)}</small>`,`<div class="deviation-excerpt"><p><b>计划</b>${esc(r.report.plan)}</p><p><b>实际</b>${esc(r.report.actual)}</p></div>`,`${deviationTag(r)}<p>${esc(r.report.basis)}</p>`,esc(r.action),paiActions(r)]:[`<span class="tag ${r.level==='P0'?'red':'orange'}">${r.level}</span><small>${esc(r.stage)}</small>`,esc(chains[r.chain]),'采购部',esc(r.owner),`<strong>${esc(r.subject)}</strong><p>${esc(r.problem)}</p>`,`<p>${esc(r.action)}</p>${paiState.kind==='priority'?'<small>计划完成：'+r.deadline+'</small>':''}`,r.date,paiActions(r)]);return `<div class="${dev?'deviation-table':'ai-detail-table ai-no-category'} pai-table">${rows.length?table(heads,cells):'<div class="empty">当前筛选范围暂无诊断记录</div>'}</div>`;}
pbRenderAI=function(){const range=paiRange(),rows=paiData(range),list=paiSelected(rows),count=k=>rows.filter(r=>r.kind===k&&(k!=='deviation'||r.finding==='deviation')).length,pages=Math.max(1,Math.ceil(list.length/listPageSize('pai-records',10)));paiState.page=Math.min(paiState.page,pages);paiVisible=new Map(rows.map(r=>[r.id,r]));const kind=paiKinds.find(k=>k[0]===paiState.kind),high=rows.filter(r=>r.level==='P0'&&r.finding!=='normal'&&r.finding!=='verify').length;
 return `<div class="pai-controls"><div class="ai-time-main"><div class="period-segment ai-time-segment">${[['day','日'],['week','周'],['month','月'],['all','总览']].map(([v,l])=>`<button data-pai-period="${v}" aria-pressed="${paiState.mode===v}">${l}</button>`).join('')}</div>${paiState.mode==='all'?'<span class="ai-date-cover">年度演示总览</span>':`<label class="ai-date-label">${paiState.mode==='month'?'月份':paiState.mode==='week'?'所在周':'日期'}<input data-pai-date type="${paiState.mode==='month'?'month':'date'}" min="${paiState.mode==='month'?range.min.slice(0,7):range.min}" max="${paiState.mode==='month'?range.limit.slice(0,7):range.limit}" value="${paiState.mode==='month'?paiState.month:paiState.date}"></label>`}<span class="ai-range-label">${range.start} — ${range.end}${range.plannedEnd>range.end?'<span class="tag orange">未结束</span>':''}</span></div><div class="ai-dimension-filters"><label>链群<select multiple data-pf-multiple data-pai-filter="chain"><option value="all">全部</option>${chains.map((c,i)=>`<option value="${i}" ${pfOptionSelected(paiState.chain,i)?'selected':''}>${c}</option>`).join('')}</select></label><label>部门 <span class="tag">采购部</span></label><label>责任采购<select data-pai-filter="owner"><option value="all">全部</option>${pbPeople.filter((n,i)=>pbScope({owner:n,chain:i%4,tier:pbState.tier==='all'?0:+pbState.tier})).map(n=>`<option ${paiState.owner===n?'selected':''}>${n}</option>`).join('')}</select></label><button class="link" data-pai-reset>重置筛选</button></div></div><div class="aigrid">${paiKinds.map(([key,title,unit],i)=>`<button type="button" class="aicard ${paiState.kind===key?'selected':''}" data-pai-kind="${key}" aria-pressed="${paiState.kind===key}"><h3>${title}</h3><div class="an num ${i===0?'red':i===2?'blue':''}">${count(key)}<span>${unit}</span></div><p>${['定位采购节点与项目延期','日报 / 周报 / 会议记录偏差分析','明确采购优先动作与完成期限','按采购风险安排人员与供应资源'][i]}</p></button>`).join('')}</div><div class="pai-summary"><span class="ai-logo" aria-hidden="true"><b>AI</b></span><p>采购部共 <b>${rows.length}</b> 条诊断记录，涉及 <b>${new Set(rows.map(r=>r.chain)).size}</b> 个链群、<b>${new Set(rows.map(r=>r.owner)).size}</b> 位采购人员；<b class="red">${high}</b> 条 P0。优先处理项目延期、供应储备缺口和执行偏差。</p></div><section class="ai-detail-block"><div class="ai-detail-heading"><div class="titlegroup"><span class="ai-detail-index">0${paiKinds.findIndex(k=>k[0]===paiState.kind)+1}</span><h3>${kind[1]}</h3><span class="tag">${list.length} 条</span></div></div>${paiState.kind==='deviation'?`<div class="deviation-filters"><div class="period-segment">${deviationSources.map(([key,label])=>`<button data-pai-report="${key}" aria-pressed="${paiState.report===key}">${label}<span>${rows.filter(r=>r.kind==='deviation'&&(key==='all'||r.report.type===key)).length}</span></button>`).join('')}</div><label>AI 判断<select data-pai-filter="finding">${deviationFindings.map(([key,label])=>`<option value="${key}" ${paiState.finding===key?'selected':''}>${label}</option>`).join('')}</select></label></div>`:''}${paiState.kind==='deviation'?`<div class="deviation-summary"><span>当前 <b>${list.length}</b> 条记录</span><span class="orange">存在偏差 <b>${list.filter(r=>r.finding==='deviation').length}</b></span><span class="green">暂无明显偏差 <b>${list.filter(r=>r.finding==='normal').length}</b></span><span class="muted">待核实 <b>${list.filter(r=>r.finding==='verify').length}</b></span></div>`:''}${paiTable(list.slice((paiState.page-1)*listPageSize('pai-records',10),paiState.page*listPageSize('pai-records',10)))}${listPager(list.length,paiState.page,listPageSize('pai-records',10),{sizeKey:'pai-records',attr:"data-pai-page"})}</section><p class="deviation-foot">采购专属演示诊断 · 风险按截止日快照，工作记录按所选期间统计；同一事项可进入不同诊断类型，条目数不等于风险数。未连接真实 AI 服务。</p>`;
};pbRenderers.ai=pbRenderAI;
function paiDecorate(){const section=$('#pb-ai');if(!section)return;section.classList.add('pai-section');const number=section.querySelector('.sectionhead .ai-logo');if(number){number.innerHTML='<b>AI</b>';number.setAttribute('aria-hidden','true')};if(!section.querySelector('[data-pai-refresh]'))section.querySelector('.sectionhead').insertAdjacentHTML('beforeend','<button class="link" data-pai-refresh>↻ 刷新诊断</button>');section.querySelectorAll('.pai-table table').forEach(rdTable);}
