pbModules.find(m=>m[0]==='management')[1]='采购部全局管理';pbModules.find(m=>m[0]==='management')[2]='采购部全局管理';moduleNames['pb-management']='采购部全局管理';
const pmStages=[0,2,3,4,5,6],pmStageNames=['到样数量','意向数量','确品数量','立项数量','上品数量','成功数量'];
