function pmPage(id,rows,heads,cells){return pbPage(id,rows,heads,cells,5);}
function pmSelectionView(){return `<div class="pm-selection-grid">${pmStages.map((stage,i)=>{const actual=pmSelectionRows(stage).length,target=pmSelectionTarget(stage),gap=Math.max(0,target-actual);return `<button class="dp-metric" data-pm-selection="${stage}"><small>${pmStageNames[i]}</small><strong class="${gap?'red':'green'}">${actual}<em> 项</em></strong><p>目标 ${target} · ${gap?'缺 '+gap+' 项':'已达标'}</p></button>`;}).join('')}</div>${table(['选品节点','数据来源','目标数量','实际数量','偏差数量','判定','操作'],pmStages.map((stage,i)=>{const n=pmSelectionRows(stage).length,t=pmSelectionTarget(stage);return [pmStageNames[i],stage<4?'数智罗盘选品管理':'运营罗盘项目管理',t,n,`<span class="${n<t?'red':'green'}">${n-t>0?'+':''}${n-t}</span>`,n<t?'<span class="tag red">数量不达标</span>':'<span class="tag green">已达标</span>',`<button class="link" data-pm-selection="${stage}">查看明细</button>`];}))}${pmRules('<p>按所选周期到样批次，截至统计截止日计算状态≥到样、意向、确品、立项的样品数量；上品为已上架产品，成功为销量达到品类标准或标记爆品。各阶段分别计数，不合计为产品总数。任一节点实际＜目标即预警，等于目标达标。</p><p>成功销量标准：'+chains.map((c,i)=>c+' '+pbStore.hot[i]+' 件').join('；')+'。当前为测试台账，立项前来源映射数智罗盘，立项及以后映射运营罗盘。</p>')}`;}
function pmQuoteView(){const all=pmQuotes(),rows=all.filter(r=>pmQuoteFilter==='all'||pmQuoteFilter==='pending'&&!r.actual||pmQuoteFilter==='late'&&r.warning);return `<div class="pb-grid-three">${pbMetric('待报价任务',all.filter(r=>!r.actual).length+'<em>项</em>','含未到期和逾期任务')}${pbMetric('延期报价',all.filter(r=>r.warning).length+'<em>项</em>','实际或统计截止日超计划日期','','','red')}${pbMetric('按时完成',all.filter(r=>r.actual&&!r.warning).length+'<em>项</em>','按报价阶段独立统计')}</div><div class="pb-filters"><label>任务状态 <select data-pm-quote-filter>${[['all','全部报价'],['pending','待报价任务'],['late','延期报价预警']].map(([v,l])=>`<option value="${v}" ${v===pmQuoteFilter?'selected':''}>${l}</option>`).join('')}</select></label></div>${pmPage('pm-quotes',rows,['采购人员','产品名称 / 型号','供应商名称','产品类型','报价阶段','计划报价时间','实际完成时间','延期天数','操作'],r=>[r.owner,pbProduct(r),r.supplier,r.type,r.phase,r.plan,r.actual||r.state,`<span class="${r.warning?'red':'green'}">${r.delay} 天</span>`,`<button class="link" data-pm-quote="${esc(r.key)}">查看详情</button>`])}${pmRules('<p>实际完成时间＞计划报价时间触发延期报价；未完成且超过计划日期，计为逾期待报价。延期天数按自然日计算，未到期不预警。同一产品不同报价阶段分别建任务。</p><p>来源映射：报价管理系统、项目管理系统、钉钉OA报价审批。当前为演示报价节点与时间，未接入真实审批数据。</p>')}`;}
function pmDeviationView(){const all=pmDeviationRows(),rows=all.filter(r=>pmRootFilter==='all'||r.root===pmRootFilter);return `<div class="pb-filters"><label>根因归类 <select data-pm-root><option value="all">全部</option>${['供应商管理','选品方向','成本管理','项目管理','流程制度','培训','人员管理'].map(n=>`<option ${n===pmRootFilter?'selected':''}>${n}</option>`).join('')}</select></label><span class="note">根因分析为待核实判断，方案与制度建议供复盘使用</span></div>${pmPage('pm-deviation',rows,['偏差事项','偏差值','根因归类','根因分析','闭环方案','责任时间','责任人','流程制度优化迭代','操作'],r=>[esc(r.name),`<strong class="red">${esc(r.value)}</strong>`,r.root,esc(r.analysis),esc(r.plan),r.due,r.owner,esc(r.iteration),`<button class="link" data-pm-deviation="${esc(r.key)}">查看详情</button>`])}`;}
const pmPreviousManagement=pbRenderManagement;pbRenderManagement=function(){const tab=pbState.tabs.management;if(tab==='score')return pmPreviousManagement().replaceAll('工作偏差复盘','部门工作偏差复盘').replaceAll('关键过程指标','部门关键指标大盘');return pmTabs()+(tab==='deviation'?pmDeviationView():pbTabs('process',[['supplier','供应商管理'],['selection','自选品管理'],['quote','报价管理']])+((pbState.tabs.process||'supplier')==='selection'?pmSelectionView():pbState.tabs.process==='quote'?pmQuoteView():pmSupplierView()));};pbRenderers.management=pbRenderManagement;
function pmModal(title,rows,heads,cells,subtitle='采购部全局管理 · 测试数据'){let page=1;openModal(title,'<div id="pm-modal-table"></div><div id="pm-modal-pages"></div>',false,subtitle);$('#dialog').classList.add('pm-dialog');function fill(){const pages=Math.max(1,Math.ceil(rows.length/listPageSize('pm-modal-pages',20)));$('#pm-modal-table').innerHTML=rows.length?table(heads,rows.slice((page-1)*listPageSize('pm-modal-pages',20),page*listPageSize('pm-modal-pages',20)).map(cells)):'<div class="empty">当前范围暂无记录</div>';$('#pm-modal-table').querySelectorAll('table').forEach(rdTable);mountListPager($('#pm-modal-pages'),rows.length,page,next=>{page=next;fill()});}fill();}
