 if(b.hasAttribute('data-pm-selection')){const stage=+b.dataset.pmSelection;pmModal(pmStageNames[pmStages.indexOf(stage)]+' · 产品明细',pmSelectionRows(stage),['产品名称 / 型号','采购人员','供应商','当前状态','到样时间','节点时间','数据来源','销量 / 爆品标记'],r=>[pbProduct(r),r.owner,r.supplier,r.stage>=5?'已上架':pbStages[r.stage],r.date,r.dates[stage]||r.dates[5]||'—',stage<4?'数智罗盘选品管理':'运营罗盘项目管理',r.volume+' 件 / '+(r.hotTag?'爆品':'无')]);}
 if(b.hasAttribute('data-pm-quote'))pmDetail(pmQuotes().find(r=>r.key===b.dataset.pmQuote));
