document.addEventListener('keydown',e=>{const b=e.target.closest('[data-dx-new-channel]');if(b&&(e.key==='Enter'||e.key===' ')){e.preventDefault();b.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});





// Product, project and R&D share components and the business ledger.
// Only one workspace is mounted at a time, preserving unique IDs and handlers.
const dwProfiles={
 product:{name:'产品部',center:'产品中心',tab:1,route:'department',excluded:[]},
 project:{name:'项目部',center:'项目部',tab:2,route:'project-department',excluded:['sales']},
 research:{name:'研发部',center:'研发部',tab:4,route:'rd-department',excluded:['sales']}
};
const dwModuleTemplate=dpModules.map(m=>[...m]);
let dwActive='product';
const dwClone=value=>JSON.parse(JSON.stringify(value));
const dwInitial={state:dwClone(dpState),panels:dwClone(dxStates),ai:dwClone(dxAI),scope:dxScope};
const dwStates=new Map();
function dwSave(){dwStates.set(dwActive,{state:dwClone(dpState),panels:dwClone(dxStates),ai:dwClone(dxAI),scope:dxScope})}
function dwReplace(target,value){Object.keys(target).forEach(k=>delete target[k]);Object.assign(target,dwClone(value))}
function dwSelect(key){
 if(key!==dwActive){dwSave();const saved=dwStates.get(key)||dwClone(dwInitial);dwReplace(dpState,saved.state);dwReplace(dxStates,saved.panels);dwReplace(dxAI,saved.ai);dxScope=saved.scope;if(!dwStates.has(key))dxAI.department=dwProfiles[key].name;dwActive=key;}
 dpDepartment=dwProfiles[key].name;
 dpModules.splice(0,dpModules.length,...dwModuleTemplate.filter(m=>!dwProfiles[key].excluded.includes(m[0])).map(m=>[...m]));
 const center=dwProfiles[key].center,titles={risk:center+'高危预警榜单 TOP6',ai:center+'AI 全局智能诊断',management:dpDepartment+'全局管理'};
 for(const m of dpModules)if(titles[m[0]])m[1]=m[2]=titles[m[0]];
 dpRiskCache.clear();dpProductCache.clear();dxModal=null;
}
const dwRender=renderDepartment;
renderDepartment=function(){
 dwRender();dpView.dataset.department=dwActive;dpView.setAttribute('aria-label',dpDepartment+'看板');
 if(dwActive!=='product')dpView.querySelectorAll('.dp-nav-links a').forEach(a=>{a.dataset.dwModule=a.hash.slice(4);a.href='#'+dwProfiles[dwActive].route+'-'+a.dataset.dwModule});
};
const dwSwitch=dpSwitchView;
function dwOpen(key,hash=true,module=null){
 closeModal();dwSelect(key);dwSwitch('department',false);dpNavButtons.forEach((n,i)=>{const on=i===dwProfiles[key].tab;n.classList.toggle('active',on);if(on)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});
 if($('.headright .optional'))$('.headright .optional').textContent=dpDepartment+'经营与执行中心';
 if(hash)history.replaceState(null,'','#'+dwProfiles[key].route+(module?'-'+module:''));
 if(module)$('#dp-'+module)?.scrollIntoView({block:'start',behavior:'instant'});
}
dpSwitchView=function(view,hash=true){
 if(view==='department')return dwOpen('product',hash);
 closeModal();dwSelect('product');dwSwitch(view,hash);dpNavButtons.forEach((n,i)=>{n.classList.toggle('active',i===0);if(i===0)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});
};
const dwPurchasing=pbSwitchView;
pbSwitchView=function(hash=true){closeModal();dwSelect('product');return dwPurchasing(hash)};
for(const key of ['project','research']){const button=dpNavButtons[dwProfiles[key].tab];button.disabled=false;button.removeAttribute('title');button.dataset.view=key;button.onclick=()=>dwOpen(key)}
document.addEventListener('click',e=>{const link=e.target.closest('[data-dw-module]');if(!link)return;e.preventDefault();history.replaceState(null,'',link.getAttribute('href'));$('#dp-'+link.dataset.dwModule)?.scrollIntoView({block:'start',behavior:'smooth'})});
function dwRoute(){for(const key of ['project','research']){const prefix='#'+dwProfiles[key].route;if(location.hash===prefix||location.hash.startsWith(prefix+'-')){const module=location.hash.slice(prefix.length+1);dwOpen(key,false,dxModuleOrder.includes(module)?module:null);return}}}
window.addEventListener('hashchange',dwRoute);
requestAnimationFrame(dwRoute);

// Shorten director ranking titles without changing risk levels or thresholds.
const directorRiskNames=['高危品质风险榜','高危劣质店铺榜','高危亏损产品榜','库存风险榜','高危滞销产品榜','高危延期项目榜','高危退货恶化榜','供应商高危预警'];
function directorRiskTitle(title){for(const name of directorRiskNames)title=title.replace(name,name.replace('高危',''));return title}
const directorRiskRender=renderRisks;
renderRisks=function(...args){const result=directorRiskRender(...args);$('#riskrail .sr-global-risk')?.remove();document.querySelectorAll('#riskrail .rhead h3').forEach(heading=>{for(const node of heading.childNodes)if(node.nodeType===Node.TEXT_NODE)node.textContent=directorRiskTitle(node.textContent)});return result};
const directorRiskModal=openModal;
openModal=function(title,...args){return directorRiskModal(dpState.view==='director'?directorRiskTitle(title):title,...args)};

// Director-only risk overview. ABCD remains the independent business matrix.
const mkDirectorSection=$('#matrix'),mkPreviousSummary=matrixAnalysisHTML;
const mkLights={red:{label:'红灯',note:'优先处理'},yellow:{label:'黄灯',note:'重点跟踪'},green:{label:'绿灯',note:'正常经营'}};
function mkRiskFacts(rows){return rows.map(p=>{
 const signals=[],gap=Math.max(0,config.profit-p.profit),add=(tone,label,detail,action)=>signals.push({tone,label,detail,action});
 if(p.profit<config.profit)add('red','利润未达标',`利润率 ${fmt(p.profit,1)}%，低于分界 ${fmt(gap,1)}%`,'核查成本与售价');
 else if(p.profit<config.profit+2)add('yellow','利润临界',`利润率 ${fmt(p.profit,1)}%，高于分界不足 2%`,'守住利润空间');
 if(p.returnRate>8)add('red','退货偏高',`退货率 ${fmt(p.returnRate,1)}%，超预警线 ${fmt(p.returnRate-8,1)}%`,'排查退货原因');
 else if(p.returnRate>=6)add('yellow','退货临界',`退货率 ${fmt(p.returnRate,1)}%，距红线 ${fmt(8-p.returnRate,1)}%`,'跟踪售后变化');
 if(['整改','下架'].includes(p.state))add('red',p.state+'中','销售状态：'+p.state,'复核整改及恢复条件');
 else if(['滞销','断货','缺货'].includes(p.state))add('yellow',p.state+'风险','销售状态：'+p.state,p.state!=='滞销'?'核对补货计划':'调整库存与动销');
 signals.sort((a,b)=>(a.tone==='red'?0:1)-(b.tone==='red'?0:1));
 return {p,signals,tone:signals.some(s=>s.tone==='red')?'red':signals.length?'yellow':'green',profitGap:p.sales*gap/100};
}).sort((a,b)=>['red','yellow','green'].indexOf(a.tone)-['red','yellow','green'].indexOf(b.tone)||b.profitGap-a.profitGap||b.p.sales-a.p.sales)}
function mkRules(){return `<details class="mk-rules"><summary>红黄绿灯口径 · 演示规则</summary><p>红灯：利润率＜${fmt(config.profit,1)}%，或总退货率＞8%，或处于整改 / 下架状态。黄灯：未触发红灯且利润率距分界不足2%，或退货率6%—8%（含边界），或滞销 / 缺货。其余为绿灯；多风险取最高等级，一个产品仅计一次。</p><p>利润分界沿用矩阵配置；退货6% / 8%为演示预警线。利润达标差额＝销售额×利润率缺口，仅作测算，不代表已发生亏损。按当前所选统计期间的经营数据判断。</p></details>`}
matrixAnalysisHTML=function(rows){
 if($('#matrix')!==mkDirectorSection)return mkPreviousSummary(rows);
 const facts=mkRiskFacts(rows),red=facts.filter(r=>r.tone==='red'),priorities=facts.filter(r=>r.tone!=='green').slice(0,3),sum=(items,fn)=>items.reduce((s,r)=>s+fn(r),0);
 return `<div class="mk-risk-overview"><div class="mk-heading"><h3>关键产品预警</h3><span>近30天 · ${rows.length} 个</span></div><div class="mk-lights">${Object.entries(mkLights).map(([tone,l])=>`<button class="mk-light ${tone}" data-mk-list="${tone}"><span><i></i>${l.label} · ${l.note}</span><strong>${facts.filter(r=>r.tone===tone).length}<small> 个</small></strong><em>查看产品 ›</em></button>`).join('')}</div><div class="mk-impact"><div><span>红灯产品销售额</span><strong>${fmt(sum(red,r=>r.p.sales),1)}<small> 万元</small></strong></div><div><span>利润达标差额 · 测算</span><strong>${fmt(sum(red,r=>r.profitGap),2)}<small> 万元</small></strong></div></div><div class="mk-priority-head"><h4>优先处理 TOP3</h4><button class="link" data-mk-list="all">查看全部 ›</button></div><div class="mk-priorities">${priorities.map(r=>`<button class="mk-priority" data-matrix-diagnosis="${r.p.id}">${riskThumbnail(r.p.name)}<span class="mk-product"><b>${esc(r.p.name)}</b><small>${esc(r.p.model)} · ${esc(r.p.channel)}</small><span class="${r.tone==='yellow'?'orange':'red'}">${esc(r.signals[0].detail)}</span><small>建议：${esc(r.signals[0].action)}</small></span><span class="tag ${r.tone==='yellow'?'orange':'red'}">${mkLights[r.tone].label}</span></button>`).join('')||'<div class="dp-empty">当前无红黄灯预警，继续保持监控。</div>'}</div>${mkRules()}</div>`;
};
function mkWithPeriod(period,fn){const old=localPeriods.matrix;localPeriods.matrix={...period};try{return withPeriod('matrix',fn)}finally{if(old)localPeriods.matrix=old;else delete localPeriods.matrix}}
function mkOpenList(tone='all',page=1,period=null,records=null){period=period||{...periodFor('matrix')};mkWithPeriod(period,()=>{
 const facts=mkRiskFacts(records||productRows(false)),range=bounds(),cutoff=range.cutoff;
 openModal('关键产品预警 · 产品明细',`<div class="mk-modal-tools" id="mk-list-tabs"></div><div id="mk-list-table" class="mk-list-table"></div><div id="mk-list-pages"></div>${mkRules()}`,false,range.start+' — '+cutoff+' · 多项命中取最高等级');
 const fill=()=>{
  const rows=facts.filter(r=>tone==='all'||r.tone===tone),pages=Math.max(1,Math.ceil(rows.length/listPageSize('mk-list-pages',20)));page=Math.max(1,Math.min(page,pages));
  $('#mk-list-tabs').innerHTML=[['all','全部'],...Object.entries(mkLights).map(([k,v])=>[k,v.label])].map(([k,label])=>`<button class="btn small ${tone===k?'primary':''}" data-mk-tone="${k}" aria-pressed="${tone===k}">${label} ${facts.filter(r=>k==='all'||r.tone===k).length}</button>`).join('');
  $('#mk-list-table').innerHTML=rows.length?table(['产品名称 / 型号','渠道','预警等级','单品利润率','总退货率','触发原因 / 偏差','操作'],rows.slice((page-1)*listPageSize('mk-list-pages',20),page*listPageSize('mk-list-pages',20)).map(r=>[titleProduct(r.p),esc(r.p.channel),`<span class="tag ${r.tone==='yellow'?'orange':r.tone}">${mkLights[r.tone].label}</span>`,fmt(r.p.profit,1)+'%',fmt(r.p.returnRate,1)+'%',r.signals.length?r.signals.map(s=>`<div class="${s.tone==='yellow'?'orange':'red'}">${esc(s.detail)}</div>`).join(''):'当前未触发预警',`<button class="link" data-mk-detail="${r.p.id}">AI 诊断</button><button class="link" data-mk-trend="${r.p.id}">趋势图</button>`])):'<div class="dp-empty">当前灯色暂无产品</div>';
  mountListPager($('#mk-list-pages'),rows.length,page,next=>{page=next;fill()});
 };
 $('#mk-list-tabs').onclick=e=>{const b=e.target.closest('[data-mk-tone]');if(b){tone=b.dataset.mkTone;page=1;fill()}};
 $('#mk-list-table').onclick=e=>{const b=e.target.closest('[data-mk-detail],[data-mk-trend]');if(!b)return;mkWithPeriod(period,()=>b.dataset.mkDetail?openMatrixDiagnosis(b.dataset.mkDetail):openNewProductTrends(b.dataset.mkTrend,false,'matrix'));$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn small" id="mk-back">返回预警列表</button>');$('#mk-back').onclick=()=>mkOpenList(tone,page,period,records)};
 fill();
 });}
document.addEventListener('click',e=>{const b=e.target.closest('#matrix [data-mk-list]');if(b)withPeriod('matrix',()=>mkOpenList(b.dataset.mkList,1,null,$('#matrix').classList.contains('kpm-main')?kpmSortedRows(kpmRows()).filter(p=>p.facts.sales>0):null))});

// Director assessment uses the selected channel and the same period GMV as its list.
function naFacts(p,period=periodFor('new')){
 const b=bounds(period),days=Math.max(1,Math.min(p.days,aiFlowDayDiff(b.start,b.cutoff)+1)),monthly=p.sales/days*30,target=dpStore.newTargets[p.chain],attain=monthly/target*100;
 const rating=p.state==='滞销'||attain<50?'滞销':attain>=100&&p.profit>=dpStore.marginTarget&&p.returnRate<=8&&p.state==='在售'?'优质':'平庸';
 return {rating,monthly,target,attain,days,marginTarget:dpStore.marginTarget,tone:{优质:'green',平庸:'orange',滞销:'red'}[rating]};
}
function naSeries(p,period){
 const b=bounds(period),start=[b.start,shiftDate(b.cutoff,-29)].sort()[0],launch=shiftDate(b.cutoff,1-p.days),count=aiFlowDayDiff(start,b.cutoff)+1;
 const raw=newProductTrendData(p,b.cutoff,count,[{name:p.channel,color:'#7773ed'}],launch)[0],inPeriod=raw.points.filter(d=>d.date>=b.start),total=inPeriod.reduce((s,d)=>s+d.salesCents,0),target=Math.round(p.sales*1000000),scale=total?target/total:0,allocated=splitTarget(target,inPeriod.map(d=>d.salesCents));let index=0;
 return {...raw,points:raw.points.map(d=>{const salesCents=d.date>=b.start?allocated[index++]:Math.round(d.salesCents*scale),unitCents=d.volume?d.salesCents/d.volume:0,volume=unitCents?Math.round(salesCents/unitCents):0;return {...d,salesCents,revenue:salesCents/1000000,volume}})};
}
function naAdvice(p,f){
 const weak=p.profit<f.marginTarget,returns=p.returnRate>8;
 return [
 ['推广',weak||returns?'先处理风险':f.rating==='优质'?'优先推广':f.rating==='滞销'?'控制投入':'限额测试',weak?'利润率未达标，先修复单品利润，再扩大投放。':returns?'退货率超过8%演示预警线，先核查售后原因。':f.rating==='优质'?'围绕当前渠道复制有效内容，小步增加投放并核对利润。':f.rating==='滞销'?'暂停低效扩量，仅保留小规模需求验证。':'用7天小预算测试卖点、受众和内容，达标后再扩量。'],
 ['调价',weak?'守住利润底线':f.rating==='滞销'?'评估促销价':'小范围验证',weak?`以利润率达到${fmt(f.marginTarget,1)}%为目标，先拆解费用，测算可承受促销价。`:f.rating==='滞销'?'结合库存与单台成本测算促销方案，避免只降价不增量。':'测试组合装或优惠券，对比销量、GMV与利润后决定价格。'],
 ['迭代',returns||p.state==='整改'?'优先整改':f.rating==='优质'?'小步优化':'验证需求',returns||p.state==='整改'?'按退货原因和用户反馈定位主要问题，复测通过后恢复放量。':f.rating==='优质'?'保留成熟卖点，优先改进高频体验问题，避免大幅改版。':'收集未转化与退货反馈，7天内明确一个卖点或体验优化方向。'],
 ['清库',f.rating==='滞销'?'优先评审':'暂不建议',f.rating==='滞销'?'先核对库存、库龄和保本价；若优化无效，提交分批清库方案。':'当前不直接清库；持续跟踪动销，出现积压后再评审。']
 ];
}
function openNewAssessment(id){withPeriod('new',()=>{
 const period={...periodFor()},p=productRows(true).find(r=>r.id===+id);if(!p)return;
 const f=naFacts(p,period),b=bounds(period),series=naSeries(p,period),advice=naAdvice(p,f);let start=shiftDate(b.cutoff,-29),end=b.cutoff;
 openModal('AI 新品评估 · '+p.name,`<article class="na-assessment"><header class="na-hero" data-product-summary><div>${riskThumbnail(p.name)}<div><h2>${esc(p.name)}</h2><p>${esc(p.model)} · ${esc(chains[p.chain])} · ${esc(p.brand)} · ${esc(p.channel)}</p><small>上架 ${p.days} 天 · 产品等级 ${p.grade}</small></div></div><span class="tag ${f.tone}">AI 评级 · ${f.rating}</span></header><section class="na-verdict"><span class="ai-logo" aria-hidden="true"><b>AI</b></span><div><strong>${f.rating==='优质'?'具备推广基础，优先验证扩量':f.rating==='滞销'?'动销不足，先止损并评审优化方案':'表现尚待提升，优先验证转化与利润'}</strong><p>月均 GMV 达成 ${fmt(f.attain,1)}% · 利润率 ${fmt(p.profit,1)}% · 总退货率 ${fmt(p.returnRate,1)}%</p></div></section><div class="na-metrics">${[['本期 GMV',fmt(p.sales,1)+' 万元'],['月均 GMV / 目标',fmt(f.monthly,1)+' / '+fmt(f.target,1)+' 万元'],['单品利润率',fmt(p.profit,1)+'%'],['总退货率',fmt(p.returnRate,1)+'%']].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><section class="na-actions"><h3>经营建议</h3><div>${advice.map(([title,label,body])=>`<section><h4>${title}<span>${label}</span></h4><p>${body}</p></section>`).join('')}</div></section><section class="na-trends"><div class="na-trend-head"><h3>销量与 GMV 趋势 <small>${esc(p.channel)}</small></h3><div class="nt-range-picker"><button id="na-recent" aria-pressed="true">近30天</button><button id="na-custom" aria-pressed="false">自定义日期</button></div></div><form id="na-date-form" class="nt-custom-range" hidden><label>开始日期<input id="na-start" type="date" min="${series.points[0].date}" max="${b.cutoff}" value="${start}" required></label><label>结束日期<input id="na-end" type="date" min="${series.points[0].date}" max="${b.cutoff}" value="${end}" required></label><button class="btn small" type="submit">应用</button><span id="na-error" role="alert"></span></form><p id="na-range" class="note"></p><div id="na-charts" class="nt-chart-grid"></div></section><details class="na-rules"><summary>评级与数据口径 · 演示</summary><p>滞销：月均 GMV 完成率＜50%，或销售状态为滞销。优质：月均 GMV 完成率≥100%、利润率≥${fmt(f.marginTarget,1)}%、退货率≤8%且在售。其余为平庸；评级与 ABCD 产品等级分开显示。</p><p>月均 GMV＝本期 GMV ÷ 本期已上架天数 ×30；目标沿用品类月均销售目标。评级基于本期数据，切换趋势日期不改变评级。${p.days<14?'上架不足14天，评级仅作阶段性参考。':''}</p><p>本期 ${b.start} — ${b.cutoff}，GMV 与新品列表一致。每日 GMV 为演示分布，销量按演示成交单价折算；未上架日期为0，跨本期的趋势日期按同一系数模拟。库存和库龄尚未纳入本评估，清库建议需核对库存后执行。</p></details></article>`,false,periodLabel(period)+' · '+b.start+' — '+b.cutoff+' · '+p.channel);
 const render=()=>{const selected={...series,points:series.points.filter(d=>d.date>=start&&d.date<=end)},totals=newTrendTotals([selected]),metrics=[{key:'volume',name:'销量',unit:'件',digits:0,value:totals.volume},{key:'revenue',name:'GMV',unit:'万元',digits:2,value:totals.revenue}];$('#na-range').textContent=start+' — '+end+' · '+selected.points.length+' 天';$('#na-charts').innerHTML=metrics.map(m=>`<section class="nt-chart"><div class="nt-chart-heading"><h3>${m.name}趋势</h3><strong>${fmt(m.value,m.digits)} ${m.unit}</strong></div>${newTrendChart([selected],m)}</section>`).join('');};
 $('#na-custom').onclick=()=>{$('#na-date-form').hidden=false;$('#na-start').focus()};
 $('#na-recent').onclick=()=>{start=shiftDate(b.cutoff,-29);end=b.cutoff;$('#na-start').value=start;$('#na-end').value=end;$('#na-date-form').hidden=true;$('#na-error').textContent='';$('#na-recent').setAttribute('aria-pressed','true');$('#na-custom').setAttribute('aria-pressed','false');render()};
 $('#na-date-form').onsubmit=e=>{e.preventDefault();const from=$('#na-start').value,to=$('#na-end').value;if(!from||!to||from>to||from<series.points[0].date||to>b.cutoff){$('#na-error').textContent='请选择有效日期范围，开始日期不能晚于结束日期';return}start=from;end=to;$('#na-error').textContent='';$('#na-recent').setAttribute('aria-pressed','false');$('#na-custom').setAttribute('aria-pressed','true');render()};
 $('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary small" id="productdraft">生成工作草稿</button>');
 
 $('#productdraft').onclick=()=>draft(p.name+' · '+f.rating+'新品经营优化');render();
 });}
const naPreviousProductDetail=productDetail;
productDetail=function(isNew,id,...args){return isNew&&dpState.view==='director'?openNewAssessment(id):naPreviousProductDetail(isNew,id,...args)};

// Director project dates share the AI day-picker presentation and period context.
const pjOriginalControls=periodControls,pjOriginalBounds=bounds,pjOriginalLabel=periodLabel,pjOriginalKey=periodKey,pjOriginalWord=word,pjOriginalChange=changePeriod;
const pjDayMinimum='2025-01-01';
bounds=function(p=periodFor()){
 if(p.mode!=='day')return pjOriginalBounds(p);
 return {first:+p.start.slice(5,7),last:+p.end.slice(5,7),start:p.start,end:p.end,cutoff:p.end,partial:false};
};
periodLabel=function(p=periodFor()){return p.mode==='day'?(p.start===p.end?p.start:p.start+' — '+p.end):pjOriginalLabel(p)};
periodKey=function(p=periodFor()){return p.mode==='day'?'day-'+p.start+'-'+p.end:pjOriginalKey(p)};
word=function(p=periodFor()){return p.mode==='day'?(p.start===p.end?'当日':'期间'):pjOriginalWord(p)};
periodControls=function(id,options){
 const html=pjOriginalControls(id,options);
 if(id!=='projects')return html;
 const p=periodFor(id);
 if(p.mode!=='day')return html.replace(/(<div class="period-segment"[^>]*>)/,'$1<button type="button" data-pj-day aria-pressed="false">日</button>');
 return `<div class="period-picker" data-time-scope="projects"><div class="period-segment" role="group" aria-label="项目进度时间粒度"><button type="button" data-pj-day aria-pressed="true">日</button>${[['month','月'],['quarter','季'],['year','年']].map(([v,l])=>`<button type="button" data-time-mode="${v}" aria-pressed="false">${l}</button>`).join('')}</div><div class="ai-day-picker"><div class="period-segment ai-day-options"><button type="button" data-pj-daymode="single" aria-pressed="${p.dayMode!=='range'}">单日</button><button type="button" data-pj-daymode="range" aria-pressed="${p.dayMode==='range'}">日期区间</button></div>${p.dayMode==='range'?`<form id="pj-day-range-form" class="ai-day-range"><label class="ai-date-label">开始<input id="pj-day-start" type="date" aria-label="项目开始日期" min="${pjDayMinimum}" max="${DATA_CUTOFF}" value="${p.start}" required></label><span>至</span><label class="ai-date-label">结束<input id="pj-day-end" type="date" aria-label="项目结束日期" min="${pjDayMinimum}" max="${DATA_CUTOFF}" value="${p.end}" required></label><button type="submit" class="btn small">应用</button><span id="pj-day-error" class="red" role="alert"></span></form>`:`<label class="ai-date-label">日期<input id="pj-date" type="date" aria-label="项目日期" min="${pjDayMinimum}" max="${DATA_CUTOFF}" value="${p.end}" required></label>`}</div><button class="follow-time" data-time-follow>↶ 恢复跟随</button></div>`;
};
changePeriod=function(id,field,value){
 if(id==='projects'&&periodFor(id).mode==='day'&&field==='mode'){
  const p=periodFor(id);localPeriods[id]={mode:'month',year:+p.end.slice(0,4),value:+p.end.slice(5,7)};
 }
 return pjOriginalChange(id,field,value);
};
function pjApplyDates(start,end,dayMode){
 const valid=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v+'T00:00:00Z'))&&iso(new Date(v+'T00:00:00Z'))===v;
 if(!valid(start)||!valid(end)||start<pjDayMinimum||end>DATA_CUTOFF||start>end)return false;
 localPeriods.projects={mode:'day',year:+end.slice(0,4),value:+end.slice(5,7),dayMode,start,end};
 projectPage=1;renderTimeControls();renderModule('projects');return true;
}
document.addEventListener('click',e=>{
 if(e.target.closest('[data-pj-day]')){const p=periodFor('projects');if(p.mode!=='day'){const end=bounds(p).cutoff;pjApplyDates(end,end,'single')}}
 const mode=e.target.closest('[data-pj-daymode]');if(mode){const p=periodFor('projects');pjApplyDates(mode.dataset.pjDaymode==='single'?p.end:p.start,p.end,mode.dataset.pjDaymode)}
});
document.addEventListener('change',e=>{if(e.target.id==='pj-date'){const input=e.target;if(!pjApplyDates(input.value,input.value,'single')){input.setCustomValidity('请选择有效日期，且不晚于数据截止日');input.reportValidity()}else input.setCustomValidity('')}});
document.addEventListener('submit',e=>{if(e.target.id!=='pj-day-range-form')return;e.preventDefault();if(!pjApplyDates($('#pj-day-start').value,$('#pj-day-end').value,'range'))$('#pj-day-error').textContent='请选择有效区间，开始日期不能晚于结束日期。'});
// Freeze monthly fixture plans before calculating day-level overdue status.
// Active projects carry over into a selected interval; they are not summed per day.
const pjOriginalProjects=projects;
projects=function(){
 const p=periodFor();if(p.mode!=='day'||activeModule!=='projects')return pjOriginalProjects();
 const saved=localPeriods.projects;
 let rows;try{localPeriods.projects={mode:'month',year:p.year,value:+p.end.slice(5,7)};rows=pjOriginalProjects()}finally{localPeriods.projects=saved}
 return rows.map(r=>{
  if(r.reference)return r;
  const completed=r.actual&&r.actual!=='—'&&r.actual<=p.end;
  const delay=completed?Math.max(0,aiFlowDayDiff(r.plan,r.actual)):r.status==='绿灯'?0:Math.max(0,aiFlowDayDiff(r.plan,p.end));
  return {...r,actual:completed?r.actual:'—',delay,status:completed?'绿灯':r.status==='绿灯'?'绿灯':delay>0?'红灯':'黄灯'};
 }).filter(r=>r.actual==='—'||r.actual>=p.start);
};

