// 建单前先核对既有分工，确认后复用同一六列表进行办理；不把多人分工降为单负责人。
function upTodoAssignmentPreview(task){
 const headers=['执行事项','负责人','状态','计划完成日期','实际完成日期','反馈/进展'];
 const rows=upTodoResponsibilityGroups(task.responsibilities).map(group=>{
  const row=group.rows[0],names=group.rows.map(r=>(r.assignee||'待分配')+'-'+(r.department||upTodoPersonDepartment(r.assignee,task)));
  return `<tr><td>${esc(row.action)}</td><td>${names.map(esc).join('<br>')}</td><td>${upTodoStatusTag(row)}</td><td data-todo-assign-date="${row.due==null?'inherit':'fixed'}">${esc(upTodoDate(row.due||task.due))}</td><td>—</td><td>—</td></tr>`;
 }).join('');
 return `<section class="up-todo-assignment-preview"><h5>执行事项</h5><div class="tablewrap"><table aria-label="任务下发"><thead><tr>${headers.map(h=>'<th>'+h+'</th>').join('')}</tr></thead><tbody>${rows}</tbody></table></div></section>`;
}
// 任务下发表格的草稿与事件；模型原子保存，展示组件不直接写存储。
function upMountTodoCollaboration(host,task,onChange){
 const emptyDraft=()=>({action:'',assignees:[],query:'',status:'pending',due:'',feedback:''});
 let adding=false,draft=emptyDraft(),deleteConfirm=null;
 const error=message=>{
  const target=host.querySelector(adding?'[data-responsibility-form] [role=alert]':'[data-collaboration-error]');
  target.textContent=message;if(message)target.scrollIntoView({block:'nearest'});
 };
 const captureDraft=()=>{
  const form=host.querySelector('[data-responsibility-form]');if(!adding||!form)return;
  draft={action:form.querySelector('[data-responsibility-action]').value,assignees:[...(form.querySelector('[data-people-picker]').upSelectedPeople||[])],query:form.querySelector('[data-people-query]').value,status:form.querySelector('[data-responsibility-status]').value,due:form.querySelector('[data-responsibility-due]').value,feedback:form.querySelector('[data-responsibility-feedback]').value};
 };
 function render(){
  captureDraft();cancelDelete();host.upPeopleMultipleCleanup?.();
  const rows=upTodoCollaborative(task)?task.responsibilities:[upTodoLegacyResponsibility(task)];
  const groups=upTodoResponsibilityGroups(rows);
  const completed=groups.filter(g=>g.rows.every(r=>r.assignee&&r.status==='done')).length;
  host.innerHTML=`<section class="up-collaboration"><header><h5>任务下发 <small>已完成 ${completed}/${groups.length} 项</small></h5><button type="button" class="link" data-responsibility-add>新增执行事项</button></header><p class="up-todo-dialog-error" data-collaboration-error role="alert"></p><div class="up-collaboration-scroll"><table aria-label="任务下发"><colgroup><col style="width:27%"><col style="width:23%"><col style="width:10%"><col style="width:12%"><col style="width:12%"><col style="width:16%"></colgroup><thead><tr>${['执行事项','负责人','状态','计划完成日期','实际完成日期','反馈/进展'].map(label=>'<th>'+label+'</th>').join('')}</tr></thead><tbody>${groups.map(g=>upTodoExecutionGroup(g,task,groups.length>1)).join('')+upTodoExecutionDraft(task,draft,adding)}</tbody></table></div></section>`;
  upBindTodoPeople(host,task);
  upBindTodoPeopleMultiple(host,task,picker=>{
   const rowId=picker.dataset.responsibilityOwners;if(!rowId)return {selected:draft.assignees};
   const group=groups.find(g=>g.rows[0].id===rowId);
   return {selected:group.rows.map(r=>r.assignee).filter(Boolean),onError:error,onChange:names=>{
    captureDraft();
    const position=rows.findIndex(r=>r.id===rowId),saved=upTodoSetActionOwners(task.id,rowId,names),focusId=saved.responsibilities[position].id;
    Object.assign(task,saved);onChange(saved);
    // 保存选择后继续编辑本行，保持下拉展开以便连续多选。
    queueMicrotask(()=>{if(!host.isConnected)return;render();host.querySelector(`[data-responsibility-owners="${CSS.escape(focusId)}"]`)?.upOpenPeople()});
   }};
  });
  if(adding)host.querySelector('[data-responsibility-form] [data-people-query]').value=draft.query;
 }
 const cancelDraft=()=>{
  if(!adding)return false;adding=false;draft=emptyDraft();render();host.querySelector('[data-responsibility-add]').focus({preventScroll:true});return true;
 };
 const cancelDelete=(focus=false)=>{if(!deleteConfirm)return false;deleteConfirm.close(focus);return true};
 host.upExecutionConfirmCleanup=()=>cancelDelete();
 host.closest('dialog').upCancelResponsibilityDraft=()=>cancelDelete(true)||cancelDraft();
 host.onclick=e=>{
  const remove=e.target.closest('[data-execution-delete]');
  if(remove&&!remove.disabled){
   cancelDelete();
   deleteConfirm=upMountExecutionDeleteConfirm(remove,()=>{
    const saved=upTodoDeleteExecution(task.id,remove.dataset.executionDelete);Object.assign(task,saved);render();onChange(saved);host.querySelector('[data-execution-group] [data-todo-field-edit="action"]')?.focus({preventScroll:true});
   },()=>{deleteConfirm=null});
   return;
  }
  const add=e.target.closest('[data-responsibility-add]');
  if(add){
   if(adding){host.querySelector('[data-responsibility-action]').focus();return}
   adding=true;render();host.querySelector('[data-responsibility-action]').focus();return;
  }
  if(e.target.closest('[data-responsibility-cancel]')){cancelDraft();return}
  if(e.target.closest('[data-responsibility-submit]')){
   const form=host.querySelector('[data-responsibility-form]');
   try{const saved=upTodoAddResponsibilities(task.id,{assignees:form.querySelector('[data-people-multiple]').upPeopleSelection(),action:form.querySelector('[data-responsibility-action]').value,status:form.querySelector('[data-responsibility-status]').value,due:form.querySelector('[data-responsibility-due]').value,feedback:form.querySelector('[data-responsibility-feedback]').value});Object.assign(task,saved);adding=false;draft=emptyDraft();render();onChange(saved)}catch(err){error(err.message)}
  }
 };
 render();
 return render;
}
// 标题复用已关联的业务对象；不以任务名称或执行内容推断关联。
function upTodoHeadingObjects(task,provided){
 const product=upSpus.get(task.spuId),shop=task.scope==='shop'||task.shopId||task.gdShopId||String(task.spuId||'').startsWith('shop:');
 const fallback={name:String(task.objectName||'').trim()||product?.name||'未关联',type:shop?'shop':product?'product':task.gdProjectId!=null?'project':''};
 const supplied=(provided?.length?provided:task.businessObjects)?.filter(object=>String(object?.name||'').trim());
 const objects=supplied?.length?supplied:[fallback],seen=new Set();
 return objects.filter(object=>String(object?.name||'').trim()).map(object=>({name:String(object.name).trim(),type:diagnosisObjectType(Object.hasOwn(object,'type')?object.type:object.name===fallback.name?fallback.type:'')})).filter(object=>{
  const key=object.type+'|'+object.name;if(seen.has(key))return false;seen.add(key);return true;
 });
}
function upTodoDetailHeading(task,provided){
 if(task.gdManualEntry)return '<span class="up-todo-heading-prefix">任务详情 -</span><span class="up-todo-heading-task-title">'+esc(task.title)+'</span>';
 const objects=upTodoHeadingObjects(task,provided);
 return '<span class="up-todo-heading-prefix">任务详情 -</span>'+objects.map(object=>'<span class="up-todo-heading-object"><span data-todo-business-object>'+esc(object.name)+'</span>'+diagnosisObjectTag(object.type,true)+'</span>').join('');
}
// 待办详情：基础信息分组展示，负责人统一在反馈区维护，依据在内容底部展开。
function upTodoCommonFields(task,editable,inline){
 const display=(key,value)=>inline?upTodoInlineDisplay(key,value):value;
 const item=(label,value)=>`<div><dt>${label}</dt><dd>${value}</dd></div>`;
 const owner=upTodoCollaborative(task)&&(!editable||task.gdWorkKey)?`<div data-up-collab-owners>${upTodoOwnerCell(task)}</div>`:editable?upTodoPeopleInput(task.assignee,task):display('assignee',esc((task.department||upTodoPersonDepartment(task.assignee,task)||'—')+' / '+(task.assignee||'待分配')));
 const planned=upTodoPlannedDate(task);
 const due=editable?`<input name="due" aria-label="计划完成日期" type="date" required value="${esc(task.due||'')}">`:`<span data-todo-planned-date>${esc(upTodoDate(planned))}</span>`;
 const priority=editable?`<select name="priority" aria-label="优先级">${Object.entries(upTodoPriorities).map(([key,label])=>`<option value="${key}" ${key===upTodoPriorityKey(task.priority)?'selected':''}>${label}</option>`).join('')}</select>`:display('priority',upTodoPriorityTag(task,false));
 const status=upTodoCollaborative(task)||inline?`<span data-up-collab-status>${upTodoStatusTag(task)}</span>`:upTodoStatusTag(task);
 const date=`<div class="up-todo-due">${due}<span data-todo-overdue>${editable?'':upTodoOverdue({...task,due:planned})}</span></div>`;
 return `<dl class="up-todo-common ${editable?'up-todo-common-assign':''}">${editable?'':item('状态',status)}${item('优先级',priority)}${item('计划完成日期',date)}${inline||editable&&task.gdWorkKey&&upTodoCollaborative(task)?'':item('责任部门/责任人',owner)}${editable?'':item('实际完成日期',`<span data-todo-completed-date>${esc(upTodoDate(task.completedAt))}</span>`)+item('下发人',esc(upTodoDispatcher(task)))+item('下发时间',esc(upTodoDispatchTime(task.assignedAt)))}</dl>`;
}
function upTodoTitleField(task,editable,businessObjects=task.businessObjects){
 // 业务对象与事项标题独立；没有关联时明确显示未关联，不拿行动标题代替。
 const names=[...new Set((businessObjects||[]).map(object=>String(object.name||'').trim()).filter(Boolean))];
 if(!names.length)names.push(task.objectName||upSpus.get(task.spuId)?.name||'未关联');
 const heading=`<section class="up-todo-title-section"><div class="up-todo-title" data-todo-business-object>${names.map(esc).join('<br>')}</div></section>`;
 return heading+(editable?`<label class="up-todo-dialog-field">事项名称<input name="title" required maxlength="120" value="${esc(task.title)}"></label>`:'');
}
function upTodoExecutionMarkup(task,inline){
 if(!upTodoCollaborative(task))return inline?upTodoInlineDisplay('plan',esc(upTodoExecutionText(task))):esc(upTodoExecutionText(task));
 return upTodoResponsibilityGroups(task.responsibilities).map(group=>{
  const role=group.rows[0],text=group.rows.map(r=>(r.department||'待分配')+' / '+(r.assignee||'待分配')).join('、')+'：'+upTodoExecutionText(task,role);
  return inline?upTodoInlineDisplay('action',esc(text),role.id):esc(text);
 }).join(inline?'':'<br>');
}
function upTodoDetailFields(task,editable,inline=false,problemMarkup=''){
 const field=(name,label,value,required=false)=>`<label class="up-todo-dialog-field">${label}<textarea name="${name}" rows="3" maxlength="3000" ${required?'required':''}>${esc(value||'')}</textarea></label>`;
 if(editable)return `${upTodoHasEvidence(task)?`<section><h5>问题描述</h5><div class="up-todo-field-text" data-todo-problem>${problemMarkup||esc(upTodoProblemSummary(task))}</div></section>`:field('description','问题描述',task.description,true)}${upTodoCollaborative(task)&&task.gdWorkKey?upTodoAssignmentPreview(task):field('plan','执行事项',task.plan)}`;
 const display=(key,value)=>inline?upTodoInlineDisplay(key,value):value;
 const problem=problemMarkup||(upTodoHasEvidence(task)?esc(upTodoProblemSummary(task)):display('description',upTodoDescriptionMarkup(task)));
 return `<section><h5>问题描述</h5><div class="up-todo-field-text" data-todo-problem>${problem}</div></section>${inline?'':`<section><h5>执行事项</h5><div class="up-todo-field-text" data-todo-execution>${upTodoExecutionMarkup(task,false)}</div></section>`}${task.evidence?`<section><h5>处理结果</h5><p>${esc(task.evidence)}</p></section>`:''}`;
}
function upOpenTodoDialog(original,mode,state,onSaved){
 const task={...original},origin=document.activeElement;
 if(['create','assign'].includes(mode))Object.assign(task,upTodoDrafts.get(task.id));
 const headingId=document.getElementById('up-todo-dialog-title')?'up-todo-dialog-title-'+crypto.randomUUID():'up-todo-dialog-title';
 const dialog=document.createElement('dialog');dialog.className='up-todo-dialog';dialog.setAttribute('aria-labelledby',headingId);
 const close=()=>{if(dialog.upFlushInline?.()===false)return;dialog.close()};
 const draw=()=>{
  dialog.upObjectEditCleanup?.();
  dialog.upInlineCleanup?.();dialog.querySelector('[data-up-collaboration]')?.upExecutionConfirmCleanup?.();dialog.querySelector('[data-up-collaboration]')?.upPeopleMultipleCleanup?.();
  dialog.upPriorityCleanup?.();dialog.upPriorityCleanup=null;
  dialog.upCancelResponsibilityDraft=null;
  const editable=['create','assign'].includes(mode),deleting=mode==='delete',inline=mode==='detail'&&task.status!=='suggested';
  dialog.classList.toggle('up-todo-dialog-detail',!editable&&!deleting);
  dialog.classList.toggle('up-todo-drawer',!deleting);
  dialog.classList.toggle('up-todo-dialog-delete',deleting);
  const titles={create:'新增待办',assign:'下发待办',basis:'任务详情',detail:'任务详情',delete:'删除任务'};
  const detailHeading=mode==='detail'||mode==='basis';
  const canDelete=detailHeading&&task.status!=='suggested'&&upTodos[task.id]&&!upTodos[task.id].deletedAt;
  const hasFooter=editable||deleting,hasEvidence=!deleting&&(upTodoHasEvidence(task)||!!state.todoEvidenceMarkup);
  const evidenceTitle=state.todoEvidenceTitle??'任务依据';
  const evidenceMarkup=hasEvidence?(state.todoEvidenceMarkup?.(task)||upTodoEvidenceMarkup(task)):'';
  const button=(action,label)=>`<button type="submit" class="btn ${action==='delete'?'up-todo-delete-confirm':'primary'}" data-todo-action="${action}">${label}</button>`;
  const basics=deleting?'':`<aside class="up-todo-basic-section" aria-label="基础信息">${upTodoCommonFields(task,editable,inline)}</aside>`;
  const content=deleting?'<p class="up-todo-delete-question">确认删除这条任务？</p>':upTodoDetailFields(task,editable,inline,state.todoProblemMarkup?.(task)||'')+(inline?'<div data-up-collaboration></div>':'')+(hasEvidence?`<section class="up-todo-evidence-section"><button type="button" class="link" data-todo-evidence aria-expanded="false" aria-controls="up-todo-evidence-panel">查看依据</button><section class="up-todo-evidence" id="up-todo-evidence-panel" data-todo-evidence-panel hidden tabindex="-1">${evidenceTitle?`<h5>${esc(evidenceTitle)}</h5>`:''}${evidenceMarkup}</section></section>`:'');
  dialog.innerHTML=`<form novalidate><header><h3 id="${headingId}" class="${detailHeading?'up-todo-detail-heading':''}">${detailHeading?upTodoDetailHeading(task,state.todoBusinessObjects):titles[mode]}</h3><div class="up-todo-dialog-header-actions">${!editable&&!deleting&&task.status==='suggested'?'<button type="button" class="btn primary" data-todo-to-assign>下发待办</button>':''}${canDelete?'<button type="button" class="btn up-todo-delete-trigger" data-todo-delete>删除任务</button>':''}<button type="button" class="up-todo-dialog-close" data-todo-close aria-label="关闭待办${deleting?'弹窗':'抽屉'}">×</button></div></header>
   ${detailHeading||deleting?'':`<div class="up-todo-heading">${upTodoTitleField(task,editable,state.todoBusinessObjects)}</div>`}
   <div class="up-todo-workspace"><div class="up-todo-dialog-body"><div id="up-todo-panel-detail">${content}</div><p class="up-todo-dialog-error" role="alert"></p></div>${basics}</div>
   ${hasFooter?`<footer><div><button type="button" class="btn" data-todo-close>${editable||deleting?'取消':'关闭'}</button>${editable?button(mode,mode==='assign'?'确认下发':'保存'):deleting?button('delete','确认删除'):task.status==='suggested'?'<button type="button" class="btn primary" data-todo-to-assign>下发待办</button>':''}</div></footer>`:''}</form>`;
  const evidenceButton=dialog.querySelector('[data-todo-evidence]');if(evidenceButton)evidenceButton.onclick=()=>{const panel=dialog.querySelector('[data-todo-evidence-panel]'),open=panel.hidden;panel.hidden=!open;evidenceButton.setAttribute('aria-expanded',String(open));evidenceButton.textContent=open?'收起依据':'查看依据';if(open){panel.focus({preventScroll:true});panel.scrollIntoView({block:'nearest'})}};
  if(editable){upBindTodoPeople(dialog,task);const picker=upMountTodoPriority(dialog.querySelector('select[name="priority"]'));dialog.upPriorityCleanup=()=>picker.destroy()}
  let refreshCollaboration=()=>{};
  const syncResponsibilitySummary=saved=>{
   if(!dialog.querySelector('[data-up-collab-status]')){draw();onSaved('edit');return}
   dialog.querySelector('[data-up-collab-status]').innerHTML=upTodoStatusTag(saved);
   const execution=dialog.querySelector('[data-todo-execution]');if(execution)execution.innerHTML=upTodoExecutionMarkup(saved,inline);
   dialog.querySelector('[data-todo-completed-date]').textContent=upTodoDate(saved.completedAt);dialog.querySelector('[data-todo-planned-date]').textContent=upTodoDate(upTodoPlannedDate(saved));dialog.querySelector('[data-todo-overdue]').innerHTML=upTodoOverdue(saved);onSaved('edit');
  };
  if(inline)upBindTodoInline(dialog,task,(key,roleId)=>{if(roleId||key==='plan')refreshCollaboration();if(roleId)syncResponsibilitySummary(task);else onSaved('edit')});
  const collaboration=dialog.querySelector('[data-up-collaboration]');
  if(collaboration)refreshCollaboration=upMountTodoCollaboration(collaboration,task,syncResponsibilitySummary);
  const form=dialog.querySelector('form');
  if(inline&&task.gdManualEntry)gdMountTaskObjectEdit(dialog,task,saved=>{Object.assign(task,saved);state.todoBusinessObjects=saved.businessObjects;onSaved('edit');draw()});
  for(const b of dialog.querySelectorAll('[data-todo-close]'))b.onclick=close;
  const remove=dialog.querySelector('[data-todo-delete]');
  if(remove)remove.onclick=()=>{
   if(dialog.upFlushInline?.()===false)return;
   // 确认层复用共用删除模型；取消不重绘父层，保留执行事项草稿和滚动位置。
   upOpenTodoDialog(upTodos[task.id]||task,'delete',state,action=>{dialog.close();onSaved(action)});
  };
  const forward=dialog.querySelector('[data-todo-to-assign]');if(forward)forward.onclick=()=>{mode='assign';Object.assign(task,upTodoDrafts.get(task.id));draw()};
  const values=()=>({...Object.fromEntries(['title','description','plan','assignee','due','priority'].filter(key=>form.elements[key]).map(key=>[key,form.elements[key].value.trim()]))});
  if(editable){form.oninput=()=>{Object.assign(task,values());upTodoDrafts.set(task.id,values());form.querySelectorAll('[data-todo-assign-date="inherit"]').forEach(node=>{node.textContent=upTodoDate(task.due)})};form.onchange=form.oninput}
  form.onsubmit=e=>{
   e.preventDefault();const action=e.submitter?.dataset.todoAction;if(!action)return;
   if(editable&&!form.checkValidity()){form.reportValidity();return}
   try{
    if(action==='delete')upDeleteTodo(original);else upSaveTodo(original,action,values());
    close();onSaved(action);
   }catch(error){const message=dialog.querySelector('.up-todo-dialog-error');message.textContent=error.message;message.scrollIntoView({block:'nearest'})}
  };
 };
 draw();document.body.append(dialog);
 dialog.addEventListener('close',()=>{dialog.upObjectEditCleanup?.();dialog.upInlineCleanup?.();dialog.upPriorityCleanup?.();dialog.querySelector('[data-up-collaboration]')?.upExecutionConfirmCleanup?.();dialog.querySelector('[data-up-collaboration]')?.upPeopleMultipleCleanup?.();dialog.remove();if(origin?.isConnected)origin.focus({preventScroll:true});else document.querySelector('[data-todo-tab][aria-selected="true"]')?.focus({preventScroll:true})},{once:true});
 dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
 dialog.showModal();
}
window.addEventListener('keydown',event=>{
 if(event.isComposing)return;
 const dialog=[...document.querySelectorAll('.up-todo-dialog[open]')].at(-1);
  if(dialog&&event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();if(dialog.upCancelObjectEdit?.())return;if(!dialog.upCancelInline?.()){const popup=dialog.querySelector('[data-todo-priority-popup]:popover-open'),people=dialog.querySelector('.up-todo-people-options:popover-open');if(popup)popup.upClosePriority?.();else if(people)people.closest('[data-people-picker]')?.upClosePeople?.();else if(!dialog.upCancelResponsibilityDraft?.())dialog.close()}}
},true);
function upTodoPeople(value='',task){
 return '<option value="">请选择</option>'+upTodoAssignable(task).map(({name})=>`<option value="${esc(name)}" ${name===value?'selected':''}>${esc(upTodoPersonLabel(name,task))}</option>`).join('');
}
function upTodoOverdue(task){return task.status!=='done'&&task.status!=='suggested'&&task.due&&task.due<aiToday()?'<span class="up-todo-overdue">已逾期</span>':''}
function upTodoStatusTag(task){return `<span class="up-todo-status ${task.status}">${upTodoStatuses[task.status]}</span>`}
function upTodoStatusSelect(task){return `<select class="up-todo-status-select ${task.status}" data-todo-status-select aria-label="任务状态">${Object.entries(upTodoStatuses).filter(([key])=>key!=='suggested').map(([key,label])=>`<option value="${key}" ${key===task.status?'selected':''}>${label}</option>`).join('')}</select>`}
function upTodoDueCell(task){return `<span class="up-todo-due">${esc(task.due||'—')}${upTodoOverdue(task)}</span>`}
function upTodoDate(value){if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(d)}
// 下发时间读取原始记录，按北京时间显示；旧记录只有日期时不补造具体时刻。
function upTodoDispatchTime(value){
 if(!value)return '—';
 if(/^\d{4}-\d{2}-\d{2}$/.test(value))return upTodoDate(value)+'（时间未记录）';
 const date=new Date(value);if(Number.isNaN(date.getTime()))return '—';
 return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(date);
}
function upTodoDispatcher(task){return task.status==='suggested'?'—':task.source==='manual'?(task.assignedBy||'手工创建'):'AI自动下发'}
function upTodoPriorityTag(task){
 const key=upTodoPriorityKey(task.priority);
 return `<span class="up-todo-priority ${key}" aria-label="${upTodoPriorities[key]}">${esc(upTodoPriorities[key])}</span>`;
}
// 一列保留部门与人员的对应关系；全局协同可传单个责任项。
function upTodoOwnerCell(task,role=null){
 const roles=role?[role]:upTodoCollaborative(task)?task.responsibilities:[upTodoLegacyResponsibility(task)];
 return roles.map(r=>`<div class="up-todo-owner"><small>${esc(r.department||upTodoPersonDepartment(r.assignee,task)||'—')}</small> / <span>${esc(r.assignee||'待分配')}</span></div>`).join('');
}
function upTodoRow(t,suggested){
 const action=(mode,label)=>`<button type="button" class="link" data-todo-open="${mode}" data-todo-id="${esc(t.id)}">${label}</button>`;
 const operations=suggested?action('detail','详情')+action('assign','下发'):action('detail','详情')+action('delete','删除');
 const subject=`<div class="up-todo-subject-cell">${suggested?`<input type="checkbox" data-todo-select="${esc(t.id)}" aria-label="选择${esc(t.title)}">`:''}<div class="up-todo-subject"><b>${esc(upTodoExecutionText(t))}</b></div></div>`;
 return [upTodoPriorityTag(t),`<div class="up-todo-description">${esc(upTodoProblemSummary(t))}</div>`,subject,upTodoOwnerCell(t),upTodoDueCell(t),esc(upTodoDate(t.completedAt)),upTodoStatusTag(t),`<div class="up-todo-row-actions">${operations}</div>`];
}
const upTaskStorageKey='unified-spu-tasks-v1';
let upTasks={};
try { const saved=JSON.parse(localStorage.getItem(upTaskStorageKey)||'{}'); if(saved&&typeof saved==='object'&&!Array.isArray(saved)) upTasks=saved; } catch(_) {}
// 旧任务仅凭可验证的SPU或对象ID关联，绝不以型号猜测关联。
function upLegacyTasks(spuId) {
  const ledger=inventoryProductLedger(),catalog=qrCatalog(),result=[];
  for(const task of Object.values(riskTasks)) {
    let p=upIdentity(task),platform=task.platform||'unknown';
    if(!p) {
      let record=null;
      if(task.kind===0) record=catalog.find(r=>r.id===task.objectId);
      if(task.kind===2) record=[...upLossSeeds.values()].find(r=>r.id===task.objectId);
      if(task.kind===3) record=ledger[task.objectId-1000];
      if(task.kind===4) record=ledger[task.objectId-2000];
      if(task.kind===6) {
        record=catalog.find(r=>r.id===Math.floor((task.objectId-3000)/6));
        platform=qrPlatforms[(task.objectId-3000)%6]||platform;
      }
      // 旧样例曾更换过主数据；名字不符时不迁移到另一个产品。
      if(record&&record.name===task.objectName) p=upIdentity(record);
    }
    if(p?.spuId!==spuId)continue;
    if([2,3,4].includes(task.kind)&&!task.platform)platform='all';
    result.push({...task,spuId,start:task.start||'',end:task.end||task.cutoff||'',platform,legacy:true});
  }
  return result;
}
function upHistory(spuId) {
  const current=Object.values(upTasks).filter(t=>t.spuId===spuId);
  const inherited=upLegacyTasks(spuId).filter(t=>!current.some(n=>n.id&&n.id===t.id));
  return [...current,...inherited].sort((a,b)=>(b.updatedAt||b.createdAt||'').localeCompare(a.updatedAt||a.createdAt||''));
}
// 抽屉复用外侧日/月/季/年控件，隔离事件和状态，不回写外侧期间。
function drawerWithPeriod(period,run,scope='risk'){
 const prior=localPeriods[scope];localPeriods[scope]=period;
 try{return withPeriod(scope,run)}finally{if(prior)localPeriods[scope]=prior;else delete localPeriods[scope]}
}
function drawerPeriodFromRange(range){return {mode:'day',year:+range.end.slice(0,4),value:+range.end.slice(5,7),start:range.start,end:range.end}}
function drawerMountPeriod(host,initial,onChange,triggerId,scope='risk'){
 let period={...initial},dayRange=upWindow(period);
 function render(){
  host.innerHTML=drawerWithPeriod(period,()=>periodControls(scope),scope)
   .replaceAll('data-time-','data-drawer-time-').replaceAll('data-risk-day','data-drawer-time-day')
   .replace('id="risk-date-trigger"','id="'+triggerId+'"').replace('aria-controls="risk-date-popover"','aria-controls="up-date-popover"');
  host.querySelector('.follow-time')?.remove();
  host.querySelector('.period-segment').setAttribute('aria-label','抽屉时间粒度');
  const picker=host.querySelector('.period-picker');picker.onclick=handleClick;picker.onchange=handleChange;
  const trigger=host.querySelector('.risk-date-trigger');
  if(trigger){trigger.setAttribute('aria-label','选择抽屉日期');trigger.onclick=()=>upOpenCalendar(trigger,dayRange,(start,end)=>{dayRange={start,end};apply(drawerPeriodFromRange(dayRange))})}
 }
 function apply(next){upCalendarClose?.(false);period=next;render();onChange({...period},upWindow(period))}
 function handleClick(e){
  const button=e.target.closest('[data-drawer-time-mode],[data-drawer-time-day]');if(!button)return;
  if(button.hasAttribute('data-drawer-time-day')){apply(drawerPeriodFromRange(dayRange));return}
  const mode=button.dataset.drawerTimeMode,range=upWindow(period);
  const month=period.mode==='day'?+range.end.slice(5,7):period.mode==='month'?period.value:period.mode==='quarter'?period.value*3:12;
  apply(normalizePeriod({mode,year:period.year,value:mode==='month'?month:mode==='quarter'?Math.ceil(month/3):1}));
 };
 function handleChange(e){
  if(!e.target.matches('[data-drawer-time-year],[data-drawer-time-value]'))return;
  const next={...period};next[e.target.hasAttribute('data-drawer-time-year')?'year':'value']=+e.target.value;apply(normalizePeriod(next));
 };
 render();
 return {set(next){period={...next};render()}};
}

// 产品和店铺详情将独立日期放在标签栏右侧；父榜单仍使用原头部位置。
