// 旧趋势调用者的比率同样按统一GSV基数，不取日百分比的平均。
const upPreviousTrendTotals=newTrendTotals;
newTrendTotals=function(series){
  const result=upPreviousTrendTotals(series),points=series.flatMap(s=>s.points);
  if(points.every(p=>Number.isInteger(p.gsvCents))){const net=points.reduce((n,p)=>n+p.gsvCents,0);result.margin=net?result.profitCents/net*100:null}
  return result;
};

// 配置改变后返回榜单，复用原填表函数并保留原分页、筛选和滚动。
const upOriginalQualityList=qrOpenList;
qrOpenList=function(...args){const result=upOriginalQualityList(...args);const host=$('#qr-list-table');if(host)host.dataset.upRevision=upRuleRevision;return result};
const upOriginalReturn=drawerReturn;
drawerReturn=function(...args){
  const returned=upOriginalReturn(...args),host=$('#qr-list-table');
  if(returned&&host?.upRefresh&&Number(host.dataset.upRevision)!==upRuleRevision){host.upRefresh();host.dataset.upRevision=upRuleRevision}
  return returned;
};

// 初始渲染由 startup/02-render.js 在全部展示适配器登记后统一执行。
// 10pp净利测算：原型毛利台账的分母为GSV；正式源字段仍需映射。
function upNetEstimate(s){const deduction=Math.round(s.gsvCents*brcNumber('finance.deduction')/100),profitCents=s.profitCents-deduction;return {profitCents,profitRate:s.gsvCents?profitCents/s.gsvCents*100:null,deductionCents:deduction,grossProfitCents:s.profitCents,grossProfitRate:s.profitRate}}
function rpLossRows(platform){
 const w=upWindow();return [...upSpus.values()].map(p=>{
  const s=upSummary(p,w.start,w.end,platform),n=upNetEstimate(s);
  return {...upProduct(p),metricPlatform:platform,lossPlatform:platform,loss:-n.profitCents/1000000,value:upMoney(n.profitCents)};
 }).filter(r=>r.loss>0).sort((a,b)=>b.loss-a.loss||a.spuId.localeCompare(b.spuId));
}

// 所有产品维度共用四链群，旧五类只在读取边界归一，不再按名称拆分个护与健康。
const pfCategories=filterCatalog.chains;
function pfCategory(record){
 return filterCatalog.normalizeChain(record.category)||filterCatalog.chainByIndex[record.chain]||null;
}
function pfAttributeField(filters,keys,attr,choices,labels,title='产品类型',multiple=false){
 const selected=keys.filter(k=>pfSelected(filters[k]).length).map(k=>labels[k]+':'+pfSelected(filters[k]).map(value=>{const option=choices[k].find(x=>typeof x==='string'?x===value:x.value===value);return typeof option==='string'?option:option?.label||value}).join('、'));
 return '<details class="pf-attribute"><summary class="unified-input-group"><span class="unified-field-name">'+esc(title)+'</span><span class="pf-attribute-value">'+esc(selected.join(' / ')||'全部')+'</span><i class="ui-dropdown-icon" aria-hidden="true"></i></summary><div class="pf-attribute-menu">'+keys.map(key=>{
  const options=[{value:'all',label:'全部'},...choices[key].map(x=>typeof x==='string'?{value:x,label:x}:x)];
  return '<div class="pf-attribute-row"><b>'+labels[key]+'</b><select hidden '+(multiple?'multiple ':'')+'tabindex="-1" '+attr+'="'+key+'" aria-label="'+labels[key]+'">'+pfOptions(choices[key],filters[key])+'</select><div role="'+(multiple?'group':'radiogroup')+'" aria-label="'+labels[key]+'">'+options.map(x=>'<button type="button" role="'+(multiple?'checkbox':'radio')+'" aria-checked="'+pfOptionSelected(filters[key]||'all',x.value)+'" data-pf-attribute-choice="'+x.value+'" data-pf-attribute-key="'+key+'"><i></i>'+esc(x.label)+'</button>').join('')+'</div></div>';
 }).join('')+'</div></details>';
}
// 从实际控件值同步摘要及选中态，筛选重置后不保留旧显示。
function pfAttributeSync(root){for(const menu of root.querySelectorAll('.pf-attribute')){
 for(const select of menu.querySelectorAll('.pf-attribute-row select'))for(const radio of select.parentElement.querySelectorAll('[data-pf-attribute-choice]'))radio.setAttribute('aria-checked',String(pfOptionSelected(pfControlValue(select),radio.dataset.pfAttributeChoice)));
 menu.querySelector('.pf-attribute-value').textContent=[...menu.querySelectorAll('select')].filter(s=>pfSelected(pfControlValue(s)).length).map(s=>s.getAttribute('aria-label')+':'+[...s.selectedOptions].filter(o=>o.value!=='all').map(o=>o.textContent).join('、')).join(' / ')||'全部';
}}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-pf-attribute-choice]');
 if(!b){for(const menu of document.querySelectorAll('.pf-attribute[open]'))if(!menu.contains(e.target))menu.open=false;return}
 const menu=b.closest('.pf-attribute'),select=b.closest('.pf-attribute-row').querySelector('select'),bar=menu.parentElement;
 const value=b.dataset.pfAttributeChoice,selected=pfSelected(pfControlValue(select));
 pfControlSet(select,pfToggleChoice(selected,value,select.multiple));
 pfAttributeSync(bar);
 select.dispatchEvent(new Event('change',{bubbles:true}));
 queueMicrotask(()=>{const next=bar.isConnected?bar:document.querySelector('#dialogbody .rp-list-tools');if(next?.querySelector('.pf-attribute'))next.querySelector('.pf-attribute').open=true});
});
// 比抽屉的document捕获事件先处理，只收起当前菜单并把焦点交还触发器。
window.addEventListener('keydown',e=>{if(e.key==='Escape')for(const menu of document.querySelectorAll('.pf-attribute[open]')){menu.open=false;menu.querySelector('summary').focus({preventScroll:true});e.stopImmediatePropagation();e.preventDefault()}},true);

// 多选只管理控件与取值；同字段 OR，跨字段仍由业务模型按 AND 组合。
function pfSelected(value){return [...new Set((Array.isArray(value)?value:[value]).filter(v=>v!=null&&!['all','全部',''].includes(String(v))).map(v=>filterCatalog.normalizeChain(v)||String(v)))]}
function pfIncludes(value,actual){const selected=pfSelected(value);return !selected.length||selected.includes(filterCatalog.normalizeChain(actual)||String(actual))}
function pfOptionSelected(value,option){const selected=pfSelected(value);return selected.length?selected.includes(String(option)):['all','全部'].includes(String(option))}
// 普通多选和分组筛选共用切换规则，保留调用方现有单/多选定义。
function pfToggleChoice(value,option,multiple=true){
 if(!multiple)return option;
 const selected=pfSelected(value);return ['all','全部'].includes(option)?'all':selected.includes(option)?selected.filter(v=>v!==option):[...selected,option];
}
function pfControlValue(control){if(!control.multiple)return control.value;const values=[...control.selectedOptions].map(o=>o.value).filter(v=>!['all','全部'].includes(v));return values.length?values:'all'}
function pfControlSet(control,value){
 if(control.multiple)for(const option of control.options)option.selected=pfOptionSelected(value,option.value);else control.value=value;
 pfMultiSync(control);
 control.uiPlatformControl?.sync();
}
function pfMultiSync(select){
 const menu=select.closest('.pf-multi');if(!menu)return;
 const selected=pfSelected(pfControlValue(select)),options=[...select.options],names=options.filter(o=>selected.includes(o.value)).map(o=>o.textContent);
 // 默认值沿用业务选项文案，例如“全部产品”“全部类目”。
 const allLabel=options.find(o=>['all','全部'].includes(o.value))?.textContent||'全部';
 const text=names.join('、')||allLabel,value=menu.querySelector('.pf-multi-value');
 if(value.textContent!==text)value.textContent=text;
 value.title=text;menu.classList.toggle('pf-multi-active',!!selected.length);
 for(const box of menu.querySelectorAll('[data-pf-multi-option]'))box.checked=selected.length?selected.includes(box.value):['all','全部'].includes(box.value);
 if(select.uiPlatformMulti)uiPlatformSyncMulti(select);
}
let pfMultiControlledId=0;
function pfMultiMount(root,{controlled=false}={}){
 for(const select of root.querySelectorAll('.pf-multi select'))pfMultiSync(select);
 for(const select of root.querySelectorAll('select')){
  if(select.closest('.pf-multi,.pf-attribute')||select.disabled)continue;
  const field=select.parentElement,label=field.querySelector(':scope > .unified-field-name')?.textContent||select.getAttribute('aria-label')||[...field.childNodes].filter(n=>n!==select).map(n=>n.textContent).join('').trim();
  if(!select.hasAttribute('data-pf-multiple')&&!['品牌','链群','所属链群','全部新品所属链群','AI链群筛选'].includes(label))continue;
  const selected=[...select.selectedOptions].map(o=>o.value);
  select.multiple=true;select.hidden=true;select.tabIndex=-1;
  const menu=document.createElement(controlled?'div':'details');menu.className='pf-multi';
  const title=select.dataset.pfLabel||(/品牌/.test(label)?'品牌':'链群');menu.dataset.pfMultiLabel=title;
  menu.innerHTML='<summary class="unified-input-group" aria-label="'+esc(title)+'多选"><span class="unified-field-name">'+esc(title)+'</span><span class="pf-multi-value"></span><i class="ui-dropdown-icon" aria-hidden="true"></i></summary><div class="pf-multi-menu" role="group" aria-label="'+esc(title)+'选项">'+[...select.options].map(o=>'<label class="pf-multi-option"><input type="checkbox" data-pf-multi-option value="'+esc(o.value)+'" '+(o.disabled?'disabled':'')+'><span>'+esc(o.textContent)+'</span></label>').join('')+'</div>';
  // 原生模态框中使用普通按钮和受控面板，避免嵌套details的浏览器原生开合/焦点处理。
  if(controlled){
   menu.dataset.pfControlled='';const summary=menu.querySelector('summary'),button=document.createElement('button'),panel=menu.querySelector('.pf-multi-menu');
   button.type='button';button.className=summary.className;button.dataset.pfMultiTrigger='';button.setAttribute('aria-expanded','false');
   panel.id='pf-controlled-'+(++pfMultiControlledId);button.setAttribute('aria-controls',panel.id);button.setAttribute('aria-label',title+'多选');
   button.append(...summary.childNodes);summary.replaceWith(button);
   Object.defineProperty(menu,'open',{get(){return this.hasAttribute('open')},set(value){const next=Boolean(value);if(next===this.hasAttribute('open'))return;this.toggleAttribute('open',next);button.setAttribute('aria-expanded',String(next));this.dispatchEvent(new Event('toggle'))}});
  }
  if(field.matches('label')){field.replaceWith(menu);menu.append(select)}else{select.before(menu);menu.append(select)}
  pfControlSet(select,selected);
 }
}
function pfMultiClose(menu,focus=false){menu.open=false;if(focus)menu.querySelector('summary,[data-pf-multi-trigger]').focus({preventScroll:true})}
document.addEventListener('change',e=>{
 const box=e.target.closest('[data-pf-multi-option]');
 if(!box){if(e.target.matches('select'))pfMultiSync(e.target);return}
 e.stopImmediatePropagation();
 const menu=box.closest('.pf-multi'),select=menu.querySelector('select'),selected=pfSelected(pfControlValue(select));
 const values=pfToggleChoice(selected,box.value);
 const parent=menu.closest('#dialogbody')||menu.closest('#department-view')||menu.closest('section.section')||menu.parentElement;
 const identity=select.id?{id:select.id}:Object.fromEntries([...select.attributes].filter(a=>a.name.startsWith('data-')).map(a=>[a.name,a.value]));
 pfControlSet(select,values);
 select.dispatchEvent(new Event('change',{bubbles:true}));
 // 部分模块整体重绘，恢复菜单及刚勾选项焦点，允许继续多选。
 queueMicrotask(()=>{
  pfMultiMount(parent);
  const next=select.isConnected?select:identity.id?document.getElementById(identity.id):[...parent.querySelectorAll('.pf-multi select')].find(s=>Object.entries(identity).every(([a,v])=>s.getAttribute(a)===v));
  const replacement=next?.closest('.pf-multi');if(!replacement)return;
  replacement.open=true;[...replacement.querySelectorAll('[data-pf-multi-option]')].find(b=>b.value===box.value)?.focus({preventScroll:true});
 });
},true);
document.addEventListener('click',e=>{
 const current=e.target.closest('.pf-multi');
 if(current?.hasAttribute('data-pf-controlled')&&e.target.closest('[data-pf-multi-trigger]'))current.open=!current.open;
 for(const menu of document.querySelectorAll('.pf-multi[open]'))if(menu!==current)pfMultiClose(menu);
});
window.addEventListener('keydown',e=>{
 if(e.key!=='Escape')return;
 const menu=document.querySelector('.pf-multi[open]');if(!menu)return;
 pfMultiClose(menu,true);e.preventDefault();e.stopImmediatePropagation();
},true);
// 品牌、类目、季品及产品类型只读主数据；缺失标记不当作老品或清仓品。
function pfDefaults(){return {brand:'all',chain:'all',attribute:'all',productType:'all'}}
function pfIdentity(record){
 const source=upIdentity(record)||sampleSpus.find(p=>p.spuId===record.spuId||p.spuCode===record.spuCode)||sampleSpuByName(record.name);
 const brand=source?.brand||(typeof record.brand==='number'?brands[record.brand]:record.brand),cohort=source?.cohort||record.cohort;
 return {brand,chain:source?.chain??record.chain,category:pfCategory(source||record),attribute:record.attribute||source?.attribute||(source?srAttribute(source.name):null),
  isNew:typeof record.isNew==='boolean'?record.isNew:cohort==='new'?true:cohort==='old'?false:null,
  clearance:typeof record.clearance==='boolean'?record.clearance:typeof source?.clearance==='boolean'?source.clearance:null};
}
function pfMatches(record,filters){const p=pfIdentity(record);return ['brand','chain','attribute','productType'].every(key=>{
 const value=filters[key]??'all';if(!pfSelected(value).length)return true;
 if(key==='productType')return pfSelected(value).some(v=>v==='new'?p.isNew===true:v==='old'?p.isNew===false:v==='clearance'?p.clearance===true:false);
 return pfSelected(value).some(v=>key==='chain'&&pfCategories.includes(v)?p.category===v:String(p[key])===v);
})}
function pfOptions(options,value,allLabel='全部'){return [{value:'all',label:allLabel},...options.map(x=>typeof x==='string'?{value:x,label:x}:x)].map(x=>`<option value="${esc(x.value)}" ${pfOptionSelected(value,x.value)?'selected':''}>${esc(x.label)}</option>`).join('')}
function pfFields(filters,keys=['brand','chain','attribute','productType'],attr='data-pf-filter',multiple=false){
 const choices={brand:[...new Set(sampleSpus.map(p=>p.brand))],chain:pfCategories,attribute:filterCatalog.seasons,productType:filterCatalog.productTypes};
 const labels={brand:'品牌',chain:'链群',attribute:'季品',productType:'属性'};
 const field=key=>`<label>${labels[key]}<select ${attr}="${key}" ${['brand','chain'].includes(key)?'multiple data-pf-multiple':''} aria-label="${labels[key]}">${pfOptions(choices[key],filters[key])}</select></label>`;
 const properties=keys.filter(k=>['attribute','productType'].includes(k));
 return keys.filter(k=>!properties.includes(k)).map(field).join('')+(properties.length?pfAttributeField(filters,properties,attr,choices,labels,'产品类型',multiple):'');
}
function pfMount(bar,filters,refresh,keys){
 if(!bar)return;bar.classList.add('pf-tools');bar.insertAdjacentHTML('beforeend',pfFields(filters,keys));
 for(const input of bar.querySelectorAll('[data-pf-filter]'))input.onchange=()=>{filters[input.dataset.pfFilter]=pfControlValue(input);refresh()};
 uiArrangeBusinessFilters(bar.parentElement);
}
// 六榜各自持有期间；库存始终使用最新快照，退货使用成熟区间及显式对照期。
const rpTimedBoards=[0,6,1,2],rpBoardPeriods={};
function rpLatestReturnMonth(reference=dashboardSyncDate()){
 const month=reference.slice(0,7);if(Number(reference.slice(8))>=21)return month;
 const stableEnd=shiftDate(reference,-16),stableMonth=stableEnd.slice(0,7),monthEnd=shiftDate(dateRangeMonthShift(stableMonth,1)+'-01',-1);
 return monthEnd<=stableEnd?stableMonth:dateRangeMonthShift(stableMonth,-1);
}
function rpReturnPeriod(mode='week',value=dashboardSyncDate(),reference=dashboardSyncDate()){
 if(mode==='month'){
  const latest=rpLatestReturnMonth(reference),month=value>latest?latest:value;
  const previousMonth=dateRangeMonthShift(month,-1),start=month+'-01';
  const monthEnd=shiftDate(dateRangeMonthShift(month,1)+'-01',-1),stableEnd=shiftDate(reference,-16);
  const end=month===reference.slice(0,7)?(stableEnd<monthEnd?stableEnd:monthEnd):monthEnd;
  return {mode:'day',year:+month.slice(0,4),value:+month.slice(5,7),start,end,comparisonMode:'month',reference,
   previousStart:previousMonth+'-01',previousEnd:shiftDate(start,-1),stableEnd};
 }
 const anchor=value;
 return {mode:'day',year:+anchor.slice(0,4),value:+anchor.slice(5,7),start:shiftDate(anchor,-22),end:shiftDate(anchor,-16),
  comparisonMode:'week',reference:anchor,previousStart:shiftDate(anchor,-29),previousEnd:shiftDate(anchor,-23),stableEnd:shiftDate(anchor,-16)};
}
function rpDefaultBoardPeriod(kind,date=dashboardSyncDate()){
 return kind===6?rpReturnPeriod('week',date,date):{mode:'day',year:+date.slice(0,4),value:+date.slice(5,7),start:shiftDate(date,-29),end:date};
}
for(const kind of rpTimedBoards)rpBoardPeriods[kind]=rpDefaultBoardPeriod(kind,DATA_CUTOFF);
function rpUsesBoardPeriods(){return wfDirector()&&(typeof pcIsActive!=='function'||!pcIsActive())}
function rpBoardPeriod(kind){return !rpUsesBoardPeriods()?periodFor('risk'):[3,4].includes(kind)?rpDefaultBoardPeriod(kind):rpBoardPeriods[kind]||rpDefaultBoardPeriod(kind)}
function rpWithBoardPeriod(kind,read,period=rpBoardPeriod(kind)){return drawerWithPeriod(period,read)}
function rpDetailPeriod(kind){
 const body=$('#dialogbody'),saved=!$('#overlay').hidden&&body.dataset.riskRankingKind===String(kind)?body.dataset.rankingPeriod:null;
 return saved?JSON.parse(saved):{...rpBoardPeriod(kind)};
}
function rpBoardRangeText(kind){
 const p=periodFor('risk');if(kind===6&&p.comparisonMode)return p.start+' ~ '+p.end+' vs '+p.previousStart+' ~ '+p.previousEnd;
 return [3,4].includes(kind)?'实时快照 '+DATA_CUTOFF:riskRangeText();
}
// 日期区间与对比标记独立呈现，纯文本口径继续供其他入口复用。
function rpBoardRangeMarkup(kind){
 const period=periodFor('risk');
 if(kind!==6||!period.comparisonMode)return esc(rpBoardRangeText(kind));
 const range=(start,end)=>'<span class="rp-date-period">'+esc(start+' ~ '+end)+'</span>';
 return range(period.start,period.end)+' <span class="rp-date-versus">vs</span> '+range(period.previousStart,period.previousEnd);
}
function rpBoardControlSlot(kind){return rpUsesBoardPeriods()&&rpTimedBoards.includes(kind)?`<div class="rp-board-period" data-rp-board-date="${kind}"></div>`:''}
function rpClearSharedDateControls(){
 const section=$('#risk');section.classList.toggle('rp-independent-dates',rpUsesBoardPeriods());
 if(rpUsesBoardPeriods()){section.querySelector('#time-risk')?.replaceChildren();section.querySelector('#time-note-risk')?.replaceChildren()}
}

// 成熟月对照期可长于当期，缓存身份必须包含两段日期。
const rpBoardOriginalPeriodKey=periodKey;
periodKey=function(p=periodFor()){return rpBoardOriginalPeriodKey(p)+(p.comparisonMode?'|'+p.comparisonMode+'|'+p.previousStart+'|'+p.previousEnd:'')};
// 普通三榜复用现有抽屉日/月/季/年控件，不注册第二套日期选择器。
function rpApplyBoardPeriod(kind,period){
 if(!rpTimedBoards.includes(kind))return;
 rpBoardPeriods[kind]={...period};renderRisks([kind]);
}
function rpMountBoardDateControls(root){
 if(!rpUsesBoardPeriods())return;
 for(const host of root.querySelectorAll('[data-rp-board-date]')){
  if(host.dataset.mounted)continue;host.dataset.mounted='true';
  const kind=+host.dataset.rpBoardDate,card=host.closest('[data-rp-board]'),head=card.querySelector('.rhead');
  if(kind===2)head.append(host);
  else{
   const actions=head.querySelector('.rp-quality-actions');
   if(actions)actions.prepend(host);
  }
  if(kind===6)rpMountReturnPeriod(host,rpBoardPeriod(kind),period=>rpApplyBoardPeriod(kind,period));
  else drawerMountPeriod(host,rpBoardPeriod(kind),period=>rpApplyBoardPeriod(kind,period),'rp-board-date-'+kind);
 }
}
// 周为滚动七日窗口；月以21日开放当月，不把成熟月初区间等长裁切上月。
function rpMountReturnPeriod(host,initial,onChange){
 let period={...initial};
 const icon='<svg viewBox="0 0 20 20" aria-hidden="true"><rect x="3" y="4" width="14" height="13" rx="2"/><path d="M6 2v4m8-4v4M3 8h14"/></svg>';
 function apply(next){period=next;paint();onChange({...period})}
 function paint(){
  const monthly=period.comparisonMode==='month',reference=dashboardSyncDate(),latest=rpLatestReturnMonth(reference);
  const years=dashboardYears(0,period.year).reverse(),max=period.year===+latest.slice(0,4)?+latest.slice(5,7):period.year>+latest.slice(0,4)?0:12;
  host.innerHTML=`<div class="period-picker rp-return-period" role="group" aria-label="退货恶化对比期间"><div class="period-segment">${[['week','周对比'],['month','月对比']].map(([mode,label])=>`<button type="button" data-rp-return-mode="${mode}" aria-pressed="${period.comparisonMode===mode}">${label}</button>`).join('')}</div>${monthly?`<select data-drawer-time-year data-rp-return-year aria-label="退货对比年份">${years.filter(year=>year<=+latest.slice(0,4)).map(year=>`<option value="${year}" ${year===period.year?'selected':''}>${year} 年</option>`).join('')}</select><select data-rp-return-month aria-label="退货对比月份">${Array.from({length:max},(_,i)=>`<option value="${i+1}" ${period.value===i+1?'selected':''}>${i+1} 月</option>`).join('')}</select>`:`<button type="button" class="risk-date-trigger" data-rp-return-anchor aria-label="选择退货周对比基准日" aria-haspopup="dialog" aria-expanded="false"><span>基准日 ${period.reference}</span>${icon}</button>`}</div>`;
  host.querySelectorAll('[data-rp-return-mode]').forEach(button=>button.onclick=()=>{
   const mode=button.dataset.rpReturnMode;if(mode===period.comparisonMode)return;
   apply(rpReturnPeriod(mode,mode==='month'?rpLatestReturnMonth():dashboardSyncDate()));
  });
  const anchor=host.querySelector('[data-rp-return-anchor]');
  if(anchor)anchor.onclick=()=>{
   if(anchor.getAttribute('aria-expanded')==='true'){dateRangeActive?.close();return}
   openDateRangePicker(anchor,{start:period.reference,end:period.reference},date=>apply(rpReturnPeriod('week',date,date)),{
    id:'rp-return-date-popover',label:'选择退货周对比基准日',single:true,presets:[],min:shiftDate(riskDateMin,29),max:dashboardSyncDate
   });
  };
  host.querySelector('[data-rp-return-year]')?.addEventListener('change',event=>{
   const year=+event.target.value,limit=year===+latest.slice(0,4)?+latest.slice(5,7):12;
   apply(rpReturnPeriod('month',year+'-'+String(Math.min(period.value,limit)).padStart(2,'0')));
  });
  host.querySelector('[data-rp-return-month]')?.addEventListener('change',event=>apply(rpReturnPeriod('month',period.year+'-'+String(event.target.value).padStart(2,'0'))));
 }
 paint();
}
// 展示字段只读取统一台账；不改各榜入池、排序和业务阈值。
const rpState={shopType:'all'};
const rpTitles={0:'产品违规榜',1:'店铺风险榜',2:'亏损产品榜',3:'缺货预警榜（实时）',4:'呆滞预警榜（实时）',6:'退货恶化榜'};
const rpCardKeys={0:['return','received','sanctions','offShelf','contact'],1:['gsv','netSales','sanctions','limited','score'],
  2:['gsv','margin','loss','return','total'],3:['gsv','margin','return','total','turn'],
  4:['staleUnits','staleValue','age','dailyNet15'],6:['gsv','netSales','margin','return','received']};
function rpField(key,name,value,tone='',hint='',target=''){return{key,name,value:String(value??'—'),tone,hint,target}}
function rpCount(n){return Number.isFinite(n)?fmt(n)+'件':'—'}
function rpTone(hit){return hit===null?'':hit?'red':'green'}
function rpGrowth(current,previous){const value=rpQualityChangeValue(current,previous);return value===null?'--':Math.round(Math.abs(value)*10)===0?'持平':rrSigned(value,1,'%')}
function rpShopType(r){return r.shopCategory||shcRules.pending}
function rpShopTypes(platform){return shcRules.options(platform)}
function rpShopTypeOptions(platform){const types=rpShopTypes(platform);if(!types.includes(rpState.shopType))rpState.shopType='all';return ['all',...types].map(t=>`<option value="${t}" ${t===rpState.shopType?'selected':''}>${t==='all'?'全部店铺类型':t}</option>`).join('')}
function rpProduct(r){const p=upIdentity(r);return p?upProduct(p):null}
function rpFieldMap(k,r,qualityOnly=true,violationPlatform='all'){
  if([3,4].includes(k)&&r.skuId)return rpStockFields(k,r,null,null);
  const w=upWindow(),p=upIdentity(r),platform=k===0?r.platform:k===6?r.channel:r.metricPlatform||'all';
  const s=p?upSummary(p,w.start,w.end,platform):null;
  const comparison=riskRange(w.start,w.end),prev=p?upSummary(p,comparison.previousStart,comparison.previousEnd,platform):null;
  const raw={},rows=[],put=(...args)=>rows.push(rpField(...args));
  if(k===1)return rpShopFields(r,qualityOnly);
  if(k===2)return rpLossFields(r,s,prev);
  if(k===6)return rpReturnFields(r,s,prev);
  if(k===3||k===4)return rpStockFields(k,r,s,prev);
  const quality=k===0?r: k===6?qrObservation(upProduct(p),r.channel,w.start,w.end):null;
  if(quality){const m=quality.monthly,events=m.events;Object.assign(raw,{fine:m.fine,frozen:m.frozen,fineAmount:m.fine,frozenAmount:m.frozen,fineCount:events.filter(e=>e.type==='罚款').length,frozenCount:events.filter(e=>e.type==='资金冻结').length,down:m.offShelf+(m.dropCount||0)});put('fine','平台罚款',pfMoneyYuan(m.fine)+'/'+events.filter(e=>e.type==='罚款').length+'次',rpTone(m.fine>0),'所选期间的平台罚款事件次数及金额。');put('frozen','资金冻结',pfMoneyYuan(m.frozen)+'/'+events.filter(e=>e.type==='资金冻结').length+'次',rpTone(m.frozen>0),'所选期间冻结事件次数及金额；缺少解冻台账，不作为实时冻结余额。');put('fineCount','罚款次数',events.filter(e=>e.type==='罚款').length+'次');put('fineAmount','罚款金额',pfMoneyYuan(m.fine),rpTone(m.fine>0));put('frozenCount','冻结次数',events.filter(e=>e.type==='资金冻结').length+'次');put('frozenAmount','冻结金额',pfMoneyYuan(m.frozen),rpTone(m.frozen>0));put('down','链接下架／掉权次数',(m.offShelf+(m.dropCount||0))+'次',rpTone(m.offShelf+(m.dropCount||0)>0),'所选期间下架与掉权事件次数合计，不增加关联链接清单。');}
  if(s){
    const totalTarget=quality?quality.monthly.target:k===2?null:r.returnTarget;
    const receivedTarget=qrbReturnTargets(p,platform).receivedTarget;
    put('return','总退货率',upPercent(s.returnRate),quality?rpTone(quality.monthly.returnHit):'','同期总退件数÷销量；目标按SPU和平台设置。'+(totalTarget===null?'':'当前样例目标 '+upPercent(totalTarget)+'；偏差为实际减目标。'),totalTarget===null?'':`偏差 ${s.returnRate===null?'—':rrSigned(s.returnRate-totalTarget,1,'%')}`);
    put('received','已收退货率',upPercent(s.receivedRate),receivedTarget===null?'':rpTone(s.receivedRate===null?null:s.receivedRate>receivedTarget),'消费者签收后发生的退货件数÷同期销量。'+(receivedTarget===null?'':'已收退目标 '+upPercent(receivedTarget)+'；偏差为实际减目标，单位为%。'),receivedTarget===null?'':`偏差 ${s.receivedRate===null?'—':rrSigned(s.receivedRate-receivedTarget,1,'%')}`);
    put('contact','进线率',upPercent(s.contactRate),quality?rpTone(quality.monthly.contactHit):'','问题进线数÷同期销量；恶化判定与品质榜共用台账。');put('bad','差评率',upPercent(s.badRate),'','差评数÷有效评价数。');
    put('returnTarget','总退货率目标',totalTarget===null?'按平台查看':upPercent(totalTarget));
    put('receivedTarget','已收退货率目标',upPercent(receivedTarget));
    put('returnGrowth','总退货率环比',rpGrowth(s.returnRate,prev.returnRate),'','与上期等长区间的总退货率比较。');put('receivedGrowth','已收退货率环比',rpGrowth(s.receivedRate,prev.receivedRate),'','比较两期已收退货率；与已收退件数环比区分。');put('contactGrowth','进线率环比增长值',qrbContactDeltaText(qrbRateDelta(s.contactRate,prev.contactRate)));
    put('sales','销量',rpCount(s.sales));put('returned','总退件数',rpCount(s.returned));put('receivedUnits','已收退件数',rpCount(s.received));put('contacts','问题进线数',fmt(s.contacts));
    const net=k===2?upNetEstimate(s):{profitCents:s.profitCents,profitRate:s.profitRate};put('gsv','GSV',upMoney(s.gsvCents));put('profit',k===2?'测算净利额':'利润额',upMoney(net.profitCents),net.profitCents<0?'red':'');put('margin',k===2?'测算净利率':'利润率',upPercent(net.profitRate),net.profitRate!==null&&net.profitRate<10?'red':'',k===2?'利润率减'+brcNumber('finance.deduction')+'%；原型按同一GSV基数测算，正式毛利率分母待映射。':'利润额÷GSV。');put('loss',k===2?'测算净亏损':'亏损金额',upMoney(Math.min(0,net.profitCents)),net.profitCents<0?'red':'');put('refund','退款金额',upMoney(s.refundCents));
    put('returnGap','总退超目标幅度',totalTarget===null||s.returnRate===null?'按平台查看':rrSigned(s.returnRate-totalTarget,1,'%'));
    put('previousReturn','上期总退货率',upPercent(prev.returnRate));put('previousReceived','上期已收退货率',upPercent(prev.receivedRate));put('previousContact','上期进线率',upPercent(prev.contactRate));
    const growth=(a,b)=>Number.isFinite(a)&&Number.isFinite(b)&&b!==0?(a-b)/b*100:null;
    Object.assign(raw,{return:s.returnRate,received:s.receivedRate,contact:s.contactRate,bad:s.badRate,returnTarget:totalTarget,receivedTarget,
      returnGrowth:growth(s.returnRate,prev.returnRate),receivedGrowth:growth(s.receivedRate,prev.receivedRate),contactGrowth:qrbRateDelta(s.contactRate,prev.contactRate),
      sales:s.sales,returned:s.returned,receivedUnits:s.received,contacts:s.contacts,gsv:s.gsvCents,profit:net.profitCents,margin:net.profitRate,loss:Math.min(0,net.profitCents),refund:s.refundCents,
      returnGap:Number.isFinite(totalTarget)&&Number.isFinite(s.returnRate)?s.returnRate-totalTarget:null,receivedGap:Number.isFinite(receivedTarget)&&Number.isFinite(s.receivedRate)?s.receivedRate-receivedTarget:null,
      previousReturn:prev.returnRate,previousReceived:prev.receivedRate,previousContact:prev.contactRate});

  }
  if(k===3||k===4){const stock=k===3?r:upPlatformStockFacts(r,platform),recent=upSummary(p,shiftDate(w.end,-14),w.end,platform);const ratio=stock.goodsValueCents?stock.staleValueCents/stock.goodsValueCents*100:null;
    Object.assign(raw,{total:stock.totalUnits,value:stock.goodsValueCents,turn:r.turn,coverage:stock.coverage,coverage15:stock.slowCoverage,staleRatio:ratio,staleValue:stock.staleValueCents,
      staleUnits:stock.staleUnits,warehouse:stock.warehouse,factory:stock.factory,undelivered:stock.undelivered,price:stock.financePriceCents/100,sales15:recent.sales,age:null});

    put('total',k===3?'高危品总库存':'总库存',rpCount(stock.totalUnits),'','仓内＋工厂＋新机未交付，三类库存互不重复。');put('value','高危品货值',upMoney(stock.goodsValueCents),'','总库存×含税含品牌财务价。');
    put('turn','库存周转率',r.turn===null?'—':fmt(r.turn,2)+(k===3?'次/30日':'次/期间'),'','期间出库成本÷期间平均库存成本。');put('coverage','可售天数',stock.coverage===null?'无动销':fmt(stock.coverage,1)+'天','','公司仓内库存÷所选平台在当前周期的日均销量；未分配平台专属库存。');
    put('coverage15','可售天数（近15天）',stock.slowCoverage===null?'无动销':fmt(stock.slowCoverage,1)+'天',stock.slow?'red':'','公司仓内库存÷所选平台近15日日均销量；只判断有动销产品，可售天数'+brcDescribe('stock.slowDays')+'时纳入滞销，不作为平台专属库存。');
    put('staleRatio','呆滞占比',upPercent(ratio),'','超库龄货值÷总库存货值。');put('staleValue','滞销金额',upMoney(stock.staleValueCents),'red','只计算超库龄部分。');put('staleUnits','超库龄库存数',rpCount(stock.staleUnits),'','按原超库龄货值比例折算的样例数量，实际数量需批次库龄台账。');
    put('warehouse','仓内库存',rpCount(stock.warehouse));put('factory','工厂库存',rpCount(stock.factory));put('undelivered','新机未交付',rpCount(stock.undelivered));put('price','财务价',pfMoneyYuan(stock.financePriceCents/100)+'/件');put('sales15','近15天销量',rpCount(recent.sales));put('attribute','产品属性',r.attribute);put('age','最大库龄','待接入','','未提供真实批次及库龄，不用低动销天数代替库龄。');put('causes','命中风险',k===3?r.reasons.map(irReasonText).join('、'):'动销产品可售天数'+brcDescribe('stock.slowDays')+'','');
  }
  const fields=rows.map(f=>({...f,sortValue:raw[f.key],...(k===6&&['returnGrowth','receivedGrowth','contactGrowth'].includes(f.key)?{tone:rpComparisonTone(raw[f.key]),hint:f.hint+rpComparisonRuleText()}:{})}));
  return k===0?rpQualityFields(r,fields,s,prev,qualityOnly,violationPlatform):fields;
}
function rpFields(k,r,keys,violationPlatform='all'){const fields=rpFieldMap(k,r,true,violationPlatform);return keys.map(key=>fields.find(f=>f.key===key)).filter(Boolean)}
function rpCauses(k,r){return k===3?r.reasons.map(irReasonText):k===4?[brcResultText('stock-stagnant-warning')]:k===2?[(r.metricPlatform&&r.metricPlatform!=='all'?r.metricPlatform:'全公司')+'测算净利为负']:r.risks||[]}
function rpRules(k){return k===0?qrbRules():k===1?sbRules():k===3?rpShortageRule():k===4?rpStagnantRule():k===2?'按SPU汇总所选平台同期业绩，全平台为公司汇总；利润率减'+brcNumber('finance.deduction')+'%后测算净利为负入榜，按测算净亏损绝对金额排序；原型基数为GSV，正式分母待映射。':'退货恶化按控件显示的稳定周／月区间比较：'+brcResultText('quality-worsening')+'入榜。增长值＝本期比率－上期比率，缺失比率不判定。'}
// 品质榜试版：卡片指标与抽屉字段共用原值、环比及处罚台账。
const rpQualityCardKeys=['fine','frozen','offShelf','gsv'];
const rpQualityListKeys=['gsv','sales','netSales','margin','return','received','violations','fine','frozen','offShelf','drop','season','productType'];
// 字段是否适用由所属平台决定；全平台仅保留列，不把不适用字段当作0。
function rpViolationMetricAllowed(key,platform='all'){
 const platforms=(Array.isArray(platform)?platform:[platform]).filter(Boolean);
 if(!platforms.length||platforms.includes('all'))return true;
 const type=({罚款:'fine',资金冻结:'frozen',掉权:'drop',下架:'offShelf'})[key]||(/^fine/.test(key)?'fine':/^frozen/.test(key)?'frozen':key);
 const excluded={fine:['抖音','视频号'],frozen:['快手','天猫','京东'],drop:['抖音','快手','视频号','天猫','京东']};
 return !excluded[type]||platforms.some(p=>!excluded[type].includes(p));
}
function rpPlatformViolationEvents(events,scope='all',platform=null){
 return events.filter(e=>rpViolationMetricAllowed(e.type,e.platform||platform||scope));
}
function rpViolationField(field,platform){
 return rpViolationMetricAllowed(field.key,platform)?field:{...field,value:'--',sortValue:null,tone:'rp-quality-gray',target:'',targetTone:'',hint:''};
}
function rpQualityMoney(yuan){return pfMoneyYuan(yuan).replace(/元$/,'')}
// 原因未分类的事件仅进入全部口径，不能默认归为品质原因。
function rpQualitySelectEvents(monthly,qualityOnly=true){
 return (monthly.allEvents||monthly.events||[]).filter(e=>['罚款','资金冻结','下架','掉权'].includes(e.type)&&(!qualityOnly||e.reasonType==='quality'));
}
function rpQualityEvents(record,start,end,qualityOnly=true){
 const product=upProduct(upIdentity(record)),observation=record.platform==='all'||Array.isArray(record.platform)?qfViolationObservation(product,record.platform,start,end):qrObservation(product,record.platform,start,end);
 return rpQualitySelectEvents(observation.monthly,qualityOnly);
}
// 常规经营环比色；进线率与差评率另按风险方向判断。
function rpQualityChangeValue(current,previous){
 if(!Number.isFinite(current)||!Number.isFinite(previous))return null;
 return current===previous?0:previous>0?(current-previous)/previous*100:null;
}
// 率和数量的正负号展示，与金额/销量使用的箭头格式分开。
function rpSignedComparisonText(raw,unit='%',digits=1){
 if(!Number.isFinite(raw))return '环比 —';
 const value=Math.round(Math.abs(raw)*10**digits)/10**digits;
 return value===0?'环比 持平':'环比 '+(raw>0?'+':'-')+fmt(value,digits)+unit;
}
function rpCountComparison(current,previous,unit='次'){
 const delta=Number.isSafeInteger(current)&&current>=0&&Number.isSafeInteger(previous)&&previous>=0?current-previous:null;
 return {target:rpSignedComparisonText(delta,unit,0),targetTone:'rp-quality-'+(delta===null||delta===0?'gray':delta>0?'red':'green')};
}
function rpCountComparisonRuleText(){return '环比＝本期次数－上期次数；涨红降绿，持平和缺失灰色。'}
function rpQualityChange(current,previous){return rpComparisonText(rpQualityChangeValue(current,previous))}
function rpComparisonText(raw){
 if(!Number.isFinite(raw))return '环比 --';
 const change=Math.sign(raw)*Math.round(Math.abs(raw)*10)/10;
 if(change===0)return '环比 持平';
 return '环比 '+(change>0?'↑ ':change<0?'↓ ':'')+upPercent(Math.abs(change));
}
// 共用相对环比色：涨跌幅度均先判灰色区间，区间外涨绿降红。
function rpComparisonTone(change,reverse=false){
 if(!Number.isFinite(change)||Math.round(Math.abs(change)*10)===0)return 'rp-quality-gray';
 const tone=brcBandTone('decline',Math.abs(change));
 return 'rp-quality-'+(tone==='red'&&(reverse?change<0:change>0)?'green':tone);
}
function rpComparisonRuleText(reverse=false){return (reverse?'涨红降绿':'涨绿降红')+'；涨跌幅度满足'+brcDescribe('lights.decline')+'时灰色；持平和无可比数据灰色。'}
function rpQualityChangeTone(current,previous,reverse=false){return rpComparisonTone(rpQualityChangeValue(current,previous),reverse)}
// 利润率与净利润率均用百分点差，不除以上期，不设置灰色区间。
function rpProfitRateComparison(current,previous){
 const delta=Number.isFinite(current)&&Number.isFinite(previous)?current-previous:null;
 const shown=Number.isFinite(delta)?Math.sign(delta)*Math.round(Math.abs(delta)*10)/10:null;
 const tone='rp-quality-'+(shown===null||shown===0?'gray':shown>0?'green':'red');
 return {target:rpSignedComparisonText(delta),targetTone:tone};
}
function rpProfitRateComparisonRuleText(){return '环比＝本期利润率 - 上期利润率，以%展示；涨绿降红，不设10%灰色区间；持平和缺失灰色。'}
// 进线率与差评率显示差值（%）；不除以上期，符号统一为正负号。
function rpRateDeltaComparison(current,previous){
 const delta=qrbRateDelta(current,previous),shown=Number.isFinite(delta)?Math.sign(delta)*Math.round(Math.abs(delta)*10)/10:null;
 // 与一位小数文案使用同一变化值，避免显示“持平”却仍有涨跌颜色。
 return {target:rpSignedComparisonText(delta),targetTone:'rp-quality-'+(shown===null||shown===0?'gray':shown>0?'red':'green')};
}
// 普通总退/已收退按实际减目标的差值判灯，两个上界均归黄灯。
const rpReturnDeviationLimits={return:2,received:0.5};
function rpReturnDeviationHint(kind='return'){
 return '偏差＝实际退货率－目标退货率，单位为%。'+(kind==='received'?brcBandText('return.received')+'。':'');
}
function rpQualityReturnRule(actual,target,kind='return'){
 if(!Number.isFinite(actual))return {tone:'rp-quality-gray',targetTone:'rp-quality-gray',target:''};
 if(!Number.isFinite(target)||target<0)return {tone:'rp-quality-normal',targetTone:'rp-quality-gray',target:''};
 const gap=actual-target,epsilon=1e-10,tone=brcBandTone('return.'+(kind==='received'?'received':'return'),gap);
 return {tone:'rp-quality-'+(tone==='green'?'normal':tone),targetTone:'rp-quality-'+tone,target:'偏差 '+(gap>epsilon?'+':'')+upPercent(Math.abs(gap)<=epsilon?0:gap)};
}
function rpQualityAmountTone(value){return 'rp-quality-'+(Number.isFinite(value)&&value>0?'red':'gray')}
function rpQualityProductFields(record){
 const identity=pfIdentity(record),tags=[];
 if(identity.isNew===true)tags.push({kind:'new',label:'新品'});
 else if(identity.isNew===false)tags.push({kind:'old',label:'老品'});
 if(identity.clearance===true)tags.push({kind:'clearance',label:'清仓品'});
 return [rpField('season','季品',identity.attribute||'—'),{...rpField('productType','属性',tags.map(t=>t.label).join('、')||'—'),tags}];
}
function rpQualityFields(record,fields,current,previous,qualityOnly=true,violationPlatform='all'){
 fields.push(...rpQualityProductFields(record));
 const events=rpPlatformViolationEvents(rpQualitySelectEvents(record.monthly,qualityOnly),violationPlatform,record.platform),earlier=rpPlatformViolationEvents(rpQualityEvents(record,previous.start,previous.end,qualityOnly),violationPlatform,record.platform);
 const fine=events.filter(e=>e.type==='罚款'),frozen=events.filter(e=>e.type==='资金冻结');
 const fineAmount=fine.reduce((sum,e)=>sum+(Number(e.amount)||0),0),frozenAmount=frozen.reduce((sum,e)=>sum+(Number(e.amount)||0),0),scope=qualityOnly?'品质原因':'全部原因';
 const patch=(key,props)=>{const field=fields.find(f=>f.key===key);if(field)Object.assign(field,props)};
 const compareHint='上期为紧邻的等长区间；环比＝（本期－上期）÷上期；'+rpComparisonRuleText();
 for(const [key,now,before] of [['sales',current.sales,previous.sales],['gsv',current.gsvCents,previous.gsvCents],['margin',current.profitRate,previous.profitRate]]){
  const old=fields.find(f=>f.key===key);
  const comparison=key==='margin'?rpProfitRateComparison(now,before):{target:rpQualityChange(now,before),targetTone:rpQualityChangeTone(now,before)};
  patch(key,{tone:Number.isFinite(now)?'':'rp-quality-gray',...comparison,hint:(old?.hint||'')+(key==='margin'?rpProfitRateComparisonRuleText():compareHint)});
 }
 const bad=fields.find(f=>f.key==='bad');
 if(bad)patch('bad',{tone:Number.isFinite(current.badRate)?'':'rp-quality-gray',...rpRateDeltaComparison(current.badRate,previous.badRate),hint:'差评率＝差评数量÷有效评价数量×100%；环比值＝本期差评率－上期差评率，单位为%；上期为0%仍可计算，缺少有效评价时显示--。'});
 for(const [key,name,metric] of [['contact','进线率','contactRate'],['qualityContact','品质问题进线率','qualityContactRate'],['experienceContact','体验问题进线率','experienceContactRate']]){
  const actual=current[metric],prior=previous[metric];
  const props={value:Number.isFinite(actual)?upPercent(actual):'--',sortValue:actual,tone:Number.isFinite(actual)?'':'rp-quality-gray',...rpRateDeltaComparison(actual,prior),hint:(key==='contact'?'总进线工单数（品质问题＋体验问题）':'对应问题类型工单数')+'÷同期销量×100%；环比增长值＝本期进线率－上期进线率，单位为%。进线预警按环比增长值'+brcDescribe('quality.contactDelta')+'判定。上期为0%且有销量仍可计算；无有效销量时不作判定。'};
  if(fields.some(f=>f.key===key))patch(key,props);else fields.push({...rpField(key,name,props.value),...props});
 }
 patch('sales',{value:fmt(current.sales),hint:'所选期间、所选平台的销量，未扣除退货；'+compareHint});
 patch('gsv',{value:rpQualityMoney(current.gsvCents/100)});
 for(const [key,name,actual,targetKey] of [['return','总退',current.returnRate,'returnTarget'],['received','已收退',current.receivedRate,'receivedTarget']]){
  const target=fields.find(f=>f.key===targetKey)?.sortValue;
  const rule=rpQualityReturnRule(actual,target,key),old=fields.find(f=>f.key===key);
  patch(key,{name,...rule,hint:(old?.hint||'')+(Number.isFinite(target)?rpReturnDeviationHint(key):'')});
 }
 patch('fine',{value:rpQualityMoney(fineAmount),sortValue:fineAmount,target:fine.length+'次',tone:rpQualityAmountTone(fineAmount),targetTone:'rp-quality-gray',hint:scope+'的平台罚款金额及次数。'});
 patch('frozen',{value:rpQualityMoney(frozenAmount),sortValue:frozenAmount,target:frozen.length+'次',tone:rpQualityAmountTone(frozenAmount),targetTone:'rp-quality-gray',hint:scope+'的资金冻结事件金额及次数，不作为实时冻结余额。'});
 const net=current.sales-current.returned,oldNet=previous.sales-previous.returned;
 fields.push({...rpField('netSales','销量',fmt(net),'','同期销量－同期总退件数；'+compareHint,rpQualityChange(net,oldNet)),sortValue:net,targetTone:rpQualityChangeTone(net,oldNet)});
 const violationComparison=rpCountComparison(events.length,earlier.length);
 fields.push({...rpField('violations','违规次数',String(events.length),'',scope+'的罚款、资金冻结、下架、掉权事件合计；上期取紧邻等长区间；'+rpCountComparisonRuleText(),violationComparison.target),sortValue:events.length,targetTone:violationComparison.targetTone});
 // 下架与掉权分别展示；每项环比都使用各自事件基数，保留合计字段供旧入口读取。
 for(const [key,name,types] of [['down','链接下架/掉权',['下架','掉权']],['offShelf','链接下架',['下架']],['drop','链接掉权',['掉权']]]){
  const count=events.filter(e=>types.includes(e.type)).length,before=earlier.filter(e=>types.includes(e.type)).length;
  const comparison=rpCountComparison(count,before);
  const field={...rpField(key,name,count+'次','','所选期间'+scope+types.join('、')+'事件次数；上期取紧邻等长区间；'+rpCountComparisonRuleText(),comparison.target),sortValue:count,targetTone:comparison.targetTone};
  if(fields.some(f=>f.key===key))patch(key,field);else fields.push(field);
 }
 const amount=fineAmount+frozenAmount;
 fields.push({...rpField('sanctions','罚款＆冻结',rpQualityMoney(amount),rpQualityAmountTone(amount),'平台罚款金额与期间冻结事件金额相加；第二行为罚款与冻结事件总次数，不作为实时冻结余额。',(fine.length+frozen.length)+'次'),sortValue:amount,targetTone:'rp-quality-gray'});
 return fields.map(field=>rpViolationField(field,record.platform));
}
function rpQualityRatesHelp(){return '<span class="metric-help rp-quality-rate-help" role="button" tabindex="0" aria-label="查看进线率与差评率计算口径" data-quality-rates="true" data-metric-rule="进线率与差评率计算口径"></span>'}
function rpQualityCardColumns(){
 const names=['平台罚款','资金冻结','链接下架','链接掉权','GSV'];
 return '<div class="rp-quality-columns">'+names.map(name=>'<span>'+name+'</span>').join('')+'</div>';
}
