  const x=typeof key==='function'?key(a):a[key],y=typeof key==='function'?key(b):b[key],knownX=Number.isFinite(x),knownY=Number.isFinite(y);
  if(knownX!==knownY)return knownX?-1:1;if(knownX&&x!==y)return (x-y)*direction;
