// 导入记录统一复用全局记录弹窗。
function ltOpenTargetHistory(){return uiImportHistory('生命周期目标')}
function ltDownloadImportErrors(entry){downloadCsv(['原始行号','字段','错误原因'],entry.errors.map(error=>[error.row,error.field,error.message]),'生命周期目标-'+entry.year+'-导入错误')}
$('#lt-target-page').addEventListener('click',event=>{
 const button=event.target.closest('button');if(!button)return;
 if(button.hasAttribute('data-lt-download'))ltDownloadTargets();
 if(button.hasAttribute('data-lt-import'))ltOpenTargetImport();
 if(button.dataset.ltHistory==='import')ltOpenTargetHistory();
});
ltImportDialog.addEventListener('cancel',event=>{event.preventDefault();ltCloseTargetImport()});
ltImportDialog.addEventListener('click',event=>{
 if(event.target.closest('[data-lt-import-close]'))ltCloseTargetImport();
 if(event.target.closest('[data-lt-template]'))ltDownloadTargets(Number(ltImportDialog.dataset.year));
});
function shcFilterSelect(key,label,values){
 return `<label class="shc-filter"><span>${label}</span><select data-shc-filter="${key}" aria-label="配置筛选${label}"><option value="all">全部</option>${values.map(value=>{const [id,text]=Array.isArray(value)?value:[value,value];return `<option value="${esc(id)}" ${shcState[key]===id?'selected':''}>${esc(text)}</option>`}).join('')}</select></label>`;
}
function shcRenderPlatforms(){
 const rows=shcRows();$('#shc-platforms').innerHTML=['all',...shcPlatforms].map(platform=>`<button type="button" data-shc-platform="${platform}" aria-pressed="${shcState.platform===platform}" class="${shcState.platform===platform?'active':''}">${platform==='all'?'全平台':rpPlatformMark(platform)+'<span>'+platform+'</span>'}<small>${rows.filter(shop=>platform==='all'||shop.channel===platform).length}</small></button>`).join('');
}
function shcRenderTable(){
 const rows=shcFiltered();shcState.page=Math.max(1,Math.min(shcState.page,Math.ceil(rows.length/listPageSize('shc-pages',20))||1));
 const visible=rows.slice((shcState.page-1)*listPageSize('shc-pages',20),shcState.page*listPageSize('shc-pages',20));
 $('#shc-results').innerHTML=`<table class="shc-table"><colgroup><col style="width:140px"><col><col style="width:140px"><col style="width:200px"><col style="width:160px"></colgroup><thead><tr><th>平台</th><th>店铺信息</th><th>品牌</th><th>店铺分类</th><th>是否考核店铺</th></tr></thead><tbody>${visible.length?visible.map(shop=>`<tr data-shc-row="${esc(shcKey(shop))}"><td><span class="shc-platform">${rpPlatformMark(shop.channel)}<span>${shop.channel}</span></span></td><td><b>${esc(shop.name)}</b><small>ID：${esc(shop.shopId)}</small></td><td>${esc(shop.brand)}</td><td><select data-shc-category="${esc(shcKey(shop))}" aria-label="店铺分类：${esc(shop.name)}">${(shop.shopCategory===shcRules.pending?'<option value="" selected disabled>无分类</option>':'')+shcRules.allowed(shop.channel).map(value=>`<option ${shop.shopCategory===value?'selected':''}>${value}</option>`).join('')}</select></td><td><button type="button" class="shc-switch" role="switch" aria-checked="${shop.assessed}" aria-label="是否考核：${esc(shop.name)}" data-shc-assessed="${esc(shcKey(shop))}"><i aria-hidden="true"></i></button><span class="shc-switch-text">${shop.assessed?'是':'否'}</span></td></tr>`).join(''):'<tr><td colspan="5" class="shc-empty">暂无符合条件的店铺</td></tr>'}</tbody></table>`;
 mountListPager($('#shc-pages'),rows.length,shcState.page,page=>{shcState.page=page;shcRenderTable()});$('#shc-error').textContent=shcState.error;
}
function shcRenderPage(){
 $('#shc-return').hidden=!shcState.returnList;shcRenderPlatforms();
 $('#shc-filters').innerHTML=`<input type="search" data-shc-search aria-label="搜索店铺名称/店铺ID" placeholder="搜索店铺名称/店铺ID" value="${esc(shcState.query)}">${shcFilterSelect('brand','品牌',[...new Set(shcRows().map(shop=>shop.brand))])}${shcFilterSelect('category','店铺分类',shcRules.options(shcState.platform))}${shcFilterSelect('assessed','是否考核',[['yes','是'],['no','否']])}<button type="button" class="link" data-shc-reset>重置</button>`;
 shcRenderTable();
}
const shcRouteHash='#system-shop-config';
function shcOpenFromRanking(){
 const names={抖音:'douyin',快手:'kuaishou',视频号:'wechat',天猫:'tmall',京东:'jd',拼多多:'pdd'},platform=names[rfState.listPlatforms[1]]||'douyin';
 const url=new URL('数智罗盘/店铺配置.html',document.baseURI);url.searchParams.set('platform',platform);
 window.open(url.href,'_blank','noopener');
}

function shcUpdate(key,patch,kind){
 const result=shcSetShop(key,patch);shcState.error=result.ok?'':result.error;
 if(result.ok){shcExternalChannel.postMessage({type:'metadata',store:shcStore});renderRisks()}shcRenderTable();
 const control=[...$('#shc-results').querySelectorAll(kind==='category'?'[data-shc-category]':'[data-shc-assessed]')].find(el=>(el.dataset.shcCategory||el.dataset.shcAssessed)===key);control?.focus({preventScroll:true});
}
document.addEventListener('input',e=>{
 if(!e.target.matches('#shc-filters [data-shc-search]'))return;
 shcState.query=e.target.value;shcState.page=1;shcRenderTable();
});
document.addEventListener('change',e=>{
 const target=e.target;
 if(target.matches('#shc-filters [data-shc-filter]')){shcState[target.dataset.shcFilter]=target.value;shcState.page=1;shcRenderTable()}
 else if(target.matches('#shc-results [data-shc-category]'))shcUpdate(target.dataset.shcCategory,{shopCategory:target.value},'category');
});
document.addEventListener('click',e=>{
 const button=e.target.closest('#shc-content button');if(!button)return;
 if(button.hasAttribute('data-shc-platform')){shcState.platform=button.dataset.shcPlatform;if(!shcRules.options(shcState.platform).includes(shcState.category))shcState.category='all';shcState.page=1;shcRenderPage()}
 else if(button.hasAttribute('data-shc-reset')){Object.assign(shcState,shcDefaults(),{page:1,error:''});shcRenderPage()}
 else if(button.hasAttribute('data-shc-assessed'))shcUpdate(button.dataset.shcAssessed,{assessed:button.getAttribute('aria-checked')!=='true'},'assessed');
 else if(button.id==='shc-return'&&shcState.returnList){const context=shcState.returnList;shcState.returnList=null;smNavigate('#risk');rpOpenList(1,false,null,context)}
});
window.shopConfigAudit=()=>({pageOpen:smActiveRoute===shcRouteHash,state:{platform:shcState.platform,query:shcState.query,brand:shcState.brand,category:shcState.category,assessed:shcState.assessed,page:shcState.page},rows:shcRows().map(({id,shopId,channel,name,brand,shopCategory,assessed})=>({id,shopId,channel,name,brand,shopCategory,assessed})),filtered:shcFiltered().map(shop=>shcKey(shop)),saved:JSON.parse(JSON.stringify(shcStore))});

function shcRefreshExternal(){
 try{const saved=JSON.parse(localStorage.getItem(shcStorageKey)||'null');const next=shcRules.store(saved);if(JSON.stringify(next)===JSON.stringify(shcStore))return;shcStore=next;shcRevision++;renderRisks();
  if(smActiveRoute===shcRouteHash)shcRenderPage();
  shcRefreshDetail();
  if(!$('#overlay').hidden&&$('#rf-list-table.rp-shop-table'))rpOpenList(1,false);
 }catch(_){/* 配置页会报告写入失败，读取失败不覆盖当前数据。 */}
}
window.addEventListener('storage',e=>{if(e.key===shcStorageKey)shcRefreshExternal()});window.addEventListener('focus',shcRefreshExternal);
const shcExternalChannel=new BroadcastChannel('compass-shop-metadata');
shcExternalChannel.onmessage=event=>{if(event.data?.type==='metadata'){try{localStorage.setItem(shcStorageKey,JSON.stringify(event.data.store));shcRefreshExternal()}catch(_){}}};

// 下层榜单节点由抽屉栈保留；返回时按元数据版本补绘，不重置筛选或日期。
function shcRefreshDetail(){
 const detail=$('.sd-detail');if(!detail)return;
 const shop=shcRows().find(s=>String(s.shopId)===detail.dataset.sdShop&&s.channel===detail.dataset.sdPlatform),field=detail.querySelector('[data-sd-category]');
 if(shop&&field)field.textContent=shop.shopCategory;
}
$('#dialogbody').addEventListener('drawer:restored',()=>{
 const host=$('#rf-list-table.rp-shop-table');if(host?.upRefresh&&Number(host.dataset.shcRevision)!==shcRevision)host.upRefresh();
 shcRefreshDetail();
});
// 关键产品经营取所选期间；SABC从月销门槛换算，库存固定最新公司快照。
const kpmGrades={S:'头部利润支柱',A:'高销低利',B:'潜力利润品',C:'尾部无竞争力'};
const kpmFilters={query:'',brand:'all',category:'all',season:'all',price:'all',min:'',max:''};
// sales沿用表头字段键，实际排序值为GSV原始金额。
const kpmDefaultSort=Object.freeze({key:'sales',direction:'desc'});
const kpmSort={...kpmDefaultSort};
const kpmPage={value:1,key:''};
function kpmPageSize(){return listPageSize('matrix-product-pager',10)}
function kpmRows(){
 const platform=kpmBusinessPlatforms(),range=upWindow(),previousEnd=shiftDate(range.start,-1),previousStart=shiftDate(range.start,-aiFlowDayDiff(range.start,range.end)-1);
 const stockBySpu=upWithRange({start:shiftDate(DATA_CUTOFF,-29),end:DATA_CUTOFF},()=>new Map(inventoryProductLedger().map(r=>[r.spuId,upStockFacts(r)])));
 return productRows(false).map(p=>{
  const identity=upIdentity(p),observed=upSummary(identity,range.start,range.end,platform),stock=stockBySpu.get(p.spuId)||null;
  const {gmvCents,refundCents,gsvCents,profitRate,profitCents,sales:units,returned,received,returnRate,receivedRate}=observed;
  const facts={gmvCents,refundCents,gsvCents,profitRate,profitCents,sales:units,returned,received,netSales:units-returned,returnRate,receivedRate};
  const sales=facts.gsvCents/1000000,profit=facts.profitRate,base={...p,sales,profit,guidePriceCents:upProduct(identity).guidePriceCents};
  const assessment=kpmGradeComparison(identity,range.end,platform,periodFor('matrix').mode,range.start),level=assessment.current.level;
  const priceStart=shiftDate(range.end,-29),priceFacts=range.start===priceStart?observed:upSummary(identity,priceStart,range.end,platform),priceCents=priceFacts.sales>0?Math.round(priceFacts.gmvCents/priceFacts.sales):null;
  const earlier=upSummary(identity,previousStart,previousEnd,platform),previous={gsvCents:earlier.gsvCents,sales:earlier.sales,returned:earlier.returned,received:earlier.received,returnRate:earlier.returnRate,receivedRate:earlier.receivedRate,netSales:earlier.sales-earlier.returned,profitRate:earlier.profitRate},targets=upReturnTargets({product:identity},{platform,start:range.start,end:range.end});
  return {...base,returnRate:returnRate??0,receivedRate,units,facts,stock,level,assessment,priceCents,category:pfCategory(p),season:pfIdentity(p).attribute,brand:pfIdentity(p).brand,previous,...targets,
   state:nspSalesState(p.state,stock),stockRisks:upStockRiskTags(stock)};
 });
}
function kpmFilterRows(rows,grade=true,change=true,filters=kpmFilters){
 const query=filters.query.trim().toLocaleLowerCase();
 return rows.filter(p=>(!query||[p.name,p.spuCode,p.model].some(v=>String(v||'').toLocaleLowerCase().includes(query)))
  &&kpmPriceMatch(p,filters)&&pfIncludes(filters.brand,p.brand)&&pfIncludes(filters.category,p.category)&&pfIncludes(filters.season,p.season)
  &&(!grade||kpmSelectedGrade==='all'||(p.level||'unrated')===kpmSelectedGrade)&&(!grade||!kpmSelectedOperating||p.level===kpmSelectedOperating&&brcProductOperatingMatch(p.level,p.assessment.current.profitRate))
  &&(!change||kpmMatchesSignal(p,kpmSelectedChange)));

}
let kpmSelectedGrade='all',kpmSelectedOperating=null;
function kpmValue(p,key){return ({sales:p.facts.gsvCents,profit:p.facts.profitRate,units:p.facts.netSales,
 returns:p.facts.returnRate,received:p.facts.receivedRate,unreceived:upUnreceivedRate(p.facts),total:p.stock?.totalUnits,
 warehouse:p.stock?.warehouse,coverage:p.stock?.coverage15,days:p.days,guidePrice:p.guidePriceCents})[key]}
function kpmSortedRows(rows){return rpSortRows(kpmFilterRows(rows),kpmSort,kpmValue)}
window.dashboardKeyProductsSnapshot=()=>withPeriod('matrix',()=>{
 const rows=kpmRows();return {scope:kpmBusinessScope,platforms:kpmBusinessPlatforms(),period:{...periodFor('matrix')},range:upWindow(),gradeRules:brcGradeRules(periodFor('matrix').mode),change:kpmSelectedChange,filters:{...kpmFilters},grade:kpmSelectedGrade,operating:kpmSelectedOperating,
  structure:kpmManagementStructure(kpmFilterRows(rows,false,false)),sort:{...kpmSort},page:kpmPage.value,size:kpmPageSize(),rows,base:kpmFilterRows(rows,false,false),visible:kpmSortedRows(rows)};
});
// 月度基准按矩阵既有周期口径换算；同一周期不随筛选结果重新分位。
const kpmBubbleBands=Object.freeze([
 {max:50e6,radius:5},
 {max:300e6,radius:7},
 {max:1000e6,radius:9},
 {max:Infinity,radius:11}
].map(Object.freeze));
function kpmBubbleTier(gsvCents,mode=periodFor('matrix').mode){const factor=brcGradeFactor(mode);return kpmBubbleBands.findIndex(band=>gsvCents<band.max*factor)}
function kpmBubbleRadius(tier,zoom=false){return kpmBubbleBands[tier].radius*(zoom?1.2:1)}
const kpmChartPoints=new Map();
let kpmChartContext={};
const kpmChartColors={S:'#009a29',A:'var(--orange)',B:'#7c8eec',C:'#e98191',unrated:'#98a5b6'};
function kpmChartLegend(){
 return Object.entries(kpmGrades).map(([g,name])=>'<span class="'+g+'"><i></i><i style="opacity:.28"></i>'+g+'级'+'</span>').join('');
}
// 图点和分区使用同周期、同规则；缺失等级数据的可定位产品保留灰点。
function kpmChartRow(p){
 const facts=p.assessment.current;
 return {...p,facts,sales:facts.gsvCents/1000000,profit:facts.profitRate};
}
// 重点区域及圆点深浅共用经营标签条件，等级色系保持一致。
function kpmChartOperatingRegions(mode){
 return kpmGradeOrder.flatMap(grade=>brcGradeSalesRanges(grade,null,mode).flatMap(sales=>
  brcRanges(brcConditions()[brcGradeKeys(grade).profit]).map(profit=>({grade,sales,profit}))));
}
function kpmChart(rows,scaleRows){
 const valid=p=>p.assessment.current.sales>0&&Number.isFinite(p.assessment.current.gsvCents)&&Number.isFinite(p.assessment.current.profitRate);
 const points=rows.filter(valid).map(kpmChartRow),scale=scaleRows.filter(valid).map(kpmChartRow);
 kpmChartPoints.clear();for(const p of points)kpmChartPoints.set(p.spuId,p);
 const range=upWindow();kpmChartContext={...range,label:periodShortText(periodFor('matrix'))};
 const gradeRules=brcGradeRules(periodFor('matrix').mode),rules=Object.values(gradeRules);
 const salesTicks=[...new Set(rules.flatMap(r=>r.salesRanges.flatMap(range=>[range.lo,range.hi])).filter(Number.isFinite))];
 const profitTicks=[...new Set([0,...kpmGradeOrder.flatMap(level=>brcRanges(brcConditions()[brcGradeKeys(level).profit]).flatMap(range=>[range.lo,range.hi])).filter(Number.isFinite)])];
 const left=62,right=738,top=42,bottom=438;
 const minX=Math.floor(Math.min(0,...scale.map(p=>p.sales*1.08))),maxX=Math.ceil(Math.max(Math.max(1,...salesTicks)*1.4,...scale.map(p=>p.sales*1.08)));
 // 正负利润率共用对称量程，0%固定居中；分区仍按真实业务阈值投影。
 const maxY=Math.ceil(Math.max(26,...profitTicks.map(v=>Math.abs(v)*1.5),...scale.map(p=>Math.abs(p.profit)*1.12))/5)*5,minY=-maxY;
 const x=v=>left+(v-minX)/(maxX-minX)*(right-left),y=v=>bottom-(v-minY)/(maxY-minY)*(bottom-top);
 const fills={S:'#f0f8f3',A:'#fffbf0',B:'#f1f4ff',C:'#fff3f5'};
 const operatingFills={S:'#cce8d6',A:'#fff0bd',B:'#dbe3ff',C:'#f8dce4'};
 // 以灰底表达未命中区，再覆盖有效等级区域，不把空档补进任一等级。
 const zones=kpmGradeOrder.flatMap(g=>gradeRules[g].regions.map(({sales,profit})=>{
  const a=x(Math.max(minX,sales.lo)),b=y(Math.min(maxY,profit.hi));
  return [g,a,b,x(Math.min(maxX,sales.hi))-a,y(Math.max(minY,profit.lo))-b];
 }).filter(([,a,b,w,h])=>w>0&&h>0));
 const operatingZones=kpmChartOperatingRegions(periodFor('matrix').mode).map(({grade,sales,profit})=>{
  const a=x(Math.max(minX,sales.lo)),b=y(Math.min(maxY,profit.hi));
  return [grade,a,b,x(Math.min(maxX,sales.hi))-a,y(Math.max(minY,profit.lo))-b];
 }).filter(([,a,b,w,h])=>w>0&&h>0);
 const xTicks=[...new Set([minX,0,...salesTicks,maxX])].sort((a,b)=>a-b),yTicks=[...new Set([minY,0,...profitTicks,maxY])].sort((a,b)=>a-b);
 return `<svg viewBox="0 0 760 490" role="group" aria-label="SABC产品经营矩阵" data-x-min="${minX}" data-x-max="${maxX}" data-y-min="${minY}" data-y-max="${maxY}">
  <text x="${left}" y="20" class="kpm-axis-title kpm-axis-profit">利润率（%）</text>
  <rect data-kpm-unmatched-area x="${left}" y="${top}" width="${right-left}" height="${bottom-top}" rx="6" fill="#f1f4f8" stroke="#e3e9f1"/>
  ${zones.map(([g,a,b,w,h])=>`<rect data-quadrant="${g}" aria-label="${g}级产品" x="${a}" y="${b}" width="${w}" height="${h}" fill="${fills[g]}" stroke="${kpmChartColors[g]}" stroke-opacity=".2"/>`).join('')}
  ${operatingZones.map(([g,a,b,w,h])=>`<rect data-kpm-operating-area="${g}" aria-label="${g}级 · ${kpmGrades[g]}" x="${a}" y="${b}" width="${w}" height="${h}" fill="${operatingFills[g]}"/>`).join('')}
  ${xTicks.filter(v=>v!==0&&v>minX&&v<maxX).map(v=>`<line data-kpm-grid x1="${x(v)}" x2="${x(v)}" y1="${top}" y2="${bottom}" stroke="#dce3ed" stroke-dasharray="3 4"/>`).join('')}
  ${yTicks.filter(v=>v!==0&&v>minY&&v<maxY).map(v=>`<line data-kpm-grid data-kpm-profit-reference="${v}" x1="${left}" x2="${right}" y1="${y(v)}" y2="${y(v)}" stroke="#8194af" stroke-width="1.5" stroke-dasharray="5 4" vector-effect="non-scaling-stroke"/>`).join('')}
  ${minX<0?`<line data-kpm-zero-axis="gsv" x1="${x(0)}" x2="${x(0)}" y1="${top}" y2="${bottom}"/>`:''}
  <line data-kpm-zero-axis="profit" x1="${left}" x2="${right}" y1="${y(0)}" y2="${y(0)}"/>
  ${zones.map(([g,a,b,w,h])=>h>=20?`<text data-kpm-zone-label="${g}" aria-label="${g}级" x="${w<32?a+w/2:a+8}" y="${b+22}" text-anchor="${w<32?'middle':'start'}" class="kpm-zone-label" style="fill:${kpmChartColors[g]}">${w<32?`<tspan>${g}</tspan><tspan x="${a+w/2}" dy="17">级</tspan>`:g+'级'}</text>`:'').join('')}
  ${xTicks.map(v=>`<text${v===0?' data-kpm-zero-tick="gsv"':''} x="${x(v)}" y="${bottom+22}" text-anchor="middle">${fmt(v)}</text>`).join('')}
  ${yTicks.map(v=>`<text${v===0?' data-kpm-zero-tick="profit"':''}${profitTicks.includes(v)&&v!==0?' data-kpm-profit-tick="'+v+'" style="fill:#526985;font-weight:600"':''} x="${left-10}" y="${y(v)+4}" text-anchor="end">${fmt(v,1)}%</text>`).join('')}
  ${[...points].sort((a,b)=>b.sales-a.sales).map(p=>{const tier=kpmBubbleTier(p.facts.gsvCents),operating=!!p.level&&brcProductOperatingMatch(p.level,p.profit),tone=!p.level?'unrated':operating?'matched':'unmatched';return `<circle data-kpm-point="${p.spuId}" data-kpm-bubble-tier="${tier}" data-kpm-point-tone="${tone}" data-kpm-grade-point="${p.level||'unrated'}" data-kpm-detail="${p.spuId}" tabindex="0" role="button" aria-label="查看${esc(p.name)}，${p.level?p.level+'级，'+(operating?'命中经营标签':'未命中经营标签'):'—'}，GSV ${fmt(p.sales,1)}w" cx="${x(p.sales)}" cy="${y(p.profit)}" r="${kpmBubbleRadius(tier)}" fill="${kpmChartColors[p.level||'unrated']}" fill-opacity="${tone==='unmatched'?'.28':'.95'}" stroke="${tone==='unmatched'?kpmChartColors[p.level]:'#fff'}" stroke-width="1.5"></circle>`}).join('')}
  <text x="${right}" y="482" text-anchor="end" class="kpm-axis-title kpm-axis-gsv">GSV（w）</text>
 </svg>${points.length?'':'<div class="kpm-chart-empty">当前筛选下暂无可绘制产品</div>'}`;
}
function kpmGradeBadge(p){return p.level?`<span class="kpm-grade ${p.level}"><b>${p.level}</b></span>`:'<span class="kpm-grade unrated">—</span>'}
function kpmFilterField(key,label,choices){return `<label>${label}<select multiple data-pf-multiple data-pf-label="${label}" data-kpm-filter="${key}" aria-label="关键产品${label}">${pfOptions(choices,kpmFilters[key])}</select></label>`}
function kpmTools(){return `<div class="kpm-tools" role="group" aria-label="关键产品搜索筛选">
 <label class="kpm-search"><input type="search" data-kpm-search aria-label="关键产品搜索" placeholder="搜索产品名称 / SPU码 / 型号" value="${esc(kpmFilters.query)}"></label>
 ${kpmFilterField('brand','品牌',[...new Set(sampleSpus.map(p=>p.brand))])}
 ${kpmPriceMarkup(kpmFilters,'main')}</div>`}
function kpmHeader(key,label){
 const active=kpmSort.key===key,action=!active?'降序':kpmSort.direction==='desc'?'升序':key===kpmDefaultSort.key?'降序':'恢复GSV降序';
 return `<button type="button" class="kpm-sort rp-sort-header" data-kpm-sort="${key}" data-direction="${active?kpmSort.direction:''}" aria-label="${label}：${action}" title="点击${action}">${label}<span class="rp-sort-arrows" aria-hidden="true"></span></button>${key==='guidePrice'?nspKpiHelp('指导价','此处为抖音渠道指导价'):netSalesHelp(key==='units'?'netSales':key)}`;
}
// 部门工作台仍使用独立的旧矩阵；克隆时移除总看板专用控件，防止筛选串用。
function kpmRestoreLegacy(section){
 if(!section.classList.contains('kpm-main'))return;
 kpmCloseChartZoom(false);
 section.querySelector('[data-kpm-scope-switch]')?.remove();
 section.querySelector('.kpm-scope-tabs')?.remove();
 section.classList.remove('kpm-main');section.querySelector('.matrixlayout').innerHTML='<div class="matrixplot"><div id="matrixchart"></div><div class="matrixlegend"><span>近30天销售额（万元）</span></div></div><div class="matrixlist"><div class="tabs" id="matrixtabs"></div><div class="tablewrap" id="matrixtable"></div><p class="note"></p></div>';
}
function kpmRender(){kpmCloseChartZoom(false);kpmHidePointTooltip();return withPeriod('matrix',()=>{
 const section=$('#matrix');section.classList.add('kpm-main');section.querySelector('.titlegroup>.tag').textContent='SABC产品分级';kpmRenderBusinessSwitch(section);
 if(!section.querySelector('.kpm-tools'))section.querySelector('.matrixlist').innerHTML=kpmTools()+'<div id="kpm-active-change" role="status" aria-live="polite"></div><div class="tablewrap" id="matrixtable"></div><div id="matrix-product-pager"></div>';
 const key=periodKey();if(kpmPage.key!==key){kpmPage.key=key;kpmPage.value=1}
 const rows=kpmRows(),base=kpmFilterRows(rows,false,false),visible=kpmSortedRows(rows),managementRows=kpmFilterRows(rows,true,false);
 // 等级与异动条件作用于明细；矩阵保留当前业务范围的完整分布。
 kpmRenderScopeTabs(section,rows);
 dashboardRenderMarkup(section.querySelector('.matrixplot'),`<div class="kpm-chart-head"><h3 id="kpm-structure-heading">产品经营矩阵</h3><div class="kpm-chart-legend">${kpmChartLegend()}</div><div class="kpm-chart-actions"><button type="button" class="kpm-expand" data-kpm-expand aria-expanded="false">⛶ 放大</button></div></div><div id="matrixchart">${kpmChart(base,base)}</div>`);
 kpmRenderSidebar(rows,managementRows);
 kpmRenderChangeCondition();
 kpmPage.value=Math.max(1,Math.min(kpmPage.value,Math.ceil(visible.length/kpmPageSize())||1));
 const tableHost=$('#matrixtable');tableHost.innerHTML=kpmTable(visible.slice((kpmPage.value-1)*kpmPageSize(),kpmPage.value*kpmPageSize()));kpmObserveTableViewport(tableHost);
 // 这三项只保留排序，使用公共无提示标记防止重绘后自动补回问号。
 for(const key of ['sales','units','profit'])tableHost.querySelector('[data-kpm-sort="'+key+'"]')?.closest('th').setAttribute('data-up-basic','true');
 for(const th of tableHost.querySelectorAll('th')){const active=[...th.querySelectorAll('[data-kpm-sort]')].some(b=>b.dataset.kpmSort===kpmSort.key);if(th.querySelector('[data-kpm-sort]'))th.setAttribute('aria-sort',!active?'none':kpmSort.direction==='asc'?'ascending':'descending')}
 const pager=$('#matrix-product-pager');pager.innerHTML=listPager(visible.length,kpmPage.value,kpmPageSize());bindListPager(pager,page=>{kpmPage.value=page;kpmRender()});
 const priceHost=section.querySelector('[data-kpm-price-host=main]');
 if(!priceHost.kpmPriceControl)priceHost.kpmPriceControl=kpmMountPriceFilter(priceHost,kpmFilters,()=>{kpmPage.value=1;kpmRender()});
 priceHost.kpmPriceControl.sync();
 pfMultiMount(section.querySelector('.kpm-tools'));decorateModule('matrix');
});}
function kpmOpenDetail(spuId,selectedRange=null,tab='operating'){kpmSuspendChartZoom();kpmHidePointTooltip();withPeriod('matrix',()=>{
 const range=selectedRange||upWindow(),period=selectedRange?drawerPeriodFromRange(range):{...periodFor('matrix')};
 upOpenDetail({spuId,...range,period,module:'matrix',platform:kpmBusinessPlatforms(),tab});
});}
document.addEventListener('input',e=>{
 if(!e.target.matches('#matrix.kpm-main [data-kpm-search]'))return;
 kpmFilters.query=e.target.value;kpmPage.value=1;kpmRender();
});
document.addEventListener('change',e=>{
 if(!e.target.matches('#matrix.kpm-main [data-kpm-filter]'))return;
 kpmFilters[e.target.dataset.kpmFilter]=pfControlValue(e.target);kpmPage.value=1;kpmRender();
});
document.addEventListener('click',e=>{
 const button=e.target.closest('#matrix.kpm-main [data-kpm-operating],#matrix.kpm-main [data-kpm-grade],#matrix.kpm-main [data-kpm-sort],#matrix.kpm-main [data-kpm-detail]');if(!button)return;
 if(button.dataset.kpmDetail)return kpmOpenDetail(button.dataset.kpmDetail,button.hasAttribute('data-kpm-point')?kpmChartContext:null);
 if(button.dataset.kpmOperating){const level=button.dataset.kpmOperating;kpmSelectedOperating=kpmSelectedOperating===level?null:level;kpmSelectedGrade=kpmSelectedOperating?level:'all';kpmSelectedChange='all';}
 else if(button.dataset.kpmGrade){const level=button.dataset.kpmGrade;kpmSelectedGrade=kpmSelectedGrade===level&&!kpmSelectedOperating?'all':level;kpmSelectedOperating=null;kpmSelectedChange='all';}
 else rpSortCycle(kpmSort,button.dataset.kpmSort,kpmDefaultSort);
 kpmPage.value=1;kpmRender();
 if(button.dataset.kpmGrade)$('#matrix.kpm-main [data-kpm-grade="'+button.dataset.kpmGrade+'"]')?.focus({preventScroll:true});
});
document.addEventListener('keydown',e=>{
 if(!e.target.matches('#matrix.kpm-main circle[data-kpm-detail]')||!['Enter',' '].includes(e.key))return;
 e.preventDefault();kpmOpenDetail(e.target.dataset.kpmDetail,kpmChartContext);
});
// 圆点浮层复用本次图表的产品事实，不另算指标或依赖浏览器原生title。
const kpmPointTooltip=document.createElement('div');
kpmPointTooltip.id='kpm-point-tooltip';kpmPointTooltip.className='metric-tooltip kpm-point-tooltip';
kpmPointTooltip.setAttribute('role','tooltip');kpmPointTooltip.hidden=true;document.body.append(kpmPointTooltip);
let kpmPointAnchor=null,kpmPointHideTimer=null;
function kpmKeepPointTooltip(){clearTimeout(kpmPointHideTimer);kpmPointHideTimer=null}
function kpmHidePointTooltip(){kpmKeepPointTooltip();kpmPointAnchor?.removeAttribute('aria-describedby');kpmPointAnchor=null;kpmPointTooltip.hidden=true;}
function kpmInsidePointTooltip(target){return target instanceof Node&&Boolean(kpmPointAnchor?.contains(target)||kpmPointTooltip.contains(target))}
// 给圆点与浮层之间留出移动时间；进入任一区域即取消关闭。
function kpmSchedulePointTooltipHide(){kpmKeepPointTooltip();kpmPointHideTimer=setTimeout(kpmHidePointTooltip,250)}
function kpmPlacePointTooltip(anchor,event){
 const rect=anchor.getBoundingClientRect(),box=kpmPointTooltip.getBoundingClientRect();
 const x=event?.clientX??rect.right,y=event?.clientY??rect.bottom;
 kpmPointTooltip.style.left=Math.max(8,Math.min(innerWidth-box.width-8,x+16+box.width<=innerWidth-8?x+16:x-box.width-16))+'px';
 kpmPointTooltip.style.top=Math.max(8,Math.min(innerHeight-box.height-8,y+12+box.height<=innerHeight-8?y+12:y-box.height-12))+'px';
}
function kpmShowPointTooltip(anchor,event){
 const p=kpmChartPoints.get(anchor?.dataset.kpmPoint);if(!anchor?.isConnected||!p)return;
 kpmKeepPointTooltip();
 if(kpmPointAnchor!==anchor||kpmPointTooltip.hidden){
  kpmHidePointTooltip();hideMetricTooltip();upHideSalesTooltip();uiHideCellTooltip();
  const range=[kpmChartContext.start,kpmChartContext.end].map(d=>d.slice(2).replaceAll('-','/')).join(' — ');
  const values=[['gsv','GSV',upMoney(p.facts.gsvCents)],['profit','单品利润率',upPercent(p.profit),p.profit<0],['amount','利润额',upMoney(p.facts.profitCents),p.facts.profitCents<0],['units','销量',fmt(p.facts.sales)],['returns','总退',upPercent(p.facts.returnRate)],['received','已收退',upPercent(p.facts.receivedRate)]];
  const guidePrice=Number.isFinite(p.guidePriceCents)?fmt(p.guidePriceCents/100,2)+'元':'—';
  kpmPointTooltip.innerHTML=`<div class="kpm-point-product">${riskThumbnail(p.name)}<div class="kpm-point-info"><b>${esc(p.name)}</b><span class="kpm-point-grade ${p.level||'unrated'}">${p.level?p.level+'级'+(brcProductOperatingMatch(p.level,p.profit)?' · '+kpmGrades[p.level]:''):'—'}</span></div><div class="kpm-point-guide" data-kpm-metric="guidePrice"><span>指导价</span><strong>${esc(guidePrice)}</strong></div></div><div class="kpm-point-period">${esc(kpmChartContext.label)} · ${range}</div><div class="kpm-point-values">${values.map(([key,label,value,red])=>`<div data-kpm-metric="${key}"><span>${label}</span><strong class="${red?'negative':''}">${esc(value)}</strong></div>`).join('')}</div>`;
  kpmPointTooltip.dataset.spuId=p.spuId;kpmPointAnchor=anchor;anchor.setAttribute('aria-describedby',kpmPointTooltip.id);kpmPointTooltip.hidden=false;
 }
 kpmPlacePointTooltip(anchor,event);
}
const kpmPointSelector='#matrix.kpm-main circle[data-kpm-point]';
for(const type of ['pointerover','pointermove'])document.addEventListener(type,e=>{if(kpmPointTooltip.contains(e.target)){kpmKeepPointTooltip();return}const anchor=e.target.closest?.(kpmPointSelector);if(anchor)kpmShowPointTooltip(anchor,e)});
document.addEventListener('pointerout',e=>{if(kpmInsidePointTooltip(e.target)&&!kpmInsidePointTooltip(e.relatedTarget))kpmSchedulePointTooltipHide()});
document.addEventListener('focusin',e=>{if(e.target.matches?.(kpmPointSelector))kpmShowPointTooltip(e.target)});
document.addEventListener('focusout',e=>{if(kpmPointAnchor?.contains(e.target)&&!kpmInsidePointTooltip(e.relatedTarget)&&!kpmPointTooltip.matches(':hover'))kpmHidePointTooltip()});
document.addEventListener('click',e=>{if(!kpmPointTooltip.contains(e.target))kpmHidePointTooltip()},true);
document.addEventListener('scroll',e=>{if(kpmPointTooltip.contains(e.target))return;if(kpmPointAnchor&&document.activeElement===kpmPointAnchor)kpmPlacePointTooltip(kpmPointAnchor);else kpmHidePointTooltip()},true);
window.addEventListener('resize',kpmHidePointTooltip);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!kpmPointTooltip.hidden){e.preventDefault();e.stopImmediatePropagation();kpmHidePointTooltip()}},true);
// 移动原图到原生模态框，保留圆点数据和事件；关闭时原位还原，不复制ID或重算指标。
let kpmZoomState=null;
function kpmCloseChartZoom(restoreFocus=true){
 const state=kpmZoomState;if(!state)return;
 kpmZoomState=null;kpmHidePointTooltip();
 if(state.dialog.open)state.dialog.close();
 state.filtersHost?.remove();state.plot.querySelector('#matrixchart').replaceChildren(...state.chartNodes);
 kpmChartPoints.clear();for(const [id,row] of state.points)kpmChartPoints.set(id,row);kpmChartContext=state.chartContext;
 state.legend.parent.insertBefore(state.legend.node,state.legend.next);
 state.marker.replaceWith(state.plot);document.body.append(kpmPointTooltip);
 state.trigger.textContent='⛶ 放大';state.trigger.setAttribute('aria-label','放大产品经营矩阵');state.trigger.setAttribute('aria-expanded','false');
 state.dialog.remove();document.documentElement.classList.remove('kpm-zoom-open');
 if(restoreFocus&&state.trigger.isConnected)state.trigger.focus({preventScroll:true});
}
function kpmOpenChartZoom(trigger){
 if(kpmZoomState)return;
 kpmHidePointTooltip();hideMetricTooltip();
 const plot=trigger.closest('.matrixplot'),marker=document.createElement('div'),dialog=document.createElement('dialog');
 marker.className='kpm-chart-placeholder';marker.style.height=plot.getBoundingClientRect().height+'px';marker.setAttribute('aria-hidden','true');
 dialog.className='kpm-chart-zoom';dialog.setAttribute('aria-label','产品经营矩阵放大');
 plot.before(marker);dialog.append(plot,kpmPointTooltip);$('#matrix').append(dialog);
 const legend=plot.querySelector('.kpm-chart-legend'),legendPosition={node:legend,parent:legend.parentNode,next:legend.nextSibling};
 plot.append(legend);
 kpmZoomState={plot,marker,dialog,trigger,legend:legendPosition,suspended:false,focus:null,chartNodes:[...plot.querySelector('#matrixchart').childNodes],points:new Map(kpmChartPoints),chartContext:{...kpmChartContext}};
 kpmMountZoomFilters(kpmZoomState);
 trigger.textContent='×';trigger.setAttribute('aria-label','关闭放大弹窗');trigger.setAttribute('aria-expanded','true');
 // 原生dialog提供焦点约束、背景不可操作及Escape取消；圆点提示随图进入顶层。
 dialog.addEventListener('cancel',e=>{e.preventDefault();kpmCloseChartZoom()});
 dialog.addEventListener('close',()=>{if(kpmZoomState?.dialog===dialog&&!kpmZoomState.suspended&&!dialog.open)kpmCloseChartZoom()});
 dialog.addEventListener('click',e=>{
  if(e.target!==dialog)return;
  const box=dialog.getBoundingClientRect();
  if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)kpmCloseChartZoom();
 });
 document.documentElement.classList.add('kpm-zoom-open');dialog.showModal();trigger.focus({preventScroll:true});
}
document.addEventListener('click',e=>{
 const trigger=e.target.closest('#matrix.kpm-main [data-kpm-expand]');if(!trigger)return;
 if(kpmZoomState)kpmCloseChartZoom();else kpmOpenChartZoom(trigger);
});

// 打开详情时暂时退出浏览器顶层，保留原图和滚动；最终关闭抽屉后恢复同一弹窗。
function kpmSuspendChartZoom(){
 const state=kpmZoomState;if(!state||state.suspended)return;
 state.suspended=true;state.focus=document.activeElement;kpmHidePointTooltip();
 state.scroll={left:state.plot.querySelector('#matrixchart').scrollLeft,top:state.plot.querySelector('#matrixchart').scrollTop};
 state.dialog.close();
}
new MutationObserver(()=>{
 const state=kpmZoomState;if(!state?.suspended||!$('#overlay').hidden)return;
 state.suspended=false;state.dialog.showModal();
 const chart=state.plot.querySelector('#matrixchart');chart.scrollLeft=state.scroll.left;chart.scrollTop=state.scroll.top;
 // 关闭抽屉后的焦点回到原图圆点；不自动弹出圆点提示。
 (state.focus?.isConnected?state.focus:state.trigger).focus({preventScroll:true});kpmHidePointTooltip();
}).observe($('#overlay'),{attributes:true,attributeFilter:['hidden']});
// 图表区域和产品等级共用图片规则；缺失等级数据的产品保留并在矩阵中显示灰色。
const kpmGradeOrder=['S','A','B','C'];
const kpmGradeRules=brcGradeRules('recent30');
const kpmChanges={up:'等级上升',down:'等级下降',same:'等级保持',new:'首次分级',pending:'无等级数据',uncompared:'上期无等级数据'};
let kpmSelectedChange='up';
function kpmMatchesChange(assessment,change='all'){
 return change==='all'||(change==='changed'?['up','down'].includes(assessment.change):assessment.change===change);
}
function kpmClassifyGrade(salesWan,profit,units=1,mode='recent30'){
 return units>0?brcProductGrade(salesWan,profit,mode):null;
}
function kpmGradeWindow(end,mode='recent30'){
 if(mode==='recent30')return {start:shiftDate(end,-29),end};
 const year=Number(end.slice(0,4)),month=Number(end.slice(5,7))-1;
 const start=new Date(Date.UTC(year,mode==='year'?0:mode==='quarter'?month-month%3:month,1)).toISOString().slice(0,10);
 return {start,end};
}
function kpmGradeAssessment(identity,end,platform='all',mode='recent30',start=null){
 start=start||kpmGradeWindow(end,mode).start;const facts=upSummary(identity,start,end,platform);
 const level=kpmClassifyGrade(facts.gsvCents/1000000,facts.profitRate,facts.sales,mode);
 return {start,end,mode,level,gsvCents:facts.gsvCents,profitRate:facts.profitRate,sales:facts.sales,profitCents:facts.profitCents,returnRate:facts.returnRate,receivedRate:facts.receivedRate};
}
function kpmGradeChange(current,previous){
 if(!current.level)return 'pending';
 if(!previous.level)return 'uncompared';
 const diff=kpmGradeOrder.indexOf(previous.level)-kpmGradeOrder.indexOf(current.level);
 return diff>0?'up':diff<0?'down':'same';
}
function kpmGradeComparison(identity,end,platform='all',mode='recent30',start=null){
 const current=kpmGradeAssessment(identity,end,platform,mode,start),previousStart=mode==='day'?shiftDate(current.start,-(aiFlowDayDiff(current.start,current.end)+1)):null,previous=kpmGradeAssessment(identity,shiftDate(current.start,-1),platform,mode,previousStart);
 const change=current.level&&!previous.level&&upProduct(identity).actualLaunch>previous.end?'new':kpmGradeChange(current,previous);
 return {current,previous,change};
}
function kpmGradeHistory(identity,end,platform='all'){
 // 历史来自同一逐日台账，每条是独立的30天窗口；上架前数据不伪造等级。
 return Array.from({length:6},(_,i)=>kpmGradeComparison(identity,shiftDate(end,-30*i),platform));
}
window.dashboardKeyProductGradeHistory=spuId=>withPeriod('matrix',()=>{
 const p=upSpus.get(spuId);return p?kpmGradeHistory(p,upWindow().end,kpmBusinessPlatforms()):[];
});
function kpmFormatGradeRange(fact){return fact.start.replaceAll('-','/')+' — '+fact.end.replaceAll('-','/')}
function kpmChangeText(assessment){
 const {current,previous}=assessment;
 return (previous.level||'—')+' → '+(current.level||'—');
}
function kpmChangeMarkup(p){
 const {current,previous}=p.assessment;
 const badge=level=>`<span class="kpm-change-grade ${level||'unrated'}">${level||'—'}</span>`;
 return `<span class="kpm-change ${p.assessment.change}" data-kpm-grade-change="${p.spuId}">${badge(previous.level)}<span class="kpm-change-arrow" aria-hidden="true">→</span>${badge(current.level)}</span>`;
}
// 升降由上方卡片切换；仅为其他经营异动显示可清除的条件。
function kpmRenderChangeCondition(){
 const rule=kpmChangeSignals.find(rule=>rule.key===kpmSelectedChange&&!['up','down'].includes(rule.key)),condition=$('#kpm-active-change');
 if(condition)condition.innerHTML=rule?'<button type="button" class="kpm-change-condition" data-kpm-clear-change aria-label="清除异动条件：'+esc(rule.label)+'">异动：'+esc(rule.label)+'<span aria-hidden="true">×</span></button>':'';
}
// 仅保留一个异动条件；从概览进入时定位到主表，并把焦点放在可操作条件上。
function kpmSelectChangeFilter(key,{reveal=false}={}){
 if(!kpmChangeSignals.some(rule=>rule.key===key))return;
 if(['up','down'].includes(key)){kpmSelectedGrade='all';kpmSelectedOperating=null;}
 kpmSelectedChange=key;kpmPage.value=1;kpmRender();
 if(reveal)$('#matrix .matrixlist')?.scrollIntoView({block:'start',behavior:'auto'});
 const control=$('#matrix [data-kpm-summary-change="'+key+'"]')||$('#matrix [data-kpm-clear-change]');
 control?.focus({preventScroll:true});
}

document.addEventListener('click',e=>{
 if(e.target.closest('#matrix.kpm-main [data-kpm-clear-change]'))return kpmSelectChangeFilter('up');
});
// 首列复用新品产品身份组件；经营退货率显示目标偏差，其余经营指标显示环比，库存保持最新快照。
function kpmMetricCell(key,field){
 const valueClass=key==='gsv'?'kpm-value-gsv':key==='profit'?'kpm-value-profit':'';
 const markup=rpListCell({key:key==='returns'?'return':key,tone:'',...field}).replace('class="rp-value ',`class="${valueClass} rp-value `);
 return `<div class="kpm-metric kpm-metric-${key}" data-kpm-metric="${key}">${markup}</div>`;
}
function kpmTableMetrics(p){
 const c=p.facts,b=p.previous;
 return [
  kpmMetricCell('guidePrice',{value:Number.isFinite(p.guidePriceCents)?fmt(p.guidePriceCents/100,2)+'元':'—'}),
  kpmMetricCell('gsv',{value:upMoney(c.gsvCents),...nspComparison(c.gsvCents,b.gsvCents)}),
  kpmMetricCell('units',{value:fmt(c.netSales),...nspComparison(c.netSales,b.netSales)}),
  kpmMetricCell('profit',{value:upPercent(c.profitRate),...nspComparison(c.profitRate,b.profitRate,{margin:true,signed:true})}),
  kpmMetricCell('returns',{value:upPercent(c.returnRate),...rpQualityReturnRule(c.returnRate,p.returnTarget)}),
  kpmMetricCell('received',{value:upPercent(c.receivedRate),...rpQualityReturnRule(c.receivedRate,p.receivedTarget,'received')}),
  kpmMetricCell('unreceived',{value:upPercent(upUnreceivedRate(c)),...rpRateDeltaComparison(upUnreceivedRate(c),upUnreceivedRate(b))}),
  kpmMetricCell('warehouse',{value:stockQuantity(p.stock?.warehouse),target:'货值 '+(Number.isFinite(p.stock?.warehouseValueCents)?upMoney(p.stock.warehouseValueCents):'—')}),
  kpmMetricCell('total',{value:stockQuantity(p.stock?.totalUnits),target:'总可售天数 '+(Number.isFinite(p.stock?.totalCoverage15)?fmt(p.stock.totalCoverage15,1)+'天':'—')})
 ];
}
function kpmTable(rows){
 const headers=['SPU信息','等级变动',kpmHeader('guidePrice','指导价'),kpmHeader('sales','GSV'),kpmHeader('units','销量'),kpmHeader('profit','利润率'),
  kpmHeader('returns','总退'),kpmHeader('received','已收退'),kpmHeader('unreceived','未收退'),kpmHeader('warehouse','我司可售库存'),kpmHeader('total','总库存'),kpmHeader('days','上线时长'),'操作'];
 return rows.length?table(headers,rows.map(p=>[
  titleProduct(p,{showBrand:false,gradeMarkup:kpmGradeBadge(p)}),kpmChangeMarkup(p),...kpmTableMetrics(p),Number.isFinite(p.days)?fmt(p.days)+'天':'—',
  `<button type="button" class="link" data-kpm-detail="${p.spuId}">查看</button>`
 ])):'<div class="kpm-empty">暂无符合条件的产品，请调整搜索或筛选</div>';
}

// 数据区显示六行半；按真实第七行中点测量，兼容列宽及名称换行。
function kpmFitTableViewport(host){
 dashboardQueueLayout(host,kpmMeasureTableViewport);
}
function kpmMeasureTableViewport(host){
 const table=host.querySelector('table');
 if(!table)return ()=>host.style.removeProperty('--kpm-table-max-height');
 if(!table.getClientRects().length)return;
 const partial=table.tBodies[0]?.rows[6];
 if(!partial)return ()=>host.style.removeProperty('--kpm-table-max-height');
 const row=partial.getBoundingClientRect(),contentHeight=row.top-table.getBoundingClientRect().top+row.height/2;
 const scrollbar=host.offsetHeight-host.clientHeight;
 const height=Math.ceil(contentHeight+scrollbar)+'px';
 if(host.style.getPropertyValue('--kpm-table-max-height')!==height)return ()=>host.style.setProperty('--kpm-table-max-height',height);
}
const kpmTableViewportObserver=new ResizeObserver(entries=>{
 for(const {target} of entries){const host=target.closest('#matrix.kpm-main #matrixtable');if(host)kpmFitTableViewport(host)}
});
function kpmObserveTableViewport(host){
 kpmTableViewportObserver.disconnect();kpmFitTableViewport(host);dashboardQueueLayout(host,dashboardMeasureResetScroll);
 const table=host.querySelector('table');if(table)kpmTableViewportObserver.observe(table);
}
// 仅管理关键产品筛选菜单的位置；选值与互斥仍复用共享多选控件。
const kpmDropdownSelector='#matrix.kpm-main :is(.kpm-tools,.kpm-zoom-filters) .pf-multi';
function kpmPositionDropdown(menu){
 const panel=menu.querySelector('.pf-multi-menu'),anchor=menu.getBoundingClientRect();
 const modal=menu.closest('dialog[open]'),bounds=modal?.getBoundingClientRect();
 let safeTop=bounds?bounds.top+8:8;
 for(const header of document.querySelectorAll('.head,.navigation-toolbar,.jumpnav')){
  const rect=header.getBoundingClientRect(),position=getComputedStyle(header).position;
  if(!modal&&['fixed','sticky'].includes(position)&&rect.top<=safeTop&&rect.bottom>0)safeTop=Math.max(safeTop,rect.bottom+8);
 }
 if(anchor.bottom<=safeTop||anchor.top>=innerHeight-8){pfMultiClose(menu);return}
 const minLeft=bounds?bounds.left+8:8,maxRight=bounds?bounds.right-8:innerWidth-8,bottom=bounds?bounds.bottom-8:innerHeight-8;
 const width=Math.min(Math.max(anchor.width,200),maxRight-minLeft),left=Math.max(minLeft,Math.min(anchor.left,maxRight-width));
 Object.assign(panel.style,{width:width+'px',minWidth:'0',maxWidth:'none',left:(left-anchor.left)+'px'});
 const desired=Math.min(270,panel.scrollHeight+2),below=Math.max(0,bottom-anchor.bottom-6),above=Math.max(0,anchor.top-safeTop-6);
 const upward=below<desired&&above>below,space=upward?above:below;
 Object.assign(panel.style,{top:upward?'auto':'calc(100% + 6px)',bottom:upward?'calc(100% + 6px)':'auto',maxHeight:Math.min(270,space)+'px'});
 menu.dataset.kpmDropDirection=upward?'up':'down';
}
let kpmDropdownFrame=0;
function kpmScheduleDropdowns(){
 if(kpmDropdownFrame||!document.querySelector(kpmDropdownSelector+'[open]'))return;
 kpmDropdownFrame=requestAnimationFrame(()=>{
  kpmDropdownFrame=0;
  for(const menu of document.querySelectorAll(kpmDropdownSelector+'[open]'))kpmPositionDropdown(menu);
 });
}
document.addEventListener('toggle',e=>{
 if(e.target.matches(kpmDropdownSelector)&&e.target.open)kpmPositionDropdown(e.target);
},true);
window.addEventListener('resize',kpmScheduleDropdowns);
document.addEventListener('scroll',kpmScheduleDropdowns,true);
// Tab 离开整个控件时收起，菜单内部移动焦点可继续多选。
document.addEventListener('focusin',e=>{
 for(const menu of document.querySelectorAll(kpmDropdownSelector+'[open]'))if(!menu.contains(e.target))pfMultiClose(menu);
});
