// 历史期间只读取当时已产生的评审、验收结果。
function kpmFollowupWork(record,end){
 const stamp=record.reviewDate||record.reportDate;if(!stamp||stamp<=end)return record;
 return {...record,note:'',review:undefined,actual:undefined,status:record.status==='done'?'working':record.status};
}
function kpmCycleTaskId(record){return 'grade-cycle|'+record.id}
function kpmCycleOrigin(record,task){
 const date=record.reviewDate||record.reportDate||record.start,sourceName=record.source.includes('周报')?record.assignee+'的'+record.source+date.slice(2).replaceAll('-',''):task.objectName+' · '+record.source;
 return {version:1,mode:'records',originId:record.id,analysisKind:'record',analysis:task.description,sources:[{id:record.id+'|record',sourceType:record.source,sourceName,date,capturedAt:new Date().toISOString(),content:task.description}]};
}
// 已保存样例仅补来源快照，保留原办理数据及问题原文。
function kpmBindCycleOrigins(){
 const next={...upTodos};let changed=false;
 for(const record of kpmCycleSamples){const task=next[kpmCycleTaskId(record)];if(!task||upTodoHasOrigin(task))continue;next[task.id]={...task,originEvidence:kpmCycleOrigin(record,task)};changed=true}
 if(changed)upPersistTodos(next);
}
kpmBindCycleOrigins();
function kpmCycleTask(record,product){
 const saved=upTodos[kpmCycleTaskId(record)];if(saved)return saved;
 record=kpmFollowupWork(record,upWindow().end);
 const stamp=record.start+'T09:00:00+08:00',done=record.status==='done';
 const task={id:kpmCycleTaskId(record),spuId:product.spuId,objectName:product.name,platform:'all',start:record.start,end:record.due,
  title:record.title,description:record.source+'：'+(record.note||record.title),plan:'针对'+product.name+'，'+record.note+' 提交关联报价、成本复核或验证记录，由产品中心确认后续投入安排。',
  department:record.department,assignee:record.assignee,due:record.due,priority:done?'green':'yellow',taskType:record.kind==='bom'?'cost-reduction':'business-improvement',
  status:record.status,source:'grade-management-demo',assignedBy:'周铭',assignedAt:stamp,createdAt:stamp,completedAt:done?record.reportDate+'T17:00:00+08:00':'',
  evidence:done?record.note:'',basis:[record.source],logs:[{at:stamp,actor:'周铭',action:'assign',from:'suggested',to:record.status,note:record.source}]};
 return {...task,originEvidence:kpmCycleOrigin(record,task)};
}
// 经营预警使用实际分级事实；AI跟进复用制度、明确承诺及已产生的验收记录。
const kpmManagementSections={changes:'等级异动',structure:'大盘结构'};
// 五类异动在概览计数和主表筛选中共用一份条件，避免两处口径漂移。
const kpmChangeSignals=[
 {key:'core',label:'利润支柱退出S级',tone:'red',detail:'优先核实规模与利润变化',match:p=>p.assessment.previous.level==='S'&&p.assessment.current.sales>0&&p.level!=='S'},
 {key:'consecutive',label:'连续两期等级下滑',tone:'red',detail:'核实持续下行原因及投入安排',match:p=>p.assessment.change==='down'&&kpmGradeComparison(upIdentity(p),p.assessment.previous.end,kpmBusinessPlatforms(),p.assessment.previous.mode).change==='down'},
 {key:'down',label:'本期等级下降',tone:'yellow',detail:'区分规模收缩与利润变化',match:p=>p.assessment.change==='down'},
 {key:'margin',label:'S/A级利润率回落',tone:'yellow',detail:'核实成本改善与贡献变化',match:p=>['S','A'].includes(p.level)&&Number.isFinite(p.assessment.previous.profitRate)&&p.assessment.current.profitRate<p.assessment.previous.profitRate},
 {key:'up',label:'本期等级上升',tone:'green',detail:'核实增长来源及利润改善的持续性',match:p=>p.assessment.change==='up'}
];
function kpmMatchesSignal(product,key='all'){
 const rule=kpmChangeSignals.find(rule=>rule.key===key);
 return rule?rule.match(product):kpmMatchesChange(product.assessment,key);
}

function kpmManagementCycles(rows){
 const end=upWindow().end,result=[];
 for(const record of kpmCycleSamples){
  const product=rows.find(p=>p.spuId===record.spuId);if(!product||record.start>end)continue;
  const company=kpmGradeAssessment(upIdentity(product),end,'all',periodFor('matrix').mode,upWindow().start),reported=record.reportDate&&record.reportDate<=end;
  const achieved=record.kind==='upgrade'?company.level==='S':record.kind==='bom'?reported&&record.actual>=5:record.reviewDate<=end&&record.review==='通过';
  const failed=record.kind==='upgrade'?company.sales>0&&Number.isFinite(company.profitRate)&&company.level!=='S':record.kind==='rescue'?record.reviewDate<=end&&record.review==='未通过':false;
  const state=achieved?'achieved':end>=record.due?(failed?'overdue':'verify'):record.due.slice(0,7)===end.slice(0,7)?'due':record.kind==='bom'?'annual':'working';
  result.push({record,product,company,state,reported,task:kpmCycleTask(record,product)});
 }
 return result;
}
function kpmManagementGroups(rows,tab='changes'){
 const group=(key,label,tone,items,detail)=>({key,label,tone,ids:[...new Set(items.map(p=>p.spuId))],detail});
 if(tab==='structure')return [
  group('core','利润支柱流出','red',rows.filter(p=>p.assessment.previous.level==='S'&&p.assessment.current.sales>0&&p.level!=='S'),'原S级产品退出利润支柱梯队'),
  group('tail','尾部产品新增','yellow',rows.filter(p=>p.level==='C'&&p.assessment.previous.level!=='C'),'关注尾部新增及后续挽救安排'),
  group('new-core','利润支柱补充','green',rows.filter(p=>p.level==='S'&&p.assessment.previous.level!=='S'),'新增S级产品及其经营贡献')];
 return kpmChangeSignals.map(rule=>group(rule.key,rule.label,rule.tone,rows.filter(rule.match),rule.detail));
}

function kpmManagementIds(rows,key,tab='changes'){
 if(key.startsWith('grade-'))return rows.filter(p=>(p.level||'unrated')===key.slice(6)).map(p=>p.spuId);
 return kpmManagementGroups(rows,tab).find(g=>g.key===key)?.ids||[];
}
function kpmManagementStructure(rows){
 const total=rows.reduce((n,p)=>n+p.facts.gsvCents,0);
 return [...kpmGradeOrder,'unrated'].map(level=>{
  const items=rows.filter(p=>(p.level||'unrated')===level),before=rows.filter(p=>(p.assessment.previous.level||'unrated')===level).length;
  const amount=items.reduce((n,p)=>n+p.facts.gsvCents,0),profit=items.reduce((n,p)=>n+p.facts.profitCents,0);
  const operating=level==='unrated'?[]:items.filter(p=>brcProductOperatingMatch(level,p.assessment.current.profitRate)),operatingBefore=level==='unrated'?[]:rows.filter(p=>p.assessment.previous.level===level&&brcProductOperatingMatch(level,p.assessment.previous.profitRate));
  return {level,count:items.length,before,operating:{count:operating.length,before:operatingBefore.length,ids:operating.map(p=>p.spuId)},share:total>0?amount/total*100:null,gsv:amount,profit,margin:amount!==0?profit/amount*100:null,ids:items.map(p=>p.spuId)};
 });
}
window.dashboardKeyProductManagementSnapshot=()=>withPeriod('matrix',()=>{
 const all=kpmRows(),rows=kpmFilterRows(all,true,false);
 return {view:'combined',structureGroups:kpmManagementGroups(rows,'structure'),baseIds:rows.map(p=>p.spuId),groups:kpmManagementGroups(rows),followups:kpmAiFollowups(rows).map(i=>({spuId:i.product.spuId,stage:i.stage,decision:i.advice.decision,issue:i.advice.issue,taskId:i.task?.id||null,policy:i.policy,progress:i.progress})),strategies:kpmStrategyItems(rows).map(i=>({spuId:i.product.spuId,category:i.strategyCategory,stage:i.stage,taskStatus:i.task?.status||null,goal:i.goal,taskId:i.task?.id||null,records:i.activities.map(a=>({id:a.record.id,source:a.record.source,stage:a.stage,effective:a.effective,verified:a.verified,metrics:a.metrics,newSpuId:a.record.newSpuId||null,batch:a.record.batch||null}))})),cycles:kpmManagementCycles(rows).map(c=>({id:c.record.id,spuId:c.product.spuId,state:c.state,due:c.record.due})),structure:kpmManagementStructure(kpmFilterRows(all,false,false))};
});
// 六卡共用基础范围，计数忽略自身等级和异动筛选。
function kpmManagementStructureView(rows){
 const changes=['up','down'].map(key=>{
  const count=rows.filter(p=>p.assessment.change===key).length,active=kpmSelectedChange===key&&kpmSelectedGrade==='all';
  return '<button type="button" class="kpm-structure-item kpm-change-card '+key+(active?' active':'')+'" data-kpm-summary-change="'+key+'" aria-pressed="'+active+'"><span class="kpm-structure-title"><i aria-hidden="true"></i>'+kpmChanges[key]+'</span><span class="kpm-structure-quantity"><strong class="kpm-structure-count">'+count+'</strong><span class="kpm-structure-unit">个</span></span></button>';
 }).join('');
 const metric=(s,operating=false)=>{
  const facts=operating?s.operating:s,label=operating?kpmGrades[s.level]:s.level+'级产品';
  const direction=facts.count===facts.before?'flat':facts.count>facts.before?'up':'down',active=kpmSelectedGrade===s.level&&(operating?kpmSelectedOperating===s.level:!kpmSelectedOperating);
  return '<button type="button" class="kpm-structure-metric '+(operating?'kpm-operating-metric':'kpm-scale-metric')+(active?' active':'')+'" data-kpm-'+(operating?'operating':'grade')+'="'+s.level+'" aria-pressed="'+active+'"><span class="'+(operating?'kpm-operating-title':'kpm-structure-title')+'">'+(operating?label:'<i aria-hidden="true"></i><span class="kpm-structure-level">'+s.level+'</span>级产品')+'</span><span class="kpm-metric-quantity"><strong class="'+(operating?'kpm-operating-count':'kpm-structure-count')+'">'+facts.count+'</strong><span class="kpm-structure-unit">个</span></span><span class="kpm-metric-comparison"><span>较上期</span><b class="kpm-structure-delta" data-direction="'+direction+'" aria-label="较上期变化">'+(direction==='flat'?'持平':(direction==='up'?'↑':'↓')+Math.abs(facts.count-facts.before))+'</b></span></button>';
 };
 return '<div class="kpm-structure-summary" role="group" aria-label="等级升降及规模、经营两组指标">'+changes+kpmManagementStructure(rows).filter(s=>s.level!=='unrated').map(s=>'<div class="kpm-structure-item kpm-dual-card" data-kpm-card-grade="'+s.level+'">'+metric(s)+metric(s,true)+'</div>').join('')+'</div>';
}
