 const reserved=i===26?'2026-09-05':i===28?'2026-09-02':i<12?`2024-${String(i%9+1).padStart(2,'0')}-12`:i<24?`2025-${String(i%10+1).padStart(2,'0')}-08`:`2026-${String(Math.min(9,i-23)).padStart(2,'0')}-05`;
