function cecSeedCell(id,month){
 const row=cecBase.ledger.find(r=>r.itemId===id&&r.month===month);
 const confirmed=row&&!row.actualMissing?row.confirmations.filter(e=>e.date<=DATA_CUTOFF):[];
 const actual=confirmed.length?confirmed.reduce((n,e)=>n+e.cents,0):null;
 return {targetCents:row?.targetCents??null,actualCents:actual,note:'',updatedAt:''};
}
// 旧项目缓存按指标归并，已保存金额相加并保留备注；不重复保留项目层。
function cecMigrate(saved){
 if(saved?.version===4&&saved.metrics&&saved.months&&saved.departmentTargets)return saved;
 if([2,3].includes(saved?.version)&&saved.metrics&&saved.months)return {...saved,version:3,metrics:Object.fromEntries(Object.entries(saved.metrics).map(([id,value])=>[id,saved.version===3?{department:value.department,metricIndex:value.metricIndex,metric:value.metric,...(Object.hasOwn(value,'category')?{category:value.category}:{}),updatedAt:value.updatedAt||''}:{updatedAt:value.updatedAt||''}]))};
 const next={version:3,metrics:{},months:{}};if(saved?.version!==1||!saved.projects||!saved.months)return next;
 const previous=new Map(cecBase.items.map(item=>[item.id,item]));for(const item of Object.values(saved.projects))previous.set(item.id,item);
 const sum=values=>{const known=values.filter(v=>v!==null&&v!==undefined);return known.length?known.reduce((a,b)=>a+b,0):null};
 for(const metric of cecBase.items){
  const members=[...previous.values()].filter(p=>p.department===metric.department&&p.metricIndex===metric.metricIndex);
  const edits=members.map(p=>saved.projects[p.id]).filter(Boolean);if(edits.length)next.metrics[metric.id]={updatedAt:edits.map(p=>p.updatedAt||'').sort().at(-1)};
  const dates=new Set(cecBase.ledger.filter(r=>r.itemId===metric.id).map(r=>r.month));
  for(const key of Object.keys(saved.months))if(members.some(p=>key.startsWith(p.id+'|')))dates.add(key.split('|')[1]);
  for(const month of dates){
   const cells=members.map(p=>({...cecSeedCell(p.id,month),...saved.months[cecRecordKey(p.id,month)]}));
   const value={targetCents:sum(cells.map(c=>c.targetCents)),actualCents:sum(cells.map(c=>c.actualCents)),note:[...new Set(cells.map(c=>c.note).filter(Boolean))].join('；'),updatedAt:cells.map(c=>c.updatedAt||'').sort().at(-1)||''},base=cecSeedCell(metric.id,month);
   if(value.targetCents!==base.targetCents||value.actualCents!==base.actualCents||value.note||value.updatedAt)next.months[cecRecordKey(metric.id,month)]=value;
  }
 }
 return next;
}
let cecStore={version:3,metrics:{},months:{}};
try{cecStore=cecMigrate(JSON.parse(localStorage.getItem(cecKey)||'null'))}catch(_){/* 缓存损坏时保留参考台账。 */}
cecStore=cecMigrateDepartmentTargets(cecStore);
const cecDirectoryUpgrade=cecUpgradeDepartmentDirectory(cecBase,cecStore);
cecBase.items=cecDirectoryUpgrade.items;cecBase.ledger=cecDirectoryUpgrade.ledger;cecStore=cecDirectoryUpgrade.store;
function cecCell(id,month){return {...cecSeedCell(id,month),...cecStore.months[cecRecordKey(id,month)]}}
function cecApplyStore(){
 ccItems.splice(0,ccItems.length,...cecMetricCatalog(cecStore));ccLedger.splice(0,ccLedger.length,...cecCopy(cecBase.ledger));
 for(const row of ccLedger)delete row.targetCents;
 ccMetrics.splice(0,ccMetrics.length,...ccItems.map(item=>({...item,name:item.metric})));
 for(const department of ccDepartments)department.metrics=ccItems.filter(item=>item.department===department.id).map(item=>item.metric);
 for(const [key,value] of Object.entries(cecStore.months)){
  const [itemId,month]=key.split('|');if(!ccItems.some(p=>p.id===itemId)||!/^\d{4}-\d{2}$/.test(month))continue;
  let row=ccLedger.find(r=>r.itemId===itemId&&r.month===month);
  if(!row){row={id:'CB-CONFIG-'+key,itemId,month,actualMissing:true,confirmations:[]};ccLedger.push(row)}

  if(Object.hasOwn(value,'actualCents')){
   const last=new Date(Date.UTC(+month.slice(0,4),+month.slice(5,7),0)).toISOString().slice(0,10),date=month===DATA_CUTOFF.slice(0,7)?DATA_CUTOFF:last;
   row.actualMissing=value.actualCents===null;row.confirmations=value.actualCents===null?[]:[{id:'CFG-'+key,date,cents:value.actualCents}];
  }
 }
}
function cecCommit(next){
 const saved=cecCopy(next),stamp=cecTime();
 for(const collection of ['metrics','months','departmentTargets'])for(const [key,value]of Object.entries(saved[collection]||{})){
  if(JSON.stringify(value)!==JSON.stringify(cecStore[collection]?.[key]))Object.assign(value,{actor:'管理员',updatedAt:stamp});
 }
 for(const detail of saved.details||[])if(!(cecStore.details||[]).some(row=>row.id===detail.id))Object.assign(detail,{actor:'管理员',updatedAt:stamp});
 try{localStorage.setItem(cecKey,JSON.stringify(saved))}catch(_){throw Error('保存失败，请检查浏览器存储后重试')}
 cecStore=saved;cecApplyStore();ccRender();
}
function cecFiltered(){const q=cecState.query.trim().toLowerCase();return ccItems.filter(p=>(!cecState.department||p.department===cecState.department)&&(!cecState.category||(cecState.category==='unclassified'?!ccCategoryByValue(p.category):p.category===cecState.category))&&(!q||p.metric.toLowerCase().includes(q)))}
cecApplyStore();
function cecPeriod(){return {mode:cecState.mode,year:cecState.year,value:cecState.mode==='month'?cecState.month:cecState.mode==='quarter'?Math.ceil(cecState.month/3):1}}
function cecSelectedMonths(){const p=cecPeriod(),first=p.mode==='year'?1:p.mode==='quarter'?(p.value-1)*3+1:p.value,last=p.mode==='year'?12:p.mode==='quarter'?p.value*3:p.value;return Array.from({length:last-first+1},(_,i)=>cecMonth(p.year,first+i))}
function cecSummaryCell(id){
 const cells=cecSelectedMonths().map(month=>cecCell(id,month));const sum=key=>{const known=cells.map(c=>c[key]).filter(v=>v!==null);return known.length?known.reduce((a,b)=>a+b,0):null};
 return {targetCents:sum('targetCents'),actualCents:sum('actualCents'),note:[...new Set(cells.map(c=>c.note).filter(Boolean))].join('；'),...cecLatestUpdate(cells)};
}
// 目标只属于部门＋月份；首次迁移按旧细项台账汇总，之后不随细项增删或改分类变化。
function cecMigrateDepartmentTargets(store){
 if(store.version===4&&store.departmentTargets)return store;
 const catalog=cecMetricCatalog(store),departmentByItem=new Map(catalog.map(item=>[item.id,item.department]));
 const records=new Map(cecBase.ledger.map(row=>[cecRecordKey(row.itemId,row.month),row.targetCents]));
 for(const [key,value] of Object.entries(store.months))if(Object.hasOwn(value,'targetCents'))records.set(key,value.targetCents);
 const departmentTargets={};
 for(const [key,value] of records){
  const [id,month]=key.split('|'),department=departmentByItem.get(id);if(!department||!Number.isFinite(value))continue;
  const targetKey=cecRecordKey(department,month),before=departmentTargets[targetKey];
  departmentTargets[targetKey]={targetCents:(before?.targetCents??0)+value,updatedAt:[before?.updatedAt||'',store.months[key]?.updatedAt||''].sort().at(-1)};
 }
 const months=Object.fromEntries(Object.entries(store.months).map(([key,value])=>{const {targetCents,...actual}=value;return [key,actual]}));
 return {...store,version:4,months,departmentTargets};
}
function cecDepartmentTargetCell(department,month){return cecStore.departmentTargets[cecRecordKey(department,month)]||{targetCents:null,updatedAt:''}}
function cecAnnualDepartmentTarget(department,year=cecState.year){
 const values=Array.from({length:12},(_,i)=>cecDepartmentTargetCell(department,cecMonth(year,i+1)).targetCents),known=values.filter(Number.isFinite);
 return {values,total:known.length?known.reduce((sum,value)=>sum+value,0):null};
}
function cecDepartmentTargetSummary(department){
 const cells=cecSelectedMonths().map(month=>cecDepartmentTargetCell(department,month)),values=cells.map(cell=>cell.targetCents).filter(Number.isFinite);
 return {targetCents:values.length?values.reduce((sum,value)=>sum+value,0):null,...cecLatestUpdate(cells)};
}
// 看板只汇总部门总目标；细项/分类调用实际模型，不分摊或推算目标。
function cecDepartmentTargetTotal(metrics,range){
 const departments=new Set(metrics.map(metric=>metric.department));let total=null;
 for(const [key,cell] of Object.entries(cecStore.departmentTargets)){
  const [department,month]=key.split('|');
  if(departments.has(department)&&month>=range.first&&month<=range.last&&Number.isFinite(cell.targetCents))total=(total??0)+cell.targetCents;
 }
 return total;
}
// 两个Tab共用全年周期边界，展示切换不改变月度原始记录。
function cecYearPeriods(){
 const mode=cecState.mode,count=mode==='month'?12:mode==='quarter'?4:1,width=12/count;
 return Array.from({length:count},(_,index)=>({key:mode+'-'+(index+1),label:mode==='month'?(index+1)+'月（元）':mode==='quarter'?'Q'+(index+1)+'（元）':'年度（元）',months:Array.from({length:width},(_,offset)=>cecMonth(cecState.year,index*width+offset+1))}));
}
function cecActualPeriodCell(id,months){
 const cells=months.map(month=>cecCell(id,month)),known=cells.map(cell=>cell.actualCents).filter(Number.isFinite);
 return {actualCents:known.length?known.reduce((sum,value)=>sum+value,0):null,...cecLatestUpdate(cells)};
}
const cecDisplayMoney=cents=>Number.isFinite(cents)?cecMoney(cents):'';
// 保留旧逐月模板读取，归一到部门＋指标；旧名称、编号不再创建额外业务对象。
const cecLegacyHeaders=['项目编号','项目名称','责任部门','降本指标','责任人','年月','目标金额','实际降本金额','备注'];
function cecValidateLegacyImport(table){
 const errors=[],entries=[],next=cecCopy(cecStore),seen=new Set(),categories=new Map(),stamp=cecTime();
 if(table.length<2)return {errors:[{row:1,message:'文件没有数据行'}],entries:[],next};
 if(table.length>3001)return {errors:[{row:1,message:'单次最多导入3000条月度数据'}],entries:[],next};
 const headers=table[0].map(v=>String(v).trim());
 const classified=headers.includes('降本分类'),columns=classified?[...cecLegacyHeaders,'降本分类']:cecLegacyHeaders;
 if(headers.length!==columns.length||new Set(headers).size!==headers.length||columns.some(h=>!headers.includes(h)))return {errors:[{row:1,message:'表头不匹配，请下载最新模板'}],entries:[],next};
 for(let i=1;i<table.length;i++){
  const source=Object.fromEntries(columns.map(h=>[h,String(table[i][headers.indexOf(h)]??'').trim()])),row=table[i].sourceRow||i+1,start=errors.length,fail=message=>errors.push({row,message,source});
  const department=cecDepartmentByName(source['责任部门']),month=source['年月'];let item=null;
  if(!department)fail('责任部门不存在');else try{
   if(classified&&!source['降本分类'])throw Error('请填写降本分类');
   item=cecResolveMetric(next,department.id,source['降本指标'],'',classified?source['降本分类']:undefined);
   if(categories.has(item.id)&&categories.get(item.id)!==item.category)throw Error('同一部门、降本指标的分类不一致');
   categories.set(item.id,item.category);next.metrics[item.id]=cecMetricMetadata(item,stamp);
  }catch(error){fail(error.message)}
  if(table[i].length>headers.length)fail('数据列数多于表头');
  if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)||!dashboardYears(4).includes(+month.slice(0,4)))fail('年月须为2025-01至'+dashboardYears(4).at(-1)+'-12，格式为YYYY-MM');
  if(source['备注'].length>200)fail('备注不能超过200字');
  if(source['目标金额'])fail('细项不维护目标，请在合并模板中使用部门目标行');
  let actualCents=null;try{actualCents=cecAmount(source['实际降本金额'])}catch(error){fail(error.message)}
  if(!source['实际降本金额']&&!source['备注'])fail('请至少填写实际降本金额或备注');
  const key=cecRecordKey(item?.id,month);if(seen.has(key))fail('文件内同一部门、降本指标及年月重复');seen.add(key);if(errors.length!==start)continue;
  const patch={...next.months[key],updatedAt:stamp};if(source['实际降本金额']!=='')patch.actualCents=actualCents;if(source['备注']!=='')patch.note=source['备注'];next.months[key]=patch;
  next.metrics[item.id]=cecMetricMetadata(item,stamp);
  const before=cecCell(item.id,month),exists=cecBase.ledger.some(r=>r.itemId===item.id&&r.month===month)||Object.hasOwn(cecStore.months,key);
  entries.push({id:item.id,name:item.metric,department:department.name,category:item.category,month,actualCents:source['实际降本金额']===''?before.actualCents:actualCents,kind:exists?'更新':'新增',row});
 }
 return {errors,entries,next};
}
// 细项实际的年度校验；合并表入口见02-combined-import，保持实际台账独立。
const cecActualHeaders=['责任部门','降本分类','降本指标','年度',...Array.from({length:12},(_,i)=>(i+1)+'月'),'备注'];
function cecValidateActualImport(table){
 const headers=table[0]?.map(v=>String(v).trim())||[];
 if(headers.includes('年月'))return {...cecValidateLegacyImport(table),headers};
 const errors=[],normalized=[[...cecLegacyHeaders,'降本分类']],origins=[];
 if(headers.length!==cecActualHeaders.length||new Set(headers).size!==headers.length||cecActualHeaders.some(h=>!headers.includes(h)))return {errors:[{row:1,message:'表头不匹配，请下载最新目标与实际模板'}],entries:[],headers:cecActualHeaders};
 if(table.length<2||table.length>3001)return {errors:[{row:1,message:table.length<2?'文件没有数据行':'单次最多导入3000行'}],entries:[],headers:cecActualHeaders};
 for(let i=1;i<table.length;i++){
  const source=Object.fromEntries(cecActualHeaders.map(h=>[h,String(table[i][headers.indexOf(h)]??'').trim()])),year=source['年度'];
  if(!/^\d{4}$/.test(year)||!dashboardYears(4).includes(+year)){errors.push({row:table[i].sourceRow||i+1,message:'年度超出可配置范围',source});continue}
  if(table[i].length>headers.length)errors.push({row:table[i].sourceRow||i+1,message:'数据列数多于表头',source});
  for(let m=1;m<=12;m++)if(source[m+'月']!==''){
   normalized.push(['',source['降本指标'],source['责任部门'],source['降本指标'],'',year+'-'+String(m).padStart(2,'0'),'',source[m+'月'],source['备注'],source['降本分类']]);origins.push({row:table[i].sourceRow||i+1,source});
  }
 }
 if(errors.length)return {errors,entries:[],headers:cecActualHeaders};
 if(!origins.length)return {errors:[{row:2,message:'请至少填写一个月的实际降本金额'}],entries:[],headers:cecActualHeaders};
 const result=cecValidateLegacyImport(normalized);result.errors=result.errors.map(error=>({...error,...origins[error.row-2]}));result.entries=result.entries.map(entry=>({...entry,row:origins[entry.row-2]?.row||entry.row}));return {...result,headers:cecActualHeaders};
}
function cecErrorDownload(result){const headers=result.headers||cecHeaders;downloadCsv(['原始行号',...headers,'错误原因'],result.errors.map(e=>[e.row,...headers.map(h=>e.source?.[h]||''),e.message]),'降本增效导入错误明细')}
const cecDepartmentTargetHeaders=['责任部门','年度',...Array.from({length:12},(_,i)=>(i+1)+'月')];
function cecValidateDepartmentTargetImport(table){
 const headers=table[0]?.map(value=>String(value).trim())||[],errors=[],entries=[],next=cecCopy(cecStore),seen=new Set(),stamp=cecTime();
 const result=()=>({errors,entries,next,headers:cecDepartmentTargetHeaders});
 if(headers.length!==cecDepartmentTargetHeaders.length||new Set(headers).size!==headers.length||cecDepartmentTargetHeaders.some(h=>!headers.includes(h))){errors.push({row:1,message:'表头不匹配，请下载最新目标与实际模板'});return result()}
 if(table.length<2||table.length>3001){errors.push({row:1,message:table.length<2?'文件没有数据行':'单次最多导入3000行'});return result()}
 for(let i=1;i<table.length;i++){
  const source=Object.fromEntries(headers.map((h,index)=>[h,String(table[i][index]??'').trim()])),department=cecDepartmentByName(source['责任部门']),year=source['年度'],start=errors.length;
  const fail=message=>errors.push({row:table[i].sourceRow||i+1,message,source});
  if(!department)fail('责任部门不存在');
  if(!/^\d{4}$/.test(year)||!dashboardYears(4).includes(+year))fail('年度超出可配置范围');
  if(table[i].length>headers.length)fail('数据列数多于表头');
  const identity=department?.id+'|'+year;if(seen.has(identity))fail('文件内同一部门、年度重复');seen.add(identity);
  if(errors.length!==start)continue;
  for(let m=1;m<=12;m++){
   const raw=source[m+'月'];if(raw==='')continue;
   let targetCents;try{targetCents=cecAmount(raw,true)}catch(error){fail(m+'月：'+error.message);continue}
   const month=cecMonth(+year,m),before=cecDepartmentTargetCell(department.id,month);
   next.departmentTargets[cecRecordKey(department.id,month)]={targetCents,updatedAt:stamp};
   entries.push({department:department.name,month,targetCents,kind:before.targetCents===null?'新增':'更新',row:table[i].sourceRow||i+1});
  }
 }
 if(!errors.length&&!entries.length)errors.push({row:2,message:'请至少填写一个月的部门目标'});
 return result();
}
// 各部门独立Sheet，目标和细项实际共同校验，全部通过才合并提交。
const cecHeaders=['责任部门','数据类型','降本分类','降本指标','年度',...Array.from({length:12},(_,i)=>(i+1)+'月'),'备注'];
const cecStructuredHeaders=['责任部门','一级类目','二级类目','数据类型','年度','年度目标（元）',...Array.from({length:12},(_,i)=>(i+1)+'月'),'备注'];
function cecTemplate(){
 const sheets=cecCombinedDepartments().map(department=>{
  const {values,total}=cecAnnualDepartmentTarget(department.id);
  const target=[department.name,'','','部门目标',cecState.year,cecInput(total),...values.map(cecInput),''];
  const actual=cecDepartmentCatalog(department.id).flatMap(group=>group.metrics.map(item=>[department.name,group.name,item.metric,'实际降本',cecState.year,'无须填写',...Array(12).fill(''),'']));
  const rows=[target,...actual];
  return {name:department.name,rows,guide:[
   '1. 每个Sheet对应一个部门；蓝底为部门目标，白底为实际降本；金额单位：元。',
   '2. 部门目标行填写年度目标及1—12月目标；年度目标须等于各月合计，不自动分摊。',
   '3. 按预填一级、二级类目填写各月实际；实际降本行的年度目标标注“无须填写”，请保留该提示或留空。空白金额保留原值，0表示零金额。',
   '4. 一次读取全部Sheet；责任部门须与Sheet名一致。'
  ],layout:{widths:[24,24,52,16,12,21,...Array(12).fill(15),28],frozenColumns:6,numericColumns:Array.from({length:13},(_,i)=>i+5),rowHeight:38,rowStyles:rows.map(row=>row[3]==='部门目标'?2:3)}};
 });
 downloadImportTemplate(cecStructuredHeaders,[],'降本目标与实际年度导入模板',{required:['责任部门','数据类型','年度'],conditional:{'一级类目':'实际降本必填','二级类目':'实际降本必填'},sheets});
}
// 新版只调整填写层次；目标仍属于部门，细项仍只维护实际金额。
function cecValidateStructuredImport(table){
 const headers=table[0].map(value=>String(value).trim()),errors=[];
 if(headers.length!==cecStructuredHeaders.length||new Set(headers).size!==headers.length||cecStructuredHeaders.some(h=>!headers.includes(h)))return {errors:[{row:1,message:'表头不匹配，请下载最新模板'}],entries:[],headers:cecStructuredHeaders};
 const sources=table.slice(1).map(cells=>Object.fromEntries(headers.map((h,i)=>[h,String(cells[i]??'').trim()])));
 const normalized=[cecHeaders,...sources.map((source,index)=>{const row=cecHeaders.map(h=>source[h==='降本分类'?'一级类目':h==='降本指标'?'二级类目':h]);row.sourceRow=table[index+1].sourceRow||index+2;return row})];
 const result=cecValidateImport(normalized);
 const sourcesByRow=new Map(table.slice(1).map((row,index)=>[row.sourceRow||index+2,sources[index]]));
 result.errors=result.errors.map(error=>({...error,source:sourcesByRow.get(error.row)||error.source}));
 sources.forEach((source,index)=>{
  const fail=message=>errors.push({row:table[index+1].sourceRow||index+2,message,source}),raw=source['年度目标（元）'];
  if(table[index+1].length>headers.length)fail('数据列数多于表头');
  if(!raw||source['数据类型']==='实际降本'&&raw==='无须填写')return;
  if(source['数据类型']!=='部门目标'){fail('年度目标仅填写在部门目标行');return}
  let annual;try{annual=cecAmount(raw,true)}catch(error){fail('年度目标：'+error.message);return}
  const department=cecDepartmentByName(source['责任部门']);if(!department||result.errors.length)return;
  const values=Array.from({length:12},(_,m)=>result.next?.departmentTargets[cecRecordKey(department.id,cecMonth(Number(source['年度']),m+1))]?.targetCents),known=values.filter(Number.isFinite);
  if(!known.length||known.reduce((sum,value)=>sum+value,0)!==annual)fail('年度目标须等于12个月目标合计，请调整各月目标；不会自动分摊');
 });
 return {...result,errors:[...result.errors,...errors],entries:result.errors.length||errors.length?[]:result.entries,headers:cecStructuredHeaders};
}
function cecTagImport(result,origins,type){
 const origin=row=>origins?.[row-2];
 return {...result,errors:result.errors.map(error=>({...error,...origin(error.row)})),entries:result.entries.map(entry=>({...entry,dataType:type,...(origin(entry.row)?{row:origin(entry.row).row}:{})}))};
}
function cecValidateImport(table){
 if(table.readErrors?.length)return {errors:table.readErrors,entries:[],headers:cecStructuredHeaders};
 const headers=table[0]?.map(value=>String(value).trim())||[];
 if(headers.includes('一级类目'))return cecValidateStructuredImport(table);
 // 旧的独立表仍可读取；下载入口始终给出合并模板。
 if(!headers.includes('数据类型')){
  const actual=headers.includes('降本指标')||headers.includes('年月');
  return cecTagImport(actual?cecValidateActualImport(table):cecValidateDepartmentTargetImport(table),null,actual?'实际降本':'部门目标');
 }
 const errors=[],targets=[cecDepartmentTargetHeaders],actuals=[cecActualHeaders],targetOrigins=[],actualOrigins=[];
 const fail=(row,message,source)=>errors.push({row,message,source});
 if(headers.length!==cecHeaders.length||new Set(headers).size!==headers.length||cecHeaders.some(h=>!headers.includes(h)))return {errors:[{row:1,message:'表头不匹配，请下载目标与实际合并模板'}],entries:[],headers:cecHeaders};
 if(table.length<2||table.length>3001)return {errors:[{row:1,message:table.length<2?'文件没有数据行':'单次最多导入3000行'}],entries:[],headers:cecHeaders};
 for(let i=1;i<table.length;i++){
  const source=Object.fromEntries(headers.map((h,index)=>[h,String(table[i][index]??'').trim()])),row=table[i].sourceRow||i+1;
  if(table[i].length>headers.length)fail(row,'数据列数多于表头',source);
  if(!Array.from({length:12},(_,m)=>source[(m+1)+'月']).some(value=>value!==''))continue;
  if(source['数据类型']==='部门目标'){
   if(source['降本分类']||source['降本指标']||source['备注']){fail(row,'部门目标行不填写分类、指标或备注',source);continue}
   targets.push(cecDepartmentTargetHeaders.map(h=>source[h]));targetOrigins.push({row,source});
  }else if(source['数据类型']==='实际降本'){
   actuals.push(cecActualHeaders.map(h=>source[h]));actualOrigins.push({row,source});
  }else fail(row,'数据类型须为部门目标或实际降本',source);
 }
 if(errors.length)return {errors,entries:[],headers:cecHeaders};
 const empty=()=>({errors:[],entries:[],next:cecCopy(cecStore)});
 const target=targets.length>1?cecTagImport(cecValidateDepartmentTargetImport(targets),targetOrigins,'部门目标'):empty();
 const actual=actuals.length>1?cecTagImport(cecValidateActualImport(actuals),actualOrigins,'实际降本'):empty();
 errors.push(...target.errors,...actual.errors);
 const entries=[...target.entries,...actual.entries].sort((a,b)=>a.row-b.row||a.month.localeCompare(b.month));
 if(!errors.length&&!entries.length)fail(2,'请至少填写一个月的目标或实际金额');
 return {errors,entries:errors.length?[]:entries,next:{...actual.next,departmentTargets:target.next.departmentTargets},headers:cecHeaders};
}
// 多Sheet先合并为统一行集，再复用一次原子校验/保存；错误保留Sheet名和原始行号。
async function cecReadImportFile(file){
 if(!/\.xlsx$/i.test(file.name))return cwReadFile(file);
 if(file.size>5*1024*1024)throw Error('文件不能超过5MB');
 const sheets=await cwReadXlsx(await file.arrayBuffer(),{allSheets:true});
 if(sheets.length===1&&!cecDepartmentByName(sheets[0].name))return uiNormalizeImportHeaders(sheets[0].rows);
 const combined=[[...cecStructuredHeaders]],errors=[];
 for(const sheet of sheets){
  const table=uiNormalizeImportHeaders(sheet.rows),headers=table[0]||[],department=cecDepartmentByName(sheet.name);
  const fail=(row,message)=>errors.push({row:sheet.name+'!'+row,message});
  if(!department)fail(9,'Sheet名称须为责任部门名称');
  const valid=headers.length===cecStructuredHeaders.length&&new Set(headers).size===headers.length&&cecStructuredHeaders.every(name=>headers.includes(name));
  if(!valid)fail(table[0]?.sourceRow||9,'表头不匹配，请下载最新模板');
  for(const original of table.slice(1)){
   const row=valid?cecStructuredHeaders.map(name=>original[headers.indexOf(name)]??''):[...original];
   row.sourceRow=sheet.name+'!'+(original.sourceRow||table.indexOf(original)+1);
   if(row.some(value=>String(value??'').trim())&&department&&valid&&String(row[0]).trim()!==department.name)fail(original.sourceRow,'责任部门须与Sheet名称一致');
   if(original.length>headers.length)fail(original.sourceRow,'数据列数多于表头');
   combined.push(row);
  }
 }
 combined.readErrors=errors;return combined;
}
function cecImportPreview(entries,updates){
 const headers=['处理方式','责任部门','数据类型','降本分类','降本指标','年月','目标金额（元）','实际金额（元）'];
 const rows=entries.slice(0,100).map(entry=>{
  const target=entry.dataType==='部门目标',values=[entry.kind,entry.department,entry.dataType,target?'—':ccCategoryName(entry.category),target?'部门总目标':entry.name,entry.month,target?cecMoney(entry.targetCents):'—',target?'—':cecMoney(entry.actualCents)];
  return '<tr data-preserve-terms>'+values.map((value,index)=>'<td'+(index>=6?' class="cec-number"':'')+'>'+esc(value)+'</td>').join('')+'</tr>';
 }).join('');
 const targets=entries.filter(entry=>entry.dataType==='部门目标').length;
 return `<div class="cec-import-summary"><strong>校验通过</strong><span>目标 ${targets} 条 · 实际 ${entries.length-targets} 条 · 更新 ${updates} 条</span></div><div class="cec-preview-scroll"><table class="cec-table"><thead><tr>${headers.map(label=>'<th>'+label+'</th>').join('')}</tr></thead><tbody>${rows}</tbody></table></div>${updates?'<label class="cec-overwrite"><input type="checkbox" id="cec-overwrite">确认更新以上已有月度数据</label>':''}`;
}
// 与已确认的九部门模板一致；明细保留原字段，汇总只取已确认的总金额列。
const cecDetailSchemas=[
 ['采购部','总降本额（元）',['月份','采购人员','T+供应商名称','产品类目（三级）','产品名称（SPU）','SPU码','产品图片','最新报价执行日期','首次出厂报价（元）','最新出厂报价（元）','出厂价降本额（元）','降本类型','首次品牌费（元）','最新品牌费（元）','品牌费降本额（元）','单台降本额（元）','单台累计降本率','提货量','总降本额（元）','备注'],['产品类目（三级）','产品名称（SPU）','SPU码']],
 ['研发中心','金额（元）',['月份','降本类型','降本明细','金额（元）','备注'],['降本明细']],
 ['产品中心','金额（元）',['月份','降本类型','降本明细','金额（元）','备注'],['降本明细']],
 ['计划部','降本金额（元）',['月份','降本类型','干线供应商','原价（元）','现价（元）','降本金额（元）','备注'],[]],
 ...['发货部','仓储部'].map(name=>[name,'总降本额（元）',['月份','降本类型','T+供应商名称','产品名称（SPU）','SPU码','快递','执行日期','原运费/件（元）','现运费/件（元）','降本单价（元）','发货量/充单量','总降本额（元）','备注（降价区域）'],['产品名称（SPU）','SPU码']]),
 ['品质中心','支持金额（元）',['月份','T+供应商名称','降本类型','事项明细','备注','支持金额（元）','沟通人'],['事项明细']],
 ['用户中心','总节约成本（元）',['月份','降本类型','T+供应商名称/发货仓','产品名称（SPU）','SPU码','总节约成本（元）','备注'],['产品名称（SPU）','SPU码']],
 ['风控中心','实际降本或增收（元）',['月份','降本类型','项目名称','事项负责人','启动日期','计划完成日期','项目状态','基准成本（元）','实际成本或回款（元）','实际降本或增收（元）'],['项目名称']]
].map(([name,amount,headers,required])=>({name,amount,headers,required:['月份','降本类型',amount,...required]}));
const cecTargetFileHeaders=['责任部门','年度','年度目标（元）',...Array.from({length:12},(_,i)=>(i+1)+'月（元）')];
const cecDerivedFields=new Set(['出厂价降本额（元）','品牌费降本额（元）','单台降本额（元）','单台累计降本率','降本单价（元）']);
const cecText=value=>String(value??'').normalize('NFKC').trim();
const cecFileHeader=value=>String(value??'').trim().replace(/^[*＊]\s*/,'').replace(/（(?:YYYY\/MM\/DD|YYYY\/MM|填报目标时必填)）$/,'').replace(/^(\d{1,2})月$/,'$1月（元）');
const cecRawCell=value=>value&&typeof value==='object'&&Object.hasOwn(value,'formula')?'[公式：'+(value.formula||'共享公式')+']':String(value??'');
const cecImportModule=kind=>kind==='target'?'降本目标值':'降本实际值';
function cecDownloadSplitTemplate(kind=cecState.tab){
 const name=kind==='target'?'降本目标值导入模板.xlsx':'降本实际值导入模板.xlsx',link=document.createElement('a');link.href='assets/templates/'+name;link.download=name;document.body.append(link);link.click();link.remove();
}
// 档案来源与模板校验分离；财务结算编码尚未维护时明确报错，不以供应商内部ID代替。
function cecDetailRegistry(){return {products:sampleSpus,categories:new Set(scpCategories.map(row=>cecText(row.name))),suppliers:scpCompanies}}
function cecValidDate(value,allowMonth=false){
 const raw=cecText(value);if(allowMonth&&/^\d{4}\/(0[1-9]|1[0-2])$/.test(raw))return true;
 if(!/^\d{4}\/\d{2}\/\d{2}$/.test(raw))return false;
 const iso=raw.replaceAll('/','-'),date=new Date(iso+'T00:00:00Z');return Number.isFinite(date.getTime())&&date.toISOString().slice(0,10)===iso;
}
function cecValidateDetail(schema,values,registry=cecDetailRegistry()){
 const errors=[],fail=(field,message)=>errors.push({field,message}),get=field=>cecText(values[schema.headers.indexOf(field)]);
 for(const field of schema.required)if(!get(field))fail(field,'必填项为空');
 const month=get('月份');if(month&&!/^\d{4}\/(0[1-9]|1[0-2])$/.test(month))fail('月份','须按YYYY/MM填写有效月份');
 const standard=ccStandardMetrics.find(row=>cecText(row.name)===get('降本类型'));
 if(get('降本类型')&&!standard)fail('降本类型','须填写已有二级类目，一格只填一个');
 for(const field of schema.headers){
  const raw=values[schema.headers.indexOf(field)],value=cecText(raw);if(!value)continue;
  if(raw&&typeof raw==='object'&&Object.hasOwn(raw,'formula')){if(!cecDerivedFields.has(field))fail(field,'请粘贴为值后导入');continue}
  if(/^#(?:REF!|VALUE!|DIV\/0!|N\/A|NAME\?|NUM!|SPILL!|CALC!)/.test(value))fail(field,'存在公式错误，请修正后导入');
  if(field.endsWith('日期')&&!cecValidDate(value,field==='执行日期'))fail(field,field==='执行日期'?'须为有效YYYY/MM或YYYY/MM/DD':'须为有效YYYY/MM/DD日期');
  if(field.endsWith('（元）')&&!cecDerivedFields.has(field)){try{cecAmount(value)}catch(error){fail(field,error.message)}}
  if(['提货量','发货量/充单量'].includes(field)&&!/^\d{1,12}$/.test(value))fail(field,'请填写非负整数数量');
 }
 let product;
 if(schema.headers.includes('SPU码')){
  const matches=registry.products.filter(row=>cecText(row.spuCode)===get('SPU码'));
  if(get('SPU码')&&matches.length!==1)fail('SPU码','须在产品档案中唯一存在，不能填写SKU码');
  product=matches.length===1?matches[0]:null;
  if(product&&cecText(product.name)!==get('产品名称（SPU）'))fail('产品名称（SPU）','须与SPU码对应的产品档案名称一致');
 }
 if(schema.headers.includes('产品类目（三级）')&&get('产品类目（三级）')&&!registry.categories.has(get('产品类目（三级）')))fail('产品类目（三级）','只填写已有三级类目名称，不填完整路径或一、二级类目');
 if(schema.headers.includes('T+供应商名称')&&get('T+供应商名称')){
  const value=get('T+供应商名称'),suppliers=registry.suppliers,code=row=>cecText(row.financialSettlementCode||row['财务结算编码']);
  const matches=suppliers.filter(row=>code(row)&&value===code(row)+'-'+cecText(row.name));
  if(!value.includes('-')||value.startsWith('-')||value.endsWith('-'))fail('T+供应商名称','须按“财务结算编码-供应商名称”填写');
  else if(matches.length!==1||suppliers.filter(row=>code(row)&&code(row)===code(matches[0]||{})).length!==1){
   const missingCode=suppliers.some(row=>!code(row)&&value.endsWith('-'+cecText(row.name)));
   fail('T+供应商名称',missingCode?'现有供应商档案尚未维护财务结算编码，请先补齐':'财务结算编码或供应商名称与现有供应商档案不唯一对应');
  }
 }
 return {errors,standard,product};
}
function cecComputeDetail(schema,values){
 const result=values.map(value=>value&&typeof value==='object'?'':String(value??'').trim()),get=field=>result[schema.headers.indexOf(field)],set=(field,value)=>{const index=schema.headers.indexOf(field);if(index>=0)result[index]=value};
 const difference=(from,to,field)=>{if(get(from)!==''&&get(to)!==''){const cents=cecAmount(get(from))-cecAmount(get(to));set(field,(cents/100).toFixed(2));return cents}set(field,'');return null};
 if(schema.name==='采购部'){
  const factory=difference('首次出厂报价（元）','最新出厂报价（元）','出厂价降本额（元）'),brand=difference('首次品牌费（元）','最新品牌费（元）','品牌费降本额（元）');
  const per=factory===null?null:factory+(brand??0),base=cecAmount(get('首次出厂报价（元）'));
  set('单台降本额（元）',per===null?'':(per/100).toFixed(2));set('单台累计降本率',per!==null&&base?((per/base)*100).toFixed(2)+'%':'');
 }else if(['发货部','仓储部'].includes(schema.name))difference('原运费/件（元）','现运费/件（元）','降本单价（元）');
 return result;
}
// 覆盖范围是文件涉及的月份，横跨所有部门；空白模板Sheet不会清除其他月份。
function cecReplaceActualMonths(entries){
 const next=cecCopy(cecStore),months=new Set(entries.map(row=>row.month));
 next.details=(next.details||[]).filter(row=>!months.has(row.month));
 for(const item of cecMetricCatalog(next))for(const month of months)next.months[cecRecordKey(item.id,month)]={actualCents:null,note:''};
 const totals=new Map();
 for(const row of entries){
  const item=cecResolveMetric(next,row.department,row.type,'',row.category);
  if(!cecMetricCatalog(next).some(metric=>metric.id===item.id))next.metrics[item.id]=cecMetricMetadata(item,'');
  const key=cecRecordKey(item.id,row.month);totals.set(key,(totals.get(key)||0)+row.amountCents);
  next.details.push({id:crypto.randomUUID(),itemId:item.id,month:row.month,amountCents:row.amountCents,productId:row.productId||'',sheet:row.sheet,sourceRow:row.sourceRow,values:row.values});
 }
 for(const [key,actualCents]of totals){if(!Number.isSafeInteger(actualCents))throw Error('月度实际合计超出可精确处理范围');next.months[key]={actualCents,note:''}}
 return {next,coverageMonths:[...months].sort()};
}
// 两个入口只接受各自的模板，全部校验完成后才构造待保存快照。
async function cecReadSplitFile(file,kind){
 if(/\.xlsx$/i.test(file.name))return {kind,sheets:await cwReadXlsx(await file.arrayBuffer(),{allSheets:true,formulaValues:true})};
 if(kind==='target'&&/\.csv$/i.test(file.name)){
  const buffer=await file.arrayBuffer();let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(buffer)}catch(_){text=new TextDecoder('gb18030').decode(buffer)}
  return {kind,sheets:[{name:'部门目标',rows:cwParseCSV(text)}]};
 }
 throw Error(kind==='actual'?'实际值请上传按部门分Sheet的.xlsx文件':'请选择.xlsx或.csv文件');
}
function cecSplitSheet(sheet,expected,errors){
 const at=sheet.rows.findIndex(row=>expected.includes(cecFileHeader(row[0]))),original=sheet.rows[at>=0?at:0]||[],headers=original.map(cecFileHeader);
 const valid=headers.length===expected.length&&new Set(headers).size===headers.length&&expected.every(field=>headers.includes(field));
 if(!valid)errors.push({row:sheet.name+'!'+(original.sourceRow||1),field:'表头',message:'表头不匹配，请使用本Tab的最新模板；不要删改或重复列'});
 const rows=sheet.rows.slice(at>=0?at+1:1).filter(row=>!String(row[0]||'').startsWith('【示例】')).map((row,index)=>({sourceRow:row.sourceRow||index+(at>=0?at:0)+2,raw:row,values:valid?expected.map(field=>row[headers.indexOf(field)]??''):[...row]}));
 return {name:sheet.name,headers,valid,rows};
}
function cecSplitResult(kind,groups,errors,entries,extra={}){
 if(errors.length)for(const group of groups)for(const row of group.rows){const key=group.name+'!'+row.sourceRow;if(!errors.some(error=>String(error.row)===key))errors.push({row:key,message:'同批文件含错误，本行未导入'})}
 const sourceTable=[['所属Sheet','原始行号']];
 for(const group of groups)for(const row of group.rows){const source=[group.name,String(row.sourceRow)];source.sourceRow=group.name+'!'+row.sourceRow;sourceTable.push(source)}
 const failureSheets=[];
 for(const group of groups){
  const byRow=new Map();for(const error of errors)if(String(error.row).startsWith(group.name+'!')){const key=String(error.row).slice(group.name.length+1);if(!byRow.has(key))byRow.set(key,[]);byRow.get(key).push((error.field?error.field+'：':'')+error.message)}
  const rows=group.rows.filter(row=>byRow.has(String(row.sourceRow))).map(row=>({row:row.sourceRow,values:row.raw.map(cecRawCell),reason:[...new Set(byRow.get(String(row.sourceRow)))].join('；')}));
  for(const [row,reasons]of byRow)if(!group.rows.some(value=>String(value.sourceRow)===row)){const reason=[...new Set(reasons)].join('；');if(rows.length)for(const failed of rows)failed.reason=reason+'；'+failed.reason;else rows.push({row,values:[],reason})}
  if(rows.length)failureSheets.push({name:group.name,headers:group.headers,rows});
 }
 const general=errors.filter(error=>!groups.some(group=>String(error.row).startsWith(group.name+'!')));
 if(general.length)failureSheets.push({name:'文件校验',headers:[],rows:general.map(error=>({row:error.row||'—',values:[],reason:error.message}))});
 return {kind,groups,errors,entries,sourceTable,failureSheets,...extra};
}
function cecValidateSplitActual(input){
 const errors=[],groups=[],entries=[],seen=new Set();
 for(const sheet of input.sheets){
  const schema=cecDetailSchemas.find(row=>row.name===sheet.name),expected=schema?.headers||[];
  if(!schema){errors.push({row:sheet.name+'!1',field:'Sheet',message:'Sheet名称须为模板中的责任部门名称'});groups.push({name:sheet.name,headers:sheet.rows[0]||[],rows:[],valid:false});continue}
  if(seen.has(sheet.name))errors.push({row:sheet.name+'!1',message:'部门Sheet重复'});seen.add(sheet.name);
  const group=cecSplitSheet(sheet,expected,errors);groups.push(group);
  // 模板内预置的公式和空行不算业务记录，也不形成覆盖月份。
  group.rows=group.rows.filter(row=>row.values.some((value,i)=>!cecDerivedFields.has(group.valid?expected[i]:group.headers[i])&&cecRawCell(value).trim()));
  if(!group.valid)continue;
  for(const row of group.rows){
   const key=sheet.name+'!'+row.sourceRow,start=errors.length;
   if(row.raw.length>expected.length)errors.push({row:key,field:'数据列',message:'数据列数多于表头'});
   const validation=cecValidateDetail(schema,row.values);errors.push(...validation.errors.map(error=>({...error,row:key})));
   if(errors.length!==start)continue;
   const values=cecComputeDetail(schema,row.values),get=field=>values[expected.indexOf(field)];
   entries.push({department:cecDepartmentByName(sheet.name).id,type:validation.standard.name,category:validation.standard.category,month:cecText(get('月份')).replace('/','-'),amountCents:cecAmount(cecText(get(schema.amount))),productId:validation.product?.spuId||'',sheet:sheet.name,sourceRow:row.sourceRow,values});
  }
 }
 const count=groups.reduce((sum,group)=>sum+group.rows.length,0);
 if(count>3000)errors.push({row:'—',message:'单次最多导入3000条明细，请拆分文件'});
 if(!count&&!errors.length)errors.push({row:'—',message:'没有有效数据行，示例行、空行和预置公式行不导入'});
 return cecSplitResult('actual',groups,errors,entries,errors.length?{}:cecReplaceActualMonths(entries));
}
function cecValidateSplitTarget(input){
 const errors=[],entries=[],groups=[],seen=new Set(),next=cecCopy(cecStore);
 for(const sheet of input.sheets){
  const group=cecSplitSheet(sheet,cecTargetFileHeaders,errors);groups.push(group);
  if(sheet.name!=='部门目标')errors.push({row:sheet.name+'!1',message:'目标值文件只允许“部门目标”Sheet'});
  group.rows=group.rows.filter(row=>(group.valid?row.values.slice(2):row.values).some(value=>cecRawCell(value).trim()));
  if(!group.valid)continue;
  for(const row of group.rows){
   const key=sheet.name+'!'+row.sourceRow,start=errors.length,values=row.values.map(cecText),department=cecDepartmentByName(values[0]),year=values[1],amounts=[];
   const fail=(field,message)=>errors.push({row:key,field,message});
   if(!department)fail('责任部门','部门不存在或未填写');
   if(!/^\d{4}$/.test(year)||!dashboardYears(4).includes(+year))fail('年度','年度超出可配置范围');
   if(row.raw.length>cecTargetFileHeaders.length)fail('数据列','数据列数多于表头');
   for(let i=2;i<15;i++){try{const cents=cecAmount(values[i],true);if(cents===null)fail(cecTargetFileHeaders[i],'必填，明确为零请填0');amounts.push(cents)}catch(error){fail(cecTargetFileHeaders[i],error.message)}}
   if(errors.length!==start)continue;
   if(amounts[0]!==amounts.slice(1).reduce((sum,value)=>sum+value,0))fail('年度目标（元）','须等于12个月目标合计，不自动分摊');
   const identity=department.id+'|'+year;if(seen.has(identity))fail('责任部门','同一部门同一年度重复');seen.add(identity);
   if(errors.length!==start)continue;
   amounts.slice(1).forEach((targetCents,i)=>next.departmentTargets[cecRecordKey(department.id,cecMonth(year,i+1))]={targetCents});entries.push({department:department.id,year});
  }
 }
 const count=groups.reduce((sum,group)=>sum+group.rows.length,0);
 if(count>3000)errors.push({row:'—',message:'单次最多导入3000行'});
 if(!count&&!errors.length)errors.push({row:'—',message:'没有填写目标值，示例行和空白目标行不导入'});
 return cecSplitResult('target',groups,errors,entries,{next});
}
const cecSplitHistoryMeta=batch=>({module:cecImportModule(batch.kind),failureSheets:batch.failureSheets,coverageMonths:batch.coverageMonths});
const cecRoute='#system-cost-efficiency';
const cecOptions=(values,current)=>values.map(([value,label])=>`<option value="${esc(String(value))}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`).join('');
const cecYears=()=>dashboardYears(4).map(y=>[y,y+'年']);
function cecPageSize(){return listPageSize('cec-pagination')}
