// 导出复用列表的字段及完整筛选结果，不按分页截取，不修改关系或导入记录。
function ssiExportValue(key,row){
 if(key==='updatedAt'){
  const time=Date.parse(row[key]);
  return Number.isFinite(time)?new Date(time).toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).replaceAll('-','/'):'';
 }
 const value=row[key]??'';
 return ['admitted','cooperation'].includes(key)?String(value).replaceAll('-','/'):String(value);
}
function ssiExport(){
 const tier=ssiState.tier,rows=ssiRows();
 if(!rows.length){toast('当前筛选下暂无可导出数据');return}
 try{
  const fields=ssiListFields(tier),headers=fields.map(([,label])=>label),data=rows.map(row=>fields.map(([key])=>ssiExportValue(key,row))),label=ssiTierLabels[tier];
  const layout={widths:fields.map(([key])=>key==='name'?34:key.toLowerCase().includes('category')?44:key==='productName'?46:key==='productCode'?34:key==='updatedAt'?25:20),rowHeight:42};
  downloadImportTemplate(headers,data,label+'_'+(ssiViewState().year==='all'?'全部年份':ssiViewState().year+'年')+'_'+dashboardToday(),{sheets:[{name:label,headers,rows:data,layout}]});
  toast('已导出'+rows.length+'条记录');
 }catch(_){toast('导出失败，请重试')}
}
// 选文件时只解析年份；确认导入才写入，替换文件或关闭后丢弃旧解析结果。
function ssiBindAnnualImport(dialog,tier){
 const input=$('#ssi-file'),button=$('#ssi-confirm'),note=dialog.querySelector('.ssi-import-coverage');let prepared=null,generation=0;
 uiBindImportFlow({dialog,input,button,
  read:file=>prepared?.file===file?prepared.table:ssiReadFile(file,tier),
  parse:table=>prepared?.file===input.files[0]?prepared.batch:ssiParseImport(table,tier),commit:ssiCommit,
  historyMeta:batch=>({coverageYears:batch.years||[]}),
  done:()=>{dialog.close();ssiRenderPage()}
 });
 input.addEventListener('change',async()=>{
  const ticket=++generation,file=input.files[0];prepared=null;note.textContent=ssiImportCoverageText(tier);if(!file)return;
  button.disabled=true;
  try{
   const config=uiUploadOptions(input);if(file.size>config.limit)throw Error('文件不能超过5MB');if(!uiUploadAccepts(input,file))throw Error('请选择 .xlsx 或 .csv 文件');
   const table=await ssiReadFile(file,tier),batch=ssiParseImport(table,tier);
   if(ticket!==generation||!dialog.open||input.files[0]!==file)return;
   prepared={file,table,batch};note.textContent=batch.errors.length?'文件校验未通过，尚未执行覆盖；确认导入后可查看失败明细。':ssiImportCoverageText(tier,batch.years);
  }catch(error){if(ticket===generation&&dialog.open)note.textContent=error.message+'；尚未执行覆盖。'}
  finally{if(ticket===generation&&dialog.open&&input.files[0]===file)button.disabled=false}
 });
 dialog.addEventListener('close',()=>{generation++;prepared=null},{once:true});
}
// 工作聚焦偏差类型字典；日志按状态筛选，其余业务分类由各自Tab负责。
const gdIssueTypes={
 'focus-direction':{label:'工作方向疑似偏离',scope:'execution/focus'},
 'focus-risk-response':{label:'重大风险响应不足',scope:'execution/focus'},
 'focus-interruption':{label:'重点工作推进中断',scope:'execution/focus'},
};
function gdWithIssueType(row){
 let type=row.issueType;
 if(!gdIssueTypes[type])throw new Error('事项未配置诊断类型：'+row.id);
 return {...row,issueType:type};
}
function gdIssueTypeOptions(part=gdState.part,tab=gdState.tabs[part]){const scope=part==='execution'?part+'/'+tab:part;return Object.entries(gdIssueTypes).filter(([,type])=>type.scope===scope)}

// 状态筛选使用现有状态码，日志与待办分别定义，避免新增办理状态。
const gdLogStatuses={missing:'未抓取到',incomplete:'内容待补齐',late:'逾期补交'};
function gdStatusValue(row){return row.task?.status||'suggested'}
function gdStatusOptions(part=gdState.part,tab=gdState.tabs[part]){
 return Object.entries(upTodoStatuses).filter(([key])=>key!=='suggested');
}

// 原因取自抓取记录与已有聚焦证据，只补充展示，不改写任务或作出失职结论。
function gdDiagnosisReasons(row){
 const stamp=value=>value?String(value).replace('T',' ').slice(0,19):'—';
 if(row.kind==='report'){
  const reasons=[],log=`${row.logOwner||row.owner} · ${row.type} · ${row.date}`;
  if(row.missing)return [{key:'log-missing',label:'未匹配到日志',basis:`${log}；应交时间 ${stamp(row.deadline)}。截至 ${stamp(row.capturedAt)} 抓取未匹配，需核实是否已提交或尚未同步。`}];
  if(row.incomplete){
   const fields=[['progress','工作进展'],['reportProblem','当前问题'],['next','下一步安排']];
   for(const [key,label] of fields)if(!String(row[key]||'').trim())reasons.push({key:'log-empty-'+key,label:label+'未填写',basis:`${log}；已抓取到日志，但“${label}”为空，需补齐后复核。`});
  }
  if(row.late)reasons.push({key:'log-late',label:'日志晚交',basis:`${log}；应交 ${stamp(row.deadline)}，实际提交 ${stamp(row.submitted)}。`});
  return reasons;
 }
 const evidence=row.kind==='focus'?row.focusEvidence:null;if(!evidence)return [];
 const owner=evidence.meeting.owner,range=evidence.window,logs=evidence.logs||[];
 const own=logs.filter(log=>log.owner===owner&&log.date>=range.start&&log.date<=range.end),prior=logs.filter(log=>log.owner===owner&&log.date<range.start),peers=logs.filter(log=>log.owner!==owner&&log.date>=range.start&&log.date<=range.end);
 const window=`${range.start}—${range.end}，${owner}的${own.length}条已抓取日志`;
 const decision=String(evidence.meeting.decision||'').replace(/[。；;\s]+$/,''),risk=String(evidence.risk?.text||'关联业务预警仍存在').replace(/[。；;\s]+$/,'');
 const types={
  'focus-direction':{label:'重点动作未见记录',basis:`${evidence.meeting.date}会议分工：${decision}。${window}未见相关动作；同期有${peers.length}条协作记录涉及该重点，需核实实际推进情况。`},
  'focus-risk-response':{label:'风险复核未见记录',basis:`${risk}。${window}未见该产品复核或整改验证记录，需核实是否已开展但未记录。`},
  'focus-interruption':{label:'后续推进未见记录',basis:`${evidence.meeting.date}会议分工：${decision}。前期已有${prior.length}条推进记录；${window}未见后续推进，需核实是否中断或未记录。`}
 };
 return types[row.issueType]?[{key:row.issueType,...types[row.issueType]}]:[];
}
// 总诊断持有独立筛选；业务事实读取各模块当前口径，不改动模块筛选。
const gdParts=[['coordination','重点工作清单'],['resource','工作偏差预警'],['execution','日周报诊断'],['tasks','任务清单']];
const gdTabs={coordination:[['project','项目卡点'],['high-risk','新增高危']],resource:[['omission','工作遗漏'],['blocker','协同卡点'],['solution','缺少方案'],['focus-shift','资源错配']],execution:[['quality','问题诊断'],['missing','日报未提交']],tasks:[]};
// 提示只解释现有诊断口径，不新增判定阈值。
const gdDeviationStandards={
 omission:'• 业务存在风险或待处理事项。\n• 已收集的会议、日周月报中未见对应工作安排。\n• 仅表示现有材料未发现，不代表实际未开展。',
 blocker:'• 上游所需的资料、确认或交付尚未完成，导致下游工作无法继续推进。\n• 从业务事项中直接识别需要跨部门共同推进或衔接的工作，明确协同部门及各方配合内容。',
 'focus-shift':'• 会议或计划已明确工作分工与优先要求，但同期实际工作记录与既定重点或先后顺序不一致。\n• 排除已批准的优先级调整和专项分工；仅未提及某项工作不直接判定偏移。',
 solution:'• 需要解决的问题已明确，但尚未形成可执行方案。\n• 方案需包含关键条件、实施安排及确认结论。'
};
const gdDayRange={start:shiftDate(DATA_CUTOFF,-29),end:DATA_CUTOFF};
const gdState={part:'coordination',tabs:{execution:'quality',coordination:'project',resource:'omission',tasks:'all'},period:drawerPeriodFromRange(gdDayRange),taskPeriod:null,taskDueRange:{start:'',end:''},filters:{},pages:{}};
function gdRange(){return uiNaturalPeriodRange(gdState.period,DATA_CUTOFF)}
// 期间只控制总诊断；日区间单独记忆，切换自然周期不覆盖其他九模块。
function gdApplyPeriod(period){
 if(gdState.part==='tasks')return gdApplyTaskPeriod(period);
 const range=uiNaturalPeriodRange(period,DATA_CUTOFF);
 if(!range||range.end<aiCoverageStart)return false;
 upCalendarClose?.(false);gdState.period={...period};
 if(period.mode==='day')Object.assign(gdDayRange,range);
 gdRefreshFilters(true);return true;
}
function gdChangePeriod(field,value){
 if(field==='mode'&&value==='day')return gdApplyPeriod(drawerPeriodFromRange(gdState.part==='tasks'?gdTaskDayRange:gdDayRange));
 const prior=gdState.part==='tasks'?gdTaskCurrentPeriod():gdState.period,range=uiNaturalPeriodRange(prior,DATA_CUTOFF),next={...prior};
 if(field==='mode'){
  if(!['month','quarter','year'].includes(value))return false;
  const month=prior.mode==='day'?+range.end.slice(5,7):prior.mode==='month'?prior.value:prior.mode==='quarter'?prior.value*3:12;
  Object.assign(next,{mode:value,value:value==='month'?month:value==='quarter'?Math.ceil(month/3):1});
 }else next[field]=Number(value);
 normalizePeriod(next);const selected=uiNaturalPeriodRange(next,DATA_CUTOFF);
 if(selected?.end<aiCoverageStart&&next.year===+aiCoverageStart.slice(0,4))next.value=next.mode==='month'?+aiCoverageStart.slice(5,7):next.mode==='quarter'?Math.ceil(+aiCoverageStart.slice(5,7)/3):1;
 return gdApplyPeriod(next);
}
