 if(next)return {kind:next.missing?(next.latestSubmittedAt?'resolved':'active'):'active',complete:true,evidence:(next.sources||[]).map(s=>s.id),reason:next.latestSubmittedAt?'原日报已补交':'本轮仍有对应诊断依据'};
