// 遗漏按不同风险选例；业务余额是事实，未见工作提及仅限本次扫描材料。
function gdOmissionSamples(context,records){
 const mentioned=new Set(records.map(r=>r.objectKey));
 const candidates=context.by('inventory').rows.filter(r=>upSpus.has(r.spuId)&&!mentioned.has('product|'+r.spuId));
 const stale=candidates.filter(r=>r.staleValueCents>0).sort((a,b)=>b.staleValueCents-a.staleValueCents)[0];
 const inspection=candidates.filter(r=>r.factoryInspection>0&&r.spuId!==stale?.spuId).sort((a,b)=>b.factoryInspection-a.factoryInspection)[0];
 const previousActions=['核实库存处置是否已有安排，补齐处置数量、工厂承接方式及完成日期。','确认库存产品的渠道去化安排，反馈可售范围与处置计划。'];
 return [[stale,'clearance'],[inspection,'inspection']].flatMap(([r,kind])=>{
  if(!r)return [];
  const product=upProduct(upSpus.get(r.spuId)),isStale=kind==='clearance',start=shiftDate(DATA_CUTOFF,-3);
  const risk=isStale?'呆滞库存金额：'+gdMoney(r.staleValueCents):'工厂待检库存：'+fmt(r.factoryInspection)+'件';
  return [{id:'work-omission-'+r.spuId,kind:'omission',department:'采购部',priority:'P2',
   object:{key:'product|'+r.spuId,name:product.name,type:'product',spuId:r.spuId},
   title:isStale?'核实呆滞品清仓去化安排':'核实待检库存验货与放行安排',
   problem:isStale?`呆滞库存金额达 ${gdMoney(r.staleValueCents)}，已收集的会议及日周月报中未见积压库存的销售或退厂处理安排，资金占用可能继续延长。`:
    `工厂有 ${fmt(r.factoryInspection)} 件待检库存，已收集材料中未见验货及放行事项；这批货尚未转为可售，渠道补货可用量无法确认。`,
   summary:isStale?'核实清仓去化覆盖':'核实验货放行覆盖',samplePreviousActions:previousActions,
   problemSource:{sourceId:'coverage-'+kind,quote:'按业务对象匹配，未找到该产品的工作提及。'},
   rolePlans:isStale?[
    ['唐琪','核实呆滞品退厂、返工或清仓承接条件，记录数量及处置日期。','已关联现有处置记录；无记录时已确认承接方式、数量和日期。'],
    ['林悦','核实尾货适销渠道与清仓节奏，反馈价格底线和去化安排。','渠道范围、价格底线及去化节点已确认。']
   ]:[
    ['唐琪','核实工厂待检批次和验货安排，协调品质反馈放行条件及日期。','已关联验货记录，待检批次、放行条件及日期已核实。'],
    ['林悦','将待检批次与渠道补货计划对照，核实放行前后的可承诺数量。','已记录待检货与可售货的区分及渠道补货承诺。']
   ],
   sources:[{id:'stock-risk-'+kind,date:DATA_CUTOFF,source:'库存管控\n'+product.name+'\n'+DATA_CUTOFF,content:risk},
    {id:'coverage-'+kind,date:DATA_CUTOFF,source:'来源扫描清单\n'+start+' — '+DATA_CUTOFF,content:`已收集 ${records.length} 条会议及日周月报记录；按业务对象匹配，未找到该产品的工作提及。`}],
   coverage:{checked:records.length,mentions:0,start,end:DATA_CUTOFF}}];
 });
}
// 当前只诊断明确重点与实际工作的方向偏移，不判断资源投入数量。
function gdResourceCategory(comparison){
 const c=comparison;
 if(!c?.scope||!c.start||!c.end||c.start>c.end||!c.priorityConfirmed||c.priorityChanged||c.approvedSpecialty)return null;
 return c.direction==='deviated'?'deviation':null;
}
function gdResourceSamples(objects,baseline){
 const {expected,diverted,qualityExpected,qualityDiverted}=baseline,day=n=>shiftDate(DATA_CUTOFF,n);
 const comparison=scope=>({scope,start:day(-3),end:DATA_CUTOFF,direction:'deviated',priorityConfirmed:true,priorityChanged:false,approvedSpecialty:false});
 const rows=[
  {id:'resource-mismatch-acceptance',object:objects.project,department:'产品中心',priority:'P1',title:'验收确认工作偏离既定分工',problemSource:{sourceId:'focus-observed-2',quote:'继续整理历史宣传素材，未记录验收口径确认进展'},problem:'验收口径确认已有明确分工，周铭连续两天仍在整理已后移的历史素材，相关验收工作未见进展记录，验收确认可能延迟。',suggestion:'先核实验收口径确认的实际进展，暂停已后移的素材整理，明确验收确认时间并反馈项目部。',people:['周铭'],sources:[expected,...diverted],relatedWork:'work-core-delivery',comparison:comparison('本周样机验收口径确认与素材整理分工')},
  {id:'resource-mismatch-returns',object:objects.product,department:'产品中心',priority:'P2',title:'退货原因分析投入偏移',problemSource:{sourceId:'quality-observed',quote:'退货原因分类工作尚未开始'},problem:'退货原因分类尚未开始，许宁本周主要投入已同意后移的常规包装图审核，品质整改所需的原因分析可能延迟。',suggestion:'按原分工优先完成退货原因分类并回传品质，常规包装图审核按已确认的后移安排执行。',people:['许宁'],sources:[qualityExpected,...qualityDiverted],comparison:comparison('本周退货原因分类与常规包装图审核分工')},
 ];
 return rows.map(row=>{
  const resourceType=gdResourceCategory(row.comparison);
  if(!resourceType)throw new Error('资源样例缺少可比依据：'+row.id);
  return {...row,kind:'mismatch',resourceType};
 });
}

// 迁移已具名的分工/观察对照；至少包含明确要求和实际工作两侧证据。
function gdFocusDeviationRows(rows,range){
 return rows.filter(row=>gdResourceCategory(row.comparison)&&row.sources.some(s=>s.type==='会议纪要')&&row.sources.some(s=>s.type!=='会议纪要')&&row.sources.some(s=>s.date>=range.start&&s.date<=range.end)).map(row=>{
  const participants=row.people.map(assignee=>({assignee,department:row.department||upTodoPersonDepartment(assignee),action:row.suggestion}));
  return {...row,kind:'focus-shift',participants,departments:[...new Set(participants.map(p=>p.department))],businessObjects:[{...row.object,id:String(row.object.spuId??row.object.projectId??row.object.key)}]};
 });
}
// 主动协同演示：来源仅记录准备工作，协同建议不等同于已发生阻塞或自动下发任务。
function gdCoordinationSamples(objects,record){
 const material=[
  record('coord-material-engineering',objects.product,'王磊','替代物料验证','替代料规格已整理，拟安排替代料小批验证，准备试装及性能验证项目。'),
  record('coord-material-purchase',objects.product,'唐琪','替代物料试样','已取得替代料试样报价，准备确认试样数量和交样日期。'),
  record('coord-material-quality',objects.product,'刘畅','替代物料检验','准备按现行物料的检验要求整理替代料验证项目，记录检验结论。')
 ];
 const support=[
  record('coord-support-product',objects.launch,'林悦','新品使用说明','正在整理新品使用说明初稿和常见问题，准备汇总对外说明内容。'),
  record('coord-support-engineering',objects.launch,'王磊','新品技术说明','正在整理新品技术参数及使用边界，准备提供使用说明中的技术内容。'),
  record('coord-support-quality',objects.launch,'刘畅','新品试用反馈','正在整理试用反馈中的使用注意事项和故障排查要点，准备形成参考内容。')
 ];
 return [
  {id:'work-coordination-material-trial',kind:'blocker',coordinationType:'proactive',object:objects.product,department:'研发中心',priority:'P2',
   title:'衔接替代物料小批验证',summary:'对齐替代物料验证安排',
   problem:'研发准备小批验证，采购准备试样，品质整理检验项目。根据三方准备工作，识别出采购交样、研发试装与品质检验需要衔接，建议提前对齐样品版本、验证项目及交接节点。',
   problemSource:{sourceId:'coord-material-engineering',quote:'拟安排替代料小批验证'},sources:material,
   rolePlans:[
    ['王磊','与采购、品质对齐替代料规格和样品版本，确认试装及性能验证项目。','已对齐样品版本和验证项目。'],
    ['唐琪','按研发、品质的样品要求确认试样数量与交样日期，反馈试用批次。','已反馈试样数量、交样日期和试用批次。'],
    ['刘畅','与研发确认检验要求及判定标准，约定验证结论回传节点。','已确认检验要求、判定标准和结论回传节点。']
   ]},
  {id:'work-coordination-launch-support',kind:'blocker',coordinationType:'proactive',object:objects.launch,department:'产品中心',priority:'P2',
   title:'对齐新品使用说明与售后口径',summary:'衔接新品说明与售后口径',
   problem:'产品、研发、品质分别准备使用说明、技术内容和试用反馈。三份内容将用于同一新品的对外说明与问题答复，建议跨部门共同核对使用边界、注意事项和排查步骤，并统一说明版本。',
   problemSource:{sourceId:'coord-support-product',quote:'正在整理新品使用说明初稿和常见问题'},sources:support,
   rolePlans:[
    ['林悦','汇总研发、品质的确认内容，统一使用说明与常见问题答复版本。','已形成各方确认的使用说明与答复版本。'],
    ['王磊','核对技术参数及使用边界，与产品中心确认说明中的技术表述。','已确认技术参数、使用边界及对应表述。'],
    ['刘畅','核对试用注意事项及故障排查步骤，与产品中心对齐问题答复口径。','已确认注意事项、排查步骤和问题答复口径。']
   ]}
 ];
}
// 演示来源以记录为单位组织；重点工作关联任务，其余资源与报告分析保持只读。
function gdAnalysisSamples(context){
 const {project,product,newProduct,supplier}=context,day=n=>shiftDate(DATA_CUTOFF,n),projectCore=gdCoreCriterion(project),productCore=gdCoreCriterion(product);
 const object=(key,name,type='product',extra={})=>({key,name,type,...extra});
 const objects={
  project:object('project|'+project.id,project.name,'project',{projectId:project.id}),
  product:object('product|'+product.spuId,product.name,'product',{spuId:product.spuId}),
  launch:object('product|'+newProduct.spuId,newProduct.name,'product',{spuId:newProduct.spuId}),
  supplier:object('admission|'+supplier.project.id,supplier.project.name,'project',{projectId:supplier.project.id})
 };
 const records=[],record=(id,obj,owner,topic,content,offset=-1,type='日报')=>{
  const department=upTodoPersonDepartment(owner),date=day(offset),entry={id,objectKey:obj.key,objectName:obj.name,objectType:obj.type,owner,department,topic,date,type,
   source:type==='会议纪要'?`钉钉文档 Excel\n产品链协同会议纪要.xlsx\n10月例会 · 第${records.length+8}行\n${date}`:`钉钉${type}\n${owner} · ${department}\n${date}`,content};
  records.push(entry);return entry;
 };
 const pricing=[record('price-purchase',objects.product,'唐琪','报价降本','已向工厂提交电机与外壳分项议价清单，正在核对阶梯报价和生效批次。'),record('price-engineering',objects.product,'王磊','报价降本','已核对电机替代规格及结构成本，输出两种物料组合的成本差异。'),record('price-product',objects.product,'周铭','报价降本','已汇总渠道毛利缺口，复核议价后的利润改善测算。')];
 const quality=[record('quality-review',objects.product,'刘畅','退货品质复核','抽取退货样机复现吸力衰减，记录电机温升与滤网堵塞情况。'),record('quality-user',objects.product,'林悦','退货品质复核','已整理售后问题分布，向品质反馈吸力衰减和噪音投诉样本。')];
 const delivery=[record('delivery-project',objects.project,'沈舟','样机交付','已汇总样机清单和未闭环节点，协调工厂反馈分批到货时间；样机交付与检测排期尚未统一，最终交付节点仍待确认。',-2),record('delivery-purchase',objects.project,'唐琪','物料齐套','核对缺料表与采购在途，已取得工厂对关键电机到料日期的书面反馈。'),record('delivery-quality',objects.project,'刘畅','检测验收','核对安规和性能测试清单，预留样机复测窗口。'),record('delivery-product',objects.project,'林悦','样机交付','核对首发验收口径与样机数量，整理渠道验收清单。')];
 const launch=[record('launch-plan',objects.launch,'林悦','首发批次方案','已收集全渠道首发与小范围试销的备货条件，首发批次方案尚未形成。'),record('launch-capacity',objects.launch,'唐琪','首发批次方案','工厂已反馈最小起订量与分批交货周期；两种首发方案尚未完成成本对比。'),record('launch-channel',objects.launch,'陈嘉','渠道准备','核对首发渠道铺货清单与详情素材，等待最终上市批次确认。')];
 const admission=record('admission-meeting',objects.supplier,'唐琪','供方准入','采购已收到候选供方样品，品质需先确认检测标准才能发样；检测结论又是准入评审的前置条件。',-2,'会议纪要');
 const packageMeeting=record('package-meeting',objects.launch,'陈嘉','包装定版','研发已提交结构尺寸，包装刀模仍待产品中心确认卖点文案；采购需等刀模定版才能安排包材打样。',-2,'会议纪要');
 const solution=record('solution-meeting',objects.project,'沈舟','外部检测方案','内部可靠性设备本月排满，会上提出外部检测；尚未形成含机构资质、检测费用、报告周期的可执行方案。',-2,'会议纪要');
 const expected=record('focus-required',objects.project,'周铭','样机验收分工','本周周铭应完成样机验收口径确认，作为渠道验收的前置工作；不安排历史宣传素材整理。',-3,'会议纪要');
 const archived=object('business|historical-material','历史产品宣传素材','');
 const diverted=[record('focus-observed-1',archived,'周铭','历史素材归档','当天工作为整理历史产品宣传页，更新素材目录。',-2),record('focus-observed-2',archived,'周铭','历史素材归档','继续整理历史宣传素材，未记录验收口径确认进展。',-1)];
 const qualityExpected=record('quality-required',objects.product,'许宁','售后原因分析分工','许宁本周负责汇总退货原因并回传品质；常规包装图审核已同意后移。',-3,'会议纪要');
 const qualityDiverted=[record('quality-observed',objects.product,'许宁','常规包装图审核','本周主要审核常规包装图，退货原因分类工作尚未开始。',-1,'周报')];
 const extraCore=gdExtraCoreSamples(context,records);
 const omissions=gdOmissionSamples(context,records);
 const priorities=gdPrioritySamples(context,records);
 const coordination=gdCoordinationSamples(objects,record);
 const work=[
  ...(projectCore?[{id:'work-core-delivery',problemSource:{sourceId:'delivery-project',quote:'样机交付与检测排期尚未统一'},kind:'core',object:objects.project,department:'项目部',priority:'P1',title:'保障关键项目样机交付',problem:`样机交付与检测节点仍未对齐；虽已整理样机清单、跟进到料并预留复测窗口，统一交期仍未确定。项目已延期 ${project.delay} 天，验收和上市可能继续后移。`,summary:'锁定样机交付节点',coreHit:projectCore.description,sources:[{id:'project-delay-fact',date:DATA_CUTOFF,source:'项目进度\n'+project.name+'\n'+DATA_CUTOFF,content:'项目状态：'+project.projectState+'\n预警：'+project.status+'\n延期：'+project.delay+'天'},...delivery]}]:[]),
  ...(productCore?[{id:'work-core-margin',problemSource:{sourceId:'price-purchase',quote:'正在核对阶梯报价和生效批次'},kind:'core',object:objects.product,department:'采购部',priority:'P1',title:'跟工厂协商降本',problem:`当前利润率为 ${gdPercent(product.profit)}；已提交议价清单并比较物料成本，阶梯报价及生效批次仍在核对，继续按现有盈利水平销售会扩大亏损。`,summary:'跟工厂协商降本',coreHit:productCore.description,sources:[{id:'product-profit-fact',date:DATA_CUTOFF,source:'关键产品\n'+product.name+'\n'+DATA_CUTOFF,content:'产品分级：'+product.level+'\n当前利润率：'+gdPercent(product.profit)},...pricing]}]:[]),
  ...extraCore,...priorities.core,...omissions,
  {id:'work-block-admission',problemSource:{sourceId:'admission-meeting',quote:'品质需先确认检测标准才能发样'},departments:["采购部","品质中心"],kind:'blocker',coordinationType:'blocked',object:objects.supplier,department:'采购部',priority:'P1',title:'打通样品检测与准入评审',problem:'样品检测标准尚未确认。采购虽已收到候选供方样品，仍无法安排发样，后续准入评审被检测环节阻塞。',summary:'对齐样品检测标准',sources:[admission],dependencies:['品质确认检测标准','采购安排发样','品质出具结论','采购组织准入评审']},
  {id:'work-block-package',problemSource:{sourceId:'package-meeting',quote:'包装刀模仍待产品中心确认卖点文案'},departments:["产品中心","研发中心","采购部"],kind:'blocker',coordinationType:'blocked',object:objects.launch,department:'产品中心',priority:'P2',title:'打通包装定版与包材打样',problem:'包装卖点文案尚未确认；研发已提交结构尺寸，刀模仍无法定版，采购包材打样排期受阻。',summary:'确认包装定版',sources:[packageMeeting],dependencies:['产品确认卖点文案','研发冻结包装刀模','采购启动包材打样']},
  ...coordination,
  {id:'work-solution-launch',problemSource:{sourceId:'launch-capacity',quote:'两种首发方案尚未完成成本对比'},departments:["产品中心","采购部"],kind:'solution',object:objects.launch,department:'产品中心',priority:'P1',title:'形成新品首发批次方案',problem:'首发批次的成本与供货条件尚未完成对比。两种首发方式的备货条件、工厂起订量及交期已收集，统一方案仍未形成，上市备货与渠道排期难以锁定。',summary:'形成首发批次方案',sources:launch.slice(0,2),gaps:['首批数量与渠道范围','两种方案的成本比较','方案结论与确认日期']},
  {id:'work-solution-test',problemSource:{sourceId:'solution-meeting',quote:'尚未形成含机构资质、检测费用、报告周期的可执行方案'},departments:["项目部","品质中心","采购部"],kind:'solution',object:objects.project,department:'品质中心',priority:'P2',title:'形成外部检测方案',problem:'内部可靠性设备本月排满；会上已提出外部检测，但尚未形成包含机构资质、费用及报告周期的可执行方案，可靠性验证仍无法排期。',summary:'形成外部检测方案',sources:[solution],gaps:['检测机构与资质','报价及费用承担','报告交付日期']}
 ];
 const mismatches=gdResourceSamples(objects,{expected,diverted,qualityExpected,qualityDiverted});
 // 当前演示批次统一抓取于截止日；原date保留日报、会议等业务日期。
 for(const source of new Set([...records,...work.flatMap(row=>row.sources),...mismatches.flatMap(row=>row.sources)])){source.capturedDate=DATA_CUTOFF;Object.assign(source,diagnosisNormalizeSource(source))}
 return {objects,records,work,mismatches,taskSamples:priorities.routine,focusRecords:[...pricing,...quality,...delivery,...launch,...diverted,...qualityDiverted]};
}
// 报告原文为演示材料；每个有问题的报告使用独立案例，原文按六个诊断维度组织。
const gdReportIssueSamples={
 '产品中心/日报':{key:'result',excerpt:'已备货 320 台，试销达成良好，暂未汇总实际签收量。',problem:'把备货量当作试销成果，尚未提供实际签收量及目标差额，销售达成判断缺少依据。',deductions:[
  {ruleId:'actual',problem:'把备货量当作试销成果，未提供实际签收量。'},
  {ruleId:'comparison',problem:'未提供销售目标与实际成果的差额。'}]},
 '产品中心/周报':{key:'risk',excerpt:'首发渠道已确定，促销价保及退差价成本暂不纳入本周风险说明。',problem:'促销价保和退差价被排除在风险说明之外，渠道活动对实际毛利的影响无法评估。',deductions:[
  {ruleId:'scope',problem:'遗漏促销价保及退差价成本风险，无法评估实际毛利影响。'}]},
 '项目部/周报':{key:'risk',excerpt:'各环节继续按原排期推进，物料到货视为已确认，采购回传条件暂略。',problem:'将关键物料到货视为已确认，未披露采购回传的前置依赖及对验收的影响，周排期的可执行性无法核对。',deductions:[
  {ruleId:'dependencies',problem:'采购回传的前置依赖未披露，将待确认的到货条件视为已确认。'}]},
 '品质中心/日报':{key:'result',excerpt:'已发现滤网堵塞，同时认为电机衰减也是原因，尚未开展电机对照试验。',problem:'已验证的滤网堵塞与未经验证的电机衰减被并列为故障原因，整改对象可能被误判。',deductions:[
  {ruleId:'verification',problem:'未经电机对照试验，将电机衰减与已验证的滤网堵塞并列为故障原因。'}]},
 '品质中心/周报':{key:'risk',excerpt:'整改复测已通过，报告未说明复测抽样台数、通过数及失败样本编号。',problem:'复测只写“通过”，未说明样本量、通过数和失败样本，品质放行结论无法复核。',deductions:[
  {ruleId:'sample-size',problem:'复测结论未说明抽样台数。'},
  {ruleId:'pass-count',problem:'复测结论未说明通过数。'},
  {ruleId:'failed-samples',problem:'复测结论未说明失败样本编号。'}]},
 '研发中心/日报':{key:'result',excerpt:'替代电机预计单台节约 2 元，测算暂未纳入工装改造及旧料切换费用。',problem:'降本测算仅比较器件单价，遗漏工装及旧料切换费用，方案净收益可能被高估。',deductions:[
  {ruleId:'total-cost',problem:'切换成本口径不完整，遗漏工装改造及旧料切换费用。'}]},
 '研发中心/周报':{key:'object',excerpt:'业务对象仅填写“该款产品”，未写产品全称、型号或项目编号。',problem:'工作条目只用“该款产品”代指业务对象，无法将温升验证和BOM变更准确关联到具体产品。',deductions:[
  {ruleId:'identity',problem:'仅用“该款产品”代称，缺少产品全称、型号或项目编号，无法明确识别业务对象。'}]},
 '采购部/日报':{key:'result',excerpt:'工厂回复新报价 26 元，未注明原价对比、起订量及适用生产批次。',problem:'工厂新报价未明确比较基准与生效批次，起订条件也未落实，采购无法据此执行或确认价格传导。',deductions:[
  {ruleId:'baseline',problem:'仅提供新报价，缺少原价比较基准。'},
  {ruleId:'moq',problem:'未说明新报价的起订量。'},
  {ruleId:'batch',problem:'未说明新报价适用的生产批次。'}]}
};
function gdReportCompleteContent(context,department,workDate){
 const date=offset=>shiftDate(workDate,offset),stamp=workDate.replaceAll('-','');
 const identity=product=>{const master=upSpus.get(product.spuId)||product;return `产品：${product.name}；型号/SPU标识：${master.model||master.spuCode||product.spuId}`};
 const product=identity(context.product),launch=identity(context.newProduct);
 const cases={
  '产品中心':{
   object:launch,
   progress:'小范围试销已完成，正推进全渠道首发批次确认，已交付渠道清单，最终批次表待确认。',
   result:`截至 ${workDate}，试销目标 500 台，实际签收 320 台，差额 180 台；备货量不计入签收成果。`,
   risk:'首发批次尚未确认，影响渠道备货；活动价保和退差价费用仍需核实，可能压低实际毛利。',
   evidence:`依据《试销签收汇总》${workDate}版及《首发方案对比表》V1，查询位置：产品资料库/试销复盘；经营结果已核对，首发方案待评审。`,
   next:`林悦于 ${date(2)} 提交首发批次对比表，组织采购部确认供货条件并发布最终批次表。`},
  '项目部':{
   object:`项目：${context.project.name}；项目ID：${context.project.id}${context.project.model?'；关联产品型号：'+context.project.model:''}`,
   progress:`节点：样机验收，计划 ${date(-3)} 完成，当前仍待验收，尚未取得物料齐套确认。`,
   result:'较计划延期 3 天，关键电机晚到，后续渠道验收窗口可能顺延。',
   risk:`依赖采购部于 ${date(1)} 回传物料齐套日；该承诺仍待确认，品质验收排期以齐套回传为前置输入。`,
   evidence:`《项目节点排期》${workDate}版与《样机验收清单》V1已归档至项目资料库/交付跟踪；沈舟负责确认节点，验收以清单为准。`,
   next:`沈舟于 ${date(2)} 汇总采购及品质排期，形成调整后的交付表；仍未确认的齐套条件提交采购负责人协调。`},
  '品质中心':{
   object:`${product}；检测批次：QA-${stamp}；样本编号：S01—S10。`,
   progress:'针对吸力衰减，在统一档位、连续运行10分钟的条件下现场复现，抽样 10 台中 3 台异常；客户投诉与现场结果分别记录。',
   result:'清理滤网后吸力恢复，滤网堵塞为已验证原因；电机衰减仍属假设，待开展电机对照试验。',
   risk:'整改复测 10 台、通过 9 台，失败样本 S10 暂留分析；暂缓本批次放行，未确认异常原因前保持隔离。',
   evidence:`《吸力复现记录》《整改复测记录》${workDate}版已存于品质资料库/复测追溯，整改前后记录按S01—S10关联。`,
   next:`刘畅于 ${date(2)} 提交复测记录核对及余下样本验证结论；达到验收标准且证据齐全后申请关闭，否则保留样本继续分析。`},
  '研发中心':{
   object:`${product}；验证部件：替代电机MTR-01；BOM版本：V2；图纸版本：V3。`,
   progress:'额定负载连续运行30分钟，替代电机温升验证10台中9台达标，测试已完成，异常尚未关闭，暂不切换生产。',
   result:'替代料预计单台节约2元，工装及旧料切换费用折合每台0.4元，预计净节约1.6元；适用于BOM V2下一生产批次，待成本确认。',
   risk:'1台温升超标，绕组参数为待验证假设，存在性能及安规影响；先进行参数对照验证，再评估交期。',
   evidence:`BOM V2、图纸V3、《替代电机温升验证》${workDate}版及《切换成本测算》V1已关联，查询位置：研发资料库/温升验证。`,
   next:`王磊于 ${date(2)} 提交绕组对比测试报告与修订BOM，交品质复核温升标准、采购核对切换物料清单。`},
  '采购部':{
   object:`${product}；物料：电机组件MTR-01；采购单：PO-${stamp}-01；供应商：协同电机制造有限公司（样例）。`,
   progress:`采购数量1000件，已到0件、未到1000件；供方已书面确认 ${date(3)} 到货，交期已确认而非询期结果。`,
   result:'原报价28元，新报价26元，均为含税含运费口径；起订量1000件，下月首批订单生效，价格条件已书面确认，降本仍需实际订单复核。',
   risk:'备用供方检测报告未齐，主供异常时存在保供风险；备选电机仅完成资料预审，尚不能直接切换供货。',
   evidence:`采购单PO-${stamp}-01、《电机报价确认》V1及《交期回执》${workDate}版已关联，查询位置：采购资料库/订单跟踪。`,
   next:`唐琪于 ${date(2)} 回收备用供方检测报告和交期回执，交刘畅复核准入条件，并反馈物料保障结果。`}
 };
 return cases[department];
}
